  public void cmdContourMenu(bool EditorMode = false)
  {
    clsMarble.frmContourMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsMarble.frmContourMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
    clsMarble.frmContourMenu.ItemType = MarbleItemType.Contour;
    clsMarble.frmContourMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedContour);
    clsMarble.frmContourMenu.MenuType.InsideMilling = buMarbleCalc.varMarbleRunSettings.InisdeMilling;
    clsMarble.frmContourMenu.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting;
    clsMarble.frmContourMenu.Init();
    if (!EditorMode)
    {
      int num1 = (int) clsMarble.frmContourMenu.ShowDialog();
    }
    if (!(clsMarble.frmContourMenu.PropertiesForm.Result == DialogResult.OK | EditorMode))
      return;
    this.SaveMarbleFile();
    buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting = clsMarble.frmContourMenu.chk_addtonesting.Check;
    if (EditorMode)
      clsMarble.frmContourMenu.ContourType = MarbleContourMenuType.Editor;
    if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileContour).Exists)
    {
      buMarbleCalc.varMarbleRunSettings.pathFromFileContour = AppPath.Base + "\\External2DFiles\\Contour";
      if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileContour).Exists)
        buMarbleCalc.varMarbleRunSettings.pathFromFileContour = AppPath.Base;
    }
    buMarbleCalc.varMarbleRunSettings.selectedContour = new marbleMenuType(clsMarble.frmContourMenu.MenuType);
    buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(clsMarble.frmContourMenu.MenuType);
    buMarbleCalc.varMarbleRunSettings.InisdeMilling = clsMarble.frmContourMenu.chk_insidemilling.Check;
    if (MarbleTempVars.ItemsContour == null)
      MarbleTempVars.ItemsContour = new List<MarbleItem>();
    else
      MarbleTempVars.ItemsContour.Clear();
    this.entitiesForContour.Clear();
    List<buEntity> EL = new List<buEntity>();
    buMarbleCalc.varMarbleRunSettings.BorderEnable = false;
    if (clsMarble.frmContourMenu.ContourType == MarbleContourMenuType.Editor)
    {
      if (clsItem.frmEditorV2 == null)
        clsItem.frmEditorV2 = new F_EditorV2();
      clsItem.frmEditorV2.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsVar.varEditorRuntimeSet.isSketchMode = true;
      clsItem.frmEditorV2.Init();
      int num2 = (int) clsItem.frmEditorV2.ShowDialog((IWin32Window) clsItem.FrmMain);
      clsInit.appEditor2.SaveEditorFile(AppPath.MachineSettings + "\\Editor.prm");
    }
    else
    {
      if (clsMarble.frmContourMenu.ContourType == MarbleContourMenuType.FromFile)
      {
        OpenFileDialog openFileDialog = new OpenFileDialog();
        openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
        openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
        openFileDialog.FilterIndex = 1;
        if (openFileDialog.ShowDialog() != DialogResult.OK)
          return;
        buMarbleCalc.varMarbleRunSettings.pathFromFileContour = buFile5.GetPath(openFileDialog.FileName);
        FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
        if (!fileInfo.Exists)
          return;
        if (fileInfo.Extension.ToLower() == ".dxf" | fileInfo.Extension.ToLower() == ".dwg")
        {
          List<Entity> EntityList = new List<Entity>();
          buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
          for (int index = 0; index <= EntityList.Count - 1; ++index)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(EntityList[index], ref copiedEntity);
            EL.Add(copiedEntity);
          }
        }
        if (fileInfo.Extension.ToLower() == ".bucadv5")
        {
          List<Entity> refEntities = new List<Entity>();
          clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, true, ref refEntities);
          for (int index = 0; index <= refEntities.Count - 1; ++index)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(refEntities[index], ref copiedEntity);
            EL.Add(copiedEntity);
          }
        }
        clsInit.appEditor.SaveEditorFile();
      }
      if (clsMarble.frmContourMenu.ContourType == MarbleContourMenuType.FromList)
      {
        if (clsItem.FrmFromFile == null)
          clsItem.FrmFromFile = new F_AddFromFile();
        clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
        clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
        clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
        clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
        clsItem.FrmFromFile.ExtensionList.Clear();
        clsItem.FrmFromFile.ExtensionList.Add(".dxf");
        clsItem.FrmFromFile.ExtensionList.Add(".dwg");
        clsItem.FrmFromFile.ExtensionList.Add(".bucadv5");
        clsItem.FrmFromFile.MoveEntities = false;
        clsItem.FrmFromFile.Init();
        int num3 = (int) clsItem.FrmFromFile.ShowDialog();
        if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
          return;
        buEntityUtilities.EntityRegenDeviation = 0.05;
        buMarbleCalc.varMarbleRunSettings.pathFromFileContour = clsItem.FrmFromFile.Path;
        clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
        for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
          EL.Add(copiedEntity);
        }
        clsInit.appEditor.SaveEditorFile();
      }
      if (clsMarble.frmContourMenu.ContourType == MarbleContourMenuType.Digitizer)
      {
        OpenFileDialog openFileDialog = new OpenFileDialog();
        openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileContour;
        openFileDialog.Filter = "All Drawing Files (*.Txt,*.budigit)|*.txt;*.budigit;|Digitizer Txt Files (*.txt)|*.txt|Bu Dgitizer File (*.budigit)|*.budigit";
        openFileDialog.FilterIndex = 1;
        if (openFileDialog.ShowDialog() != DialogResult.OK)
          return;
        ArrayList StringList = new ArrayList();
        List<List<string>> CalcList1 = new List<List<string>>();
        buMarbleCalc.varMarbleRunSettings.pathFromFileContour = buFile5.GetPath(openFileDialog.FileName);
        buFile5.OpenFromFile(openFileDialog.FileName, ref StringList);
        buStatics.ListToSpecificList("<Contour>", "</Contour>", true, StringList, ref CalcList1);
        for (int index1 = 0; index1 <= CalcList1.Count - 1; ++index1)
        {
          List<string> CalcList2 = new List<string>();
          buStatics.ListToSpecificList("<Outer>", "</Outer>", false, CalcList1[index1], ref CalcList2);
          List<Point3D> PL = new List<Point3D>();
          for (int index2 = 0; index2 <= CalcList2.Count - 1; ++index2)
          {
            string[] strArray = CalcList2[index2].Split(';');
            if (strArray.Length >= 2)
            {
              Point3D point3D = new Point3D(Convert.ToDouble(strArray[0]), Convert.ToDouble(strArray[1]));
              PL.Add(point3D);
            }
          }
          if (PL.Count >= 2)
          {
            List<List<Point3D>> PLFixed = new List<List<Point3D>>();
            clsInit.cVector5.FixPoints(PL, ref PLFixed);
            if (clsItem.frmEditor == null)
              clsItem.frmEditor = new F_Editor();
            clsVar.varEditorRuntimeSet.isSketchMode = false;
            clsVar.varEditorRuntimeSet.isSewingMode = false;
            clsItem.frmEditor = new F_Editor();
            clsItem.frmEditor.entitiesExisting.Clear();
            for (int index3 = 0; index3 <= PLFixed.Count - 1; ++index3)
            {
              LinearPath linearPath = new LinearPath((ICollection<Point3D>) PLFixed[index3]);
              clsItem.frmEditor.entitiesExisting.Add((Entity) linearPath);
            }
            clsItem.frmEditor.OpenFileExtension.Clear();
            clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
            clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
            clsItem.frmEditor.Init();
            int num4 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
          }
        }
        for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
          if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
            EL.Add(copiedEntity);
        }
        clsInit.appEditor.SaveEditorFile();
      }
      this.cmdContourCommon(EL);
    }
  }

