      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        if (clsItem.frmEditor.viewport.Entities[index] is ICurve)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
          if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve && clsItem.frmEditor.viewport.Entities[index].GetType() != typeof (devDept.Eyeshot.Entities.Point))
            copyEntities.Add(copiedEntity);
        }
      }
    }
    if (clsMarble.frmLibraryMenu.LibraryType == MarbleLibraryMenuType.FromList)
    {
      clsVar.varLibrary.pathLibrary = buMarbleCalc.varMarbleRunSettings.pathFromFileLibray;
      this.cmdLibDraw();
      if (clsMarble.FrmLibraryDraw.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileLibray = clsVar.varLibrary.pathLibrary;
      clsInit.cVector5.CopyEntitiesToEntities(clsMarble.FrmLibraryDraw.LibraryEntities, ref copyEntities, new EntitiesCopySettings(false, false, true, true, true, true, true, 0.05, 0.1)
      {
        ForcePlaneXY = true
      });
      for (int index = 0; index <= copyEntities.Count - 1; ++index)
      {
        if (copyEntities[index] is buArc)
        {
          buArc buArc = copyEntities[index] as buArc;
          buArc.StartAngle = clsInit.cVector5.PointAngle(buArc.StartPoint, buArc.Center);
          buArc.EndAngle = clsInit.cVector5.PointAngle(buArc.EndPoint, buArc.Center);
        }
      }
    }
    this.cmdContourCommon(copyEntities);
    copyEntities.Clear();
  }

