  public void cmdContourCommon(List<buEntity> EL)
  {
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
    if (EL.Count > 0)
    {
      clsInit.cVector5.RemoveDublicatedEntities(ref EL);
      if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Minus)
        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisZ, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Minus)
        clsInit.cVector5.Rotate(new Point3D(), -180.0, Vector3D.AxisZ, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate90Plus)
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisZ, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.Rotate180Plus)
        clsInit.cVector5.Rotate(new Point3D(), 180.0, Vector3D.AxisZ, ref EL);
      if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorX)
        clsInit.cVector5.Mirror(new Point3D(), new Point3D(100.0, 0.0, 0.0), Plane.XY, ref EL);
      if (buMarbleCalc.varMarbleRunSettings.selectedType.MirrorY)
        clsInit.cVector5.Mirror(new Point3D(), new Point3D(0.0, 100.0, 0.0), Plane.XY, ref EL);
      entityToolType entityToolType = entityToolType.Saw;
      bool isMilling = false;
      bool isMillingHead = false;
      bool isWaterJet = false;
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling)
      {
        entityToolType = entityToolType.Milling;
        isMilling = true;
      }
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead)
      {
        entityToolType = entityToolType.MillingHead;
        isMillingHead = true;
      }
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
      {
        entityToolType = entityToolType.WaterJet;
        isWaterJet = true;
      }
      if (entityToolType == entityToolType.Saw)
        clsInit.cMarble.AnalyzeImportEntities(ref EL);
      this.entitiesGroupForContour.Clear();
      this.entitiesGroupForContour = new List<buEntitiesGroup>();
      this.entitiesGroupForRefEntities.Clear();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(EL, ref MinPoint, ref MidPoint, ref MaxPoint);
      if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomLeft)
        clsInit.cVector5.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomCenter)
        clsInit.cVector5.Move(-MidPoint.X, -MinPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomRight)
        clsInit.cVector5.Move(-MaxPoint.X, -MinPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleLeft)
        clsInit.cVector5.Move(-MinPoint.X, -MidPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleCenter)
        clsInit.cVector5.Move(-MidPoint.X, -MidPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleRight)
        clsInit.cVector5.Move(-MaxPoint.X, -MidPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopLeft)
        clsInit.cVector5.Move(-MinPoint.X, -MaxPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopCenter)
        clsInit.cVector5.Move(-MidPoint.X, -MaxPoint.Y, -MinPoint.Z, ref EL);
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopRight)
        clsInit.cVector5.Move(-MaxPoint.X, -MaxPoint.Y, -MinPoint.Z, ref EL);
      this.entitiesGroupForContour.Clear();
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Saw)
      {
        if (!buMarbleCalc.varMarbleSettings.OutsideEntityIsReferance)
        {
          clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref this.entitiesGroupForContour, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
        }
        else
        {
          List<buEntitiesGroup> Groups = new List<buEntitiesGroup>();
          clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref Groups, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
          this.entitiesGroupForContour.Clear();
          for (int index1 = 0; index1 <= Groups.Count - 1; ++index1)
          {
            if (Groups[index1].Inside != null)
            {
              for (int index2 = 0; index2 <= Groups[index1].Inside.Count - 1; ++index2)
                this.entitiesGroupForContour.Add(new buEntitiesGroup()
                {
                  Outside = new buEntityList(Groups[index1].Inside[index2])
                });
            }
            if (Groups[index1].Outside.Entities.Count > 0)
              this.entitiesGroupForRefEntities.Add(new buEntitiesGroup()
              {
                Outside = new buEntityList(Groups[index1].Outside)
              });
          }
        }
      }
      else
        clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), EL, Plane.XY, ref this.entitiesGroupForContour, new FindEntitiesGroupSettings(SortingIntersectionRulesType.LowerIndex, SortingNextGroupFindRulesType.ClosestLength, 0.05, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection, buMarbleCalc.varOperation.settingMarbleCam.ContourInsideDirection));
      if (this.entitiesGroupForContour.Count > 0)
        buMarbleCalc.CountertopRefEntGroup = new buEntitiesGroup(this.entitiesGroupForContour[0]);
      for (int index3 = 0; index3 <= this.entitiesGroupForContour.Count - 1; ++index3)
      {
        this.entitiesGroupForContour[index3].Outside.Marble = new marbleEntityData();
        clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref this.entitiesGroupForContour[index3].Outside.Marble);
        this.entitiesGroupForContour[index3].Outside.ToolType = entityToolType;
        if (this.entitiesGroupForContour[index3].Outside.Entities.Count > 0 && buMarbleCalc.varMarbleRunSettings.InisdeMilling)
          this.entitiesGroupForContour[index3].Outside.ToolType = entityToolType.Saw;
        if (this.entitiesGroupForContour[index3].Inside != null)
        {
          for (int index4 = 0; index4 <= this.entitiesGroupForContour[index3].Inside.Count - 1; ++index4)
          {
            this.entitiesGroupForContour[index3].Inside[index4].ToolType = entityToolType;
            if (buMarbleCalc.varMarbleRunSettings.InisdeMilling)
              this.entitiesGroupForContour[index3].Inside[index4].ToolType = entityToolType.Milling;
            this.entitiesGroupForContour[index3].Inside[index4].Marble = new marbleEntityData();
            clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref this.entitiesGroupForContour[index3].Inside[index4].Marble);
          }
        }
        if (this.entitiesGroupForContour[index3].OpenEntities != null)
        {
          for (int index5 = 0; index5 <= this.entitiesGroupForContour[index3].OpenEntities.Count - 1; ++index5)
          {
            this.entitiesGroupForContour[index3].OpenEntities[index5].ToolType = entityToolType;
            if (buMarbleCalc.varMarbleRunSettings.InisdeMilling)
              this.entitiesGroupForContour[index3].OpenEntities[index5].ToolType = entityToolType.Milling;
            this.entitiesGroupForContour[index3].OpenEntities[index5].Marble = new marbleEntityData();
            clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref this.entitiesGroupForContour[index3].OpenEntities[index5].Marble);
          }
        }
      }
      if (buMarbleCalc.varMarbleRunSettings.selectedContourAddNesting)
      {
        if (clsInit.appNesting == null)
          return;
        clsInit.appNesting.doAddShapePart(this.entitiesGroupForContour);
      }
      else
      {
        clsInit.appMarble.activeItemType = MarbleItemType.Contour;
        this.doAddItemShapeContour(new Point3D(), false, false, false, isMilling, isMillingHead, isWaterJet, false, -1);
        clsInit.appMarble.entitiesForMove.Clear();
        if (MarbleTempVars.ItemsContour.Count > 0)
        {
          for (int index = 0; index <= EL.Count - 1; ++index)
          {
            Entity copiedEntity = (Entity) null;
            buEntity.Copy(EL[index], ref copiedEntity);
            clsInit.appMarble.entitiesForMove.Add(copiedEntity);
          }
          for (int index6 = 0; index6 <= MarbleTempVars.ItemsContour.Count - 1; ++index6)
          {
            if (MarbleTempVars.ItemsContour[index6].ItemEntities.SolidEntity != null)
            {
              for (int index7 = 0; index7 <= MarbleTempVars.ItemsContour[index6].ItemEntities.SolidEntity.Count - 1; ++index7)
              {
                Entity copiedEntity = (Entity) null;
                buEntity.Copy(MarbleTempVars.ItemsContour[index6].ItemEntities.SolidEntity[index7], ref copiedEntity);
                clsInit.appMarble.entitiesForMove.Add(copiedEntity);
              }
            }
          }
          this.MoveCreatedEntity = true;
          if (clsItem.pnlSettings != null)
          {
            Size PanelSize = new Size(clsItem.pnlSettings.Size.Width, clsItem.pnlSettings.Size.Height);
            if (clsItem.pnlSettings.Parent != null && PanelSize.Width < clsItem.pnlSettings.Parent.Size.Width - 10)
              PanelSize.Width = clsItem.pnlSettings.Parent.Size.Width - 6;
            this.OperationControlSizeAdjustment(PanelSize, buMarbleCalc.varOperation);
            clsItem.pnlSettings.Visible = true;
          }
        }
        this.cmdOperationCommon();
      }
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

  public void cmdLibDraw()
  {
    if (clsMarble.FrmLibraryDraw == null)
      clsMarble.FrmLibraryDraw = new F_SketchLibrary();
    clsMarble.FrmLibraryDraw.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsMarble.FrmLibraryDraw.varLib = new setLibrary(clsVar.varLibrary);
