        num4 = (int) buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYCount;
      }
      Point3D MinPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate((Entity) wireEntity, ref MinPoint, ref MidPoint, ref MaxPoint);
      if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomLeft)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomCenter)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MidPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.BottomRight)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MaxPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleLeft)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MinPoint.X, -MidPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleCenter)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MidPoint.X, -MidPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.MiddleRight)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MaxPoint.X, -MidPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopLeft)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MinPoint.X, -MaxPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopCenter)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MidPoint.X, -MaxPoint.Y, -MinPoint.Z, ref refEntities);
      }
      else if (buMarbleCalc.varMarbleRunSettings.selectedType.objectAlignment == ObjectAlignment.TopRight)
      {
        Entity refEntities = wireEntity as Entity;
        clsInit.cVector5.Move(-MaxPoint.X, -MaxPoint.Y, -MinPoint.Z, ref refEntities);
      }
      double num6 = MaxPoint.X - MinPoint.X + num5 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXDistance;
      double num7 = MaxPoint.Y - MinPoint.Y + num5 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYDistance;
      for (int index1 = 0; index1 <= num3 - 1; ++index1)
      {
        for (int index2 = 0; index2 <= num4 - 1; ++index2)
        {
          double dx = (double) index1 * num6;
          double dy = (double) index2 * num7;
          Entity copiedEntity = (Entity) null;
          buEntity.Copy((Entity) wireEntity, ref copiedEntity);
          copiedEntity.Translate(dx, dy);
          clsInit.appMarble.entitiesForMove.Add(copiedEntity);
        }
      }
      clsInit.appMarble.activeItemType = MarbleItemType.Shape;
      clsInit.appMarble.MoveCreatedEntity = true;
      this.cmdOperationCommon();
    }
  }

