      clsInit.cVector5.GetEntityEndPointByCamDirection(this.entitiesForProfiling[this.entitiesForProfiling.Count - 1], ref pntEnd);
      if (!clsInit.cVector5.isEntitiesClosed(this.entitiesForProfiling))
      {
        if (Math.Round(pntStart.Y, 5) > 0.0)
          this.entitiesForProfiling.Insert(0, (buEntity) new buLine(new Point3D(pntStart.X, 0.0, pntStart.Z), pntStart));
        if (Math.Round(pntEnd.Y, 5) > 0.0)
