      clsItem.frmEditor.Init();
      int num2 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
          refEntities1.Add(copiedEntity);
      }
    }
    if (clsMarble.frmSweepMenu.SweepType == MarbleSweepMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileSweep;
      openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileSweep = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (!fileInfo.Exists)
        return;
      if (fileInfo.Extension.ToLower() == ".dxf" | fileInfo.Extension.ToLower() == ".dwg")
      {
        List<Entity> EntityList = new List<Entity>();
        buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
        for (int index = 0; index <= EntityList.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(EntityList[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      if (fileInfo.Extension.ToLower() == ".bucadv5")
      {
        List<Entity> refEntities2 = new List<Entity>();
        clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, true, ref refEntities2);
        for (int index = 0; index <= refEntities2.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntities2[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmSweepMenu.SweepType == MarbleSweepMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileSweep;
      clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmFromFile.ExtensionList.Clear();
      clsItem.FrmFromFile.ExtensionList.Add(".dxf");
      clsItem.FrmFromFile.ExtensionList.Add(".dwg");
      clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num3 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileSweep = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
        refEntities1.Add(copiedEntity);
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (refEntities1.Count > 0)
    {
      F_MarbleSweepCut fMarbleSweepCut = new F_MarbleSweepCut();
      fMarbleSweepCut.varSweep = new marbleSweepPars(buMarbleCalc.varOperation.settingSweepCut);
      fMarbleSweepCut.Init();
      int num4 = (int) fMarbleSweepCut.ShowDialog((IWin32Window) clsItem.FrmMain);
      MarbleTempVars.ItemsSweep.Clear();
      if (MarbleTempVars.SweepZFormEntities == null)
        MarbleTempVars.SweepZFormEntities = new List<buEntity>();
      MarbleTempVars.SweepZFormEntities.Clear();
      if ((fMarbleSweepCut.SweepZFormEntities == null ? 0 : (fMarbleSweepCut.SweepZFormEntities.Count > 0 ? 1 : 0)) != 0)
        buEntity.Copy(fMarbleSweepCut.SweepZFormEntities, ref MarbleTempVars.SweepZFormEntities);
      buMarbleCalc.varOperation.settingSweepCut = new marbleSweepPars(fMarbleSweepCut.varSweep);
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(refEntities1, ref MinPoint, ref MaxPoint);
      clsInit.cVector5.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities1);
      SortbuSettings Settings = new SortbuSettings();
      Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
      List<buEntity> SortedEntities = new List<buEntity>();
      clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref refEntities1, Settings, ref SortedEntities);
      clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref this.entitiesForSweep);
      clsInit.appMarble.activeItemType = MarbleItemType.Sweep;
      this.doAddItemSweep(new Point3D());
      this.cmdOperationCommon();
      clsInit.appMarble.entitiesForMove.Clear();
      MarbleTempVars.isSolidMove = true;
      if (MarbleTempVars.ItemsSweep.Count <= 0)
        return;
      for (int index1 = 0; index1 <= MarbleTempVars.ItemsSweep.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= MarbleTempVars.ItemsSweep[index1].ItemEntities.SourceEntities.Count - 1; ++index2)
        {
          List<Point3D> points = new List<Point3D>();
          buVector5.Copy(MarbleTempVars.ItemsSweep[index1].ItemEntities.SourceEntities[index2].Vertices, ref points);
          clsInit.cVector5.PointFilterByLength(5.0, ref points);
          Entity entity = (Entity) new LinearPath((ICollection<Point3D>) points);
          clsInit.appMarble.entitiesForMove.Add(entity);
        }
      }
      clsInit.cVector5.BoxSizeCalculate(clsInit.appMarble.entitiesForMove, ref MinPoint, ref MaxPoint);
      Entity rectangleEntity = (Entity) null;
      clsInit.cVector5.DrawRectangle(MinPoint, MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y, Plane.XY, ref rectangleEntity);
      rectangleEntity.Translate(0.0, 0.0, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
      clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
      this.MoveCreatedEntity = true;
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

  public void cmdCavityMenu()
  {
    if (buMarbleForms.frmCavity == null)
      buMarbleForms.frmCavity = new F_MarbleCavity();
    buMarbleForms.frmCavity.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    buMarbleForms.frmCavity.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
    buMarbleForms.frmCavity.varSettings = new marbleCavityPars(buMarbleCalc.varOperation.settingCavity);
    buMarbleForms.frmCavity.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    buMarbleForms.frmCavity.Init();
    int num1 = (int) buMarbleForms.frmCavity.ShowDialog();
    if (buMarbleForms.frmCavity.PropertiesForm.Result != DialogResult.OK)
      return;
    buMarbleCalc.varOperation.settingCavity = new marbleCavityPars(buMarbleForms.frmCavity.varSettings);
    buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = buMarbleForms.frmCavity.ToolType;
    double thickness = buMarbleCalc.activeToolSaw.Geometry.Thickness;
    clsInit.cMarble.GetToolThickness(buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool, ref thickness);
    this.entitiesForCavity.Clear();
    for (int index1 = 0; index1 <= buMarbleCalc.varOperation.settingCavity.CavityCount - 1; ++index1)
    {
      int upper = (int) buNumeric5.RoundToUpper((buMarbleCalc.varOperation.settingCavity.CavityHeight - thickness) / (thickness * 0.8));
      double num2 = upper > 0 ? (buMarbleCalc.varOperation.settingCavity.CavityHeight - thickness) / (double) upper : 0.0;
      Entity rectangle = (Entity) CompositeCurve.CreateRectangle(buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityHeight);
      rectangle.Translate(0.0, (double) index1 * buMarbleCalc.varOperation.settingCavity.CavitySpace);
      rectangle.Rotate(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingCavity.CavityAngle), Vector3D.AxisZ, new Point3D());
      buEntity copiedEntity = (buEntity) null;
      buEntity.Copy(rectangle, ref copiedEntity);
      this.entitiesForCavity.Add(copiedEntity);
      for (int index2 = 0; index2 <= upper; ++index2)
      {
        double Length = thickness / 2.0 + (double) index2 * num2 + (double) index1 * buMarbleCalc.varOperation.settingCavity.CavitySpace;
        Point3D EndPnt1 = new Point3D();
        Point3D EndPnt2 = new Point3D();
        clsInit.cVector5.LineWithLengthAndAngle(EndPnt1, Length, buMarbleCalc.varOperation.settingCavity.CavityAngle + 90.0, ref EndPnt1);
        if (Length == 0.0)
          clsInit.cVector5.LineWithLengthAndAngle(EndPnt1, buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityAngle, ref EndPnt2);
        else
          clsInit.cVector5.LineWithLengthAndAngle(EndPnt1, buMarbleCalc.varOperation.settingCavity.CavityLength, buMarbleCalc.varOperation.settingCavity.CavityAngle, ref EndPnt2);
        this.entitiesForCavity.Add((buEntity) new buLine(EndPnt1, EndPnt2));
      }
    }
    if (this.entitiesForCavity.Count > 0)
    {
      if (MarbleTempVars.ItemsCavity == null)
        MarbleTempVars.ItemsCavity = new List<MarbleItem>();
      MarbleTempVars.ItemsCavity.Clear();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.appMarble.activeItemType = MarbleItemType.Cavity;
      this.doAddItemCavity(new Point3D());
      this.cmdOperationCommon();
      clsInit.appMarble.entitiesForMove.Clear();
      MarbleTempVars.isSolidMove = true;
      if (MarbleTempVars.ItemsCavity.Count <= 0)
        return;
      for (int index3 = 0; index3 <= MarbleTempVars.ItemsCavity.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= MarbleTempVars.ItemsCavity[index3].ItemEntities.SourceEntities.Count - 1; ++index4)
        {
          List<Point3D> copiedPoint = new List<Point3D>();
          buVector5.Copy(MarbleTempVars.ItemsCavity[index3].ItemEntities.SourceEntities[index4].Vertices, ref copiedPoint);
          Entity entity = (Entity) new LinearPath((ICollection<Point3D>) copiedPoint);
          clsInit.appMarble.entitiesForMove.Add(entity);
        }
      }
      clsInit.cVector5.BoxSizeCalculate(clsInit.appMarble.entitiesForMove, ref MinPoint, ref MaxPoint);
      Entity rectangleEntity = (Entity) null;
      clsInit.cVector5.DrawRectangle(MinPoint, MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y, Plane.XY, ref rectangleEntity);
      rectangleEntity.Translate(0.0, 0.0, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
      clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
      this.MoveCreatedEntity = true;
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

  public void cmdTapMenu()
