  public void cmdDrillMenu()
  {
    clsMarble.frmDrillMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsMarble.frmDrillMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
    clsMarble.frmDrillMenu.ItemType = MarbleItemType.Drill;
    clsMarble.frmDrillMenu.MenuType = new marbleMenuType(buMarbleCalc.varMarbleRunSettings.selectedDrill);
    clsMarble.frmDrillMenu.Init();
    int num1 = (int) clsMarble.frmDrillMenu.ShowDialog();
    if (clsMarble.frmDrillMenu.PropertiesForm.Result != DialogResult.OK)
      return;
    buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(clsMarble.frmDrillMenu.MenuType);
    buMarbleCalc.varMarbleRunSettings.selectedDrill = new marbleMenuType(clsMarble.frmDrillMenu.MenuType);
    if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileDrill).Exists)
    {
      buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = AppPath.Base + "\\External2DFiles\\Drill";
      if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileDrill).Exists)
        buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = AppPath.Base;
    }
    if (MarbleTempVars.ItemsDrill == null)
      MarbleTempVars.ItemsDrill = new List<MarbleItem>();
    else
      MarbleTempVars.ItemsDrill.Clear();
    this.entitiesForDrill.Clear();
    List<buEntity> refEntities = new List<buEntity>();
    bool isFinished = false;
    if (clsMarble.frmDrillMenu.DrillType == MarbleDrillMenuType.Editor)
    {
      if (clsItem.frmEditor == null)
        clsItem.frmEditor = new F_Editor();
      clsVar.varEditorRuntimeSet.isSketchMode = false;
      clsVar.varEditorRuntimeSet.isSewingMode = false;
      clsItem.frmEditor = new F_Editor();
      clsItem.frmEditor.OpenFileExtension.Clear();
      clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
      clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.frmEditor.Init();
      int num2 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index].GetType() == typeof (Circle))
        {
          copiedEntity.Marble = new MarbleInfo();
          copiedEntity.Marble.Depth = buMarbleCalc.varMarbleRunSettings.DrillDepth;
          refEntities.Add(copiedEntity);
        }
      }
    }
    if (clsMarble.frmDrillMenu.DrillType == MarbleDrillMenuType.FromTable)
    {
      F_MarbleHoleTable fMarbleHoleTable = new F_MarbleHoleTable();
      fMarbleHoleTable.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      fMarbleHoleTable.Hole = new DiameterDepthPoint(new Point3D(buMarbleCalc.varMarbleRunSettings.DrillXPosition, buMarbleCalc.varMarbleRunSettings.DrillYPosition, buMarbleCalc.varMarbleRunSettings.DrillZPosition), buMarbleCalc.varMarbleRunSettings.DrillDiameter, buMarbleCalc.varMarbleRunSettings.DrillDepth);
      fMarbleHoleTable.Init();
      int num3 = (int) fMarbleHoleTable.ShowDialog();
      if (fMarbleHoleTable.PropertiesForm.Result == DialogResult.OK)
      {
        buMarbleCalc.varMarbleRunSettings.DrillXPosition = fMarbleHoleTable.Hole.Position.X;
        buMarbleCalc.varMarbleRunSettings.DrillYPosition = fMarbleHoleTable.Hole.Position.Y;
        buMarbleCalc.varMarbleRunSettings.DrillZPosition = fMarbleHoleTable.Hole.Position.Z;
        buMarbleCalc.varMarbleRunSettings.DrillDiameter = fMarbleHoleTable.Hole.Diameter;
        buMarbleCalc.varMarbleRunSettings.DrillDepth = fMarbleHoleTable.Hole.Depth;
        if (fMarbleHoleTable.Holes.Count > 0)
        {
          for (int index = 0; index <= fMarbleHoleTable.Holes.Count - 1; ++index)
          {
            buCircle buCircle = new buCircle(fMarbleHoleTable.Holes[index].Position, fMarbleHoleTable.Holes[index].Diameter / 2.0);
            buCircle.Marble = new MarbleInfo();
            buCircle.Marble.Depth = fMarbleHoleTable.Holes[index].Depth;
            refEntities.Add((buEntity) buCircle);
          }
          isFinished = true;
        }
      }
    }
    if (clsMarble.frmDrillMenu.DrillType == MarbleDrillMenuType.Coordinate)
    {
      F_MarbleHoleData fMarbleHoleData = new F_MarbleHoleData();
      fMarbleHoleData.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
      fMarbleHoleData.Hole = new DiameterDepthPoint(new Point3D(buMarbleCalc.varMarbleRunSettings.DrillXPosition, buMarbleCalc.varMarbleRunSettings.DrillYPosition, buMarbleCalc.varMarbleRunSettings.DrillZPosition), buMarbleCalc.varMarbleRunSettings.DrillDiameter, buMarbleCalc.varMarbleRunSettings.DrillDepth);
      fMarbleHoleData.Init();
      int num4 = (int) fMarbleHoleData.ShowDialog();
      if (fMarbleHoleData.PropertiesForm.Result == DialogResult.OK)
      {
        buMarbleCalc.varMarbleRunSettings.DrillXPosition = fMarbleHoleData.Hole.Position.X;
        buMarbleCalc.varMarbleRunSettings.DrillYPosition = fMarbleHoleData.Hole.Position.Y;
        buMarbleCalc.varMarbleRunSettings.DrillZPosition = fMarbleHoleData.Hole.Position.Z;
        buMarbleCalc.varMarbleRunSettings.DrillDiameter = fMarbleHoleData.Hole.Diameter;
        buMarbleCalc.varMarbleRunSettings.DrillDepth = fMarbleHoleData.Hole.Depth;
        buCircle buCircle = new buCircle(fMarbleHoleData.Hole.Position, fMarbleHoleData.Hole.Diameter / 2.0);
        buCircle.Marble = new MarbleInfo();
        buCircle.Marble.Depth = buMarbleCalc.varMarbleRunSettings.DrillDepth;
        refEntities.Add((buEntity) buCircle);
        isFinished = true;
      }
    }
    if (clsMarble.frmDrillMenu.DrillType == MarbleDrillMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileDrill;
      openFileDialog.Filter = "Drill Files (*.budrill)|*.budrill";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (!fileInfo.Exists)
        return;
      if (fileInfo.Extension.ToLower() == ".budrill")
      {
        this.OpenMarbleDrillFile(fileInfo.FullName);
        if (this.DrillList.Count > 0)
        {
          for (int index = 0; index <= this.DrillList.Count - 1; ++index)
          {
            buCircle buCircle = new buCircle(this.DrillList[index].pntCenter, this.DrillList[index].Diameter);
            buCircle.Marble = new MarbleInfo();
            buCircle.Marble.Depth = this.DrillList[index].Depth;
            refEntities.Add((buEntity) buCircle);
          }
        }
      }
      isFinished = true;
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmDrillMenu.DrillType == MarbleDrillMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileDrill;
      clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmFromFile.ExtensionList.Clear();
      clsItem.FrmFromFile.ExtensionList.Add(".budrill");
      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num5 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileDrill = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
        refEntities.Add(copiedEntity);
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (refEntities.Count > 0)
    {
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
      if (!isFinished)
        clsInit.cVector5.Move(-((buCircle) refEntities[0]).Center.X, -((buCircle) refEntities[0]).Center.Y, -((buCircle) refEntities[0]).Center.Z, ref refEntities);
      for (int index = 0; index <= refEntities.Count - 1; ++index)
      {
        if (refEntities[index] is buCircle)
          this.entitiesForDrill.Add(buEntity.Copy(refEntities[index]));
        if (refEntities[index] is buEllipse)
          this.entitiesForDrill.Add(buEntity.Copy(refEntities[index]));
      }
      clsInit.appMarble.activeItemType = MarbleItemType.Drill;
      this.doAddItemDrill(new Point3D(), isFinished);
      this.cmdOperationCommon();
      if (isFinished)
        return;
      clsInit.appMarble.entitiesForMove.Clear();
      if (MarbleTempVars.ItemsDrill.Count <= 0)
        return;
      for (int index1 = 0; index1 <= MarbleTempVars.ItemsDrill.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= MarbleTempVars.ItemsDrill[index1].ItemEntities.DrillEntities.Count - 1; ++index2)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(MarbleTempVars.ItemsDrill[index1].ItemEntities.DrillEntities[index2], ref copiedEntity);
          clsInit.appMarble.entitiesForMove.Add(copiedEntity);
        }
      }
      this.MoveCreatedEntity = true;
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

