        buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
        for (int index = 0; index <= EntityList.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(EntityList[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      if (fileInfo.Extension.ToLower() == ".bucadv5")
      {
        List<Entity> refEntities2 = new List<Entity>();
        clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, true, ref refEntities2);
        for (int index = 0; index <= refEntities2.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntities2[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmColomnsMenu.ColumnsType == MarbleColumnsMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
