      clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
      clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.frmEditor.Init();
      int num2 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
          refEntities1.Add(copiedEntity);
      }
    }
    if (clsMarble.frmLatheMenu.LatheType == MarbleLatheMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileColumns;
      openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileColumns = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (!fileInfo.Exists)
        return;
      if (fileInfo.Extension.ToLower() == ".dxf" | fileInfo.Extension.ToLower() == ".dwg")
      {
        List<Entity> EntityList = new List<Entity>();
        buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
        for (int index = 0; index <= EntityList.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(EntityList[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      if (fileInfo.Extension.ToLower() == ".bucadv5")
      {
        List<Entity> refEntities2 = new List<Entity>();
        clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, true, ref refEntities2);
        for (int index = 0; index <= refEntities2.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntities2[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmLatheMenu.LatheType == MarbleLatheMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileLathe;
      clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmFromFile.ExtensionList.Clear();
      clsItem.FrmFromFile.ExtensionList.Add(".dxf");
      clsItem.FrmFromFile.ExtensionList.Add(".dwg");
      clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num3 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileLathe = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        if (clsItem.FrmFromFile.viewport.Entities[index] is ICurve && clsItem.FrmFromFile.viewport.Entities[index].GetType() != typeof (devDept.Eyeshot.Entities.Point))
        {
          buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
          refEntities1.Add(copiedEntity);
        }
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (refEntities1.Count > 0)
    {
      Point3D MinPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      double dY = 0.0;
      if (isHorizontal)
      {
        F_MarbleLathe fMarbleLathe = new F_MarbleLathe();
        fMarbleLathe.varSettings = new MarbleItemSettings(buMarbleCalc.varOperation);
        fMarbleLathe.Init();
        int num4 = (int) fMarbleLathe.ShowDialog();
        if (fMarbleLathe.Properties.Result != DialogResult.OK)
          return;
        buMarbleCalc.varOperation.settingLatheCut = new marbleLathePars(fMarbleLathe.varSettings.settingLatheCut);
        buMarbleCalc.varOperation.settingProfileCut.RoughDevideLen = buMarbleCalc.activeToolSaw.Geometry.Thickness;
        this.cmdOperationCommon();
        clsInit.cVector5.BoxSizeCalculate(refEntities1, ref MinPoint, ref MaxPoint);
        if (buMarbleCalc.varOperation.settingLatheCut.LatheRadiusTopDistance != 0.0)
          dY = buMarbleCalc.varOperation.settingLatheCut.LatheRadiusTopDistance - MaxPoint.Y;
        clsInit.cVector5.Move(-MinPoint.X, dY, 0.0, ref refEntities1);
        SortbuSettings Settings = new SortbuSettings();
        Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
        List<buEntity> buEntityList = new List<buEntity>();
        clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref refEntities1, Settings, ref this.entitiesForLathe);
        clsInit.appMarble.activeItemType = MarbleItemType.LatheHorizontal;
        if (buMarbleCalc.varMarbleMachineSettings.LatheSettings.LathePosition == LeftRightType.Right)
          this.doAddItemLathe(new Point3D(buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheXOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset), true);
        else
          this.doAddItemLathe(new Point3D(buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheXOffset + (MaxPoint.X - MinPoint.X), buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset), true);
      }
      else
      {
        F_MarbleLatheVertical marbleLatheVertical = new F_MarbleLatheVertical();
        marbleLatheVertical.varSettings = new MarbleItemSettings(buMarbleCalc.varOperation);
        marbleLatheVertical.Init();
        int num5 = (int) marbleLatheVertical.ShowDialog();
        if (marbleLatheVertical.Properties.Result != DialogResult.OK)
          return;
        buMarbleCalc.varOperation.settingLatheVerticalCut = new marbleLatheVerticalPars(marbleLatheVertical.varSettings.settingLatheVerticalCut);
        clsInit.cVector5.BoxSizeCalculate(refEntities1, ref MinPoint, ref MidPoint, ref MaxPoint);
        double dX = 0.0;
        if (buMarbleCalc.varOperation.settingLatheVerticalCut.LatheRadiusTopDistance != 0.0)
          dX = buMarbleCalc.varOperation.settingLatheVerticalCut.LatheRadiusTopDistance - MaxPoint.X;
        clsInit.cVector5.Move(dX, -MinPoint.Y, 0.0, ref refEntities1);
        SortbuSettings Settings = new SortbuSettings();
        Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
        List<buEntity> buEntityList = new List<buEntity>();
        clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref refEntities1, Settings, ref this.entitiesForLathe);
        clsInit.appMarble.activeItemType = MarbleItemType.LatheVertical;
        this.doAddItemLatheVertical(new Point3D());
        this.cmdOperationCommon();
        clsInit.appMarble.entitiesForMove.Clear();
        if (MarbleTempVars.ItemsLathe.Count <= 0)
          return;
        for (int index1 = 0; index1 <= MarbleTempVars.ItemsLathe.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= MarbleTempVars.ItemsLathe[index1].ItemEntities.SolidEntity.Count - 1; ++index2)
          {
            Entity copiedEntity = (Entity) null;
            buEntity.Copy(MarbleTempVars.ItemsLathe[index1].ItemEntities.SolidEntity[index2], ref copiedEntity);
            clsInit.appMarble.entitiesForMove.Add(copiedEntity);
            if (copiedEntity.BoxMin == (Point3D) null)
              copiedEntity.Regen(buMarbleCalc.varMarbleDrawSettings.SolidOnlineDrawDeviation);
            Entity rectangleEntity = (Entity) null;
            clsInit.cVector5.DrawRectangle(copiedEntity.BoxMin, copiedEntity.BoxMax.X - copiedEntity.BoxMin.X, copiedEntity.BoxMax.Y - copiedEntity.BoxMin.Y, Plane.XY, ref rectangleEntity);
            rectangleEntity.Translate(0.0, 0.0, buMarbleCalc.varMarbleDrawSettings.WireframeOnlineDrawZOffset);
            clsInit.appMarble.entitiesForMove.Add(rectangleEntity);
          }
        }
        this.MoveCreatedEntity = true;
      }
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

