    clsMarble.frmSawMillingMenu.Init();
    int num1 = (int) clsMarble.frmSawMillingMenu.ShowDialog();
    if (clsMarble.frmSawMillingMenu.PropertiesForm.Result != DialogResult.OK)
      return;
    clsMarble.frmSawMillingMenu.MenuType.selectedMeshType = CamTriangularMeshType.ConstantZ;
