      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num2 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileEngraving = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
        copiedEntity.Color = Color.WhiteSmoke;
        copiedEntity.ColorMethod = colorMethodType.byEntity;
        refEntities.Add(copiedEntity);
      }
    }
    if (refEntities.Count > 0)
    {
      MarbleTempVars.ImportedEntitites.Clear();
      clsInit.appMarble.entitiesForMove.Clear();
      Point3D MidPoint = new Point3D();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
      if (buMarbleForms.frmShape3DBaseAndXYZ == null)
        buMarbleForms.frmShape3DBaseAndXYZ = new F_MarbleEditBaseHAndXYZ();
      double num3 = MaxPoint.X - MinPoint.X;
      double num4 = MaxPoint.Y - MinPoint.Y;
      double num5 = MaxPoint.Z - MinPoint.Z;
      buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleWidth = MaxPoint.X - MinPoint.X;
      buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint.Y;
      buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleDepth = MaxPoint.Z - MinPoint.Z;
      buMarbleForms.frmShape3DBaseAndXYZ.varRuntime.ScaleKeepRatio = buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio;
      buMarbleForms.frmShape3DBaseAndXYZ.Init();
      int num6 = (int) buMarbleForms.frmShape3DBaseAndXYZ.ShowDialog();
      if (buMarbleForms.frmShape3DBaseAndXYZ.Properties.Result != DialogResult.OK)
        return;
      clsInit.appMarble.activeItemType = MarbleItemType.Shape3D;
      buMarbleCalc.varMarbleRunSettings.ScaleWidth = buMarbleForms.frmShape3DBaseAndXYZ.spn_scalewidth.Value;
      buMarbleCalc.varMarbleRunSettings.ScaleHeight = buMarbleForms.frmShape3DBaseAndXYZ.spn_scaleheight.Value;
      buMarbleCalc.varMarbleRunSettings.ScaleDepth = buMarbleForms.frmShape3DBaseAndXYZ.spn_scaledepth.Value;
      buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio = buMarbleForms.frmShape3DBaseAndXYZ.chk_keepratio.Check;
      if (!buCompare5.EQ(num3, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num4, buMarbleCalc.varMarbleRunSettings.ScaleHeight) | !buCompare5.EQ(num5, buMarbleCalc.varMarbleRunSettings.ScaleDepth))
      {
        if (buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
        {
          double scaleX = 1.0;
          double scaleY = 1.0;
          double num7 = 1.0;
          if (!buCompare5.EQ(num3, buMarbleCalc.varMarbleRunSettings.ScaleWidth))
          {
            scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3);
            scaleY = scaleX;
            num7 = scaleX;
          }
          else if (!buCompare5.EQ(num4, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
          {
            scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num4);
            scaleX = scaleY;
            num7 = scaleY;
          }
          else if (!buCompare5.EQ(num5, buMarbleCalc.varMarbleRunSettings.ScaleDepth))
          {
            double num8 = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleDepth / num5);
            scaleX = num8;
            scaleY = num8;
          }
          clsInit.cVector5.Scale(MinPoint, scaleX, scaleY, 1.0, ref refEntities);
        }
        else
        {
          double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3);
          double scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num4);
          double scaleZ = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleDepth / num5);
          if (scaleX <= 0.0)
            scaleX = 1.0;
          if (scaleY <= 0.0)
            scaleY = 1.0;
          if (scaleZ <= 0.0)
            scaleZ = 1.0;
          clsInit.cVector5.Scale(MinPoint, scaleX, scaleY, scaleZ, ref refEntities);
        }
      }
      MinPoint = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
      MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
      clsInit.cVector5.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref refEntities);
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint.X, MaxPoint.Y - MinPoint.Y);
      clsInit.appMarble.entitiesForMove.Add((Entity) rectangle);
      this.cmdOperationCommon();
      MarbleTempVars.isSolidMove = false;
      for (int index = 0; index <= refEntities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(refEntities[index], ref copiedEntity);
        MarbleTempVars.ImportedEntitites.Add(copiedEntity);
      }
      this.MoveCreatedEntity = true;
      refEntities.Clear();
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

