    buMarbleCalc.varMarbleRunSettings.selectedType = new marbleMenuType(clsMarble.frmSawMillingMenu.MenuType);
    buMarbleCalc.varMarbleRunSettings.selectedSawMilling = new marbleMenuType(clsMarble.frmSawMillingMenu.MenuType);
    if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling).Exists)
    {
      buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = AppPath.Base + "\\External3DFiles";
      if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling).Exists)
        buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = AppPath.Base;
    }
    buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = buMarbleCalc.varMarbleRunSettings.selectedSawMilling.selectedTool;
    clsInit.appMarble.entitiesForMove.Clear();
    List<Entity> refEntities = new List<Entity>();
    if (clsMarble.frmSawMillingMenu.EngraveType == MarbleEngraveMenuType.Editor)
      ;
    if (clsMarble.frmSawMillingMenu.EngraveType == MarbleEngraveMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling;
      openFileDialog.Filter = "3D Files (.stl  .step  .igs)|*.stl;*.step;*.stp;*.iges;*.igs";
      openFileDialog.FilterIndex = 1;
      openFileDialog.Multiselect = false;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (fileInfo.Exists)
      {
        if (fileInfo.Extension.ToLower() == ".stl")
          buFile5.OpenStl(ref refEntities, fileInfo.FullName);
        if (fileInfo.Extension.ToLower() == ".stp" | fileInfo.Extension.ToLower() == ".step")
          buFile5.OpenStep(ref refEntities, fileInfo.FullName);
        if (fileInfo.Extension.ToLower() == ".igs" | fileInfo.Extension.ToLower() == ".iges")
          buFile5.OpenIges(ref refEntities, fileInfo.FullName);
      }
      clsInit.appMarble.activeItemType = MarbleItemType.SawHorizontalMillingRough;
      clsInit.appMarble.entitiesForMove.Clear();
    }
    if (clsMarble.frmSawMillingMenu.EngraveType == MarbleEngraveMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling;
      clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmFromFile.ExtensionList.Clear();
      clsItem.FrmFromFile.ExtensionList.Add(".stl");
      clsItem.FrmFromFile.ExtensionList.Add(".igs");
      clsItem.FrmFromFile.ExtensionList.Add(".iges");
      clsItem.FrmFromFile.ExtensionList.Add(".step");
      clsItem.FrmFromFile.ExtensionList.Add(".stp");
      clsItem.FrmFromFile.ExtensionList.Add(".obj");
      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num2 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromFileSawMilling = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
        copiedEntity.Color = Color.WhiteSmoke;
        copiedEntity.ColorMethod = colorMethodType.byEntity;
        refEntities.Add(copiedEntity);
      }
      clsInit.appMarble.activeItemType = MarbleItemType.SawHorizontalMillingRough;
      clsInit.appMarble.entitiesForMove.Clear();
    }
    if (refEntities.Count > 0)
    {
      Point3D MinPoint1 = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint1, ref MaxPoint);
      double num3 = MaxPoint.X - MinPoint1.X;
      double num4 = MaxPoint.Y - MinPoint1.Y;
      clsMarble.frmEditBaseHAndXY.varRuntime = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
      clsMarble.frmEditBaseHAndXY.varRuntime.ScaleWidth = MaxPoint.X - MinPoint1.X;
      clsMarble.frmEditBaseHAndXY.varRuntime.ScaleHeight = MaxPoint.Y - MinPoint1.Y;
      clsMarble.frmEditBaseHAndXY.Properties.FormCloseMode = FormCloseModeType.Invisible;
      clsMarble.frmEditBaseHAndXY.Properties.FormPosition = FormStartPosition.CenterScreen;
      clsMarble.frmEditBaseHAndXY.Init();
      int num5 = (int) clsMarble.frmEditBaseHAndXY.ShowDialog();
      if (clsMarble.frmEditBaseHAndXY.Properties.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(clsMarble.frmEditBaseHAndXY.varRuntime);
      if (!buCompare5.EQ(num3, buMarbleCalc.varMarbleRunSettings.ScaleWidth) | !buCompare5.EQ(num4, buMarbleCalc.varMarbleRunSettings.ScaleHeight))
      {
        if (buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
        {
          double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3);
          double scaleY = scaleX;
          clsInit.cVector5.Scale(MinPoint1, scaleX, scaleY, 1.0, ref refEntities);
        }
        else
        {
          double scaleX = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3);
          double scaleY = Math.Abs(buMarbleCalc.varMarbleRunSettings.ScaleHeight / num4);
          clsInit.cVector5.Scale(MinPoint1, scaleX, scaleY, 1.0, ref refEntities);
        }
      }
      Point3D MinPoint2 = new Point3D(double.MaxValue, double.MaxValue, double.MaxValue);
      MaxPoint = new Point3D(double.MinValue, double.MinValue, double.MinValue);
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint2, ref MaxPoint);
      clsInit.cVector5.Move(-MinPoint2.X, -MinPoint2.Y, -MinPoint2.Z, ref refEntities);
      CompositeCurve rectangle = CompositeCurve.CreateRectangle(MaxPoint.X - MinPoint2.X, MaxPoint.Y - MinPoint2.Y);
      refEntities.Add((Entity) rectangle);
      this.cmdOperationCommon();
      MarbleTempVars.isSolidMove = false;
      for (int index = 0; index <= refEntities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(refEntities[index], ref copiedEntity);
        clsInit.appMarble.entitiesForMove.Add(copiedEntity);
      }
      this.MoveCreatedEntity = true;
    }
    else
      buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
  }

  public void cmdCutRemainMaterial()
  {
    if (buMarbleForms.frmCutRemainMaterial == null)
      buMarbleForms.frmCutRemainMaterial = new F_MarbleCutRemailMaterial();
    buMarbleForms.frmCutRemainMaterial.Settings = new marbleCutRemainMaterial(buMarbleCalc.varOperation.settingCutRemailMaterial);
    buMarbleForms.frmCutRemainMaterial.SettingsMaterial = new marbleMaterialPars(buMarbleCalc.varOperation.MaterialParameter);
    buMarbleForms.frmCutRemainMaterial.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    buMarbleForms.frmCutRemainMaterial.Init();
    int num1 = (int) buMarbleForms.frmCutRemainMaterial.ShowDialog();
    if (buMarbleForms.frmCutRemainMaterial.PropertiesForm.Result == DialogResult.OK)
    {
      buMarbleCalc.varOperation.settingCutRemailMaterial = new marbleCutRemainMaterial(buMarbleForms.frmCutRemainMaterial.Settings);
      buMarbleCalc.varOperation.MaterialParameter = new marbleMaterialPars(buMarbleForms.frmCutRemainMaterial.SettingsMaterial);
      this.SaveMarbleFile();
      double x = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
      double y = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
      bool flag1 = buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalCutEnable;
      bool flag2 = buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalCutEnable;
      if (this.activeJob.Items.Count > 0)
      {
        clsInit.cMarble.GetBoxSizeJobItems(this.activeJob, ref this.activeJob.SizeOfOperations.MinPoint, ref this.activeJob.SizeOfOperations.MaxPoint);
        x = this.activeJob.SizeOfOperations.MaxPoint.X + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset;
        y = this.activeJob.SizeOfOperations.MaxPoint.Y + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset;
      }
      if (buMarbleCalc.varOperation.settingCutRemailMaterial.UseMaterialData)
      {
        double num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialWidth - this.activeJob.SizeOfOperations.MaxPoint.X;
        double num3 = buMarbleCalc.varOperation.MaterialParameter.MaterialHeight - this.activeJob.SizeOfOperations.MaxPoint.Y;
        if (num2 < buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialHorizontalMinDistance)
          flag2 = false;
        if (num3 < buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialVerticalMinDistance)
          flag1 = false;
        if (!flag1)
          y = buMarbleCalc.varOperation.MaterialParameter.MaterialHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
        if (!flag2)
          x = buMarbleCalc.varOperation.MaterialParameter.MaterialWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
      }
      else
      {
        if (!buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalCutEnable)
          y = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutHeight + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset * 2.0;
        if (!buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalCutEnable)
          x = buMarbleCalc.varOperation.settingCutRemailMaterial.MaterialCutWidth + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset * 2.0;
      }
      if (flag1)
      {
        buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = x + buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset + 10.0;
        this.doAddItemSingleCut(new Point3D(-buMarbleCalc.varOperation.settingCutRemailMaterial.HorizontalOffset, y, 0.0), 0.0, 0.0, true, 0);
      }
      if (!flag2)
        return;
      buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = y + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset + 10.0;
      this.doAddItemSingleCut(new Point3D(x, y + buMarbleCalc.varOperation.settingCutRemailMaterial.VerticalOffset + 0.0, 0.0), 0.0, -90.0, true, 0);
    }
    else
      clsInit.appCommand.Reset();
  }

