  public void cmdAddCam()
  {
    if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.Item || !(buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexItem <= this.activeJob.Items.Count - 1))
      return;
    MarbleItem marbleItem = this.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
    if (marbleItem.ItemType == MarbleItemType.Shape3D)
    {
      if (buMarbleForms.frmCam3DCommands == null)
        buMarbleForms.frmCam3DCommands = new F_MarbleCam3D();
      buMarbleForms.frmCam3DCommands.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmCam3DCommands.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmCam3DCommands.Init();
      int num1 = (int) buMarbleForms.frmCam3DCommands.ShowDialog();
      if (buMarbleForms.frmCam3DCommands.CommandType == MarbleCamType.None)
        return;
