  public void cmdPointerSave()
  {
    SaveFileDialog saveFileDialog = new SaveFileDialog();
    saveFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathItems;
    saveFileDialog.Filter = "Dxf Files (.dxf)|*.dxf|Dwg Files (.dwg)|*.dwg|Stl Files (.stl)|*.stl";
    saveFileDialog.FilterIndex = 1;
    if (saveFileDialog.ShowDialog() != DialogResult.OK)
      return;
    string fileExtension = buFile5.getFileExtension(saveFileDialog.FileName);
    if (fileExtension.ToLower() == ".dxf" | fileExtension.ToLower() == ".dwg")
    {
      List<Entity> EntityList = new List<Entity>();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is ICurve)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ref copiedEntity);
          EntityList.Add(copiedEntity);
        }
      }
      buFile5.SaveDxfDwg(EntityList, saveFileDialog.FileName);
    }
    else
    {
      if (!(fileExtension.ToLower() == ".stl"))
        return;
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
        if (entity is Mesh | entity is Brep | entity is devDept.Eyeshot.Entities.Surface && (entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0)
        {
          CustomData entityData = entity.EntityData as CustomData;
          if (entityData.Command != null && entityData.typeDefination == entityTypeDefination.MarbleItem & entityData.Tags == "Solid")
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
        }
      }
      buFile5.SaveStl((Design) ccVars.Pages[ccVars.PageIndex].Form.viewportcad, saveFileDialog.FileName, 0.1, true);
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    }
  }

