  public void cmdCreateMaterial()
  {
    clsMarble.frmSheet.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsMarble.frmSheet.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
    clsMarble.frmSheet.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting;
    clsMarble.frmSheet.chk_editimage.Check = buMarbleCalc.varMarbleRunSettings.selectedSheetEdit;
    clsMarble.frmSheet.Init();
    int num1 = (int) clsMarble.frmSheet.ShowDialog();
    if (clsMarble.frmSheet.PropertiesForm.Result != DialogResult.OK)
      return;
    buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting = clsMarble.frmSheet.chk_addtonesting.Check;
    buMarbleCalc.varMarbleRunSettings.selectedSheetEdit = clsMarble.frmSheet.chk_editimage.Check;
    if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromSheet).Exists)
    {
      buMarbleCalc.varMarbleRunSettings.pathFromSheet = AppPath.Base + "\\External2DFiles\\Contour";
      if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromSheet).Exists)
        buMarbleCalc.varMarbleRunSettings.pathFromSheet = AppPath.Base;
    }
    List<buEntity> AllEntities = new List<buEntity>();
    if (clsMarble.frmSheet.SheetType == MarbleSheetMenuType.Editor)
    {
      if (clsItem.frmEditor == null)
        clsItem.frmEditor = new F_Editor();
      clsVar.varEditorRuntimeSet.isSketchMode = false;
      clsVar.varEditorRuntimeSet.isSewingMode = false;
      clsItem.frmEditor = new F_Editor();
      clsItem.frmEditor.OpenFileExtension.Clear();
      clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
      clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.frmEditor.ZoomOutValue = 2500;
      clsItem.frmEditor.Init();
      int num2 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
          AllEntities.Add(copiedEntity);
      }
    }
    if (clsMarble.frmSheet.SheetType == MarbleSheetMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromSheet;
      openFileDialog.Filter = "All Drawing Files (*.Dxf,*.Dwg,*.bucadV5)|*.dxf;*.dwg;*.bucadV5;|Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|BuCad Files (*.bucadV5)|*.bucadV5";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromSheet = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (!fileInfo.Exists)
        return;
      if (fileInfo.Extension.ToLower() == ".dxf" | fileInfo.Extension.ToLower() == ".dwg")
      {
        List<Entity> EntityList = new List<Entity>();
        buFile5.OpenDxfDwg(ref EntityList, fileInfo.FullName);
        for (int index = 0; index <= EntityList.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(EntityList[index], ref copiedEntity);
          AllEntities.Add(copiedEntity);
        }
      }
      if (fileInfo.Extension.ToLower() == ".bucadv5")
      {
        List<Entity> refEntities = new List<Entity>();
        clsInit.appFiles.OpenBuCadFileVer5(fileInfo.FullName, true, ref refEntities);
        for (int index = 0; index <= refEntities.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntities[index], ref copiedEntity);
          AllEntities.Add(copiedEntity);
        }
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmSheet.SheetType == MarbleSheetMenuType.FromList)
    {
      if (clsItem.FrmFromFile == null)
        clsItem.FrmFromFile = new F_AddFromFile();
      clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromSheet;
      clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmFromFile.ExtensionList.Clear();
      clsItem.FrmFromFile.ExtensionList.Add(".dxf");
      clsItem.FrmFromFile.ExtensionList.Add(".dwg");
      clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
      clsItem.FrmFromFile.MoveEntities = false;
      clsItem.FrmFromFile.Init();
      int num3 = (int) clsItem.FrmFromFile.ShowDialog();
      if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleRunSettings.pathFromSheet = clsItem.FrmFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
      for (int index = 0; index <= clsItem.FrmFromFile.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[index], ref copiedEntity);
        AllEntities.Add(copiedEntity);
      }
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmSheet.SheetType == MarbleSheetMenuType.Data)
    {
      F_MaterialRect3D fMaterialRect3D = new F_MaterialRect3D();
      CreateModelProperties Properties = new CreateModelProperties();
      clsInit.appCommand.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
      Properties.CoordinateSystemIconVisible = false;
      Properties.ViewCubeIconVisible = false;
      Properties.OrigineCaptionVisible = false;
      Properties.ToolBorVisible = false;
      Properties.OrigineSize = 5;
      fMaterialRect3D.viewportLayout = clsInit.cVector5.CreateModelControl(clsVar.UnlockKey, Properties);
      fMaterialRect3D.viewportLayout.CompileUserInterfaceElements();
      fMaterialRect3D.pnl_model.Controls.Add((System.Windows.Forms.Control) fMaterialRect3D.viewportLayout);
      fMaterialRect3D.viewportLayout.Entities.Clear();
      fMaterialRect3D.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      fMaterialRect3D.Material = new MaterialBase5(buMarbleCalc.varOperation.MaterialParameter.MaterialWidth, buMarbleCalc.varOperation.MaterialParameter.MaterialHeight, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness);
      fMaterialRect3D.Init((MaterialBase5) null);
      fMaterialRect3D.StartPosition = FormStartPosition.CenterParent;
      int num4 = (int) fMaterialRect3D.ShowDialog();
      if (fMaterialRect3D.PropertiesForm.Result == DialogResult.OK)
      {
        buMarbleCalc.varOperation.MaterialParameter.MaterialWidth = fMaterialRect3D.Material.Size.Width;
        buMarbleCalc.varOperation.MaterialParameter.MaterialHeight = fMaterialRect3D.Material.Size.Height;
        buMarbleCalc.varOperation.MaterialParameter.MaterialThickness = fMaterialRect3D.Material.Size.Depth;
        buEntity rectangleEntity = (buEntity) null;
        clsInit.cVector5.DrawRectangle(new Point3D(), buMarbleCalc.varOperation.MaterialParameter.MaterialWidth, buMarbleCalc.varOperation.MaterialParameter.MaterialHeight, Plane.XY, ref rectangleEntity);
        AllEntities.Add(rectangleEntity);
      }
    }
    if (AllEntities.Count <= 0)
      return;
    if (buMarbleCalc.varMarbleRunSettings.selectedSheetEdit)
    {
      if (clsItem.frmEditor == null)
        clsItem.frmEditor = new F_Editor();
      clsVar.varEditorRuntimeSet.isSketchMode = false;
      clsVar.varEditorRuntimeSet.isSewingMode = false;
      clsItem.frmEditor = new F_Editor();
      clsItem.frmEditor.OpenFileExtension.Clear();
      clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
      clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.frmEditor.entitiesExisting.Clear();
      for (int index = 0; index <= AllEntities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(AllEntities[index], ref copiedEntity);
        if (copiedEntity != null)
          clsItem.frmEditor.entitiesExisting.Add(copiedEntity);
      }
      clsItem.frmEditor.Init();
      int num5 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      AllEntities = new List<buEntity>();
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
          AllEntities.Add(copiedEntity);
      }
    }
    List<buEntitiesGroup> Groups = new List<buEntitiesGroup>();
    clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), AllEntities, Plane.XY, ref Groups);
    if (Groups.Count <= 0)
      return;
    if (buMarbleCalc.varMarbleRunSettings.selectedSheetAddNesting)
    {
      if (clsInit.appNesting == null)
        return;
      for (int index = 0; index <= Groups.Count - 1; ++index)
        clsInit.appNesting.doAddShapeSheet(Groups[index]);
    }
    else
    {
      this.activeJob.SheetGroup = new buEntitiesGroup(Groups[0]);
      Entity entMarble1 = (Entity) null;
      Entity entMarble2 = (Entity) null;
      Point3D Offset = new Point3D();
      this.activeJob.SheetSolidEntities = new List<Entity>();
      this.CreateMarbleMaterial(this.activeJob.SheetGroup, Math.Abs(buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset), Offset, true, MarbleTempVars.layerMarbleSheet.Name, ref entMarble1);
      this.CreateMarbleMaterial(this.activeJob.SheetGroup, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, Offset, false, MarbleTempVars.layerMarbleSheet.Name, ref entMarble2);
      if (entMarble1 != null & entMarble2 != null)
      {
        entMarble2.ColorMethod = colorMethodType.byEntity;
        entMarble2.Color = Color.FromArgb(150, MarbleTempVars.layerMarbleSheet.Color);
        entMarble2.Selectable = false;
        entMarble1.Translate(0.01, 0.01);
        entMarble1.Selectable = false;
        this.activeJob.SheetSolidEntities.Add(entMarble1);
        this.activeJob.SheetSolidEntities.Add(entMarble2);
        clsInit.cVector5.BoxSizeCalculate(this.activeJob.SheetGroup, ref this.activeJob.Material.BoxMinPoint, ref this.activeJob.Material.BoxMaxPoint);
        this.activeJob.Material.BoxMinPoint.Z = 0.0;
        this.activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
        this.activeJob.Material.Size.Width = this.activeJob.Material.BoxMaxPoint.X - this.activeJob.Material.BoxMinPoint.X;
        this.activeJob.Material.Size.Height = this.activeJob.Material.BoxMaxPoint.Y - this.activeJob.Material.BoxMinPoint.Y;
        this.activeJob.Material.Size.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
        this.AddOrUpdateMarbleSheet(this.activeJob.SheetSolidEntities, this.activeJob.SheetGroup);
        this.JobUpdate();
      }
      buEyeItems.viewportCadCam.Invalidate();
    }
  }

  public void cmdCreateMaterialFromPhoto()
  {
    string name = "";
    double num1 = 0.0;
    double num2 = 0.0;
    clsMarble.frmImageMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    clsMarble.frmImageMenu.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
    clsMarble.frmImageMenu.chk_addtonesting.Check = buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting;
    clsMarble.frmImageMenu.chk_editimage.Check = buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit;
    clsMarble.frmImageMenu.Init();
    int num3 = (int) clsMarble.frmImageMenu.ShowDialog();
    if (clsMarble.frmImageMenu.PropertiesForm.Result != DialogResult.OK)
      return;
    buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting = clsMarble.frmImageMenu.chk_addtonesting.Check;
    buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit = clsMarble.frmImageMenu.chk_editimage.Check;
    if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromPhoto).Exists)
    {
      buMarbleCalc.varMarbleRunSettings.pathFromPhoto = AppPath.Base + "\\Materials\\Marble";
      if (!new DirectoryInfo(buMarbleCalc.varMarbleRunSettings.pathFromPhoto).Exists)
        buMarbleCalc.varMarbleRunSettings.pathFromPhoto = AppPath.Base;
    }
    if (clsMarble.frmImageMenu.PhotoType == MarblePhotoMenuType.FromFile)
    {
      OpenFileDialog openFileDialog = new OpenFileDialog();
      openFileDialog.InitialDirectory = buMarbleCalc.varMarbleRunSettings.pathFromPhoto;
      openFileDialog.Filter = "All Image Files Files (*.Png,*.Jpg,*.Jpeg,*.Bmp)|*.png;*.jpg;*.jpeg;*.bmp|PNG Files (*.png)|*.png|JpegFiles (*.jpeg,*.jpg)|*.jpg;*.jpeg|BMP Files (*.bmp)|*.bmp";
      openFileDialog.FilterIndex = 1;
      if (openFileDialog.ShowDialog() != DialogResult.OK)
        return;
      name = buFile5.getFileNameWithoutExtension(openFileDialog.FileName);
      buMarbleCalc.varMarbleRunSettings.pathFromPhoto = buFile5.GetPath(openFileDialog.FileName);
      FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
      if (!fileInfo.Exists)
        return;
      this.activeJob.Material.matImage = Image.FromFile(fileInfo.FullName);
      num1 = (double) this.activeJob.Material.matImage.Width * buMarbleCalc.varImageSettings.PixelToMmX;
      num2 = (double) this.activeJob.Material.matImage.Height * buMarbleCalc.varImageSettings.PixelToMmY;
      buEntity rectangleEntity = (buEntity) null;
      clsInit.cVector5.DrawRectangle(new Point3D(), num1, num2, Plane.XY, ref rectangleEntity);
      this.activeJob.SheetGroup = new buEntitiesGroup();
      this.activeJob.SheetGroup.Outside.Entities.Add(rectangleEntity);
      clsInit.appEditor.SaveEditorFile();
    }
    if (clsMarble.frmImageMenu.PhotoType == MarblePhotoMenuType.FromList)
    {
      if (clsItem.FrmImageFromFile == null)
        clsItem.FrmImageFromFile = new F_AddImageFromFile();
      clsItem.FrmImageFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.FrmImageFromFile.StartPosition = FormStartPosition.CenterParent;
      clsItem.FrmImageFromFile.Path = buMarbleCalc.varMarbleRunSettings.pathFromPhoto;
      clsItem.FrmImageFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
      clsItem.FrmImageFromFile.ExtensionList.Clear();
      clsItem.FrmImageFromFile.ExtensionList.Add(".png");
      clsItem.FrmImageFromFile.ExtensionList.Add(".jpg");
      clsItem.FrmImageFromFile.ExtensionList.Add(".jpeg");
      clsItem.FrmImageFromFile.ExtensionList.Add(".bmp");
      clsItem.FrmImageFromFile.MoveEntities = false;
      clsItem.FrmImageFromFile.Init();
      int num4 = (int) clsItem.FrmImageFromFile.ShowDialog();
      if (clsItem.FrmImageFromFile.PropertiesForm.Result != DialogResult.OK)
        return;
      name = buFile5.getFileNameWithoutExtension(clsItem.FrmImageFromFile.FileName);
      this.activeJob.Material.matImage = clsItem.FrmImageFromFile.refImage;
      num1 = (double) this.activeJob.Material.matImage.Width * buMarbleCalc.varImageSettings.PixelToMmX;
      num2 = (double) this.activeJob.Material.matImage.Height * buMarbleCalc.varImageSettings.PixelToMmY;
      buEntity rectangleEntity = (buEntity) null;
      clsInit.cVector5.DrawRectangle(new Point3D(), num1, num2, Plane.XY, ref rectangleEntity);
      this.activeJob.SheetGroup = new buEntitiesGroup();
      this.activeJob.SheetGroup.Outside.Entities.Add(rectangleEntity);
      buMarbleCalc.varMarbleRunSettings.pathFromPhoto = clsItem.FrmImageFromFile.Path;
      clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmImageFromFile.KeepRatio;
      clsInit.appEditor.SaveEditorFile();
    }
    if (!(this.activeJob.Material.matImage != null & this.activeJob.SheetGroup != null))
      return;
    if (buMarbleCalc.varMarbleRunSettings.selectedPhotoEdit)
    {
      if (clsItem.frmEditor == null)
        clsItem.frmEditor = new F_Editor();
      clsVar.varEditorRuntimeSet.isSketchMode = false;
      clsVar.varEditorRuntimeSet.isSewingMode = false;
      clsItem.frmEditor = new F_Editor();
      clsItem.frmEditor.OpenFileExtension.Clear();
      clsItem.frmEditor.OpenFileExtension.Add("Autocad Files (*.dxf)|*.dxf");
      clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      clsItem.frmEditor.refImage = (Image) this.activeJob.Material.matImage.Clone();
      clsItem.frmEditor.refImageSize = new SizeObject(num1, num2, 0.0);
      clsItem.frmEditor.ZoomOutValue = 2500;
      clsItem.frmEditor.Init();
      int num5 = (int) clsItem.frmEditor.ShowDialog((IWin32Window) clsItem.FrmMain);
      List<buEntity> BaseRefEntities = new List<buEntity>();
      for (int index = 0; index <= clsItem.frmEditor.viewport.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(clsItem.frmEditor.viewport.Entities[index], ref copiedEntity);
        if (copiedEntity != null & clsItem.frmEditor.viewport.Entities[index] is ICurve)
          BaseRefEntities.Add(copiedEntity);
      }
      if (BaseRefEntities.Count > 0)
      {
        SortbuSettings Settings = new SortbuSettings();
        SortbuResult Result = new SortbuResult();
        Settings.Option.IntersectionRules = SortingIntersectionRulesType.LowerIndex;
        Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
        List<buEntity> SortedEntities = new List<buEntity>();
        List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
        clsInit.cVector5.SortEntitiesByRefPoint(BaseRefEntities[0].StartPoint, ref BaseRefEntities, Settings, ref SortedEntities, ref Result);
        clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
        for (int index = 0; index <= SplitedEntitites.Count - 1; ++index)
        {
          if (clsInit.cVector5.isEntitiesClosed(SplitedEntitites[index]))
          {
            if (this.activeJob.SheetGroup.Inside == null)
              this.activeJob.SheetGroup.Inside = new List<buEntityList>();
            buEntityList buEntityList = new buEntityList();
            buEntity.Copy(SplitedEntitites[index], ref buEntityList.Entities);
            this.activeJob.SheetGroup.Inside.Add(buEntityList);
          }
        }
      }
    }
    if (buMarbleCalc.varMarbleRunSettings.selectedPhotoAddNesting)
    {
      if (clsInit.appNesting == null)
        return;
      clsInit.appNesting.doAddShapeSheet(this.activeJob.SheetGroup);
    }
    else
    {
      Entity entMarble1 = (Entity) null;
      Entity entMarble2 = (Entity) null;
      Point3D Offset = new Point3D();
      this.activeJob.SheetSolidEntities = new List<Entity>();
      this.CreateMarbleMaterial(this.activeJob.SheetGroup, Math.Abs(buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset), Offset, true, MarbleTempVars.layerMarbleSheet.Name, ref entMarble1);
      this.CreateMarbleMaterial(this.activeJob.SheetGroup, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, Offset, false, MarbleTempVars.layerMarbleSheet.Name, ref entMarble2);
      if (entMarble1 != null & entMarble2 != null)
      {
        entMarble2.ColorMethod = colorMethodType.byEntity;
        entMarble2.Color = Color.FromArgb(50, MarbleTempVars.layerMarbleSheet.Color);
        entMarble2.Selectable = false;
        entMarble1.Translate(0.01, -0.11);
        entMarble1.Selectable = false;
        entMarble2.Selectable = false;
        this.activeJob.SheetSolidEntities.Add(entMarble1);
        this.activeJob.SheetSolidEntities.Add(entMarble2);
        int index1 = -1;
        for (int index2 = 0; index2 <= buEyeItems.viewportCadCam.Materials.Count - 1; ++index2)
        {
          if (name == buEyeItems.viewportCadCam.Materials[index2].Name)
            index1 = index2;
        }
        if (index1 >= 0)
          buEyeItems.viewportCadCam.Materials.RemoveAt(index1);
        Bitmap image = new Bitmap(this.activeJob.Material.matImage);
        Material material = new Material(name, Color.FromArgb(100, 100, 100), Color.White, 1f, image.ToByteArray())
        {
          LinearUnits = linearUnitsType.Millimeters,
          MassUnits = massUnitsType.Kilograms,
          Density = 6E-07,
          TextureLength = 2000f,
          Environment = 0.01f
        };
        buEyeItems.viewportCadCam.Materials.Add(material);
        buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerMarbleSheet.Name].MaterialName = material.Name;
        clsInit.cVector5.BoxSizeCalculate(this.activeJob.SheetGroup, ref this.activeJob.Material.BoxMinPoint, ref this.activeJob.Material.BoxMaxPoint);
        this.activeJob.Material.BoxMinPoint.Z = 0.0;
        this.activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
        this.activeJob.Material.Size.Width = this.activeJob.Material.BoxMaxPoint.X - this.activeJob.Material.BoxMinPoint.X;
        this.activeJob.Material.Size.Height = this.activeJob.Material.BoxMaxPoint.Y - this.activeJob.Material.BoxMinPoint.Y;
        this.activeJob.Material.Size.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
        this.AddOrUpdateMarbleSheet(this.activeJob.SheetSolidEntities, this.activeJob.SheetGroup);
        this.JobUpdate();
      }
      buEyeItems.viewportCadCam.Invalidate();
    }
  }

  public void cmdMenuPageCommandExecute(
    object Data1,
    object Data2,
    object Data3,
    object Data4,
    object Data5)
  {
    if (Data1 == null)
      return;
