  public void cmdShowLanguage()
  {
    if (buMarbleForms.frmLangMenu == null)
      buMarbleForms.frmLangMenu = new F_MarbleLanguageMenu();
    buMarbleForms.frmLangMenu.Language = clsVar.varRuntime.Language;
    buMarbleForms.frmLangMenu.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
    buMarbleForms.frmLangMenu.Init();
    buMarbleForms.frmLangMenu.StartPosition = FormStartPosition.CenterParent;
    int num = (int) buMarbleForms.frmLangMenu.ShowDialog((IWin32Window) clsItem.FrmMain);
    if (buMarbleForms.frmLangMenu.PropertiesForm.Result != DialogResult.OK)
      return;
    clsVar.varRuntime.Language = buMarbleForms.frmLangMenu.Language;
    clsInit.appSystem.SetLanguage(clsVar.varRuntime.Language, AppPath.Settings + "\\Runtime.prm", false);
    if (clsVar.varRuntime.Language == 0)
      buLangTranslate.ChangeLanguage("English");
    else if (clsVar.varRuntime.Language == 1)
      buLangTranslate.ChangeLanguage("Turkish");
    else if (clsVar.varRuntime.Language == 2)
      buLangTranslate.ChangeLanguage("Chinese");
    this.LoadLanguage();
  }

  public void cmdSetAngle()
  {
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      if (entity.EntityData != null & entity.EntityData is CustomData && ((CustomData) entity.EntityData).Tags == "Edge")
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selectable = true;
    }
    MarbleTempVars.SetAngle = true;
  }

  public void cmdShowGcode()
  {
    if (this.activeJob == null)
      return;
    string strGCodes = "";
    if (!this.activeJob.CamCalculated)
      this.doCamCalculateMarbleJob(ref this.activeJob);
    if (!this.activeJob.isGCodeCreated)
      this.doCreateGCode(this.activeJob, ref strGCodes);
    F_Notepad fNotepad = new F_Notepad();
    fNotepad.Init(strGCodes);
    fNotepad.Show();
    if (clsItem.FrmProgress == null)
      return;
    clsItem.FrmProgress.Visible = false;
  }

  public void cmdCreateGCode()
  {
    if (this.activeJob == null)
      return;
    this.activeJob.CamCalculated = false;
    for (int index1 = 0; index1 <= this.activeJob.Items.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= this.activeJob.Items[index1].CamList.Count - 1; ++index2)
        this.activeJob.Items[index1].CamList[index2].isCamCalculated = false;
    }
    this.doCamCalculateMarbleJob(ref this.activeJob);
  }

  public void cmdStartSimulation()
  {
    if (this.SimIndex == -1)
    {
      clsMarble.lastSimToolPurpose = ToolPurpose.None;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
      this.DeleteSimulationEntities();
      this.DrawSimulationEntities(false, true, true, MarbleToolType.Saw);
      if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.IsAnimationRunning)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
      this.SimToolIndex = 0;
      this.SimIndex = 0;
      this.SimItemIndex = 0;
      this.timSim.Enabled = true;
    }
    else
      this.timSim.Enabled = true;
  }

  public void cmdStopSimulation()
  {
    if (this.timSim.Enabled)
    {
      this.timSim.Enabled = false;
    }
    else
    {
      this.SimIndex = -1;
      this.SimItemIndex = -1;
      this.SimToolIndex = -1;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
      this.DeleteSimulationEntities();
    }
  }

  public void cmdNextSimulation() => this.Sim_Tick((object) null, (EventArgs) null);

  public void cmdPreSimulation()
  {
    this.SimIndex -= clsMarble.SimStep;
    this.SimIndex -= clsMarble.SimStep;
    if (this.SimIndex < 0)
    {
      if (this.SimItemIndex > 0)
        --this.SimItemIndex;
      if (this.SimItemIndex >= 0)
        this.SimIndex = this.activeJob.Cams[this.SimItemIndex].SimilationPoint.SimMove.Count - clsMarble.SimStep - 1;
    }
    this.Sim_Tick((object) null, (EventArgs) null);
    this.timSim.Enabled = false;
  }

  public void cmdCalculate() => this.doCamCalculateMarbleJob(ref this.activeJob);

  public void cmdTakePhoto(Image image)
  {
    try
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Picture && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null ? 0 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData ? 1 : 0)) != 0 && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.CameraImage)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
      MarbleTempVars.CameraImage = (Entity) null;
      AppBool.CameraCaptured = false;
      Image image1 = (Image) null;
      if (image == null)
      {
        // ISSUE: reference to a compiler-generated field
        if (this.okCommandWithFiveDataEventHandler_0 != null)
        {
          // ISSUE: reference to a compiler-generated field
          this.okCommandWithFiveDataEventHandler_0((object) MarbleHMICommands.ShowWarning, (object) buLangTranslate.preSentences.ImageIsNull, (object) null, (object) null, (object) null);
        }
        this.doReset();
      }
      else
      {
        Image image2 = (Image) image.Clone();
        if (image2 == null)
          return;
        int width = image2.Width;
        int height = image2.Height;
        Bitmap image3 = buImage5.CropBitmap((Bitmap) image2.Clone(), buMarbleCalc.varMarbleSettings.CameraCropX, buMarbleCalc.varMarbleSettings.CameraCropY, buMarbleCalc.varMarbleSettings.CameraCropWidth, buMarbleCalc.varMarbleSettings.CameraCropHeight);
        byte[] byteArray = image3.ToByteArray();
        if (buMarbleCalc.varMarbleSettings.CopyImageToArchive)
        {
          DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\ImageArchive");
          if (!directoryInfo.Exists)
            directoryInfo.Create();
          string[] strArray = new string[7];
          int num = DateTime.Now.Year;
          strArray[0] = num.ToString("D2");
          num = DateTime.Now.Month;
          strArray[1] = num.ToString("D2");
          num = DateTime.Now.Day;
          strArray[2] = num.ToString("D2");
          strArray[3] = "_";
          num = DateTime.Now.Hour;
          strArray[4] = num.ToString("D2");
          num = DateTime.Now.Minute;
          strArray[5] = num.ToString("D2");
          num = DateTime.Now.Second;
          strArray[6] = num.ToString("D2");
          string str = string.Concat(strArray);
          image3.Save($"{AppPath.Base}\\ImageArchive\\ArciveImage_{str}.jpg");
        }
        double cameraImageOffsetX = buMarbleCalc.varMarbleSettings.CameraImageOffsetX;
        double cameraImageOffsetY = buMarbleCalc.varMarbleSettings.CameraImageOffsetY;
        if (buMarbleCalc.varMarbleSettings.AutoLensCalibrationFromMaterialHeight)
          ;
        Picture picture = new Picture(Plane.XY, buMarbleCalc.varMarbleSettings.CameraImageWidth, buMarbleCalc.varMarbleSettings.CameraImageHeight, byteArray);
        if (buMarbleCalc.varMarbleSettings.ImageRotateAngle != 0.0)
          ;
        picture.Translate(cameraImageOffsetX, cameraImageOffsetY, buMarbleCalc.varMarbleSettings.ImageZPosition);
        picture.Selectable = false;
        picture.LayerName = MarbleTempVars.layerWood.Name;
        picture.Lighted = false;
        picture.EntityData = (object) new CustomData()
        {
          typeDefination = entityTypeDefination.CameraImage
        };
        picture.Regen(0.1);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) picture);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
        AppBool.CameraCapturing = false;
        AppBool.CameraCaptured = true;
        image1 = (Image) null;
      }
    }
    catch (Exception ex)
    {
      AppBool.CameraCapturing = false;
    }
  }

