  public void cmdContourUserSettingsPage()
  {
    try
    {
      if (buMarbleForms.frmContourSetting == null)
        buMarbleForms.frmContourSetting = new F_MarbleCamSettings();
      buMarbleForms.frmContourSetting.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmContourSetting.Settings = new marbleCamPars(buMarbleCalc.varOperation.settingMarbleCam);
      buMarbleForms.frmContourSetting.SettingsProgram = new MarbleProgramSettings(buMarbleCalc.varMarbleSettings);
      buMarbleForms.frmContourSetting.Sequences.Clear();
      for (int index = 0; index <= buMarbleCalc.varOperation.CuttingSequence.Count - 1; ++index)
        buMarbleForms.frmContourSetting.Sequences.Add(buMarbleCalc.varOperation.CuttingSequence[index]);
      buMarbleForms.frmContourSetting.Init(0);
      buMarbleForms.frmContourSetting.StartPosition = FormStartPosition.CenterParent;
      int num = (int) buMarbleForms.frmContourSetting.ShowDialog();
      if (buMarbleForms.frmContourSetting.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingMarbleCam = new marbleCamPars(buMarbleForms.frmContourSetting.Settings);
      buMarbleCalc.varMarbleSettings = new MarbleProgramSettings(buMarbleForms.frmContourSetting.SettingsProgram);
      buMarbleCalc.varOperation.CuttingSequence.Clear();
      for (int index = 0; index <= buMarbleForms.frmContourSetting.Sequences.Count - 1; ++index)
        buMarbleCalc.varOperation.CuttingSequence.Add(buMarbleForms.frmContourSetting.Sequences[index]);
      this.SaveMarbleFile();
      clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref this.activeJob);
    }
    catch (Exception ex)
    {
