  public void cmdSettingsProgram()
  {
    string str = nameof (cmdSettingsProgram);
    try
    {
      F_SettingsTreeView settingsTreeView = new F_SettingsTreeView();
      settingsTreeView.CaptionHeader.Clear();
      settingsTreeView.Classes = new List<object>();
      settingsTreeView.Classes.Add((object) new MarbleProgramSettings(buMarbleCalc.varMarbleSettings));
      settingsTreeView.Classes.Add((object) new MarbleMachineSettings(buMarbleCalc.varMarbleMachineSettings));
      settingsTreeView.Classes.Add((object) new MarbleDisplaySettings(buMarbleCalc.varMarbleDisplaySettings));
      settingsTreeView.Classes.Add((object) new MarbleDrawingSetting(buMarbleCalc.varMarbleDrawSettings));
      settingsTreeView.Classes.Add((object) new MarbleEntitiesSettings(buMarbleCalc.varMarbleEntitiesSettings));
      settingsTreeView.Init();
      settingsTreeView.StartPosition = FormStartPosition.CenterParent;
      int num = (int) settingsTreeView.ShowDialog();
      if (settingsTreeView.Result != DialogResult.OK)
        return;
      buMarbleCalc.varMarbleSettings = new MarbleProgramSettings((MarbleProgramSettings) settingsTreeView.Classes[0]);
      buMarbleCalc.varMarbleMachineSettings = new MarbleMachineSettings((MarbleMachineSettings) settingsTreeView.Classes[1]);
      buMarbleCalc.varMarbleDisplaySettings = new MarbleDisplaySettings((MarbleDisplaySettings) settingsTreeView.Classes[2]);
      buMarbleCalc.varMarbleDrawSettings = new MarbleDrawingSetting((MarbleDrawingSetting) settingsTreeView.Classes[3]);
      buMarbleCalc.varMarbleEntitiesSettings = new MarbleEntitiesSettings((MarbleEntitiesSettings) settingsTreeView.Classes[4]);
      buLogVer5.addToLog(this.string_0, str, "Ok", "", 0.0, 0.0, true);
      this.SaveMarbleFile();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

