  public void AddCompositeCurvePoint(Point3D Points)
  {
    if (ccVars.pntDynamicCompositeCurve.Count == 0)
      ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 0.0));
    else if (!MarbleTempVars.DrawIsArc)
      ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 0.0));
    else if (ccVars.pntDynamicCompositeCurve[ccVars.pntDynamicCompositeCurve.Count - 1].W == 1.0)
      ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 2.0));
    else
      ccVars.pntDynamicCompositeCurve.Add(new Point4D(Points.X, Points.Y, Points.Z, 1.0));
    this.CheckCompositeCurvePoint();
  }

  public void CheckCompositeCurvePoint()
  {
    if (ccVars.pntDynamicCompositeCurve.Count < 3 || !buCompare5.EQ(ccVars.pntDynamicCompositeCurve[0], ccVars.pntDynamicCompositeCurve[ccVars.pntDynamicCompositeCurve.Count - 1]))
      return;
    this.AddCompositeCurve();
  }

  public void AddCompositeCurve()
  {
    if (!MarbleTempVars.DrawIsInside)
      this.entityGroupDraw = new buEntitiesGroup();
    List<buEntity> refEntities = new List<buEntity>();
    for (int index1 = 1; index1 <= ccVars.pntDynamicCompositeCurve.Count - 1; ++index1)
    {
      Point4D point4D1 = ccVars.pntDynamicCompositeCurve[index1 - 1];
      Point4D point4D2 = ccVars.pntDynamicCompositeCurve[index1];
      if (point4D2.W == 0.0)
      {
        Entity refEntity = (Entity) new Line(new Point3D(point4D1.X, point4D1.Y, point4D1.Z), new Point3D(point4D2.X, point4D2.Y, point4D2.Z));
        if (refEntity != null)
        {
          if (refEntity.Vertices == null)
            refEntity.Regen(0.1);
          for (int index2 = 0; index2 <= refEntity.Vertices.Length - 1; ++index2)
            ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(refEntity.Vertices[index2]), osnapType.Point));
          CustomData customData = new CustomData();
          customData.typeDefination = entityTypeDefination.TempDraw;
          refEntity.LayerName = MarbleTempVars.layerDrawing.Name;
          refEntity.Color = Color.Red;
          refEntity.ColorMethod = colorMethodType.byEntity;
          refEntity.LineWeight = 3f;
          refEntity.LineWeightMethod = colorMethodType.byEntity;
          refEntity.EntityData = (object) customData;
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntity, ref copiedEntity);
          if (copiedEntity != null)
            refEntities.Add(copiedEntity);
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(refEntity);
        }
      }
      else if (point4D2.W == 2.0)
      {
        Point4D point4D3 = ccVars.pntDynamicCompositeCurve[index1 - 2];
        Entity refEntity = (Entity) new Arc(new Point3D(point4D3.X, point4D3.Y, point4D3.Z), new Point3D(point4D1.X, point4D1.Y, point4D1.Z), new Point3D(point4D2.X, point4D2.Y, point4D2.Z), false);
        if (refEntity != null)
        {
          if (refEntity.Vertices == null)
            refEntity.Regen(0.1);
          ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(new Point3D(point4D1.X, point4D1.Y, point4D1.Z), osnapType.Point));
          ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(new Point3D(point4D2.X, point4D2.Y, point4D2.Z), osnapType.Point));
          CustomData customData = new CustomData();
          customData.typeDefination = entityTypeDefination.TempDraw;
          refEntity.LayerName = MarbleTempVars.layerDrawing.Name;
          refEntity.Color = Color.Red;
          refEntity.ColorMethod = colorMethodType.byEntity;
          refEntity.LineWeight = 3f;
          refEntity.LineWeightMethod = colorMethodType.byEntity;
          refEntity.EntityData = (object) customData;
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntity, ref copiedEntity);
          if (copiedEntity != null)
            refEntities.Add(copiedEntity);
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(refEntity);
        }
      }
    }
    if (refEntities.Count > 0)
    {
      if (!MarbleTempVars.DrawIsInside)
      {
        buEntity.Copy(refEntities, ref this.entityGroupDraw.Outside.Entities);
      }
      else
      {
        buEntityList buEntityList = new buEntityList();
        buEntity.Copy(refEntities, ref buEntityList.Entities);
        this.entityGroupDraw.Inside.Add(buEntityList);
      }
    }
    ccVars.pntDynamicCompositeCurve.Clear();
  }

  public void AddPolyLine(Point3D Points)
  {
    if (Points != (Point3D) null)
      ccVars.pntBuffered.Add(buVector5.ToPoint3D(Points));
    ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
    for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
      ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(ccVars.pntBuffered[index]);
    ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
    if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
    if (Points != (Point3D) null)
    {
      if (clsVar.varEntities.FinishPolylineIfClosed && ccVars.pntBuffered.Count >= 3 && buCompare5.EQ(ccVars.pntBuffered[0], ccVars.pntBuffered[ccVars.pntBuffered.Count - 1], clsVar.varSelection.CompareResolution))
      {
        if (ccVars.pntBuffered.Count >= 2)
        {
          LinearPath linearPath = new LinearPath((ICollection<Point3D>) ccVars.pntBuffered);
          if (linearPath != null)
          {
            if (linearPath.Vertices == null)
              linearPath.Regen(0.1);
            for (int index = 0; index <= linearPath.Vertices.Length - 1; ++index)
              ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath.Vertices[index]), osnapType.Point));
            CustomData customData = new CustomData();
            customData.typeDefination = entityTypeDefination.TempDraw;
            linearPath.LayerName = MarbleTempVars.layerDrawing.Name;
            linearPath.Color = Color.Red;
            linearPath.ColorMethod = colorMethodType.byEntity;
            linearPath.LineWeight = 3f;
            linearPath.LineWeightMethod = colorMethodType.byEntity;
            linearPath.EntityData = (object) customData;
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) linearPath);
          }
        }
        clsInit.appCommand.Reset();
      }
    }
    else
    {
      if (ccVars.pntBuffered.Count >= 2)
      {
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) ccVars.pntBuffered);
        if (linearPath != null)
        {
          if (linearPath.Vertices == null)
            linearPath.Regen(0.1);
          for (int index = 0; index <= linearPath.Vertices.Length - 1; ++index)
            ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath.Vertices[index]), osnapType.Point));
          CustomData customData = new CustomData();
          customData.typeDefination = entityTypeDefination.TempDraw;
          linearPath.LayerName = MarbleTempVars.layerDrawing.Name;
          linearPath.Color = Color.Red;
          linearPath.ColorMethod = colorMethodType.byEntity;
          linearPath.LineWeight = 3f;
          linearPath.LineWeightMethod = colorMethodType.byEntity;
          linearPath.EntityData = (object) customData;
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) linearPath);
        }
      }
      clsInit.appCommand.Reset();
    }
    if (!(Points != (Point3D) null))
      return;
    ccVars.pntBase = buVector5.ToPoint3D(Points);
  }

  public void AddLine(Point3D Points)
  {
    ccVars.pntBuffered.Add(buVector5.ToPoint3D(Points));
    ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
    for (int index = 0; index <= ccVars.pntBuffered.Count - 1; ++index)
      ccVars.pntDrawDynamicArr[index] = buVector5.ToPoint3D(ccVars.pntBuffered[index]);
    ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
    Line line = new Line(ccVars.pntBase, Points);
    if (line == null)
      return;
    if (line.Vertices == null)
      line.Regen(0.1);
    for (int index = 0; index <= line.Vertices.Length - 1; ++index)
      ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(line.Vertices[index]), osnapType.Point));
    CustomData customData = new CustomData();
    customData.typeDefination = entityTypeDefination.TempDraw;
    line.LayerName = MarbleTempVars.layerDrawing.Name;
    line.Color = Color.Red;
    line.ColorMethod = colorMethodType.byEntity;
    line.LineWeight = 3f;
    line.LineWeightMethod = colorMethodType.byEntity;
    line.EntityData = (object) customData;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) line);
    ccVars.pntBase = buVector5.ToPoint3D(Points);
  }

  public void AddRectangle(Point3D Points)
  {
    Entity entRectangle = (Entity) null;
    clsInit.cVector5.Rectangle2Point(ccVars.pntBase, Points, Plane.XY, ref entRectangle);
    if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
    if (entRectangle != null)
    {
      if (entRectangle.Vertices == null)
        entRectangle.Regen(0.1);
      for (int index = 0; index <= entRectangle.Vertices.Length - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(entRectangle.Vertices[index]), osnapType.Point));
      CustomData customData = new CustomData();
      customData.typeDefination = entityTypeDefination.TempDraw;
      entRectangle.LayerName = MarbleTempVars.layerDrawing.Name;
      entRectangle.Color = Color.Red;
      entRectangle.ColorMethod = colorMethodType.byEntity;
      entRectangle.LineWeight = 3f;
      entRectangle.LineWeightMethod = colorMethodType.byEntity;
      entRectangle.EntityData = (object) customData;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entRectangle);
      clsInit.appCommand.Reset();
    }
    ccVars.pntBase = buVector5.ToPoint3D(Points);
  }

  public void AddPolygon(Point3D Points)
  {
    List<Pnt3D> Vertices = new List<Pnt3D>();
    List<Point3D> points = new List<Point3D>();
    double s1;
    double t1;
    Plane.XY.Project(ccVars.pntBase, out s1, out t1);
    double s2;
    double t2;
    Plane.XY.Project(Points, out s2, out t2);
    clsInit.cVector.Length3D(new Pnt3D(s1, t1), new Pnt3D(s2, t2));
    clsInit.cVector.PointAngle(new Pnt3D(s2, t2), new Pnt3D(s1, t1));
    clsInit.cVector.PolygonCenter(new Pnt3D(s1, t1), new Pnt3D(s2, t2), clsVar.varInterface.PolygonVar.Side, new WorkPlane(planeType.XY, 1), ref Vertices);
    for (int index = 0; index <= Vertices.Count - 1; ++index)
      points.Add(new Point3D(Vertices[index].X, Vertices[index].Y, 0.0));
    if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
    LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
    if (linearPath != null)
    {
      if (linearPath.Vertices == null)
        linearPath.Regen(0.1);
      for (int index = 0; index <= linearPath.Vertices.Length - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(linearPath.Vertices[index]), osnapType.Point));
      CustomData customData = new CustomData();
      customData.typeDefination = entityTypeDefination.TempDraw;
      linearPath.LayerName = MarbleTempVars.layerDrawing.Name;
      linearPath.Color = Color.Red;
      linearPath.ColorMethod = colorMethodType.byEntity;
      linearPath.LineWeight = 3f;
      linearPath.LineWeightMethod = colorMethodType.byEntity;
      linearPath.EntityData = (object) customData;
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) linearPath);
      clsInit.appCommand.Reset();
    }
    ccVars.pntBase = buVector5.ToPoint3D(Points);
  }

  public void AddCircle(Point3D Points, double Diameter)
  {
    if (!MarbleTempVars.DrawIsInside)
      this.entityGroupDraw = new buEntitiesGroup();
    List<buEntity> refEntities = new List<buEntity>();
    if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
    double num = Point3D.Distance(ccVars.pntBase, Points);
    if (Diameter > 0.0)
      num = Diameter / 2.0;
    if (num > 0.01)
    {
      Entity refEntity = (Entity) new Circle(Plane.XY, ccVars.pntBase, num);
      if (refEntity != null)
      {
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(ccVars.pntBase), osnapType.Center));
        Point3D Q1 = (Point3D) null;
        Point3D Q2 = (Point3D) null;
        Point3D Q3 = (Point3D) null;
        Point3D Q4 = (Point3D) null;
        clsInit.cVector5.CircleQuadrantPoints(ccVars.pntBase, num, Plane.XY, ref Q1, ref Q2, ref Q3, ref Q4);
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q1, osnapType.Outer));
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q2, osnapType.Outer));
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q3, osnapType.Outer));
        ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(Q4, osnapType.Outer));
        CustomData customData = new CustomData();
        customData.typeDefination = entityTypeDefination.TempDraw;
        refEntity.LayerName = MarbleTempVars.layerDrawing.Name;
        refEntity.Color = Color.Red;
        refEntity.ColorMethod = colorMethodType.byEntity;
        refEntity.LineWeight = 3f;
        refEntity.LineWeightMethod = colorMethodType.byEntity;
        refEntity.EntityData = (object) customData;
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(refEntity, ref copiedEntity);
        if (copiedEntity != null)
          refEntities.Add(copiedEntity);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(refEntity);
        clsInit.appCommand.Reset();
      }
    }
    if (refEntities.Count > 0)
    {
      if (!MarbleTempVars.DrawIsInside)
      {
        buEntity.Copy(refEntities, ref this.entityGroupDraw.Outside.Entities);
      }
      else
      {
        buEntityList buEntityList = new buEntityList();
        buEntity.Copy(refEntities, ref buEntityList.Entities);
        this.entityGroupDraw.Inside.Add(buEntityList);
      }
    }
    ccVars.pntBase = buVector5.ToPoint3D(Points);
  }

  public void AddArc(Point3D StartPoint, Point3D MidPoint, Point3D EndPoint)
  {
    if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
      ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
    Arc arc = new Arc(StartPoint, MidPoint, EndPoint, false);
    if (arc == null)
      return;
    ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(ccVars.pntBase), osnapType.Point));
    ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(MidPoint), osnapType.Point));
    ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Add(new OsnapPoint(buVector5.ToPoint3D(EndPoint), osnapType.Point));
    CustomData customData = new CustomData();
    customData.typeDefination = entityTypeDefination.TempDraw;
    arc.LayerName = MarbleTempVars.layerDrawing.Name;
    arc.Color = Color.Red;
    arc.ColorMethod = colorMethodType.byEntity;
    arc.LineWeight = 3f;
    arc.LineWeightMethod = colorMethodType.byEntity;
    arc.EntityData = (object) customData;
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity) arc);
    clsInit.appCommand.Reset();
  }

  public void DeleteTempDrawings()
  {
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.TempDraw)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void viewportMouseDown(Point3D Points, object sender, MouseEventArgs e)
  {
    if ((e.Button != MouseButtons.Left || ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode != devDept.Eyeshot.actionType.None ? 1 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Viewports[0].ToolBar.Contains(e.Location) ? 1 : 0)) != 0 || e.Button != MouseButtons.Left)
      return;
    AppBool.MouseDown = true;
    ccVars.pntMouseDownFirst.X = Points.X;
    ccVars.pntMouseDownFirst.Y = Points.Y;
    if (this.MoveCreatedEntity)
    {
      Point3D pntMove = new Point3D(Points.X, Points.Y, Points.Z);
      bool isIntersect = false;
      bool isOut = false;
      ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
      this.ViewportOsnap(viewportcad, Points, ref pntMove, ref isIntersect, ref isOut);
      this.MoveCreatedEntity = false;
      for (int index = 0; index <= viewportcad.Entities.Count - 1; ++index)
      {
        viewportcad.Entities[index].Selected = false;
        if (viewportcad.Entities[index].EntityData != null & viewportcad.Entities[index].EntityData is CustomData && (viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Temp)
          viewportcad.Entities[index].Selected = true;
      }
      viewportcad.Entities.DeleteSelected();
      bool isMilling = false;
      bool isWaterJet = false;
      bool isMillingHead = false;
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.Milling)
        isMilling = true;
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.WaterJet)
        isWaterJet = true;
      if (buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool == MarbleToolType.MillingHead)
        isMillingHead = true;
      if (clsInit.appMarble.activeItemType == MarbleItemType.VerticalCut)
        clsInit.appMarble.doAddItemVerHorMainForm(pntMove, MarbleTempVars.VerticalStartPos.C, buMarbleCalc.varMarbleRunSettings.CutLengthVertical, true);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.HorizontalCut)
        clsInit.appMarble.doAddItemVerHorMainForm(pntMove, MarbleTempVars.HorizontalStartPos.C, buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal, true);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.HorizontalVerticalCut)
        clsInit.appMarble.doAddItemVerHorBothMainForm(pntMove, pntMove, MarbleTempVars.HorizontalStartPos.C, buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal, buMarbleCalc.varMarbleRunSettings.CutLengthVertical, true);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Slices)
        clsInit.appMarble.doAddItemSlice(pntMove, 0.0, true);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.SingleCut)
        clsInit.appMarble.doAddItemSingleCut(pntMove, MarbleTempVars.SingleCutPos.A, MarbleTempVars.SingleCutPos.C, true);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Contour)
        clsInit.appMarble.doAddItemShapeContour(pntMove, false, true, false, isMilling, isMillingHead, isWaterJet, buMarbleCalc.varMarbleSettings.ContourOnlineCamCalculation, -1);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Shape)
        clsInit.appMarble.doAddItemShapeContour(pntMove, true, true, false, isMilling, isMillingHead, isWaterJet, buMarbleCalc.varMarbleSettings.ContourOnlineCamCalculation, -1);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Engraving)
        clsInit.appMarble.doAddItemEngraving(pntMove, clsInit.appMarble.entitiesForMove, buMarbleCalc.varMarbleSettings.EngraveOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Shape3D)
        clsInit.appMarble.doAddItem3DFile(pntMove, MarbleTempVars.ImportedEntitites);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.SawHorizontalMillingRough)
        clsInit.appMarble.doAddItemSawMilling(pntMove, MarbleTempVars.ImportedEntitites, true, true, buMarbleCalc.varMarbleSettings.EngraveOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.SawVerticalMillingRough)
        clsInit.appMarble.doAddItemSawMilling(pntMove, MarbleTempVars.ImportedEntitites, false, true, buMarbleCalc.varMarbleSettings.EngraveOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Profiling)
        clsInit.appMarble.doAddItemProfiling(new Point3D(pntMove.X, pntMove.Y, pntMove.Z), true, buMarbleCalc.varMarbleSettings.ProfileOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.ProfileCurve)
        clsInit.appMarble.doAddItemProfileCurve(new Point3D(pntMove.X, pntMove.Y, pntMove.Z), true, buMarbleCalc.varMarbleSettings.ProfileOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Sweep)
        clsInit.appMarble.doAddItemSweep(pntMove, true, buMarbleCalc.varMarbleSettings.SweepOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Cavity)
        clsInit.appMarble.doAddItemCavity(pntMove, true, buMarbleCalc.varMarbleSettings.CavityOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Drill)
        clsInit.appMarble.doAddItemDrill(pntMove, true, buMarbleCalc.varMarbleSettings.DrillOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Text | clsInit.appMarble.activeItemType == MarbleItemType.TextWireframe | clsInit.appMarble.activeItemType == MarbleItemType.Text3D)
      {
        if (buMarbleCalc.varMarbleRunSettings.Text3D)
        {
          List<Entity> Entities = new List<Entity>();
          for (int index1 = 0; index1 <= MarbleTempVars.ItemsContour.Count - 1; ++index1)
          {
            for (int index2 = 0; index2 <= MarbleTempVars.ItemsContour[index1].ItemEntities.SolidEntity.Count - 1; ++index2)
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(MarbleTempVars.ItemsContour[index1].ItemEntities.SolidEntity[index2], ref copiedEntity);
              Entities.Add(copiedEntity);
            }
          }
          clsInit.appMarble.doAddItemEngraving(pntMove, Entities, true, buMarbleCalc.varMarbleSettings.TextOnlineCamCalculation);
        }
        else
          clsInit.appMarble.doAddItemShapeContour(pntMove, false, true, true, isMilling, isMillingHead, isWaterJet, buMarbleCalc.varMarbleSettings.TextOnlineCamCalculation, -1);
      }
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Columns)
        clsInit.appMarble.doAddItemColumns(pntMove, true, buMarbleCalc.varMarbleSettings.ColumnsOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.LatheHorizontal)
        clsInit.appMarble.doAddItemLathe(pntMove, true, buMarbleCalc.varMarbleSettings.LatheOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.LatheVertical)
        clsInit.appMarble.doAddItemLatheVertical(pntMove, true, buMarbleCalc.varMarbleSettings.LatheOnlineCamCalculation);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.Milling5AxisRotary)
        clsInit.appMarble.doAddItemMilling5AxisRotary(pntMove, clsInit.appMarble.entitiesForMove);
      else if (clsInit.appMarble.activeItemType == MarbleItemType.VacuumAdd)
      {
        if (buMarbleForms.frmVacuumMove == null)
        {
          buMarbleForms.frmVacuumMove = new F_MarbleVacuumMove();
          buMarbleForms.frmVacuumMove.VacuumCommand += new OkCommandWithFiveDataEventHandler(this.method_7);
        }
        buMarbleForms.frmVacuumMove.spn_distance.Value = buMarbleCalc.varMarbleRunSettings.VacuumMove;
        buMarbleForms.frmVacuumMove.PropertiesForm.TopMost = true;
        buMarbleForms.frmVacuumMove.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
        buMarbleForms.frmVacuumMove.Init();
        int num = (int) buMarbleForms.frmVacuumMove.ShowDialog();
        if (buMarbleForms.frmVacuumMove.PropertiesForm.Result == DialogResult.OK)
          buMarbleCalc.varMarbleRunSettings.VacuumMove = buMarbleForms.frmVacuumMove.spn_distance.Value;
      }
      clsInit.appMarble.MoveCreatedEntity = false;
      clsInit.appMarble.activeItemType = MarbleItemType.None;
      ccVars.selectionProcess = true;
      clsInit.appCommand.Reset();
    }
    if (!MarbleTempVars.Editing)
      return;
    int num1 = 0;
    while (num1 <= this.activeJob.Items.Count - 1)
      ++num1;
  }

  public void viewportMouseUp(Point3D Points, object sender, MouseEventArgs e)
  {
    AppBool.MouseDown = false;
    ccVars.pntDrawDynamicLines.Clear();
    if (AppBool.EditMode && ccVars.SelectionOP.Selections.Count > 0 && Math.Abs(Points.X - ccVars.pntMouseDownFirst.X) > 1.0 | Math.Abs(Points.Y - ccVars.pntMouseDownFirst.Y) > 1.0)
    {
      clsInit.cVector5.GetSelectedEntitiesInfo((Design) ccVars.Pages[ccVars.PageIndex].Form.viewportcad, ref ccVars.numberOfSelectedEntity, ref ccVars.pntSelectedMin, ref ccVars.pntSelectedMid, ref ccVars.pntSelectedMax);
      ccVars.lastRotatedAngle = clsInit.cVector5.PointAngle(Points, ccVars.pntSelectedMid);
      AppBool.EditMode = false;
      this.doDrawActiveJob();
      this.SetSelectedToEntities();
      AppBool.EditMode = true;
    }
    if (e.Button != MouseButtons.Left || !MarbleTempVars.SetAngle)
      return;
    this.doSetAngle();
  }

  public void viewportMouseMove(Point3D Points, object sender, MouseEventArgs e)
  {
    try
    {
      Point3D pntMove = new Point3D(Points.X, Points.Y, Points.Z);
      ViewportCC.textDynamical = (string) null;
      // ISSUE: reference to a compiler-generated field
      if (this.okCommandWithFiveDataEventHandler_0 != null)
      {
        this.MarbleArg.pntMove.X = Points.X;
        this.MarbleArg.pntMove.Y = Points.Y;
        this.MarbleArg.pntMove.Z = Points.Z;
        this.MarbleArg.refPlane = ccVars.planeActive;
        this.MarbleArg.pntScreen.X = e.X;
        this.MarbleArg.pntScreen.Y = e.Y;
        // ISSUE: reference to a compiler-generated field
        this.okCommandWithFiveDataEventHandler_0((object) MarbleHMICommands.MoveMouse, (object) this.MarbleArg, (object) null, (object) null, (object) null);
      }
      if (this.MoveCreatedEntity)
      {
        ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
        for (int index = 0; index <= viewportcad.Entities.Count - 1; ++index)
        {
          viewportcad.Entities[index].Selected = false;
          if (viewportcad.Entities[index].EntityData != null & viewportcad.Entities[index].EntityData is CustomData && (viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Temp)
            viewportcad.Entities[index].Selected = true;
        }
        viewportcad.Entities.DeleteSelected();
        bool isIntersect = false;
        bool isOut = false;
        this.ViewportOsnap(viewportcad, Points, ref pntMove, ref isIntersect, ref isOut);
        for (int index = 0; index <= clsInit.appMarble.entitiesForMove.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(clsInit.appMarble.entitiesForMove[index], ref copiedEntity);
          if (copiedEntity != null)
          {
            bool flag = true;
            if (!MarbleTempVars.isSolidMove)
            {
              flag = false;
              if (copiedEntity is ICurve)
                flag = true;
            }
            if (flag)
            {
              copiedEntity.EntityData = (object) new CustomData()
              {
                typeDefination = entityTypeDefination.Temp
              };
              copiedEntity.LayerName = viewportcad.Layers[MarbleTempVars.layerMarblePart.Index].Name;
              copiedEntity.Translate(pntMove.X, pntMove.Y, 0.1);
              copiedEntity.Regen(0.5);
              if (isIntersect | isOut)
              {
                copiedEntity.Color = Color.Red;
                copiedEntity.ColorMethod = colorMethodType.byEntity;
              }
              viewportcad.Entities.Add(copiedEntity);
              if (isOut)
                this.ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationOutofMaterial, Color.Red, 20f);
              if (isIntersect)
                this.ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationOnthePart, Color.Red, 20f);
            }
          }
        }
        viewportcad.Invalidate();
      }
      if (AppBool.EditMode)
      {
        if (!this.MoveCreatedEntity & ccVars.Action == actionTypeBU.None & AppBool.MouseDown & ccVars.numberOfUnderSelectedEntity > 0 & buMarbleCalc.varOperation.settingEvent.eventMoveByMouse)
        {
          this.doMoveSelectedItem(ccVars.pntMouseMove.X - ccVars.pntMouseDown.X, ccVars.pntMouseMove.Y - ccVars.pntMouseDown.Y);
          ccVars.pntMouseDown.X = ccVars.pntMouseMove.X;
          ccVars.pntMouseDown.Y = ccVars.pntMouseMove.Y;
        }
        if (!this.MoveCreatedEntity & MarbleTempVars.OperationageMode == MarbleOperationPageMode.Event & ccVars.Action == actionTypeBU.None & AppBool.MouseDown & ccVars.numberOfUnderSelectedEntity == 0 & ccVars.numberOfSelectedEntity > 0 & buMarbleCalc.varOperation.settingEvent.eventRotateByMouse)
        {
          ccVars.pntDrawDynamicLines.Clear();
          ccVars.pntDrawDynamicLines.Add(ccVars.pntSelectedMid);
          ccVars.pntDrawDynamicLines.Add(pntMove);
          double num = clsInit.cVector5.PointAngle(pntMove, ccVars.pntSelectedMid);
          this.doRotateSelectedItem(num - ccVars.lastRotatedAngle);
          ccVars.lastRotatedAngle = num;
        }
      }
      if (clsInit.appMarble.activeItemType != MarbleItemType.VacuumAdd)
        return;
      this.GetVacuumLineByMouse(Points, 0.0, 0.0, false);
    }
    catch (Exception ex)
    {
    }
  }

  public void ViewportOsnap(
    ViewportCC View,
    Point3D Points,
    ref Point3D pntMove,
    ref bool isIntersect,
    ref bool isOut)
  {
    if (!this.MoveCreatedEntity)
      return;
    Point3D pntOver = new Point3D();
    if ((this.activeJob == null || this.activeJob.Material == null ? 0 : (this.activeJob.Material.Enable ? 1 : 0)) != 0)
    {
      for (int index = 1; index <= this.activeJob.Material.Points.Count - 1; ++index)
      {
        pntOver = new Point3D();
        if (clsInit.cVector5.isPointOverLine(this.activeJob.Material.Points[index - 1], this.activeJob.Material.Points[index], Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
        {
          pntMove.X = pntOver.X;
          pntMove.Y = pntOver.Y;
          pntMove.Z = pntOver.Z;
          this.ViewportDynamicalText(pntMove, $"{buLangTranslate.preDef.Material} {buLangTranslate.preDef.Catch}", Color.Black, 20f);
        }
      }
    }
    if (MarbleTempVars.MaterialLimits.Count > 0)
    {
      for (int index = 1; index <= MarbleTempVars.MaterialLimits.Count - 1; ++index)
      {
        pntOver = new Point3D();
        if (clsInit.cVector5.isPointOverLine(MarbleTempVars.MaterialLimits[index - 1], MarbleTempVars.MaterialLimits[index], Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
        {
          pntMove.X = pntOver.X;
          pntMove.Y = pntOver.Y;
          pntMove.Z = pntOver.Z;
          this.ViewportDynamicalText(pntMove, buLangTranslate.preSentences.OperationCatchPart, Color.Black, 20f);
        }
      }
    }
    if (clsInit.cVector5.isPointOverLine(new Point3D(), new Point3D(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, 0.0, 0.0), Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
    {
      pntMove.X = pntOver.X;
      pntMove.Y = pntOver.Y;
      pntMove.Z = pntOver.Z;
      this.ViewportDynamicalText(pntMove, $"{buLangTranslate.preDef.Limit} {buLangTranslate.preDef.Catch}", Color.Black, 20f);
    }
    pntOver = new Point3D();
    if (clsInit.cVector5.isPointOverLine(new Point3D(), new Point3D(0.0, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, 0.0), Points, buMarbleCalc.varMarbleSettings.EntityCatchDistance, ref pntOver))
    {
      pntMove.X = pntOver.X;
      pntMove.Y = pntOver.Y;
      pntMove.Z = pntOver.Z;
      this.ViewportDynamicalText(pntMove, $"{buLangTranslate.preDef.Limit} {buLangTranslate.preDef.Catch}", Color.Black, 20f);
    }
    isIntersect = false;
    isOut = false;
    if (buMarbleCalc.varMarbleSettings.MaterialBorderControl & this.activeJob.Material.Enable && this.activeJob.Material.Points.Count > 0)
    {
      for (int index1 = 0; index1 <= clsInit.appMarble.entitiesForMove.Count - 1; ++index1)
      {
        if (clsInit.appMarble.entitiesForMove[index1].Vertices != null)
        {
          for (int index2 = 0; index2 <= clsInit.appMarble.entitiesForMove[index1].Vertices.Length - 1; ++index2)
          {
            Point3D RefPoint = new Point3D(clsInit.appMarble.entitiesForMove[index1].Vertices[index2].X + pntMove.X, clsInit.appMarble.entitiesForMove[index1].Vertices[index2].Y + pntMove.Y, clsInit.appMarble.entitiesForMove[index1].Vertices[index2].Z);
            if (!clsInit.cVector5.IsPointInsidePolygon(this.activeJob.Material.Points, RefPoint, Plane.XY, true))
              isOut = true;
          }
        }
      }
    }
    if (!buMarbleCalc.varMarbleSettings.IntersectionEnable)
      return;
    for (int index3 = 0; index3 <= clsInit.appMarble.entitiesForMove.Count - 1; ++index3)
    {
      Entity copiedEntity = (Entity) null;
      buEntity.Copy(clsInit.appMarble.entitiesForMove[index3], ref copiedEntity);
      if (copiedEntity != null)
      {
        copiedEntity.EntityData = (object) new CustomData()
        {
          typeDefination = entityTypeDefination.Temp
        };
        copiedEntity.LayerName = View.Layers[MarbleTempVars.layerMarblePart.Index].Name;
        copiedEntity.Translate(pntMove.X, pntMove.Y);
        copiedEntity.Regen(0.1);
        if (copiedEntity is ICurve)
        {
          for (int index4 = 0; index4 <= View.Entities.Count - 1; ++index4)
          {
            if (View.Entities[index4] is ICurve)
            {
              Point3D[] point3DArray = ((ICurve) View.Entities[index4]).IntersectWith((ICurve) copiedEntity);
              if ((point3DArray == null ? 0 : (point3DArray.Length != 0 ? 1 : 0)) != 0)
                isIntersect = true;
            }
          }
        }
      }
    }
  }

  public void ViewportDynamicalText(Point3D pntMove, string Info, Color clr, float FontSize)
  {
    if ((ccVars.Pages == null ? 0 : (ccVars.Pages.Count > 0 ? 1 : 0)) == 0)
      return;
    clsVar.varView.DynamicTextAlignment = ContentAlignment.MiddleLeft;
    clsVar.varView.DynamicTextSize = (double) FontSize;
    clsVar.varView.colorDynamicText = clr;
    ViewportCC.textDynamical = Info;
  }

  public void DeleteSimulationEntities()
  {
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = false;
      if ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null ? 0 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData ? 1 : 0)) != 0)
      {
        CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
        if (entityData.typeDefination == entityTypeDefination.MachineParts | entityData.typeDefination == entityTypeDefination.MachineBody | entityData.typeDefination == entityTypeDefination.ToolParts | entityData.typeDefination == entityTypeDefination.Tool && ((entityData.infoString == null ? 1 : 0) | (entityData.infoString == null ? 0 : (entityData.infoString != "NotDelete" ? 1 : 0))) != 0)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void GetSimulationEntities(
    bool cam,
    bool machine,
    int EntityCount,
    ref List<Entity> EntList,
    ref List<Block> Blocks,
    ref List<int> MovePartIndex)
  {
    MovePartIndex.Clear();
    EntList = new List<Entity>();
    Blocks = new List<Block>();
    if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawHead)
    {
      int num = EntityCount;
      if ((!machine || ccVars.SimMachine == null ? 0 : (ccVars.SimMachine.MachineParts != null ? 1 : 0)) != 0)
      {
        for (int index1 = 0; index1 <= ccVars.SimMachine.MachineParts.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= ccVars.SimMachine.MachineParts[index1].Entities.Count - 1; ++index2)
          {
            if (ccVars.SimMachine.MachineParts[index1].PartType != "Lathe")
            {
              buMachinePart buMachinePart = new buMachinePart(ccVars.SimMachine.MachineParts[index1].PartName);
              buMachinePart.ARotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.A;
              buMachinePart.BRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.B;
              buMachinePart.CRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.C;
              buMachinePart.XMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.X;
              buMachinePart.YMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Y;
              buMachinePart.ZMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Z;
              buMachinePart.centerPointOfA = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Y - 0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Z - clsMarble.activeKinematic.RotateCenterOffsetOfC.Z);
              buMachinePart.centerPointOfC = new Point3D();
              buMachinePart.Color = ccVars.SimMachine.MachineParts[index1].Color;
              buMachinePart.ColorMethod = colorMethodType.byEntity;
              double dx = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetX;
              double dy = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetY;
              double dz = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetZ;
              if (buMachinePart.ARotation)
              {
                buMachinePart.centerPointOfA = new Point3D();
                buMachinePart.centerPointOfC = new Point3D(0.0, -(clsMarble.activeKinematic.RotateCenterOffsetOfA.Y + clsMarble.activeKinematic.RotateCenterOffsetOfC.Y), 0.0);
                if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.MovePartFromKinematicDistances)
                {
                  dy = dy - clsMarble.activeKinematic.RotateCenterOffsetOfC.Y + buMarbleCalc.activeToolSaw.Geometry.Thickness / 2.0;
                  dz -= clsMarble.activeKinematic.RotateCenterOffsetOfA.Z;
                  buMachinePart.centerPointOfA = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Y, clsMarble.activeKinematic.RotateCenterOffsetOfA.Z);
                  buMachinePart.centerPointOfC = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfC.Y, 0.0);
                }
                else
                {
                  buMachinePart.centerPointOfA = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Y, clsMarble.activeKinematic.RotateCenterOffsetOfA.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance);
                  buMachinePart.centerPointOfC = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfC.Y, 0.0);
                }
                if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.MovePartFromKinematicDistances)
                  dz += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance;
              }
              if (ccVars.SimMachine.MachineParts[index1].PartName == "Spindle")
              {
                dx += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX;
                dy += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY;
                dz += buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetZ;
                buMachinePart.centerPointOfC = new Point3D(-buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX, -buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY);
              }
              buMachinePart.Translate(dx, dy, dz);
              buMachinePart.Regen(new RegenParams(0.1, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
              buMachinePart.EntityData = (object) new CustomData()
              {
                typeDefination = entityTypeDefination.MachineParts,
                OriginalEntityIndex = num,
                EntityName = ccVars.SimMachine.MachineParts[index1].PartName
              };
              buMachinePart.ColorMethod = colorMethodType.byEntity;
              buMachinePart.Color = Color.FromArgb(100, ccVars.SimMachine.MachineParts[index1].Color);
              buMachinePart.LayerName = MarbleTempVars.layerMachine.Name;
              EntList.Add((Entity) buMachinePart);
              ++num;
            }
            else
            {
              buMachinePart buMachinePart = new buMachinePart(ccVars.SimMachine.MachineParts[index1].PartName);
              buMachinePart.ARotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.A;
              buMachinePart.BRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.B;
              buMachinePart.CRotation = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.C;
              buMachinePart.XMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.X;
              buMachinePart.YMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Y;
              buMachinePart.ZMove = ccVars.SimMachine.MachineParts[index1].MoveAxisPermision.Z;
              buMachinePart.centerPointOfA = new Point3D(0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Y - 0.0, clsMarble.activeKinematic.RotateCenterOffsetOfA.Z - clsMarble.activeKinematic.RotateCenterOffsetOfC.Z);
              buMachinePart.centerPointOfC = new Point3D();
              buMachinePart.Color = ccVars.SimMachine.MachineParts[index1].Color;
              buMachinePart.ColorMethod = colorMethodType.byEntity;
              double dx = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetX;
              double dy = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetY;
              double dz = ccVars.SimMachine.MachineParts[index1].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[index1].PositionAuxOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawCommonOffsetZ;
              buMachinePart.Translate(dx, dy, dz);
              buMachinePart.Regen(new RegenParams(0.1, (IWorkspace) ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
              buMachinePart.EntityData = (object) new CustomData()
              {
                typeDefination = entityTypeDefination.MachineParts,
                OriginalEntityIndex = num,
                EntityName = ccVars.SimMachine.MachineParts[index1].PartName
              };
              buMachinePart.ColorMethod = colorMethodType.byEntity;
              buMachinePart.Color = Color.FromArgb(100, ccVars.SimMachine.MachineParts[index1].Color);
              buMachinePart.LayerName = MarbleTempVars.layerMachine.Name;
              EntList.Add((Entity) buMachinePart);
              ++num;
            }
          }
        }
      }
    }
    this.DrawTool(buMarbleCalc.activeToolSaw, buMarbleCalc.activeToolMilling, buMarbleCalc.activeToolMillingHead, buMarbleCalc.activeToolWaterjet, buMarbleCalc.activeToolAirDry, buMarbleCalc.activeToolLaserPointer, clsMarble.activeKinematic, EntityCount, ref EntList, ref Blocks, ref MovePartIndex);
  }

  public void DrawSimulationEntities(
    bool cam,
    bool machine,
    bool DrawAllTool,
    MarbleToolType ActiveToolType)
  {
    this.list_0.Clear();
    List<Entity> EntList = new List<Entity>();
    List<Block> Blocks = new List<Block>();
    MarbleTempVars.DontDrawAirDry = false;
    MarbleTempVars.DontDrawLaserPointer = false;
    MarbleTempVars.DontDrawMilling = false;
    MarbleTempVars.DontDrawMillingHead = false;
    MarbleTempVars.DontDrawSaw = false;
    MarbleTempVars.DontDrawWaterJet = false;
    if (!DrawAllTool)
    {
      MarbleTempVars.DontDrawAirDry = true;
      MarbleTempVars.DontDrawLaserPointer = true;
      MarbleTempVars.DontDrawMilling = true;
      MarbleTempVars.DontDrawMillingHead = true;
      MarbleTempVars.DontDrawSaw = true;
      MarbleTempVars.DontDrawWaterJet = true;
      if (ActiveToolType == MarbleToolType.Milling)
        MarbleTempVars.DontDrawMilling = false;
      if (ActiveToolType == MarbleToolType.MillingHead)
        MarbleTempVars.DontDrawMillingHead = false;
      if (ActiveToolType == MarbleToolType.Saw)
        MarbleTempVars.DontDrawSaw = false;
      if (ActiveToolType == MarbleToolType.WaterJet)
        MarbleTempVars.DontDrawWaterJet = false;
    }
    clsInit.appMarble.GetSimulationEntities(cam, machine, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count, ref EntList, ref Blocks, ref this.list_0);
    for (int index = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Count - 1; index >= 0; --index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index].Name == "ToolSaw")
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(index);
      else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index].Name == "ToolMilling")
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(index);
      else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[index].Name == "ToolMillingHead")
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.RemoveAt(index);
    }
    if (DrawAllTool)
    {
      for (int index = 0; index <= Blocks.Count - 1; ++index)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[index]);
    }
    else
    {
      for (int index = 0; index <= Blocks.Count - 1; ++index)
      {
        if (Blocks[index].Name == "ToolSaw" & ActiveToolType == MarbleToolType.Saw)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[index]);
        if (Blocks[index].Name == "ToolMilling" & ActiveToolType == MarbleToolType.Milling)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[index]);
        if (Blocks[index].Name == "ToolMillingHead" & ActiveToolType == MarbleToolType.MillingHead)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[index]);
        if (Blocks[index].Name == "WaterJet" & ActiveToolType == MarbleToolType.WaterJet)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(Blocks[index]);
      }
    }
    for (int index = 0; index <= EntList.Count - 1; ++index)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(EntList[index]);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void DrawTool(
    ToolBase5 ToolSaw,
    ToolBase5 ToolMilling,
    ToolBase5 ToolMillingHead,
    ToolBase5 ToolWaterJet,
    ToolBase5 ToolAirDry,
    ToolBase5 ToolLaserPointer,
    KinematicBase5 Kinematic,
    int EntityCount,
    ref List<Entity> EntList,
    ref List<Block> Blocks,
    ref List<int> MovePartIndex)
  {
    try
    {
      Block block1 = (Block) null;
      Block block2 = (Block) null;
      Block block3 = (Block) null;
      Block block4 = (Block) null;
      Block block5 = (Block) null;
      Block block6 = (Block) null;
      bool flag1 = true;
      bool flag2 = true;
      if (buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawHead)
      {
        flag1 = false;
        flag2 = false;
      }
      if (ToolSaw != null)
      {
        List<Mesh> refMeshes = new List<Mesh>();
        clsInit.appMW.CreateTool(ToolSaw, true, false, false, false, ref refMeshes);
        refMeshes[0].Regen(0.1);
        if (ToolSaw.Geometry.SocketThickness > ToolSaw.Geometry.Thickness)
        {
          Mesh mesh1 = new devDept.Eyeshot.Entities.Region((IList<ICurve>) new List<ICurve>()
          {
            (ICurve) new Circle(Plane.XY, ToolSaw.Geometry.Diameter / 2.0),
            (ICurve) new Circle(Plane.XY, ToolSaw.Geometry.Diameter / 2.0 - 20.0)
          }).ExtrudeAsMesh((ToolSaw.Geometry.SocketThickness - ToolSaw.Geometry.Thickness) / 2.0, 1.0, Mesh.natureType.RichSmooth);
          mesh1.Translate(0.0, 0.0, ToolSaw.Geometry.Thickness);
          mesh1.Regen(0.05);
          mesh1.Color = Color.Gray;
          refMeshes.Add(mesh1);
          Mesh mesh2 = new devDept.Eyeshot.Entities.Region((IList<ICurve>) new List<ICurve>()
          {
            (ICurve) new Circle(Plane.XY, ToolSaw.Geometry.Diameter / 2.0),
            (ICurve) new Circle(Plane.XY, ToolSaw.Geometry.Diameter / 2.0 - 20.0)
          }).ExtrudeAsMesh(-(ToolSaw.Geometry.SocketThickness - ToolSaw.Geometry.Thickness) / 2.0, 1.0, Mesh.natureType.RichSmooth);
          mesh2.Regen(0.05);
          mesh2.Color = Color.Gray;
          refMeshes.Add(mesh2);
        }
        block1 = new Block(nameof (ToolSaw));
        Mesh mesh = new Mesh();
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Regen(0.1);
          if (ToolSaw.Geometry.GeometryType == buClass.ToolType.Saw)
          {
            refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
            refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
            refMeshes[index].Regen(0.1);
            refMeshes[index].Translate(0.0, -Kinematic.RotateCenterOffsetOfC.Y - ToolSaw.Geometry.Thickness / 1.0, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance - clsMarble.activeKinematic.RotateCenterOffsetOfA.Z);
          }
          refMeshes[index].Regen(0.1);
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Color = Color.FromArgb((int) byte.MaxValue, refMeshes[index].Color);
          block1.Entities.Add((Entity) refMeshes[index]);
          block1.Entities.Regen();
        }
      }
      if (ToolMilling != null)
      {
        List<Mesh> refMeshes = new List<Mesh>();
        clsInit.appMW.CreateTool(ToolMilling, true, true, ToolMilling.Geometry.DrawArbor & flag1, ToolMilling.Geometry.DrawHolder & flag2, ref refMeshes);
        block2 = new Block(nameof (ToolMilling));
        Mesh mesh = new Mesh();
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Regen(0.1);
          double dx = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingToolOffsetX + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX;
          double dy = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingToolOffsetY + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY;
          double dz = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingToolOffsetZ + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetZ;
          if (ToolMilling.Purpose == ToolPurpose.Milling)
            refMeshes[index].Translate(dx, dy, dz);
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Color = Color.FromArgb((int) byte.MaxValue, refMeshes[index].Color);
          refMeshes[index].Regen(0.1);
          block2.Entities.Add((Entity) refMeshes[index]);
        }
      }
      if (ToolMillingHead != null)
      {
        List<Mesh> refMeshes = new List<Mesh>();
        clsInit.appMW.CreateTool(ToolMillingHead, true, true, false, false, ref refMeshes);
        block3 = new Block(nameof (ToolMillingHead));
        Mesh mesh = new Mesh();
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Regen(0.1);
          if (ToolMillingHead.Purpose == ToolPurpose.MillingHead)
          {
            refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
            refMeshes[index].Regen(0.1);
            refMeshes[index].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
            refMeshes[index].Regen(0.1);
            refMeshes[index].Translate(buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolXOffset, -ToolMillingHead.Geometry.Length + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolYOffset - Kinematic.RotateCenterOffsetOfC.Y, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance - clsMarble.activeKinematic.RotateCenterOffsetOfA.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawMillingHeadToolZOffset);
          }
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Color = Color.FromArgb((int) byte.MaxValue, refMeshes[index].Color);
          refMeshes[index].Regen(0.1);
          block3.Entities.Add((Entity) refMeshes[index]);
        }
      }
      if (ToolAirDry != null)
      {
        List<Mesh> refMeshes = new List<Mesh>();
        clsInit.appMW.CreateTool(ToolAirDry, true, true, false, false, ref refMeshes);
        block5 = new Block(nameof (ToolAirDry));
        Mesh mesh = new Mesh();
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Regen(0.1);
          double drawAirDryOffsetX = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawAirDryOffsetX;
          double drawAirDryOffsetY = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawAirDryOffsetY;
          double drawAirDryOffsetZ = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawAirDryOffsetZ;
          if (ToolMilling.Purpose == ToolPurpose.AirDry)
            refMeshes[index].Translate(drawAirDryOffsetX, drawAirDryOffsetY, drawAirDryOffsetZ);
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Color = Color.FromArgb((int) byte.MaxValue, refMeshes[index].Color);
          refMeshes[index].Regen(0.1);
          block5.Entities.Add((Entity) refMeshes[index]);
        }
      }
      if (ToolLaserPointer != null)
      {
        List<Mesh> refMeshes = new List<Mesh>();
        clsInit.appMW.CreateTool(ToolLaserPointer, true, true, false, false, ref refMeshes);
        block6 = new Block(nameof (ToolLaserPointer));
        Mesh mesh = new Mesh();
        for (int index = 0; index <= refMeshes.Count - 1; ++index)
        {
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Regen(0.1);
          double laserPointerOffsetX = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawLaserPointerOffsetX;
          double laserPointerOffsetY = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawLaserPointerOffsetY;
          double laserPointerOffsetZ = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawLaserPointerOffsetZ;
          if (ToolMilling.Purpose == ToolPurpose.Pointer)
            refMeshes[index].Translate(laserPointerOffsetX, laserPointerOffsetY, laserPointerOffsetZ);
          refMeshes[index].ColorMethod = colorMethodType.byEntity;
          refMeshes[index].Color = Color.FromArgb((int) byte.MaxValue, refMeshes[index].Color);
