  public void MoveSimPart(Pnt6DSimMove PntMove, bool SpindleDown, ToolBase5 Tool)
  {
    this.pnt6D_0.X = Tool.CamData.SimMoveOffset.X + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveXOffset;
    this.pnt6D_0.Y = Tool.CamData.SimMoveOffset.Y + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveYOffset;
    this.pnt6D_0.Z = Tool.CamData.SimMoveOffset.Z + buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulatioOfflineMoveZOffset;
    if (ccVars.Pages.Count > 0 && !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.IsAnimationRunning)
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
    for (int index = 0; index <= this.list_0.Count - 1; ++index)
    {
      if (this.list_0[index] <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
      {
        Entity entity1 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]];
        buMachinePart entity2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]] as buMachinePart;
        CustomData entityData = entity1.EntityData as CustomData;
        int num1 = this.list_0[index];
        if (this.list_0[index] >= 0 & this.list_0[index] <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
        {
          double num2 = 0.0;
          double num3 = 0.0;
          double num4 = 0.0;
          if (SpindleDown)
          {
            num2 = -buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetX;
            num3 = -buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimDrawSpindleOffsetY;
            num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimSpindleG54OffsetZ + buMarbleCalc.activeToolMilling.Geometry.Length;
          }
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]].GetType() == typeof (buTool))
          {
            buTool entity3 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]] as buTool;
            if (entity3.BlockName == "ToolMilling")
            {
              if (entity3.HeadNumber == 1)
              {
                num4 -= buMarbleCalc.activeToolMilling.Geometry.Length;
                if (SpindleDown)
                  num4 -= buMarbleCalc.varMarbleMachineSettings.SimulationSettings.ExternalMillingSpindleStroke;
                entity3.zPos = PntMove.Z + this.pnt6D_0.Z + num4;
              }
              if (entity3.HeadNumber == 2)
              {
                entity3.ARotation = true;
                entity3.centerPointOfA.X = 0.0;
                entity3.centerPointOfA.Y = 0.0;
                entity3.centerPointOfA.Z = 0.0;
                num4 -= buMarbleCalc.activeToolMilling.Geometry.Length;
                entity3.zPos = PntMove.Z;
              }
            }
            else
            {
              num4 = num4 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance + clsMarble.activeKinematic.RotateCenterOffsetOfA.Z;
              ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]]).zPos = PntMove.Z + clsMarble.activeKinematic.RotateCenterOffsetOfC.Z + buMarbleCalc.activeToolSaw.Geometry.Diameter / 2.0 + this.pnt6D_0.Z + num4;
            }
            ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]]).xPos = PntMove.X + this.pnt6D_0.X + num2;
            ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]]).yPos = PntMove.Y + this.pnt6D_0.Y + num3;
            ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]]).aPos = PntMove.A;
            ((buTool) ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]]).cPos = PntMove.C;
          }
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[this.list_0[index]].GetType() == typeof (buMachinePart) && entityData.typeDefination == entityTypeDefination.MachineBody | entityData.typeDefination == entityTypeDefination.MachineParts && entityData.ActionName != "Lathe")
          {
            entity2.xPos = PntMove.X + num2;
            entity2.yPos = PntMove.Y + num3;
            entity2.aPos = PntMove.A;
            entity2.cPos = PntMove.C;
            if (ccVars.SimMachine.MachineParts[index].PartName != "Spindle")
            {
              double num5 = num4 - buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimACAxesZDistance + clsMarble.activeKinematic.RotateCenterOffsetOfA.Z;
              entity2.zPos = PntMove.Z + this.pnt6D_0.Z + num5 + clsMarble.activeKinematic.RotateCenterOffsetOfC.Z + buMarbleCalc.activeToolSaw.Geometry.Diameter / 2.0;
            }
