              if (SpindleDown)
                num4 -= buMarbleCalc.varMarbleMachineSettings.SimulationSettings.ExternalMillingSpindleStroke;
              entity2.zPos = PntMove.Z + this.pnt6D_0.Z + num4;
            }
          }
        }
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void Sim_Tick(object sender, EventArgs e)
  {
    ToolBase5 toolBase5 = new ToolBase5();
    AppProcess.TickSave = 0;
    if (this.SimItemIndex >= 0 & this.SimItemIndex <= this.activeJob.Cams.Count - 1)
    {
      camTp cam = this.activeJob.Cams[this.SimItemIndex];
      if (clsMarble.lastSimToolPurpose == ToolPurpose.None)
      {
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
        MarbleToolType ActiveToolType;
        if (cam.Tool.Purpose == ToolPurpose.WaterJet)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          ActiveToolType = MarbleToolType.WaterJet;
        }
        else if (cam.Tool.Purpose == ToolPurpose.Milling)
        {
          MarbleTempVars.SimSpindlePistonDown = true;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.Milling;
        }
        else if (cam.Tool.Purpose == ToolPurpose.Milling5Axis)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.Milling;
        }
        else if (cam.Tool.Purpose == ToolPurpose.MillingHead)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = !buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawSawToolForMillingHeadOperation;
          ActiveToolType = MarbleToolType.MillingHead;
        }
        else
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = true;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.Saw;
        }
        MarbleTempVars.ActiveSimulationToolType = ActiveToolType;
        this.DeleteSimulationEntities();
        this.DrawSimulationEntities(false, true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, ActiveToolType);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
      }
      else
      {
        MarbleToolType ActiveToolType = MarbleToolType.Saw;
        bool flag = false;
        if (cam.Tool.Purpose == ToolPurpose.WaterJet & clsMarble.lastSimToolPurpose != ToolPurpose.WaterJet)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          ActiveToolType = MarbleToolType.WaterJet;
          flag = true;
        }
        if (cam.Tool.Purpose == ToolPurpose.Saw & clsMarble.lastSimToolPurpose != ToolPurpose.Saw)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = true;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.Saw;
          flag = true;
        }
        if (cam.Tool.Purpose == ToolPurpose.Milling & clsMarble.lastSimToolPurpose != ToolPurpose.Milling)
        {
          MarbleTempVars.SimSpindlePistonDown = true;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.MillingHead;
          flag = true;
        }
        if (cam.Tool.Purpose == ToolPurpose.Milling5Axis & clsMarble.lastSimToolPurpose != ToolPurpose.Milling5Axis)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = false;
          ActiveToolType = MarbleToolType.Milling;
          flag = true;
        }
        if (cam.Tool.Purpose == ToolPurpose.MillingHead & clsMarble.lastSimToolPurpose != ToolPurpose.MillingHead)
        {
          MarbleTempVars.SimSpindlePistonDown = false;
          MarbleTempVars.DontDrawMillingHead = false;
          MarbleTempVars.DontDrawSaw = !buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawSawToolForMillingHeadOperation;
          ActiveToolType = MarbleToolType.MillingHead;
          flag = true;
        }
        MarbleTempVars.ActiveSimulationToolType = ActiveToolType;
        if (flag)
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
          this.DeleteSimulationEntities();
          this.DrawSimulationEntities(false, true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, ActiveToolType);
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
        }
      }
      if (cam != null)
      {
        if (this.SimIndex >= 0 & this.SimIndex < cam.SimilationPoint.SimMove.Count - 1)
        {
          MarbleTempVars.SimulationPoint.X = cam.SimilationPoint.SimMove[this.SimIndex].X;
          MarbleTempVars.SimulationPoint.Y = cam.SimilationPoint.SimMove[this.SimIndex].Y;
          MarbleTempVars.SimulationPoint.Z = cam.SimilationPoint.SimMove[this.SimIndex].Z;
          MarbleTempVars.SimulationPoint.A = cam.SimilationPoint.SimMove[this.SimIndex].A;
          MarbleTempVars.SimulationPoint.C = cam.SimilationPoint.SimMove[this.SimIndex].C;
          if (MarbleTempVars.SimulationPoint.ToolName == null)
            MarbleTempVars.SimulationPoint.ToolName = "";
          for (int index = 0; index <= ccVars.Tools[0].Tools.Count - 1; ++index)
          {
            if (!(ccVars.Tools[0].Tools[index].Data.Name == MarbleTempVars.SimulationPoint.ToolName) || new ToolBase5(ccVars.Tools[0].Tools[index]).Geometry.GeometryType != buClass.ToolType.Saw)
              ;
          }
          if (MarbleTempVars.SimulationPoint.MCode == 40)
            MarbleTempVars.SimSpindlePistonDown = false;
          if (MarbleTempVars.SimulationPoint.MCode == 41)
            MarbleTempVars.SimSpindlePistonDown = true;
          this.MoveSimPart(MarbleTempVars.SimulationPoint, MarbleTempVars.SimSpindlePistonDown, cam.Tool);
          // ISSUE: reference to a compiler-generated field
          if (this.marbleSimCoordinateUpdated_0 != null)
          {
            // ISSUE: reference to a compiler-generated field
            this.marbleSimCoordinateUpdated_0(cam.SimilationPoint.SimMove[this.SimIndex], cam.Tool, -1);
          }
          if (this.SimIndex == cam.SimilationPoint.SimMove.Count - 1 && cam.SimilationPoint.MoveCommand == SimulationMoveCommand.DrawMaterial)
          {
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
            this.doDrawActiveJob();
          }
          this.SimIndex += clsMarble.SimStep;
        }
        else
        {
          if (cam.SimilationPoint.MoveCommand == SimulationMoveCommand.DrawMaterial)
          {
            if ((cam.SimilationPoint.Obj1 == null ? 0 : (cam.SimilationPoint.Obj1.GetType() == typeof (List<MaterialBase5>) ? 1 : 0)) != 0)
            {
              if (MarbleTempVars.tempMaterials == null)
                MarbleTempVars.tempMaterials = new List<MaterialBase5>();
              MarbleTempVars.tempMaterials.Clear();
              MaterialBase5.Copy((List<MaterialBase5>) cam.SimilationPoint.Obj1, ref MarbleTempVars.tempMaterials);
            }
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
            this.DeleteAllMaterials();
            this.AddTempMaterials();
            this.DeleteSimulationEntities();
            this.DrawSimulationEntities(false, true, buMarbleCalc.varMarbleMachineSettings.SimulationSettings.DrawAllTool, MarbleTempVars.ActiveSimulationToolType);
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation();
          }
          ++this.SimItemIndex;
          this.SimIndex = 0;
        }
        clsMarble.lastSimToolPurpose = cam.Tool.Purpose;
      }
      else
      {
        ++this.SimToolIndex;
        this.SimIndex = 0;
        if (this.SimToolIndex >= 2)
        {
          this.SimToolIndex = 0;
          ++this.SimItemIndex;
        }
      }
    }
    else
    {
      MarbleTempVars.SimSpindlePistonDown = false;
      this.SimIndex = 0;
      ++this.SimItemIndex;
      if (this.SimItemIndex >= this.activeJob.Items.Count)
      {
        this.SimIndex = -1;
        this.SimItemIndex = -1;
        this.timSim.Enabled = false;
        this.DeleteSimulationEntities();
      }
    }
    if (!this.StepMove)
      return;
    this.timSim.Enabled = false;
  }

  public void SimulationCommand(object Data1, object Data2, object Data3)
  {
    if ((SimulationCommands) Data1 == SimulationCommands.Start)
    {
      clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
      clsInit.appMarble.cmdStartSimulation();
    }
    if ((SimulationCommands) Data1 == SimulationCommands.Stop)
    {
      clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
      clsInit.appMarble.cmdStopSimulation();
    }
    if ((SimulationCommands) Data1 == SimulationCommands.Pause)
    {
      clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
      clsInit.appMarble.cmdStopSimulation();
    }
    if ((SimulationCommands) Data1 == SimulationCommands.Next)
    {
      clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
      clsInit.appMarble.Sim_Tick((object) null, (EventArgs) null);
    }
    if ((SimulationCommands) Data1 == SimulationCommands.Previous)
    {
      clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
      clsInit.appMarble.SimIndex -= clsMarble.SimStep * 2;
      clsInit.appMarble.Sim_Tick((object) null, (EventArgs) null);
    }
    if ((SimulationCommands) Data1 != SimulationCommands.StepChanged)
      return;
    clsMarble.SimStep = Convert.ToInt32(Data2.ToString());
  }

  public void DrawPreview(List<Entity> refEntities)
  {
    if (this.timSim.Enabled || clsItem.ModelMainPreview == null)
      return;
    clsItem.ModelMainPreview.Entities.Clear();
    for (int index = 0; index <= refEntities.Count - 1; ++index)
      clsItem.ModelMainPreview.Entities.Add(refEntities[index]);
    clsItem.ModelMainPreview.SetView(viewType.Trimetric);
    clsItem.ModelMainPreview.ZoomFit(10);
    clsItem.ModelMainPreview.Invalidate();
  }

  public void DrawPreview(ToolBase5 Tool, int ItemIndex)
  {
    if (this.timSim.Enabled)
      ;
    if (clsItem.ModelMainPreview == null)
      return;
    clsItem.ModelMainPreview.ActiveViewport.DisplayMode = displayType.Rendered;
    clsItem.ModelMainPreview.Rendered.ShadowMode = shadowType.None;
    for (int index1 = 0; index1 <= buEyeItems.viewportCadCam.Materials.Count - 1; ++index1)
    {
      bool flag = false;
      for (int index2 = 0; index2 <= clsItem.ModelMainPreview.Materials.Count - 1; ++index2)
      {
        if (buEyeItems.viewportCadCam.Materials[index1].Name == clsItem.ModelMainPreview.Materials[index2].Name)
          flag = true;
      }
      if (!flag)
      {
        Material material = (Material) buEyeItems.viewportCadCam.Materials[index1].Clone();
        clsItem.ModelMainPreview.Materials.Add(material);
      }
    }
    for (int index3 = 0; index3 <= buEyeItems.viewportCadCam.Layers.Count - 1; ++index3)
    {
      bool flag = false;
      for (int index4 = 0; index4 <= clsItem.ModelMainPreview.Layers.Count - 1; ++index4)
      {
        if (buEyeItems.viewportCadCam.Layers[index3].Name == clsItem.ModelMainPreview.Layers[index4].Name)
          flag = true;
      }
      if (!flag)
      {
        Layer layer = (Layer) buEyeItems.viewportCadCam.Layers[index3].Clone();
        clsItem.ModelMainPreview.Layers.Add(layer);
      }
    }
    if (Tool != null)
    {
      clsItem.ModelMainPreview.Entities.Clear();
      List<Mesh> refMeshes = new List<Mesh>();
      clsInit.appMW.CreateTool(Tool, true, false, false, false, ref refMeshes);
      for (int index = 0; index <= refMeshes.Count - 1; ++index)
        clsItem.ModelMainPreview.Entities.Add((Entity) refMeshes[index]);
    }
    else if (ItemIndex == -1)
    {
      clsItem.ModelMainPreview.Entities.Clear();
      for (int index = 0; index <= buEyeItems.viewportCadCam.Entities.Count - 1; ++index)
      {
        if ((buEyeItems.viewportCadCam.Entities[index].EntityData == null ? 0 : (buEyeItems.viewportCadCam.Entities[index].EntityData is CustomData ? 1 : 0)) != 0)
        {
          CustomData entityData = buEyeItems.viewportCadCam.Entities[index].EntityData as CustomData;
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(buEyeItems.viewportCadCam.Entities[index], ref copiedEntity);
          if (copiedEntity.GetType() != typeof (devDept.Eyeshot.Entities.Text) & copiedEntity.GetType() != typeof (BlockReference))
            clsItem.ModelMainPreview.Entities.Add(copiedEntity);
        }
      }
    }
    else
    {
      clsItem.ModelMainPreview.Entities.Clear();
      for (int index = 0; index <= buEyeItems.viewportCadCam.Entities.Count - 1; ++index)
      {
        if ((buEyeItems.viewportCadCam.Entities[index].EntityData == null ? 0 : (buEyeItems.viewportCadCam.Entities[index].EntityData is CustomData ? 1 : 0)) != 0 && (buEyeItems.viewportCadCam.Entities[index].EntityData as CustomData).GroupIdIndex == ItemIndex)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(buEyeItems.viewportCadCam.Entities[index], ref copiedEntity);
          if (copiedEntity.GetType() != typeof (devDept.Eyeshot.Entities.Text) & copiedEntity.GetType() != typeof (BlockReference))
            clsItem.ModelMainPreview.Entities.Add(copiedEntity);
        }
      }
    }
    clsItem.ModelMainPreview.SetView(viewType.Trimetric);
    clsItem.ModelMainPreview.ZoomFit();
    clsItem.ModelMainPreview.Invalidate();
  }

