  public Design doDrawCameraImage(Design Viewport)
  {
    try
    {
      for (int index = 0; index <= Viewport.Entities.Count - 1; ++index)
      {
        if (Viewport.Entities[index] is Picture & Viewport.Entities[index].EntityData != null && (Viewport.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.CameraImage)
          Viewport.Entities[index].Selected = true;
      }
      Viewport.Entities.DeleteSelected();
      if (MarbleTempVars.CameraImage != null)
      {
        if (MarbleTempVars.CameraImage.EntityData == null)
          MarbleTempVars.CameraImage.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.CameraImage
          };
        else if (MarbleTempVars.CameraImage.EntityData.GetType() != typeof (CustomData))
          MarbleTempVars.CameraImage.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.CameraImage
          };
        Viewport.Entities.Add(MarbleTempVars.CameraImage);
      }
      return Viewport;
    }
    catch (Exception ex)
    {
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
      return Viewport;
    }
  }

  public void EntitiesSelectableStates(
    bool EdgeSelectable,
    bool OperationSelectable,
    bool CollapseSelectable,
    bool SlatSelectable,
    bool VacuumSelectable)
  {
    MarbleTempVars.selectableCollapse = CollapseSelectable;
    MarbleTempVars.selectableSlat = SlatSelectable;
    MarbleTempVars.selectableEdge = EdgeSelectable;
    MarbleTempVars.selectableOperation = OperationSelectable;
    MarbleTempVars.selectableVacuum = VacuumSelectable;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      entity.Selectable = false;
      if ((entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0)
      {
        CustomData entityData = entity.EntityData as CustomData;
        if ((entityData.Tags == null ? 0 : (entityData.Tags == "Solid" ? 1 : 0)) != 0)
          entity.Selectable = OperationSelectable;
        if ((entityData.Tags == null ? 0 : (entityData.Tags == "Edge" ? 1 : 0)) != 0)
          entity.Selectable = EdgeSelectable;
        if ((entityData.Tags == null ? 0 : (entityData.Tags == "VacuumCut" ? 1 : 0)) != 0)
          entity.Selectable = VacuumSelectable;
        if ((entityData.Tags == null ? 0 : (entityData.Tags == "Slat" ? 1 : 0)) != 0)
          entity.Selectable = SlatSelectable;
        if ((entityData.Tags == null ? 0 : (entityData.Tags == "Collapse" ? 1 : 0)) != 0)
          entity.Selectable = CollapseSelectable;
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.UpdateVisibleSelection();
  }

  public void doDrawActiveJob()
  {
    try
    {
      if (!AppBool.EditMode)
        clsInit.cMarble.GetMaterialBorderLimits(this.activeJob, buMarbleCalc.activeToolSaw);
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null)
        {
          CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
          if (entityData.typeDefination == entityTypeDefination.MarbleItem)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if (entityData.typeDefination == entityTypeDefination.Material)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if (entityData.typeDefination == entityTypeDefination.TempDraw)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if ((entityData.typeDefination != entityTypeDefination.Dimension ? 0 : (this.activeJob.Items.Count == 0 ? 1 : 0)) != 0)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
        }
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count == 0)
      {
        Entity entWood = (Entity) null;
        if (buMarbleCalc.varMarbleSettings.DrawWoodBase)
        {
          this.CreateWoodMaterial(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, buMarbleCalc.varMarbleMachineSettings.BaseWoodThickness, buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset + buMarbleCalc.varOperation.settingMarbleCam.TargetZ, true, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[MarbleTempVars.layerWood.Index].Name, ref entWood);
          entWood.Selectable = false;
          if (entWood != null)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entWood);
        }
      }
      List<Entity> collection = new List<Entity>();
      for (int index1 = 0; index1 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index1)
      {
        MarbleItem MI = clsInit.appMarble.activeJob.Items[index1];
        if (MI.ItemEntities.SolidEntity != null)
        {
          for (int index2 = 0; index2 <= MI.ItemEntities.SolidEntity.Count - 1; ++index2)
          {
            Entity copiedEntity = (Entity) null;
            buEntity.Copy(MI.ItemEntities.SolidEntity[index2], ref copiedEntity);
            Entity entity = clsInit.cMarble.SetEntityData(copiedEntity, MI, index1, index2, -1, "Solid", entityTypeDefination.MarbleItem, MarbleTempVars.layerMarblePart.Name, MarbleTempVars.selectableOperation, 1.0, Color.FromArgb(buMarbleCalc.varMarbleColorSettings.SolidTranperancy, copiedEntity.Color));
            ((CustomData) entity.EntityData).Command = clsInit.cMarble.SetEntityCommand(MarbleCommandsEntity.Operation.ToString(), MI.ID, -1, -1, -1, -1, "", "");
            entity.Translate(MI.OffsetX, MI.OffsetY);
            collection.Add(entity);
          }
        }
        if (MI.ItemEntities.SolidInsideEntity != null)
        {
          for (int index3 = 0; index3 <= MI.ItemEntities.SolidInsideEntity.Count - 1; ++index3)
