            ((CustomData) entity.EntityData).Command = clsInit.cMarble.SetEntityCommand(MarbleCommandsEntity.Operation.ToString(), MI.ID, -1, -1, -1, -1, "", "");
            entity.Translate(MI.OffsetX, MI.OffsetY);
