  public void AddTempMaterials()
  {
    List<Entity> collection = new List<Entity>();
    if ((MarbleTempVars.tempMaterials == null ? 0 : (MarbleTempVars.tempMaterials.Count > 0 ? 1 : 0)) == 0)
      return;
    for (int index = 0; index <= MarbleTempVars.tempMaterials.Count - 1; ++index)
    {
      MaterialBase5 tempMaterial = MarbleTempVars.tempMaterials[index];
      Entity copiedEntity = (Entity) null;
      buEntity.Copy(MarbleTempVars.tempMaterials[index].Entities[0], ref copiedEntity);
      copiedEntity = clsInit.cMarble.SetEntityData(copiedEntity, (MarbleItem) null, -1, index, -1, "VacuumMaterial", entityTypeDefination.Material, MarbleTempVars.layerDrawing.Name, false, 1.0, Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemVacuumCutMaterial.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemVacuumCutMaterial.Color));
      ((CustomData) copiedEntity.EntityData).Sequence = index;
      copiedEntity.Translate(tempMaterial.OffsetX, tempMaterial.OffsetY, buMarbleCalc.varMarbleSettings.ImageZPosition + 0.02);
      collection.Add(copiedEntity);
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.AddRange((IEnumerable<Entity>) collection);
  }

  public void AddMainMaterials()
  {
    List<Entity> collection = new List<Entity>();
    if ((clsInit.appMarble.activeJob.Material == null ? 0 : (clsInit.appMarble.activeJob.Material.Enable ? 1 : 0)) != 0)
    {
      if (clsInit.appMarble.activeJob.Material.matImage != null)
      {
        byte[] byteArray = clsInit.appMarble.activeJob.Material.matImage.ToByteArray();
        Picture picture = new Picture(Plane.XY, clsInit.appMarble.activeJob.Material.Size.Width, clsInit.appMarble.activeJob.Material.Size.Height, byteArray);
        picture.Translate(0.0, 0.0, buMarbleCalc.varMarbleSettings.ImageZPosition);
        picture.Selectable = false;
        picture.LayerName = MarbleTempVars.layerMarbleSheet.Name;
        picture.EntityData = (object) new CustomData()
        {
          typeDefination = entityTypeDefination.Material
        };
        picture.Selectable = false;
        collection.Add((Entity) picture);
      }
      if (clsInit.appMarble.activeJob.Material.Entities.Count > 0)
      {
        for (int index = 0; index <= clsInit.appMarble.activeJob.Material.Entities.Count - 1; ++index)
        {
          clsInit.appMarble.activeJob.Material.Entities[index].Selected = false;
          collection.Add(clsInit.appMarble.activeJob.Material.Entities[index]);
        }
        if (buMarbleCalc.varMarbleDrawSettings.DrawMaterialDimension)
        {
          double num = clsInit.appMarble.activeJob.Material.Size.Width;
          if (clsInit.appMarble.activeJob.Material.Size.Height < num)
            num = clsInit.appMarble.activeJob.Material.Size.Height;
          double textHeight = num * 0.08;
          if (textHeight < 10.0)
            textHeight = 10.0;
          LinearDim linearDim1 = new LinearDim(Plane.XY, new Point3D(), new Point3D(clsInit.appMarble.activeJob.Material.Size.Width, 0.0, 0.0), new Point3D(clsInit.appMarble.activeJob.Material.Size.Width / 2.0, -200.0, 0.0), textHeight);
          linearDim1.TextOverride = $"{buLangTranslate.preChar.Width}: {linearDim1.Distance.ToString()}";
          linearDim1.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Material
          };
          linearDim1.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
          collection.Add((Entity) linearDim1);
          Plane drawingPlane = (Plane) null;
          clsInit.cVector5.LinearDimCalculate(new Point3D(0.0, 0.0), new Point3D(0.0, clsInit.appMarble.activeJob.Material.Size.Height), new Point3D(-200.0, clsInit.appMarble.activeJob.Material.Size.Height / 2.0), 100.0, Plane.XY, ref drawingPlane);
          LinearDim linearDim2 = new LinearDim(drawingPlane, new Point3D(), new Point3D(0.0, clsInit.appMarble.activeJob.Material.Size.Height, 0.0), new Point3D(-200.0, clsInit.appMarble.activeJob.Material.Size.Height / 2.0, 0.0), textHeight);
          linearDim2.TextOverride = $"{buLangTranslate.preChar.Height}: {linearDim2.Distance.ToString()}";
          linearDim2.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Material
          };
          linearDim2.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
          collection.Add((Entity) linearDim2);
          clsInit.cVector5.LinearDimCalculate(new Point3D(0.0, 0.0, 0.0), new Point3D(0.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth), new Point3D(-200.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth / 2.0), 100.0, Plane.XZ, ref drawingPlane);
          LinearDim linearDim3 = new LinearDim(drawingPlane, new Point3D(0.0, 0.0, 0.0), new Point3D(0.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth), new Point3D(-200.0, 0.0, clsInit.appMarble.activeJob.Material.Size.Depth / 2.0), textHeight);
          linearDim3.TextOverride = $"{buLangTranslate.preChar.Depth}: {linearDim3.Distance.ToString()}";
          linearDim3.EntityData = (object) new CustomData()
          {
            typeDefination = entityTypeDefination.Material
          };
          linearDim3.Color = buMarbleCalc.varMarbleColorSettings.colorMaterialDimension.Color;
          collection.Add((Entity) linearDim3);
        }
      }
    }
    if (MarbleTempVars.MaterialLimits.Count >= 3 & buMarbleCalc.varMarbleSettings.ShowMaterialLimits)
    {
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) MarbleTempVars.MaterialLimits);
      linearPath.LayerName = MarbleTempVars.layerMarbleSheet.Name;
      linearPath.EntityData = (object) new CustomData()
      {
        typeDefination = entityTypeDefination.Material
      };
      linearPath.Selectable = false;
      linearPath.Color = Color.Cyan;
      linearPath.ColorMethod = colorMethodType.byEntity;
      linearPath.LineWeight = 3f;
      linearPath.LineWeightMethod = colorMethodType.byEntity;
      collection.Add((Entity) linearPath);
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.AddRange((IEnumerable<Entity>) collection);
  }

  public void AddDimension(Entity Ent, bool isLinear)
  {
    Ent.ColorMethod = colorMethodType.byEntity;
    Ent.LineTypeMethod = colorMethodType.byEntity;
    Ent.LineWeightMethod = colorMethodType.byEntity;
    Ent.Color = buMarbleCalc.varMarbleEntitiesSettings.DimensionColor;
    Ent.LineWeight = Convert.ToSingle(buMarbleCalc.varMarbleEntitiesSettings.DimensionThickness);
    Ent.LayerName = "Default";
    if ((Ent.EntityData == null ? 0 : (Ent.EntityData is CustomData ? 1 : 0)) != 0)
    {
      ((CustomData) Ent.EntityData).typeDefination = entityTypeDefination.Dimension;
      if (isLinear)
        ((CustomData) Ent.EntityData).infoString = buLangTranslate.preDef.Linear;
      else
        ((CustomData) Ent.EntityData).infoString = buLangTranslate.preDef.Aligned;
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void DeleteAllDimension()
  {
    buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
    dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
    dialogMessageBoxYesNo.Init(buLangTranslate.preDef.DeleteAll, buLangTranslate.preSentences.DoYouWanttoDeleteAllDimension);
    int num = (int) dialogMessageBoxYesNo.ShowDialog();
    if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
      return;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Dimension)
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void DeleteAllMaterials()
  {
