    dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
    dialogMessageBoxYesNo.Init(buLangTranslate.preDef.DeleteAll, buLangTranslate.preSentences.DoYouWanttoDeleteAllDimension);
    int num1 = (int) dialogMessageBoxYesNo.ShowDialog();
    if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
      return;
    int num2 = 0;
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Dimension)
      {
        if (num2 == Index)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
        ++num2;
      }
    }
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void CreateMaterialsAndLayers(string pathWood, string pathMarble, ref ViewportCC viewport)
  {
    List<string> Files1 = new List<string>();
    buFile5.GetFilesInDirectory(pathWood, "png", ref Files1);
    buFile5.GetFilesInDirectory(pathWood, "jpg", ref Files1);
    viewport.Layers.Clear();
    if (Files1.Count > 0)
    {
      string str = Files1[0];
      for (int index = 0; index <= Files1.Count - 1; ++index)
      {
        string lower = buFile5.getFileNameWithoutExtension(Files1[index]).Trim().ToLower();
        if (buMarbleCalc.varMarbleRunSettings.WoodTextureName.ToLower() == lower)
          str = Files1[index];
      }
      buMarbleCalc.varMarbleRunSettings.WoodTextureName = buFile5.getFileNameWithoutExtension(str).Trim();
      Bitmap image = new Bitmap(str);
      Material material = new Material(buMarbleCalc.varMarbleRunSettings.WoodTextureName, Color.FromArgb(100, 100, 100), Color.White, 1f, image.ToByteArray())
      {
        LinearUnits = linearUnitsType.Millimeters,
        MassUnits = massUnitsType.Kilograms,
        Density = 6E-07,
        TextureLength = 2000f,
        Environment = 0.01f
      };
      viewport.Materials.Add(material);
      viewport.Layers.Add(new Layer(MarbleTempVars.layerWood.Name, MarbleTempVars.layerWood.Color)
      {
        LineWeight = (float) MarbleTempVars.layerWood.Thickness,
        MaterialName = material.Name
      });
    }
    viewport.Layers.Add(new Layer(MarbleTempVars.layerMarbleSheet.Name, Color.FromArgb(buMarbleCalc.varMarbleSettings.MarbleMaterialTransparan, MarbleTempVars.layerMarbleSheet.Color))
    {
      LineWeight = (float) MarbleTempVars.layerMarbleSheet.Thickness
    });
    List<string> Files2 = new List<string>();
    buFile5.GetFilesInDirectory(pathMarble, "png", ref Files2);
    buFile5.GetFilesInDirectory(pathMarble, "jpg", ref Files2);
    if (Files2.Count > 0)
    {
      string str = Files2[0];
      for (int index = 0; index <= Files2.Count - 1; ++index)
      {
        string lower = buFile5.getFileNameWithoutExtension(Files2[index]).Trim().ToLower();
        if (buMarbleCalc.varMarbleRunSettings.MarbleTextureName.ToLower() == lower)
          str = Files2[index];
      }
      buMarbleCalc.varMarbleRunSettings.MarbleTextureName = buFile5.getFileNameWithoutExtension(str).Trim();
      Bitmap image = new Bitmap(str);
      Material material = new Material(buMarbleCalc.varMarbleRunSettings.MarbleTextureName, Color.FromArgb(100, 100, 100), Color.White, 1f, image.ToByteArray())
      {
        LinearUnits = linearUnitsType.Millimeters,
        MassUnits = massUnitsType.Kilograms,
        Density = 6E-07,
        TextureLength = 2000f,
        Environment = 0.01f
      };
      viewport.Materials.Add(material);
      viewport.Layers.Add(new Layer(MarbleTempVars.layerMarblePart.Name, MarbleTempVars.layerMarblePart.Color)
      {
        LineWeight = (float) MarbleTempVars.layerMarblePart.Thickness,
        MaterialName = material.Name
      });
    }
    else
      viewport.Layers.Add(new Layer(MarbleTempVars.layerMarblePart.Name, MarbleTempVars.layerMarblePart.Color)
      {
        LineWeight = (float) MarbleTempVars.layerDrawing.Thickness
      });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerDrawing.Name, MarbleTempVars.layerDrawing.Color)
    {
      LineWeight = (float) MarbleTempVars.layerDrawing.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerCutting.Name, MarbleTempVars.layerCutting.Color)
    {
      LineWeight = (float) MarbleTempVars.layerCutting.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerMachine.Name, MarbleTempVars.layerMachine.Color)
    {
      LineWeight = (float) MarbleTempVars.layerMachine.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerShape.Name, MarbleTempVars.layerShape.Color)
    {
      LineWeight = (float) MarbleTempVars.layerShape.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layer3D.Name, MarbleTempVars.layer3D.Color)
    {
      LineWeight = (float) MarbleTempVars.layer3D.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerCam.Name, Color.Red)
    {
      LineWeight = (float) MarbleTempVars.layerCam.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerAngle.Name, MarbleTempVars.layerAngle.Color)
    {
      LineWeight = (float) MarbleTempVars.layerAngle.Thickness
    });
    viewport.Layers.Add(new Layer(MarbleTempVars.layerEngrave.Name, MarbleTempVars.layerEngrave.Color)
    {
      LineWeight = (float) MarbleTempVars.layerEngrave.Thickness
    });
    if (viewport.Layers[0].Name == "Default")
      viewport.Layers.RemoveAt(0);
    ccVars.Pages[ccVars.PageIndex].Layers.Clear();
    for (int index = 0; index <= viewport.Layers.Count - 1; ++index)
    {
      LayerBase5 buLayer = new LayerBase5();
      buConversion5.eyeLayerTobuLayer(viewport.Layers[index], ref buLayer);
      ccVars.Pages[ccVars.PageIndex].Layers.Add(buLayer);
    }
  }

