  public void CreateWoodMaterial(
    double Width,
    double Height,
    double Depth,
    double OffsetZ,
    bool TopOnZero,
    string LayerName,
    ref Entity entWood)
  {
    entWood = (Entity) Brep.CreateBox(Width, Height, Depth);
    if (TopOnZero)
      entWood.Translate(0.0, 0.0, -Depth + OffsetZ);
    else
      entWood.Translate(0.0, 0.0, OffsetZ);
    entWood.LayerName = LayerName;
    entWood.EntityData = (object) new CustomData()
    {
      ActionName = "woodbase",
      infoWidth = Width,
      infoHeight = Height,
      infoDepth = Depth,
      typeDefination = entityTypeDefination.Base
    };
  }

  public void CreateMarbleMaterial(
    buEntitiesGroup entGroup,
    double Thickness,
    Point3D Offset,
    bool TopOnZero,
    string LayerName,
    ref Entity entMarble)
  {
    clsInit.cVector5.surfaceFromOutterInner(entGroup, Thickness, ref entMarble, Inside: buMarbleCalc.varImageSettings.SheetInnerMakeItHoleas3D, AsMesh: false);
    if (entMarble == null)
      return;
    if (TopOnZero)
      entMarble.Translate(Offset.X, Offset.Y, -Thickness + Offset.Z);
    else
      entMarble.Translate(Offset.X, Offset.Y, Offset.Z);
    entMarble.LayerName = LayerName;
    entMarble.EntityData = (object) new CustomData()
    {
      ActionName = "marblematerial",
      infoDepth = Thickness,
      typeDefination = entityTypeDefination.Sheet
    };
  }

  public void AddOrUpdateMarbleSheet(List<Entity> entSheets, buEntitiesGroup Group)
  {
    for (int index = 0; index <= buEyeItems.viewportCadCam.Entities.Count - 1; ++index)
    {
      Entity entity = buEyeItems.viewportCadCam.Entities[index];
      if ((entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0 && (entity.EntityData as CustomData).typeDefination == entityTypeDefination.Sheet)
        buEyeItems.viewportCadCam.Entities[index].Selected = true;
    }
    buEyeItems.viewportCadCam.Entities.DeleteSelected();
    for (int index = 0; index <= entSheets.Count - 1; ++index)
      buEyeItems.viewportCadCam.Entities.Add(entSheets[index]);
    if (Group != null && Group.Inside != null)
    {
      for (int index1 = 0; index1 <= Group.Inside.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= Group.Inside[index1].Entities.Count - 1; ++index2)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Group.Inside[index1].Entities[index2], ref copiedEntity);
          if (copiedEntity != null)
          {
            copiedEntity.ColorMethod = colorMethodType.byEntity;
            copiedEntity.Color = Color.Red;
            copiedEntity.LineTypeMethod = colorMethodType.byEntity;
            copiedEntity.LineWeight = 3f;
            copiedEntity.Selectable = false;
            copiedEntity.EntityData = (object) new CustomData()
            {
              typeDefination = entityTypeDefination.Sheet
            };
            buEyeItems.viewportCadCam.Entities.Add(copiedEntity);
          }
        }
      }
    }
    buEyeItems.viewportCadCam.Invalidate();
  }

