  public void Job_AfterSelect(object sender, TreeViewEventArgs e)
  {
    buCadCamResVer5.TreeNodeSettings selectedNode = (buCadCamResVer5.TreeNodeSettings) ((TreeView) sender).SelectedNode;
    buMarbleCalc.SelectedItem.ActiveItem.indexCamList = -1;
    string command = selectedNode.Command;
    switch (Class5.smethod_167(command))
    {
      case 2039528:
        if (!(command == "CamNode"))
          break;
        buMarbleCalc.SelectedItem.SelectionItems.Clear();
        buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand = MarbleOperationSelectionCommand.CamNode;
        buMarbleCalc.SelectedItem.ActiveItem.indexEdge = -1;
        buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub = -1;
