          node.Checked = true;
          this.tnPanel.Nodes.Add((TreeNode) node);
        }
        if (this.tnPanel != null)
        {
          this.tnPanel.Expand();
          this.tnCamList.Expand();
          buMarbleControls.treeJob.Nodes.Add((TreeNode) this.tnPanel);
        }
        this.JobUpdating = false;
      }
    }
    catch (Exception ex)
    {
      this.JobUpdating = false;
      buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buException.throwException(ex, MethodBase.GetCurrentMethod().Name, true, "");
    }
  }

  public void JobDelete()
  {
    if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.Item && buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexItem <= this.activeJob.Items.Count - 1)
      this.doDeleteItems(false, this.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem].ID);
    if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.CamNode && buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexItem <= this.activeJob.Items.Count - 1)
    {
      MarbleItem marbleItem = this.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
      if (buMarbleCalc.SelectedItem.ActiveItem.indexCam >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexCam <= marbleItem.CamList.Count - 1)
        this.doDeleteCam(false, buMarbleCalc.SelectedItem.ActiveItem.indexItem, buMarbleCalc.SelectedItem.ActiveItem.indexCam);
