  public void JobCamEnableDisable()
  {
    if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.CamListNode || !(buMarbleCalc.SelectedItem.ActiveItem.indexCamList >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= this.activeJob.Cams.Count - 1))
      return;
    camTp cam = this.activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
    string str = !cam.Enable ? buLangTranslate.preDef.Enable : buLangTranslate.preDef.Disable;
    buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
    dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
    dialogMessageBoxYesNo.Init($"{buLangTranslate.preDef.Enable} / {buLangTranslate.preDef.Disable}", $"{cam.Name}{Environment.NewLine}{buLangTranslate.preSentences.DoYouWantToChange}, {str}");
    int num = (int) dialogMessageBoxYesNo.ShowDialog();
    if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
      return;
    cam.Enable = !cam.Enable;
    this.activeJob.isGCodeCreated = false;
    this.activeJob.isSimulationDone = false;
    if ((this.tnPanel == null ? 0 : (this.tnPanel.Nodes != null ? 1 : 0)) == 0)
      return;
    for (int index = 0; index <= this.tnPanel.Nodes.Count - 1; ++index)
    {
      buCadCamResVer5.TreeNodeSettings node1 = this.tnPanel.Nodes[index] as buCadCamResVer5.TreeNodeSettings;
      if (node1.Command == MarbleOperationSelectionCommand.CamList.ToString())
      {
        buCadCamResVer5.TreeNodeSettings node2 = node1.Nodes[buMarbleCalc.SelectedItem.ActiveItem.indexCamList] as buCadCamResVer5.TreeNodeSettings;
        if (!cam.Enable)
        {
          node2.ForeColor = Color.Red;
          node2.NodeFont = new Font("Microsoft Sans Serif", 10f, FontStyle.Bold | FontStyle.Strikeout);
        }
        else
        {
          node2.ForeColor = Color.Black;
          node2.NodeFont = new Font("Microsoft Sans Serif", 10f, FontStyle.Bold);
        }
      }
    }
  }

  public void JobCamMoveUpDown(bool Up)
  {
    if (buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand != MarbleOperationSelectionCommand.CamListNode || !(buMarbleCalc.SelectedItem.ActiveItem.indexCamList >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= this.activeJob.Cams.Count - 1))
      return;
    camTp cam1 = this.activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
    string str = !Up ? $"{buLangTranslate.preDef.Move} {buLangTranslate.preDef.Down}" : $"{buLangTranslate.preDef.Move} {buLangTranslate.preDef.Up}";
    buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
    dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
    dialogMessageBoxYesNo.Init($"{buLangTranslate.preDef.Up} / {buLangTranslate.preDef.Down}", $"{cam1.Name}{Environment.NewLine}{buLangTranslate.preSentences.DoYouWantToChange}, {str}");
    int num = (int) dialogMessageBoxYesNo.ShowDialog();
    if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
      return;
    this.activeJob.isGCodeCreated = false;
    this.activeJob.isSimulationDone = false;
    if (Up)
    {
      if (buMarbleCalc.SelectedItem.ActiveItem.indexCamList <= 0)
        return;
      camTp cam2 = this.activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
      this.activeJob.Cams.RemoveAt(buMarbleCalc.SelectedItem.ActiveItem.indexCamList);
      this.activeJob.Cams.Insert(buMarbleCalc.SelectedItem.ActiveItem.indexCamList - 1, cam2);
    }
    else
    {
      if (buMarbleCalc.SelectedItem.ActiveItem.indexCamList > this.activeJob.Cams.Count - 2)
        return;
      camTp cam3 = this.activeJob.Cams[buMarbleCalc.SelectedItem.ActiveItem.indexCamList];
      this.activeJob.Cams.RemoveAt(buMarbleCalc.SelectedItem.ActiveItem.indexCamList);
      this.activeJob.Cams.Insert(buMarbleCalc.SelectedItem.ActiveItem.indexCamList + 1, cam3);
    }
  }

