    else if (Item.ItemType == MarbleItemType.Sweep)
      str = $"{str}{buLangTranslate.preDef.Sweep} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.Contour)
    {
      str = $"{str}{buLangTranslate.preDef.Contour} {buLangTranslate.preDef.Cutting}";
      if (Item.ItemName.Trim().Length > 0)
        str = $"{str} : {Item.ItemName}";
