      str = $"{str}{buLangTranslate.preDef.Drill} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.Library)
      str = $"{str}{buLangTranslate.preDef.Library} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.LatheHorizontal)
      str = $"{str}{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.Columns)
      str = $"{str}{buLangTranslate.preDef.Columns} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.LatheVertical)
      str = $"{str}{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.ProfileCurve)
      str = $"{str}{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Curve} {buLangTranslate.preDef.Cutting}";
    else if (Item.ItemType == MarbleItemType.AirDry)
      str = $"{str}{buLangTranslate.preDef.Air} {buLangTranslate.preDef.Dry}";
    else if (Item.ItemType == MarbleItemType.MaterialClean)
      str = $"{str}{buLangTranslate.preDef.Material} {buLangTranslate.preDef.Cleaning}";
    else if (Item.ItemType == MarbleItemType.Shape3D)
      str = $"{str}{buLangTranslate.preDef.Shape} 3D";
    else if (Item.ItemType == MarbleItemType.Cavity)
      str += buLangTranslate.preDef.Cavity;
    else if (Item.ItemType == MarbleItemType.Tap)
      str += buLangTranslate.preDef.Tapping;
    return str;
