  public void ItemListAnalyse(
    marbleCuttingItems[] cutItems,
    ref List<marbleCuttingItems> listCutItems,
    double StartAngleSing = 1.0,
    double EndAngleSing = 1.0)
  {
    for (int index = 0; index <= cutItems.Length - 1; ++index)
    {
      if (Math.Abs(cutItems[index].Length) > 0.1 & cutItems[index].Count > 0)
      {
        marbleCuttingItems marbleCuttingItems = new marbleCuttingItems(cutItems[index]);
        marbleCuttingItems.StartAngle *= StartAngleSing;
        marbleCuttingItems.EndAngle *= EndAngleSing;
        listCutItems.Add(marbleCuttingItems);
      }
    }
  }

