  public void OpenMarbleDrillFile(string Filename)
  {
    FileInfo fileInfo = new FileInfo(Filename);
    if (!fileInfo.Exists)
      return;
    List<string> StringList = new List<string>();
    buFile5.OpenFromFile(fileInfo.FullName, ref StringList);
    this.DrillList.Clear();
    for (int index = 0; index <= StringList.Count - 1; ++index)
    {
      string[] strArray = StringList[index].Split(';');
      if ((strArray == null ? 0 : (strArray.Length >= 4 ? 1 : 0)) != 0)
      {
        marbleDrillType marbleDrillType = new marbleDrillType();
        if (buNumeric5.IsNumeric(strArray[0]) & buNumeric5.IsNumeric(strArray[1]) & buNumeric5.IsNumeric(strArray[2]) & buNumeric5.IsNumeric(strArray[3]))
        {
          marbleDrillType.Depth = double.Parse(strArray[3]);
          marbleDrillType.Diameter = double.Parse(strArray[2]);
          marbleDrillType.pntCenter = new Point3D(double.Parse(strArray[0]), double.Parse(strArray[1]), buMarbleCalc.varOperation.MaterialParameter.MaterialThickness - marbleDrillType.Depth);
          this.DrillList.Add(marbleDrillType);
        }
      }
    }
  }

  public void SaveMarbleJob(string FileName, MarbleJob Job)
  {
    ArrayList StringList = new ArrayList();
    StringList.AddRange((ICollection) MarbleJob.ToDef(Job, 2));
    buFile5.SaveToFile(StringList, FileName);
  }

  public void OpenMarbleJob(string FileName, ref MarbleJob Job)
  {
    ArrayList StringList = new ArrayList();
    buFile5.OpenFromFile(FileName, ref StringList);
    this.activeJob = new MarbleJob();
    MarbleJob refJob = new MarbleJob();
    MarbleJob.Decode(StringList, ref refJob);
    if (refJob.VacuumCuts != null)
      refJob.VacuumCuts.Clear();
    if (refJob.Material.Enable)
    {
      List<Point3D> copiedPoint1 = new List<Point3D>();
      List<List<Point3D>> copiedPoint2 = new List<List<Point3D>>();
      buVector5.Copy(refJob.Material.Points, ref copiedPoint1);
      if (refJob.Material.InnerPoints != null)
        buVector5.Copy(refJob.Material.InnerPoints, ref copiedPoint2);
      clsInit.cMarble.CreateMaterial(copiedPoint1, copiedPoint2, refJob.Material.Shapes, refJob.Material.Size.Depth, refJob.Material.matImage, ref refJob.Material);
    }
    this.activeJob.Name = refJob.Name;
    this.activeJob.Material = new MaterialBase5(refJob.Material);
    this.activeJob.SizeOfOperations = new BoxSize5(refJob.SizeOfOperations);
    Entity entSurface = (Entity) null;
    if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
    {
      for (int index1 = 0; index1 <= refJob.Items.Count - 1; ++index1)
      {
        List<Point3D> Points1 = new List<Point3D>();
        List<List<Point3D>> Inners = new List<List<Point3D>>();
        MarbleItem marbleItem1 = new MarbleItem(refJob.Items[index1]);
        if (marbleItem1.EntGroup != null)
        {
          if (marbleItem1.EntGroup.Outside.Entities.Count > 0)
          {
            clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleItem1.EntGroup.Outside.Entities, ref Points1);
            if (marbleItem1.EntGroup.Inside.Count > 0)
            {
              for (int index2 = 0; index2 <= marbleItem1.EntGroup.Inside.Count - 1; ++index2)
              {
                List<Point3D> Points2 = new List<Point3D>();
                clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleItem1.EntGroup.Inside[index2].Entities, ref Points2);
                Inners.Add(Points2);
              }
            }
            clsInit.cVector5.surfaceFromOutterInner(Points1, Inners, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
          }
          if (entSurface != null)
          {
            marbleItem1.ItemEntities.SolidEntity = new List<Entity>();
            entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
            entSurface.ColorMethod = colorMethodType.byEntity;
            marbleItem1.ItemEntities.SolidEntity.Add(entSurface);
          }
          MarbleTempVars.ItemsContour.Clear();
          MarbleTempVars.ItemsContour.Add(marbleItem1);
          this.doAddCamItemContour(false, false, false, false, -1);
          MarbleItem marbleItem2 = (MarbleItem) null;
          if (this.activeJob.Items.Count > 0)
            marbleItem2 = this.activeJob.Items[this.activeJob.Items.Count - 1];
          for (int index3 = 0; index3 <= refJob.Items[index1].Edges.Count - 1; ++index3)
          {
            if (index3 <= marbleItem2.Edges.Count - 1)
            {
              marbleItem2.Edges[index3].CamID = refJob.Items[index1].Edges[index3].CamID;
              marbleItem2.Edges[index3].EdgeID = refJob.Items[index1].Edges[index3].EdgeID;
              marbleItem2.Edges[index3].ItemID = refJob.Items[index1].Edges[index3].ItemID;
            }
            if (refJob.Items[index1].Edges[index3].Slat.DataSlat.Enable)
              this.doSlatAdd(new AddSlatArgs(refJob.Items[index1].Edges[index3].Slat.DataSlat.indexEntitiy, -1, refJob.Items[index1].ID, refJob.Items[index1].Edges[index3].Slat.DataSlat.EdgeID, refJob.Items[index1].Edges[index3].Slat.DataSlat.CamID));
          }
          if (refJob.Items[index1].Collapses.Count > 0)
          {
            for (int index4 = 0; index4 <= refJob.Items[index1].Collapses.Count - 1; ++index4)
            {
              if (index4 <= marbleItem2.Edges.Count - 1)
              {
                marbleItem2.Edges[index4].CamID = refJob.Items[index1].Edges[index4].CamID;
                marbleItem2.Edges[index4].EdgeID = refJob.Items[index1].Edges[index4].EdgeID;
                marbleItem2.Edges[index4].ItemID = refJob.Items[index1].Edges[index4].ItemID;
              }
              if (refJob.Items[index1].Collapses[index4].Enable)
                this.doCollopseAdd(new AddCollapseArgs(refJob.Items[index1].Collapses[index4].IndexInsideEntity, refJob.Items[index1].Collapses[index4].ItemID));
            }
          }
        }
      }
    }
    this.doDrawActiveJob();
  }

  public void LoadLanguage()
  {
    List<string> stringList = new List<string>();
    FileInfo fileInfo = clsVar.appModes_0.DeveloperPCMode ? new FileInfo("D:\\PCProjects\\Generation5\\CommonFolder\\Language\\buMarble.lng") : new FileInfo(AppPath.Language + "\\buMarble.lng");
    if (fileInfo.Exists)
    {
      List<string> StringList = new List<string>();
      buMarble.LangMarbleMessage = new List<string>();
      buMarble.LangMarbleCaptions = new List<string>();
      buFile.OpenFromFile(fileInfo.FullName, ref StringList);
      buString5.GetItemsAccordingToTheLang(buString5.ReadXmlItem("<Message>", "</Message>", StringList), clsVar.varRuntime.Language, ref buMarble.LangMarbleMessage);
      buString5.GetItemsAccordingToTheLang(buString5.ReadXmlItem("<Captions>", "</Captions>", StringList), clsVar.varRuntime.Language, ref buMarble.LangMarbleCaptions);
      StringList.Clear();
    }
    else
    {
      buLog.addLog("MarbleLanguage", "Not Ok", MethodBase.GetCurrentMethod().Name);
      buString5.MessageBoxError("Laser Language File Missing");
    }
  }

  private void method_6(
    object object_0,
    object object_1,
    object object_2,
    object object_3,
    object object_4)
  {
    Cmd = MarbleCadCamCommands.None;
    alingmentCommands = MarbleAlingmentCommands.None;
    double num = 0.0;
    if (!(object_0 is MarbleCadCamCommands Cmd))
      ;
    if (object_1 != null && buNumeric5.IsNumeric(object_1.ToString()))
      num = Convert.ToDouble(object_1.ToString());
    if (!(object_2 is MarbleAlingmentCommands alingmentCommands))
      ;
    this.doUpdateSelectionFromSelectedItem();
    if (alingmentCommands == MarbleAlingmentCommands.Magnet)
      this.doAlignment(Cmd, num);
    if (alingmentCommands == MarbleAlingmentCommands.Move)
      this.doAlignmentMove(Cmd, num);
    if (alingmentCommands != MarbleAlingmentCommands.Side)
      return;
    this.doAlignmentSide(Cmd, num);
  }

  private void method_7(
    object object_0,
    object object_1,
    object object_2,
    object object_3,
    object object_4)
  {
    marbleCadCamCommands = MarbleCadCamCommands.None;
    double num = 0.0;
    if (!(object_0 is MarbleCadCamCommands marbleCadCamCommands))
      ;
    if (object_1 != null && buNumeric5.IsNumeric(object_1.ToString()))
      num = Convert.ToDouble(object_1.ToString());
    if (object_2 is MarbleVacuumCommands)
      ;
    double MoveDistanceX = 0.0;
    double MoveDistanceY = 0.0;
    switch (marbleCadCamCommands)
    {
      case MarbleCadCamCommands.MoveLeft:
        MoveDistanceX = -num;
        break;
      case MarbleCadCamCommands.MoveLeftUp:
        MoveDistanceX = -num;
        MoveDistanceY = num;
        break;
      case MarbleCadCamCommands.MoveLeftDown:
        MoveDistanceX = -num;
        MoveDistanceY = -num;
        break;
      case MarbleCadCamCommands.MoveUp:
        MoveDistanceY = num;
        break;
      case MarbleCadCamCommands.MoveDown:
        MoveDistanceY = -num;
        break;
      case MarbleCadCamCommands.MoveRight:
        MoveDistanceX = num;
        break;
      case MarbleCadCamCommands.MoveRightUp:
        MoveDistanceX = num;
        MoveDistanceY = num;
        break;
      case MarbleCadCamCommands.MoveRightDown:
        MoveDistanceX = num;
        MoveDistanceY = -num;
        break;
    }
    this.GetVacuumLineByMouse(ccVars.pntMouseDownFirst, MoveDistanceX, MoveDistanceY, true);
  }

  public void GetVacuumLineByMouse(
    Point3D pntView,
    double MoveDistanceX,
    double MoveDistanceY,
    bool Finished)
  {
    if (ccVars.pntDrawDynamicLines == null)
      ccVars.pntDrawDynamicLines = new List<Point3D>();
    ccVars.pntDrawDynamicLines.Clear();
    Point3D pntStart = (Point3D) null;
    Point3D pntEnd = (Point3D) null;
    bool flag = false;
    HorizontalVertical horizontalVertical = HorizontalVertical.Horizontal;
    Point3D point3D1 = (Point3D) null;
    Point3D point3D2 = buVector5.ToPoint3D(this.activeJob.SizeOfOperations.MaxPoint);
    Point3D point3D3 = buVector5.ToPoint3D(this.activeJob.SizeOfOperations.MinPoint);
    MaterialBase5 FoundMat = (MaterialBase5) null;
    double vacuumExtension = buMarbleCalc.varOperation.settingVacuum.VacuumExtension;
    double vacuumOffset = buMarbleCalc.varOperation.settingVacuum.VacuumOffset;
    List<MarbleItem> FoundItems = new List<MarbleItem>();
    if (this.activeJob.VacuumMaterials != null)
    {
      if (this.activeJob.VacuumMaterials.Count > 0)
      {
        clsInit.cMarble.FindMaterialWithPoint(this.activeJob.VacuumMaterials, pntView, ref FoundMat);
        if (FoundMat == null)
          ;
      }
      else
        FoundMat = this.activeJob.Material;
    }
    else
      FoundMat = this.activeJob.Material;
    if (FoundMat != null)
      clsInit.cMarble.FindItemsInsideMaterials(FoundMat, this.activeJob.Items, ref FoundItems);
    else
      FoundMat = this.activeJob.Material;
    double width = FoundMat.Size.Width;
    double height = FoundMat.Size.Height;
    if (FoundItems.Count > 0)
      clsInit.cMarble.GetBoxSizeJobItems(FoundItems, ref point3D3, ref point3D2);
    for (int index1 = 0; index1 <= this.activeJob.Items.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= this.activeJob.Items[index1].CamList.Count - 1; ++index2)
      {
        for (int index3 = 0; index3 <= this.activeJob.Items[index1].CamList[index2].WireEntities.Count - 1; ++index3)
        {
          for (int index4 = 0; index4 <= this.activeJob.Items[index1].CamList[index2].WireEntities[index3].Count - 1; ++index4)
          {
            if (clsInit.cVector5.isPointOverEntity(this.activeJob.Items[index1].CamList[index2].WireEntities[index3][index4], pntView, 10.0))
            {
              flag = true;
              point3D1 = this.activeJob.Items[index1].CamList[index2].WireEntities[index3][index4].StartPoint;
              double num = clsInit.cVector5.PointAngle(this.activeJob.Items[index1].CamList[index2].WireEntities[index3][index4].EndPoint, this.activeJob.Items[index1].CamList[index2].WireEntities[index3][index4].StartPoint);
              if (buCompare5.EQ(num, 90.0, 1.0) | buCompare5.EQ(num, -90.0, 1.0) | buCompare5.EQ(num, 270.0, 1.0))
              {
                horizontalVertical = HorizontalVertical.Vertical;
                break;
              }
              break;
            }
          }
        }
      }
    }
    if (flag & point3D1 != (Point3D) null)
    {
      if (horizontalVertical == HorizontalVertical.Vertical)
      {
        pntStart = new Point3D(point3D1.X, point3D3.Y - vacuumExtension, 0.0);
        pntEnd = new Point3D(point3D1.X, point3D3.Y + height + 2.0 * vacuumExtension, 0.0);
      }
      else
      {
        pntStart = new Point3D(point3D3.X - vacuumExtension, point3D1.Y, 0.0);
        pntEnd = new Point3D(point3D3.X + width + 2.0 * vacuumExtension, point3D1.Y, 0.0);
      }
    }
    if (!flag)
    {
      if (pntView.X > point3D2.X)
      {
        pntStart = new Point3D(point3D2.X + vacuumOffset, point3D3.Y - vacuumExtension, 0.0);
        pntEnd = new Point3D(point3D2.X + vacuumOffset, point3D3.Y + height + 2.0 * vacuumExtension, 0.0);
      }
      else if (pntView.Y > point3D2.Y)
      {
        pntStart = new Point3D(point3D3.X - vacuumExtension, point3D2.Y + vacuumOffset, 0.0);
        pntEnd = new Point3D(point3D3.X + width + 2.0 * vacuumExtension, point3D2.Y + vacuumOffset, 0.0);
      }
    }
    if ((this.activeJob.VacuumCuts == null ? 0 : (this.activeJob.VacuumCuts.Count > 0 ? 1 : 0)) != 0)
      ;
    if (Finished)
    {
      ccVars.pntDrawDynamicLines.Clear();
      if ((!(pntStart != (Point3D) null) ? 0 : (pntEnd != (Point3D) null ? 1 : 0)) == 0)
        return;
      this.VacuumAdd(pntView, pntStart, pntEnd, MoveDistanceX, MoveDistanceY);
    }
    else
    {
      if ((!(pntStart != (Point3D) null) ? 0 : (pntEnd != (Point3D) null ? 1 : 0)) == 0)
        return;
      ccVars.pntDrawDynamicLines.Add(pntStart);
      ccVars.pntDrawDynamicLines.Add(pntEnd);
    }
  }

  public void VacuumAdd(
    Point3D pntClick,
    Point3D pntStart,
    Point3D pntEnd,
    double MoveDistanceX,
    double MoveDistanceY)
  {
    double num1 = MoveDistanceX;
    double num2 = MoveDistanceY;
    MarbleVacuumCut CutLine = new MarbleVacuumCut();
    CutLine.StartPoint = new Point3D(pntStart.X, pntStart.Y, 0.0);
    CutLine.EndPoint = new Point3D(pntEnd.X, pntEnd.Y, 0.0);
    double AngleC = clsInit.cVector5.PointAngle(CutLine.EndPoint, CutLine.StartPoint);
    if (buCompare5.EQ(AngleC, 0.0) | buCompare5.EQ(AngleC, 180.0))
    {
      CutLine.Direction = HorizontalVertical.Horizontal;
      num2 = MoveDistanceY;
    }
    if (buCompare5.EQ(AngleC, 90.0) | buCompare5.EQ(AngleC, 270.0))
    {
      CutLine.Direction = HorizontalVertical.Vertical;
      num1 = MoveDistanceX;
    }
    CutLine.VacuumCutEntity = (buEntity) new buLine(CutLine.StartPoint, CutLine.EndPoint);
    CutLine.VacuumID = 1;
    if (this.activeJob.VacuumCuts == null)
      this.activeJob.VacuumCuts = new List<MarbleVacuumCut>();
    if (this.activeJob.VacuumMaterials == null)
      this.activeJob.VacuumMaterials = new List<MaterialBase5>();
    if (this.activeJob.VacuumCuts.Count == 0)
    {
      MaterialBase5 FirstMaterial = new MaterialBase5();
      MaterialBase5 SecondMaterial = new MaterialBase5();
      clsInit.cMarble.DevideVacuumMaterial(this.activeJob.Material, CutLine, num1, num2, ref FirstMaterial, ref SecondMaterial);
      this.activeJob.VacuumMaterials.Add(FirstMaterial);
      this.activeJob.VacuumMaterials.Add(SecondMaterial);
      CutLine.Selected = true;
      this.activeJob.VacuumCuts.Add(CutLine);
      this.activeJob.VacuumSelectedIndex = this.activeJob.VacuumCuts.Count - 1;
    }
    else
    {
      int index1 = -1;
      for (int index2 = 0; index2 <= this.activeJob.VacuumMaterials.Count - 1; ++index2)
      {
        MaterialBase5 vacuumMaterial = this.activeJob.VacuumMaterials[index2];
        if (clsInit.cVector5.IsPointInsideBoxsize(pntClick, vacuumMaterial.BoxMinPoint, vacuumMaterial.BoxMaxPoint, Plane.XY))
          index1 = index2;
      }
      if (index1 >= 0)
      {
        MaterialBase5 vacuumMaterial = this.activeJob.VacuumMaterials[index1];
        MaterialBase5 FirstMaterial = new MaterialBase5();
        MaterialBase5 SecondMaterial = new MaterialBase5();
        clsInit.cMarble.DevideVacuumMaterial(vacuumMaterial, CutLine, num1, num2, ref FirstMaterial, ref SecondMaterial);
        this.activeJob.VacuumMaterials.RemoveAt(index1);
        this.activeJob.VacuumMaterials.Add(FirstMaterial);
        this.activeJob.VacuumMaterials.Add(SecondMaterial);
        CutLine.Selected = true;
        this.activeJob.VacuumCuts.Add(CutLine);
        this.activeJob.VacuumSelectedIndex = this.activeJob.VacuumCuts.Count - 1;
      }
    }
    clsInit.cMarble.MoveVacuumCut(ref this.activeJob, num1, num2, this.activeJob.VacuumSelectedIndex);
    buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle = CutLine.VacuumCutEntity.Length();
    this.doAddItemSingleCut(new Point3D(CutLine.StartPoint.X, CutLine.StartPoint.Y, 0.0), 0.0, AngleC, true, this.activeJob.VacuumCuts.Count - 1, true);
    List<MaterialBase5> CopiedList = new List<MaterialBase5>();
    MaterialBase5.Copy(this.activeJob.VacuumMaterials, ref CopiedList);
    if (this.activeJob.SimMaterials == null)
      this.activeJob.SimMaterials = new List<List<MaterialBase5>>();
    this.activeJob.SimMaterials.Add(CopiedList);
    this.doDrawActiveJob();
  }

  public string DebugExecute(DebugCommandEventArg e)
  {
    string str;
    if (e.DebugCommand.ToString().ToLower() == "showmwdialog")
    {
      if (clsInit.cMwCalc != null)
      {
        clsInit.cMwCalc.Settings.ShowMwDialogBox = true;
        str = buLangTranslate.preDef.Ok;
      }
      else
        str = buLangTranslate.preDef.Error;
    }
    else if (e.DebugCommand.ToString().ToLower() == "hidemwdialog")
    {
      if (clsInit.cMwCalc != null)
      {
        clsInit.cMwCalc.Settings.ShowMwDialogBox = false;
        str = buLangTranslate.preDef.Ok;
      }
      else
        str = buLangTranslate.preDef.Error;
    }
    else
      str = buLangTranslate.preDef.Error;
    return str;
  }

  public ToolBase5 FindToolFromType(MarbleToolType ToolType)
  {
    ToolBase5 toolFromType = (ToolBase5) null;
    switch (ToolType)
    {
      case MarbleToolType.Saw:
        toolFromType = new ToolBase5(buMarbleCalc.activeToolSaw);
        break;
      case MarbleToolType.Milling:
        toolFromType = new ToolBase5(buMarbleCalc.activeToolMilling);
        break;
      case MarbleToolType.WaterJet:
        toolFromType = new ToolBase5(buMarbleCalc.activeToolWaterjet);
        break;
      case MarbleToolType.MillingHead:
        toolFromType = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        break;
    }
    return toolFromType;
  }

