  public void OperationControlValueChanged(object sender, double Value)
  {
    System.Windows.Forms.Control control = sender as System.Windows.Forms.Control;
    if (!buMarbleControls.Inited)
      return;
    if ((buMarbleControls.spnMaterialThickness == null ? 0 : (control.Name == buMarbleControls.spnMaterialThickness.Name ? 1 : 0)) != 0)
      buMarbleCalc.varOperation.MaterialParameter.MaterialThickness = buMarbleControls.spnMaterialThickness.Value;
    if ((buMarbleControls.spnCuttingSpeed == null ? 0 : (control.Name == buMarbleControls.spnCuttingSpeed.Name ? 1 : 0)) != 0)
      buMarbleCalc.varOperation.settingMarbleCam.SawForwardCuttingVelocity = buMarbleControls.spnCuttingSpeed.Value;
    if ((buMarbleControls.spnForwardStep == null ? 0 : (control.Name == buMarbleControls.spnForwardStep.Name ? 1 : 0)) != 0)
      buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance = buMarbleControls.spnForwardStep.Value;
    if ((buMarbleControls.spnPlungeSpeed == null ? 0 : (control.Name == buMarbleControls.spnPlungeSpeed.Name ? 1 : 0)) != 0)
      buMarbleCalc.varOperation.settingMarbleCam.SawPlungeVelocity = buMarbleControls.spnPlungeSpeed.Value;
    if ((buMarbleControls.spnTargetZ == null ? 0 : (control.Name == buMarbleControls.spnTargetZ.Name ? 1 : 0)) == 0)
      return;
    buMarbleCalc.varOperation.settingMarbleCam.TargetZ = buMarbleControls.spnTargetZ.Value;
  }

  public void MarbleItemOsnapCalculations()
  {
    ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints.Clear();
