  public void UndoBuffer()
  {
    if (MarbleTempVars.UndoApplying)
      return;
    Task.Run((Action) (() => this.UndoBufferApply()));
  }

  public void UndoBufferApply()
  {
    try
    {
      MarbleTempVars.UndoApplying = true;
      if (buMarbleCalc.varOperation.settingEvent.UndoEnable)
      {
        MarbleJob marbleJob = new MarbleJob(this.activeJob);
        buMarbleCalc.UndoJobList.Add(marbleJob);
        if (buMarbleCalc.UndoJobList.Count > buMarbleCalc.varOperation.settingEvent.UndoLimit)
          buMarbleCalc.UndoJobList.RemoveAt(0);
      }
      MarbleTempVars.UndoApplying = false;
    }
    catch (Exception ex)
    {
      MarbleTempVars.UndoApplying = false;
    }
  }

  public void UndoGetback()
  {
    if (buMarbleCalc.UndoJobList.Count <= 0)
      return;
    clsInit.appMarble.activeJob = new MarbleJob(buMarbleCalc.UndoJobList[buMarbleCalc.UndoJobList.Count - 1]);
    buMarbleCalc.UndoJobList.RemoveAt(buMarbleCalc.UndoJobList.Count - 1);
    this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
    this.JobUpdate();
    this.doDrawActiveJob();
  }

  public void doNestingResult(buNestedResultEventArg NestResult)
  {
    if (!(NestResult.SelectedSheet >= 0 & NestResult.SelectedSheet <= NestResult.nestedResult.NestedResultSheets.Count - 1))
      return;
    buNestedSheet nestedResultSheet = NestResult.nestedResult.NestedResultSheets[NestResult.SelectedSheet];
    for (int index = 0; index <= nestedResultSheet.Parts.Count - 1; ++index)
    {
      this.entitiesGroupForContour.Clear();
      this.entitiesGroupForContour.Add(new buEntitiesGroup(nestedResultSheet.Parts[index].EntitiesGroup));
      this.doAddItemShapeContour(new Point3D(), false, true, false, false, false, false, false, -1);
    }
  }

  public void Tick_New(object sender, EventArgs e)
  {
    if (this.NewTickCount == 0)
    {
      buEyeItems.viewportCadCam = (Design) ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
      buEyeItems.viewportCadCam = this.CreateMaterialsAndLayers(MarbleTempVars.fileNameWood, MarbleTempVars.fileNameMarble, buEyeItems.viewportCadCam, linearUnitsType.Millimeters);
      Entity entWood = (Entity) null;
      if (buMarbleCalc.varMarbleSettings.DrawWoodBase)
      {
        this.CreateWoodMaterial(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, buMarbleCalc.varMarbleMachineSettings.BaseWoodThickness, buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset + buMarbleCalc.varOperation.settingMarbleCam.TargetZ, true, buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerWood.Index].Name, ref entWood);
        entWood.Selectable = false;
        if (entWood != null)
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entWood);
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomFit(10);
      }
    }
    this.activeJob.Items.Clear();
    this.activeJob = new MarbleJob();
    this.activeJob.Material.BoxMinPoint.X = 0.0;
    this.activeJob.Material.BoxMinPoint.Y = 0.0;
    this.activeJob.Material.BoxMaxPoint.X = buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth;
    this.activeJob.Material.BoxMaxPoint.Y = buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight;
    this.activeJob.Material.BoxMinPoint.Z = 0.0;
    this.activeJob.Material.BoxMaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
    this.activeJob.Material.Size.Width = this.activeJob.Material.BoxMaxPoint.X - this.activeJob.Material.BoxMinPoint.X;
    this.activeJob.Material.Size.Height = this.activeJob.Material.BoxMaxPoint.Y - this.activeJob.Material.BoxMinPoint.Y;
    this.activeJob.Material.Size.Depth = this.activeJob.Material.BoxMaxPoint.Z - this.activeJob.Material.BoxMinPoint.Z;
    ++this.NewTickCount;
    this.timNew.Enabled = false;
    clsInit.appMarble.InitCadCamSimulation();
    buEyeItems.viewportDialogs = this.CreateMaterialsAndLayers(MarbleTempVars.fileNameWood, MarbleTempVars.fileNameMarble, buEyeItems.viewportDialogs, linearUnitsType.Meters);
    clsInit.appCommand.LayerConvertFromEyeLayerToBuLayer(buEyeItems.viewportCadCam.Layers, ref ccVars.Pages[ccVars.PageIndex].Layers);
    clsInit.appCommand.LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, true, -1);
    this.JobUpdate();
    this.doDrawActiveJob();
    this.DrawPreview((ToolBase5) null, -1);
    clsInit.appCommand.cmdViewZoomFit(25);
  }

