  public void doReset()
  {
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StopAnimation();
    this.MoveCreatedEntity = false;
    if (clsItem.pnlSettings != null)
      clsItem.pnlSettings.Visible = false;
    this.entitiesGroupForContour.Clear();
    this.entitiesForContour.Clear();
    this.entitiesForSweep.Clear();
    this.entitiesForDrill.Clear();
    this.entitiesForProfiling.Clear();
    this.entitiesForMove.Clear();
    AppBool.EditMode = false;
    AppBool.FileCopied = false;
    AppBool.CameraCaptured = false;
    AppBool.CameraCapturing = false;
    MarbleTempVars.VacuumIndex = -1;
    MarbleTempVars.VacuumEnable = false;
    if (buMarbleForms.frmEventVacuum != null)
      buMarbleForms.frmEventVacuum.Visible = false;
    MarbleTempVars.isDialogItem = false;
    MarbleTempVars.Commands = MarbleCommands.None;
    MarbleTempVars.SetAngle = false;
    MarbleTempVars.Editing = false;
    MarbleTempVars.ItemsContour.Clear();
    MarbleTempVars.ItemsSlice.Clear();
    MarbleTempVars.ItemsProfile.Clear();
    MarbleTempVars.ItemsDrill.Clear();
    MarbleTempVars.ItemsSweep.Clear();
    buMarbleCalc.SelectedItem.SelectionItems.Clear();
    clsInit.appMarble.activeItemType = MarbleItemType.None;
    ccVars.Pages[ccVars.PageIndex].Form.lbl_information.Visible = false;
    ViewportCC viewportcad = ccVars.Pages[ccVars.PageIndex].Form.viewportcad;
    for (int index = 0; index <= viewportcad.Entities.Count - 1; ++index)
    {
      viewportcad.Entities[index].Selected = false;
      if (viewportcad.Entities[index].EntityData != null & viewportcad.Entities[index].EntityData is CustomData && (viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.Temp)
        viewportcad.Entities[index].Selected = true;
    }
    viewportcad.Entities.DeleteSelected();
    this.doSelectionClearItems();
  }

  public void doPageClosed()
  {
    this.activeJob.Items.Clear();
    this.activeJob = new MarbleJob();
    this.JobUpdate();
    if (clsItem.ModelMainPreview == null)
      return;
    clsItem.ModelMainPreview.Entities.Clear();
    clsItem.ModelMainPreview.Invalidate();
  }

  public void doToolSelected(ToolBase5 selectedTool)
  {
    if (selectedTool == null)
      return;
    if (selectedTool.Purpose == ToolPurpose.Milling | selectedTool.Purpose == ToolPurpose.General | selectedTool.Purpose == ToolPurpose.Milling5Axis)
      buMarbleCalc.activeToolMilling = new ToolBase5(selectedTool);
    else if (selectedTool.Purpose == ToolPurpose.Saw)
      buMarbleCalc.activeToolSaw = new ToolBase5(selectedTool);
    else if (selectedTool.Purpose == ToolPurpose.MillingHead)
    {
      buMarbleCalc.activeToolMillingHead = new ToolBase5(selectedTool);
    }
    else
    {
      if (selectedTool.Purpose != ToolPurpose.WaterJet)
        return;
      buMarbleCalc.activeToolWaterjet = new ToolBase5(selectedTool);
    }
  }

  public void doToolUpdate(int SelectedGroupIndex, int SelectedIndex)
  {
    if (!(SelectedGroupIndex >= 0 & SelectedIndex >= 0) || SelectedGroupIndex > ccVars.Tools.Count - 1 || SelectedIndex > ccVars.Tools[SelectedGroupIndex].Tools.Count - 1)
      return;
    if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose == ToolPurpose.Saw)
      buMarbleCalc.activeToolSaw = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
    else if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose == ToolPurpose.Milling)
      buMarbleCalc.activeToolMilling = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
    else if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose == ToolPurpose.Milling5Axis)
      buMarbleCalc.activeToolMilling = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
    else if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose == ToolPurpose.MillingHead)
    {
      buMarbleCalc.activeToolMillingHead = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
    }
    else
    {
      if (ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex].Purpose != ToolPurpose.WaterJet)
        return;
      buMarbleCalc.activeToolWaterjet = new ToolBase5(ccVars.Tools[SelectedGroupIndex].Tools[SelectedIndex]);
    }
  }

  public void doPartCreateFromTempDrawings()
  {
    try
    {
      List<buEntity> AllEntities = new List<buEntity>();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.TempDraw)
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ref copiedEntity);
          AllEntities.Add(copiedEntity);
        }
      }
      this.entitiesGroupForContour.Clear();
      clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), AllEntities, Plane.XY, ref this.entitiesGroupForContour);
      this.doAddItemShapeContour((Point3D) null, false, true, false, false, false, false, false, -1);
      this.doDrawActiveJob();
    }
    catch (Exception ex)
    {
    }
  }

  public void doMaterialCreateFromTempDrawings()
  {
    try
    {
      List<buEntity> AllEntities = new List<buEntity>();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData).typeDefination == entityTypeDefination.TempDraw)
        {
          ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ref copiedEntity);
          AllEntities.Add(copiedEntity);
        }
      }
      this.entitiesGroupForContour.Clear();
      clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), AllEntities, Plane.XY, ref this.entitiesGroupForContour);
      clsInit.appMarble.activeJob.Material.Enable = false;
      clsInit.appMarble.activeJob.Material.Shapes = MaterialShapes.Irregular;
      clsInit.appMarble.activeJob.Material.Entities.Clear();
      if (this.entitiesGroupForContour.Count > 0)
      {
        List<Point3D> Points1 = new List<Point3D>();
        List<List<Point3D>> PLInner = new List<List<Point3D>>();
        if (this.entitiesGroupForContour[0].Outside.Entities.Count > 0)
        {
          clsInit.cVector5.EntitiesToPointsWithCamDirection(this.entitiesGroupForContour[0].Outside.Entities, ref Points1);
          if (this.entitiesGroupForContour[0].Inside.Count > 0)
          {
            for (int index = 0; index <= this.entitiesGroupForContour[0].Inside.Count - 1; ++index)
            {
              List<Point3D> Points2 = new List<Point3D>();
              clsInit.cVector5.EntitiesToPointsWithCamDirection(this.entitiesGroupForContour[0].Inside[index].Entities, ref Points2);
              PLInner.Add(Points2);
            }
          }
          clsInit.cMarble.CreateMaterial(Points1, PLInner, MaterialShapes.Irregular, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, (Image) null, ref clsInit.appMarble.activeJob.Material);
        }
      }
      this.doDrawActiveJob();
    }
    catch (Exception ex)
    {
    }
  }

