  {
    this.activeJob.Material.Enable = false;
    this.activeJob.Material.Shapes = MaterialShapes.Rectangle;
    this.activeJob.Material.Entities.Clear();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
