    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
    ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
  }

  public void doDeleteCameraImage()
  {
    string str = nameof (doDeleteCameraImage);
    try
    {
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Picture && (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData == null ? 0 : (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData ? 1 : 0)) != 0)
        {
          CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
          if (entityData.typeDefination == entityTypeDefination.CameraImage)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
          if (entityData.typeDefination == entityTypeDefination.Material)
            ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected = true;
        }
      }
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
      ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
      MarbleTempVars.CameraImage = (Entity) null;
      if (this.activeJob == null)
        return;
      this.activeJob.Material.matImage = (Image) null;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void CreateShape(
    Point3D refPoint,
    MarbleShapeTypes Type,
    double Thickness,
    ref MarbleItem Item,
    MarbleToolType ToolType)
  {
    if (Item == null)
      Item = new MarbleItem();
    Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
    Item.EntGroup = new buEntitiesGroup();
    Item.ItemEntities.EdgeEntities = new List<buEntity>();
    Item.ItemEntities.ExtensionEntities = new List<buEntity>();
    ICurve wireEntity = (ICurve) null;
    buEntity copiedEntity = (buEntity) null;
    Entity solidEntity = (Entity) null;
    clsInit.cMarble.CreateShape(Type, Thickness, ref solidEntity, ref wireEntity);
    buEntity.Copy(wireEntity, ref copiedEntity, 0.1);
    solidEntity.Translate(refPoint.X, refPoint.Y);
    Item.ItemEntities.SolidEntity = new List<Entity>();
    solidEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
    solidEntity.ColorMethod = colorMethodType.byEntity;
    if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
      Item.ItemEntities.SolidEntity.Add(solidEntity);
    Item.ItemType = MarbleItemType.Shape;
    Item.ShapeType = Type;
    Item.ToolType = ToolType;
    clsInit.cVector5.BoxSizeCalculate(solidEntity, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
    ObjectSize3D.CalculateSize(ref Item.SizeItem);
    copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
    if (copiedEntity is buCompositeCurve)
    {
      for (int index = 0; index <= ((buCompositeCurve) copiedEntity).CurveList.Count - 1; ++index)
      {
        ((buCompositeCurve) copiedEntity).CurveList[index].Marble = new MarbleInfo();
        Item.EntGroup.Outside.Entities.Add(((buCompositeCurve) copiedEntity).CurveList[index]);
        Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
      }
      if (Type != MarbleShapeTypes.Arc)
        ;
    }
    else
    {
      copiedEntity.Marble = new MarbleInfo();
      Item.EntGroup.Outside.Entities.Add(copiedEntity);
      Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
    }
    if (Item.SizeItem.Height > Item.SizeItem.Width)
      Item.isTextVertical = !MarbleTempVars.isHorizontal;
    if (Item.EntGroup.Outside.Entities.Count > 0)
      clsInit.cMarble.ShapeTypeAngleSet(ref Item);
    if (Item.ToolType != 0)
      ;
    Item.ClockDir = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
    Item.ID = MarbleTempVars.ItemID;
    Item.SortRefPoint = buVector5.ToPoint3D(copiedEntity.StartPoint);
    Item.ItemName = clsInit.cMarble.ItemShapeToName(Type);
    ++MarbleTempVars.ItemID;
  }

  public void CreateTextContour(
    Point3D refPoint,
    List<buEntitiesGroup> entContour,
    double Thickness,
    ref List<MarbleItem> Items,
    MarbleToolType ToolType)
  {
    string str = nameof (CreateTextContour);
    try
    {
      MarbleItem marbleItem = new MarbleItem()
      {
        ItemEntities = {
          GroupEntities = new List<buEntitiesGroup>()
        },
        EntGroup = new buEntitiesGroup()
      };
      marbleItem.EntGroup.Inside = new List<buEntityList>();
      marbleItem.ItemEntities.SourceEntities = new List<buEntity>();
      marbleItem.ItemEntities.DrawWireEntities = new List<buEntity>();
      marbleItem.ItemEntities.EdgeEntities = new List<buEntity>();
      marbleItem.ItemEntities.ExtensionEntities = new List<buEntity>();
      marbleItem.ItemEntities.WireEntities = new List<List<buEntity>>();
      marbleItem.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
      marbleItem.ItemEntities.SolidEntity = new List<Entity>();
      marbleItem.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      for (int index1 = 0; index1 <= entContour.Count - 1; ++index1)
      {
        List<Point3D> Points1 = new List<Point3D>();
        List<List<Point3D>> Inners = new List<List<Point3D>>();
        Entity entSurface = (Entity) null;
        if (buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
        {
          if (entContour[index1].Outside.Entities.Count > 0)
          {
            clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour[index1].Outside.Entities, ref Points1);
            if (entContour[index1].Inside.Count > 0)
            {
              for (int index2 = 0; index2 <= entContour[index1].Inside.Count - 1; ++index2)
              {
                List<Point3D> Points2 = new List<Point3D>();
                clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour[index1].Inside[index2].Entities, ref Points2);
                Inners.Add(Points2);
              }
            }
            clsInit.cVector5.surfaceFromOutterInner(Points1, Inners, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
          }
          if (entSurface != null)
          {
            if (refPoint != (Point3D) null)
              entSurface.Translate(refPoint.X, refPoint.Y);
            entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemText.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemText.Color);
            entSurface.ColorMethod = colorMethodType.byEntity;
            marbleItem.ItemEntities.SolidEntity.Add(entSurface);
          }
        }
        marbleItem.ItemType = clsInit.appMarble.activeItemType;
        marbleItem.ToolType = MarbleToolType.Saw;
        switch (ToolType)
        {
          case MarbleToolType.WaterJet:
            marbleItem.ToolType = MarbleToolType.WaterJet;
            break;
          case MarbleToolType.MillingHead:
            marbleItem.ToolType = MarbleToolType.MillingHead;
            break;
          default:
            marbleItem.ToolType = MarbleToolType.Milling;
            break;
        }
        if (!buMarbleCalc.varMarbleRunSettings.BorderEnable)
        {
          for (int index3 = 0; index3 <= entContour[index1].Outside.Entities.Count - 1; ++index3)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(entContour[index1].Outside.Entities[index3], ref copiedEntity);
            if (refPoint != (Point3D) null)
              copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
            copiedEntity.Marble = new MarbleInfo();
            marbleItem.EntGroup.Outside.Entities.Add(copiedEntity);
            marbleItem.EntGroup.Outside.ToolType = entContour[index1].Outside.ToolType;
            if (entContour[index1].Outside.Marble != null)
            {
              marbleItem.EntGroup.Outside.Marble = new marbleEntityData(entContour[index1].Outside.Marble);
            }
            else
            {
              marbleItem.EntGroup.Outside.Marble = new marbleEntityData();
              clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItem.ToolType, ref marbleItem.EntGroup.Outside.Marble);
            }
          }
        }
        else if (index1 == 0)
        {
          for (int index4 = 0; index4 <= entContour[index1].Outside.Entities.Count - 1; ++index4)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(entContour[index1].Outside.Entities[index4], ref copiedEntity);
            if (refPoint != (Point3D) null)
              copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
            copiedEntity.Marble = new MarbleInfo();
            marbleItem.EntGroup.Outside.Entities.Add(copiedEntity);
            marbleItem.EntGroup.Outside.ToolType = entContour[index1].Outside.ToolType;
            if (entContour[index1].Outside.Marble != null)
            {
              marbleItem.EntGroup.Outside.Marble = new marbleEntityData(entContour[index1].Outside.Marble);
            }
            else
            {
              marbleItem.EntGroup.Outside.Marble = new marbleEntityData();
              clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItem.ToolType, ref marbleItem.EntGroup.Outside.Marble);
            }
          }
        }
        else
        {
          buEntityList buEntityList = new buEntityList();
          for (int index5 = 0; index5 <= entContour[index1].Outside.Entities.Count - 1; ++index5)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(entContour[index1].Outside.Entities[index5], ref copiedEntity);
            if (refPoint != (Point3D) null)
              copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
            copiedEntity.Marble = new MarbleInfo();
            buEntityList.Entities.Add(copiedEntity);
            buEntityList.ToolType = entContour[index1].Outside.ToolType;
            if (entContour[index1].Outside.Marble != null)
            {
              buEntityList.Marble = new marbleEntityData(entContour[index1].Outside.Marble);
            }
            else
            {
              buEntityList.Marble = new marbleEntityData();
              clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItem.ToolType, ref buEntityList.Marble);
            }
          }
          if (buEntityList.Entities.Count > 0)
            marbleItem.EntGroup.Inside.Add(buEntityList);
        }
        if ((entContour[index1].Inside == null ? 0 : (entContour[index1].Inside.Count > 0 ? 1 : 0)) != 0)
        {
          for (int index6 = 0; index6 <= entContour[index1].Inside.Count - 1; ++index6)
          {
            buEntityList buEntityList = new buEntityList();
            for (int index7 = 0; index7 <= entContour[index1].Inside[index6].Entities.Count - 1; ++index7)
            {
              buEntity copiedEntity = (buEntity) null;
              buEntity.Copy(entContour[index1].Inside[index6].Entities[index7], ref copiedEntity);
              if (refPoint != (Point3D) null)
                copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
              copiedEntity.Marble = new MarbleInfo();
              buEntityList.Entities.Add(copiedEntity);
            }
            buEntityList.ToolType = entContour[index1].Inside[index6].ToolType;
            if (entContour[index1].Inside[index6].Marble != null)
            {
              buEntityList.Marble = new marbleEntityData(entContour[index1].Inside[index6].Marble);
            }
            else
            {
              buEntityList.Marble = new marbleEntityData();
              clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItem.ToolType, ref buEntityList.Marble);
            }
            marbleItem.EntGroup.Inside.Add(buEntityList);
          }
        }
        if ((entContour[index1].OpenEntities == null ? 0 : (entContour[index1].OpenEntities.Count > 0 ? 1 : 0)) != 0)
        {
          marbleItem.EntGroup.OpenEntities = new List<buEntityList>();
          for (int index8 = 0; index8 <= entContour[index1].OpenEntities.Count - 1; ++index8)
          {
            buEntityList buEntityList = new buEntityList();
            for (int index9 = 0; index9 <= entContour[index1].OpenEntities[index8].Entities.Count - 1; ++index9)
            {
              buEntity copiedEntity = (buEntity) null;
              buEntity.Copy(entContour[index1].OpenEntities[index8].Entities[index9], ref copiedEntity);
              if (refPoint != (Point3D) null)
                copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
              copiedEntity.Marble = new MarbleInfo();
              buEntityList.Entities.Add(copiedEntity);
            }
            buEntityList.ToolType = entContour[index1].OpenEntities[index8].ToolType;
            if (entContour[index1].OpenEntities[index8].Marble != null)
            {
              buEntityList.Marble = new marbleEntityData(entContour[index1].OpenEntities[index8].Marble);
            }
            else
            {
              buEntityList.Marble = new marbleEntityData();
              clsInit.cMarble.convOperationParameterToEntityDataParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItem.ToolType, ref buEntityList.Marble);
            }
            marbleItem.EntGroup.OpenEntities.Add(buEntityList);
          }
        }
        if (marbleItem.ItemType == MarbleItemType.TextWireframe)
        {
          if (marbleItem.EntGroup.Outside.Entities.Count > 0)
          {
            for (int index10 = 0; index10 <= marbleItem.EntGroup.Outside.Entities.Count - 1; ++index10)
            {
              for (int index11 = 1; index11 <= marbleItem.EntGroup.Outside.Entities[index10].Vertices.Count - 1; ++index11)
              {
                List<Point3D> OffsetedPoints = new List<Point3D>();
                clsInit.cVector5.OffsetOpenContour(new List<Point3D>()
                {
                  marbleItem.EntGroup.Outside.Entities[index10].Vertices[index11 - 1],
                  marbleItem.EntGroup.Outside.Entities[index10].Vertices[index11]
                }, 3.0, OffsetCornerType.Line, CamOpenContourType.Left, Plane.XY, 0.0, ref OffsetedPoints);
                Entity entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) OffsetedPoints)).ExtrudeAsMesh(3.0, 0.01, Mesh.natureType.RichSmooth);
                marbleItem.ItemEntities.SolidEntity.Add(entity);
              }
            }
          }
          if (marbleItem.EntGroup.OpenEntities != null)
          {
            for (int index12 = 0; index12 <= marbleItem.EntGroup.OpenEntities.Count - 1; ++index12)
            {
              for (int index13 = 0; index13 <= marbleItem.EntGroup.OpenEntities[index12].Entities.Count - 1; ++index13)
              {
                for (int index14 = 1; index14 <= marbleItem.EntGroup.OpenEntities[index12].Entities[index13].Vertices.Count - 1; ++index14)
                {
                  List<Point3D> OffsetedPoints = new List<Point3D>();
                  clsInit.cVector5.OffsetOpenContour(new List<Point3D>()
                  {
                    marbleItem.EntGroup.OpenEntities[index12].Entities[index13].Vertices[index14 - 1],
                    marbleItem.EntGroup.OpenEntities[index12].Entities[index13].Vertices[index14]
                  }, 3.0, OffsetCornerType.Line, CamOpenContourType.Left, Plane.XY, 0.0, ref OffsetedPoints);
                  Entity entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) new LinearPath((ICollection<Point3D>) OffsetedPoints)).ExtrudeAsMesh(3.0, 0.01, Mesh.natureType.RichSmooth);
                  marbleItem.ItemEntities.SolidEntity.Add(entity);
                }
              }
            }
          }
        }
        clsInit.cVector5.BoxSizeCalculate(marbleItem.EntGroup, ref marbleItem.SizeItem.MinPoint, ref marbleItem.SizeItem.MidPoint, ref marbleItem.SizeItem.MaxPoint);
        marbleItem.SizeItem.MaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
        ObjectSize3D.CalculateSize(ref marbleItem.SizeItem);
        if ((!(marbleItem.ItemEntities.SolidEntity != null & marbleItem.ItemEntities.SolidEntity.Count > 0) ? 0 : (marbleItem.BaseHeight > 0.0 ? 1 : 0)) != 0)
        {
          Entity surfaceEntity = (Entity) null;
          clsInit.cVector5.surfaceBox(marbleItem.SizeItem.MinPoint, marbleItem.SizeItem.MaxPoint.X - marbleItem.SizeItem.MinPoint.X, marbleItem.SizeItem.MaxPoint.Y - marbleItem.SizeItem.MinPoint.Y, marbleItem.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
          if (surfaceEntity != null)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(surfaceEntity, ref copiedEntity);
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
            marbleItem.ItemEntities.BaseEntities = new List<buEntity>();
            marbleItem.ItemEntities.BaseEntities.Add(copiedEntity);
          }
        }
        if (ToolType == MarbleToolType.Saw | ToolType == MarbleToolType.WaterJet)
        {
          if (entContour[index1].Outside.Entities.Count > 0)
            clsInit.cMarble.CreateEdgeEntities(entContour[index1].Outside.Entities, refPoint, true, 0, 0, ref marbleItem);
          if (entContour[index1].Inside.Count > 0)
          {
            for (int index15 = 0; index15 <= entContour[index1].Inside.Count - 1; ++index15)
              clsInit.cMarble.CreateEdgeEntities(entContour[index1].Inside[index15].Entities, refPoint, false, index15, 0, ref marbleItem);
          }
        }
      }
      marbleItem.ID = MarbleTempVars.ItemID;
      ++MarbleTempVars.ItemID;
      Items.Add(marbleItem);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Drill Settings Decoder Error");
    }
  }

  public void CreateShapeContour(
    Point3D refPoint,
    List<buEntitiesGroup> entContour,
    double Thickness,
    ref List<MarbleItem> Items,
    MarbleToolType ToolType,
    bool isText = false)
  {
    for (int index = 0; index <= entContour.Count - 1; ++index)
    {
      MarbleItem marbleItem = new MarbleItem();
      this.CreateShapeContour(refPoint, entContour[index], Thickness, buMarbleCalc.varOperation.settingMarbleCam.TargetZ, ref marbleItem, ToolType, isText);
      Items.Add(marbleItem);
    }
  }

  public void CreateShapeContour(
    Point3D refPoint,
    buEntitiesGroup entContour,
    double Thickness,
    double TargetZ,
    ref MarbleItem Item,
    MarbleToolType ToolType,
    bool isText = false)
  {
    string str = nameof (CreateShapeContour);
    try
    {
      Item = new MarbleItem();
      Item.ItemEntities.GroupEntities = new List<buEntitiesGroup>();
      Item.EntGroup = new buEntitiesGroup();
      Item.ItemEntities.SourceEntities = new List<buEntity>();
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      Item.ItemEntities.EdgeEntities = new List<buEntity>();
      Item.ItemEntities.ExtensionEntities = new List<buEntity>();
      this.CreateShapeEntities(refPoint, entContour, ref Item, isText);
      Item.ItemType = MarbleItemType.Contour;
      Item.ToolType = ToolType;
      Item.ItemName = buLangTranslate.preDef.Contour;
      for (int index1 = 0; index1 <= this.entitiesGroupForRefEntities.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= this.entitiesGroupForRefEntities[index1].Outside.Entities.Count - 1; ++index2)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(this.entitiesGroupForRefEntities[index1].Outside.Entities[index2], ref copiedEntity);
          if (refPoint != (Point3D) null)
            copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
          Item.ItemEntities.DrawWireEntities.Add(copiedEntity);
        }
      }
      if (entContour.Outside.Marble != null)
        Item.EntGroup.Outside.Marble = new marbleEntityData(entContour.Outside.Marble);
      else
        clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref Item.EntGroup.Outside.Marble);
      for (int index = 0; index <= entContour.Outside.Entities.Count - 1; ++index)
      {
        buEntity copiedEntity = (buEntity) null;
        buEntity.Copy(entContour.Outside.Entities[index], ref copiedEntity);
        if (refPoint != (Point3D) null)
          copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
        if (copiedEntity.Marble == null)
          copiedEntity.Marble = new MarbleInfo();
        Item.EntGroup.Outside.InOutType = entContour.Outside.InOutType;
        Item.EntGroup.Outside.Entities.Add(copiedEntity);
        Item.EntGroup.Outside.ToolType = entContour.Outside.ToolType;
      }
      if ((entContour.Inside == null ? 0 : (entContour.Inside.Count > 0 ? 1 : 0)) != 0)
      {
        Item.EntGroup.Inside = new List<buEntityList>();
        for (int index3 = 0; index3 <= entContour.Inside.Count - 1; ++index3)
        {
          buEntityList buEntityList = new buEntityList();
          buEntityList.InOutType = entContour.Inside[index3].InOutType;
          if (entContour.Inside[index3].Marble != null)
            buEntityList.Marble = new marbleEntityData(entContour.Inside[index3].Marble);
          else
            clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref buEntityList.Marble);
          for (int index4 = 0; index4 <= entContour.Inside[index3].Entities.Count - 1; ++index4)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(entContour.Inside[index3].Entities[index4], ref copiedEntity);
            if (refPoint != (Point3D) null)
              copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
            if (copiedEntity.Marble == null)
              copiedEntity.Marble = new MarbleInfo();
            buEntityList.Entities.Add(copiedEntity);
          }
          buEntityList.ToolType = entContour.Inside[index3].ToolType;
          if (entContour.Inside[index3].Entities.Count == 1 && entContour.Inside[index3].Entities[0] is buCircle)
            entContour.Inside[index3].ToolType = entityToolType.Milling;
          Item.EntGroup.Inside.Add(buEntityList);
        }
      }
      if ((entContour.OpenEntities == null ? 0 : (entContour.OpenEntities.Count > 0 ? 1 : 0)) != 0)
      {
        Item.EntGroup.OpenEntities = new List<buEntityList>();
        for (int index5 = 0; index5 <= entContour.OpenEntities.Count - 1; ++index5)
        {
          buEntityList buEntityList = new buEntityList();
          if (entContour.OpenEntities[index5].Marble != null)
            buEntityList.Marble = new marbleEntityData(entContour.OpenEntities[index5].Marble);
          else
            clsInit.cMarble.MarbleEntityCamDataSet(ToolType, TargetZ, ref buEntityList.Marble);
          for (int index6 = 0; index6 <= entContour.OpenEntities[index5].Entities.Count - 1; ++index6)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(entContour.OpenEntities[index5].Entities[index6], ref copiedEntity);
            if (refPoint != (Point3D) null)
              copiedEntity.Translate(refPoint.X, refPoint.Y, 0.0);
            if (copiedEntity.Marble == null)
              copiedEntity.Marble = new MarbleInfo();
            buEntityList.Entities.Add(copiedEntity);
          }
          buEntityList.ToolType = entContour.OpenEntities[index5].ToolType;
          Item.EntGroup.OpenEntities.Add(buEntityList);
        }
      }
      if (Item.ToolType != 0)
        ;
      clsInit.cVector5.BoxSizeCalculate(Item.EntGroup.Outside.Entities, ref Item.SizeItem.MinPoint, ref Item.SizeItem.MidPoint, ref Item.SizeItem.MaxPoint);
      Item.SizeItem.MaxPoint.Z = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
      Item.SizeItem.Depth = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness - Item.SizeItem.MinPoint.Z;
      Item.SizeItem.Width = Item.SizeItem.MaxPoint.X - Item.SizeItem.MinPoint.X;
      Item.SizeItem.Height = Item.SizeItem.MaxPoint.Y - Item.SizeItem.MinPoint.Y;
      Item.EntGroup.Outside.Direction = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
      clsInit.cMarble.ItemClockDirectionCheck(ref Item, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection);
      Item.ClockDir = clsInit.cVector5.EntitiesClockDirection(Item.EntGroup.Outside.Entities);
      Item.ID = MarbleTempVars.ItemID;
      ++MarbleTempVars.ItemID;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Drill Settings Decoder Error");
    }
  }

  public void CreateShapeEntities(
    Point3D refPoint,
    buEntitiesGroup entContour,
    ref MarbleItem Item,
    bool isText = false)
  {
    Entity entSurface = (Entity) null;
    if (!buMarbleCalc.varOperation.settingMarbleCam.Contour3DCreate)
      return;
    List<Point3D> Points1 = new List<Point3D>();
    List<List<Point3D>> Inners = new List<List<Point3D>>();
    if (entContour.Outside.Entities.Count > 0)
    {
      clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour.Outside.Entities, ref Points1);
      if (entContour.Inside.Count > 0)
      {
        for (int index = 0; index <= entContour.Inside.Count - 1; ++index)
        {
          List<Point3D> Points2 = new List<Point3D>();
          clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour.Inside[index].Entities, ref Points2);
          Inners.Add(Points2);
        }
      }
      clsInit.cVector5.surfaceFromOutterInner(Points1, Inners, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness, ref entSurface);
    }
    if (entSurface == null)
      return;
    if (refPoint != (Point3D) null)
      entSurface.Translate(refPoint.X, refPoint.Y);
    Item.ItemEntities.SolidEntity = new List<Entity>();
    if (!isText)
    {
      entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
      entSurface.ColorMethod = colorMethodType.byEntity;
    }
    else
    {
      entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemText.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemText.Color);
      entSurface.ColorMethod = colorMethodType.byEntity;
    }
    Item.ItemEntities.SolidEntity.Add(entSurface);
  }

  public void doAddItem3DFile(Point3D refPoint, List<Entity> Entities)
  {
    string str = nameof (doAddItem3DFile);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      MarbleItem MI = new MarbleItem();
      MI.ItemType = MarbleItemType.Shape3D;
      MI.ItemEntities.EngravingEntities = new List<buEntity>();
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (clsInit.cVector5.isEntitySolid(Entities[index]))
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          if (copiedEntity != null)
          {
            if (MI.ItemEntities.SolidEntity == null)
              MI.ItemEntities.SolidEntity = new List<Entity>();
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
            copiedEntity.ColorMethod = colorMethodType.byEntity;
            switch (copiedEntity)
            {
              case Mesh _:
                MI.ItemEntities.SolidEntity.Add(copiedEntity);
                continue;
              case Brep _:
                MI.ItemEntities.SolidEntity.Add((Entity) ((Brep) copiedEntity).ConvertToMesh(0.01));
                continue;
              case devDept.Eyeshot.Entities.Surface _:
                devDept.Eyeshot.Entities.Surface surface = (devDept.Eyeshot.Entities.Surface) copiedEntity;
                surface.Regen(0.05);
                MI.ItemEntities.SolidEntity.Add((Entity) surface.ConvertToMesh(0.01));
                continue;
              default:
                continue;
            }
          }
        }
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
        ObjectSize3D.CalculateSize(ref MI.SizeItem);
      }
      if ((MI.ItemEntities.SolidEntity == null ? 0 : (MI.BaseHeight > 0.0 ? 1 : 0)) != 0)
      {
        Entity surfaceEntity = (Entity) null;
        clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
        if (surfaceEntity != null)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(surfaceEntity, ref copiedEntity);
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
          MI.ItemEntities.BaseEntities = new List<buEntity>();
          MI.ItemEntities.BaseEntities.Add(copiedEntity);
        }
      }
      this.doAddItemCommonProps(ref MI);
      this.AddOperationBeforeThings();
      this.doAddItemToJob(MI, true, true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItem3DShape(
    Point3D pntActive,
    List<buEntity> refEntities,
    double Height,
    bool isFinished,
    int JobListIndex)
  {
    string str = nameof (doAddItem3DShape);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (!isFinished)
        return;
      clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref clsInit.appMarble.entitiesForMove);
      MarbleItem MI = new MarbleItem();
      MI.ItemType = MarbleItemType.Shape3D;
      MI.EntGroup = new buEntitiesGroup();
      MI.EntGroupBottom = new buEntitiesGroup();
      buEntity.Copy(refEntities, ref MI.EntGroup.Outside.Entities);
      clsInit.cVector5.Move(pntActive.X, pntActive.Y, Height, ref MI.EntGroup.Outside.Entities);
      buEntity.Copy(refEntities, ref MI.EntGroupBottom.Outside.Entities);
      clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref MI.EntGroupBottom.Outside.Entities);
      this.Create3DShapeEntities(new Point3D(), MI.EntGroup, MI.EntGroupBottom, ref MI);
      this.AddOperationBeforeThings();
      this.doAddItemToJob(MI, true, true);
      buMarbleCalc.SelectedItem.ActiveItem.indexItem = this.activeJob.Items.Count - 1;
      clsInit.appCommand.Reset();
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

  public void doAddInsideOperation(
    Point3D pntActive,
    List<buEntity> refEntities,
    double Depth,
    bool isFinished,
    planeNames refPlane)
  {
    string str = nameof (doAddInsideOperation);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (!isFinished || !(buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexItem <= this.activeJob.Items.Count - 1))
        return;
      clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref clsInit.appMarble.entitiesForMove);
      MarbleItem marbleItem = this.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
      if (marbleItem.EntGroup != null)
      {
        List<buEntity> refEntities1 = new List<buEntity>();
        buEntity.Copy(refEntities, ref refEntities1);
        if (refPlane == planeNames.Top)
          clsInit.cVector5.Move(pntActive.X, pntActive.Y, marbleItem.SizeItem.Depth, ref refEntities1);
        else
          clsInit.cVector5.Move(pntActive.X, pntActive.Y, 0.0, ref refEntities1);
        this.Create3DShapeInsideEntities(new Point3D(), refEntities1, Depth, refPlane, ref marbleItem);
      }
      clsInit.appCommand.Reset();
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

  public void doContourPocketCamAdd(
    MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType)
  {
    if (CamType == MarbleCamType.MillingRoughInside2D)
    {
      MarbleItemCam marbleCam;
      if (Item.EntGroup != null && Item.EntGroup.Inside != null)
      {
        for (int index = 0; index <= Item.EntGroup.Inside.Count - 1; ++index)
        {
          CamWireFrameType WireType = CamWireFrameType.Pocket;
          marbleCam = new MarbleItemCam()
          {
            CamName = $"{buLangTranslate.preDef.Pocket} {buLangTranslate.preDef.Inside}",
            CamMarbleType = CamType,
            CamMode = MarbleCamMode.Rough,
            CamPlane = planeNames.Top,
            setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar)
          };
          marbleCam.setCam.Steps.StartValue = Item.SizeItem.MaxPoint.Z;
          marbleCam.setCam.Steps.EndValue = Item.SizeItem.MaxPoint.Z - Item.EntGroup.Inside[index].Depth;
          marbleCam.setCam.Steps.Enable = true;
          if (this.activeJob.Material.Enable && this.activeJob.Material.Size.Depth > marbleCam.setCam.Steps.StartValue)
            marbleCam.setCam.Steps.StartValue = this.activeJob.Material.Size.Depth;
          marbleCam.ToolType = CuttingToolType;
          marbleCam.WireType = WireType;
          marbleCam.MeshType = CamTriangularMeshType.None;
          marbleCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(WireType);
          marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
          marbleCam.EntityList = new buEntityList();
          marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroup.Inside[index])
          {
            Depth = Item.EntGroup.Inside[index].Depth
          }.Entities);
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
          Item.CamList.Add(marbleCam);
          this.doShapeMillingCamCalc(ref Item, ref marbleCam);
        }
      }
      if (Item.EntGroupBottom != null && Item.EntGroupBottom.Inside != null)
      {
        for (int index = 0; index <= Item.EntGroupBottom.Inside.Count - 1; ++index)
        {
          marbleCam = new MarbleItemCam()
          {
            CamName = $"{buLangTranslate.preDef.Pocket} {buLangTranslate.preDef.Inside}",
            CamMarbleType = CamType,
            CamMode = MarbleCamMode.Rough,
            CamPlane = planeNames.Bottom,
            setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar)
          };
          marbleCam.setCam.Steps.StartValue = Item.EntGroupBottom.Inside[index].Depth;
          marbleCam.setCam.Steps.EndValue = 0.0;
          marbleCam.setCam.Steps.Enable = true;
          marbleCam.ToolType = CuttingToolType;
          marbleCam.WireType = CamWireFrameType.Pocket;
          marbleCam.MeshType = CamTriangularMeshType.None;
          marbleCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Pocket);
          marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
          marbleCam.EntityList = new buEntityList();
          marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroupBottom.Inside[index])
          {
            Depth = Item.EntGroupBottom.Inside[index].Depth
          }.Entities);
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
          Item.CamList.Add(marbleCam);
          this.doShapeMillingCamCalc(ref Item, ref marbleCam);
        }
      }
    }
    else
    {
      MarbleItemCam marbleCam;
      if (Item.EntGroup != null)
      {
        CamWireFrameType WireType = CamWireFrameType.Pocket;
        marbleCam = new MarbleItemCam()
        {
          CamName = $"{buLangTranslate.preDef.Pocket} {buLangTranslate.preDef.Inside}",
          CamMarbleType = CamType,
          CamMode = MarbleCamMode.Rough,
          CamPlane = planeNames.Top,
          setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar)
        };
        marbleCam.setCam.Steps.StartValue = Item.SizeItem.MaxPoint.Z;
        marbleCam.setCam.Steps.EndValue = Item.SizeItem.MaxPoint.Z - Item.EntGroup.Outside.Depth;
        marbleCam.setCam.Steps.Enable = true;
        if (this.activeJob.Material.Enable && this.activeJob.Material.Size.Depth > marbleCam.setCam.Steps.StartValue)
          marbleCam.setCam.Steps.StartValue = this.activeJob.Material.Size.Depth;
        marbleCam.ToolType = CuttingToolType;
        marbleCam.WireType = WireType;
        marbleCam.MeshType = CamTriangularMeshType.None;
        marbleCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(WireType);
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.EntityList = new buEntityList();
        marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroup.Outside)
        {
          Depth = Item.EntGroup.Outside.Depth
        }.Entities);
        if (Item.EntGroup.Inside != null)
        {
          for (int index = 0; index <= Item.EntGroup.Inside.Count - 1; ++index)
            marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroup.Inside[index])
            {
              Depth = Item.EntGroup.Inside[index].Depth
            }.Entities);
        }
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        Item.CamList.Add(marbleCam);
        this.doShapeMillingCamCalc(ref Item, ref marbleCam);
      }
      if (Item.EntGroupBottom != null)
      {
        marbleCam = new MarbleItemCam()
        {
          CamName = $"{buLangTranslate.preDef.Pocket} {buLangTranslate.preDef.Inside}",
          CamMarbleType = CamType,
          CamMode = MarbleCamMode.Rough,
          CamPlane = planeNames.Top,
          setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DRough.buPar)
        };
        marbleCam.setCam.Steps.StartValue = Item.EntGroupBottom.Outside.Depth;
        marbleCam.setCam.Steps.EndValue = 0.0;
        marbleCam.setCam.Steps.Enable = true;
        marbleCam.ToolType = CuttingToolType;
        marbleCam.WireType = CamWireFrameType.Pocket;
        marbleCam.MeshType = CamTriangularMeshType.None;
        marbleCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Pocket);
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.EntityList = new buEntityList();
        marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroupBottom.Outside)
        {
          Depth = Item.EntGroupBottom.Outside.Depth
        }.Entities);
        if (Item.EntGroupBottom.Inside != null)
        {
          for (int index = 0; index <= Item.EntGroupBottom.Inside.Count - 1; ++index)
            marbleCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(Item.EntGroupBottom.Inside[index])
            {
              Depth = Item.EntGroupBottom.Inside[index].Depth
            }.Entities);
        }
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        Item.CamList.Add(marbleCam);
        this.doShapeMillingCamCalc(ref Item, ref marbleCam);
      }
    }
    this.AddOperationAfterThings();
  }

  public void Create3DShapeInsideEntities(
    Point3D refPoint,
    List<buEntity> refEntities,
    double Depth,
    planeNames refPlane,
    ref MarbleItem Item)
  {
    List<Point3D> Points = new List<Point3D>();
    if (refEntities.Count <= 0)
      return;
    ICurve outer = (ICurve) null;
    clsInit.cVector5.EntitiesToPointsWithCamDirection(refEntities, ref Points);
    if (Points.Count >= 3)
      outer = (ICurve) new LinearPath((ICollection<Point3D>) Points);
    if (outer == null)
      return;
    if (Item.ItemEntities.SolidInsideEntity == null)
      Item.ItemEntities.SolidInsideEntity = new List<Entity>();
    if (refPlane == planeNames.Top)
    {
      Entity entity = (Entity) new devDept.Eyeshot.Entities.Region(outer).ExtrudeAsMesh(new Vector3D(0.0, 0.0, -Depth), 0.1, Mesh.natureType.RichSmooth);
      entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemInside.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemInside.Color);
      entity.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidInsideEntity.Add(entity);
      buEntityList buEntityList = new buEntityList();
      buEntity.Copy(refEntities, ref buEntityList.Entities);
      buEntityList.Depth = Depth;
      Item.EntGroup.Outside.Depth = Depth;
      Item.EntGroup.Inside.Add(buEntityList);
    }
    if (refPlane != planeNames.Bottom)
      return;
    Entity entity1 = (Entity) new devDept.Eyeshot.Entities.Region(outer).ExtrudeAsMesh(new Vector3D(0.0, 0.0, Depth), 0.1, Mesh.natureType.RichSmooth);
    entity1.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemInside.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemInside.Color);
    entity1.ColorMethod = colorMethodType.byEntity;
    Item.ItemEntities.SolidInsideEntity.Add(entity1);
    buEntityList buEntityList1 = new buEntityList();
    buEntity.Copy(refEntities, ref buEntityList1.Entities);
    buEntityList1.Depth = Depth;
    Item.EntGroupBottom.Outside.Depth = Depth;
    Item.EntGroupBottom.Inside.Add(buEntityList1);
  }

  public void Create3DShapeEntities(
    Point3D refPoint,
    buEntitiesGroup entContourTopPlane,
    buEntitiesGroup entContourBottomPlane,
    ref MarbleItem Item)
  {
    Entity entity = (Entity) null;
    List<Point3D> Points1 = new List<Point3D>();
    List<Point3D> Points2 = new List<Point3D>();
    List<List<Point3D>> point3DListList = new List<List<Point3D>>();
    ICurve outer1 = (ICurve) null;
    ICurve outer2 = (ICurve) null;
    if (entContourTopPlane.Outside.Entities.Count > 0)
      clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourTopPlane.Outside.Entities, ref Points1);
    if (entContourBottomPlane.Outside.Entities.Count > 0)
      clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourBottomPlane.Outside.Entities, ref Points2);
    if (entContourTopPlane.Inside.Count > 0)
    {
      for (int index = 0; index <= entContourTopPlane.Inside.Count - 1; ++index)
      {
        List<Point3D> Points3 = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(entContourTopPlane.Inside[index].Entities, ref Points3);
        point3DListList.Add(Points3);
      }
    }
    if (Points1.Count >= 3)
      outer1 = (ICurve) new LinearPath((ICollection<Point3D>) Points1);
    if (Points2.Count >= 3)
      outer2 = (ICurve) new LinearPath((ICollection<Point3D>) Points2);
    if ((outer1 == null ? 0 : (outer2 != null ? 1 : 0)) != 0)
    {
      devDept.Eyeshot.Entities.Region region1 = new devDept.Eyeshot.Entities.Region(outer1);
      devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer2);
      entity = (Entity) Brep.Ruled((devDept.Eyeshot.Entities.Surface) region1.ConvertToSurface(), (devDept.Eyeshot.Entities.Surface) region2.ConvertToSurface()).ConvertToMesh(0.1);
    }
    if (entity == null)
      return;
    if (refPoint != (Point3D) null)
      entity.Translate(refPoint.X, refPoint.Y);
    Item.ItemEntities.SolidEntity = new List<Entity>();
    entity.Regen(0.1);
    entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemContour.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemContour.Color);
    entity.ColorMethod = colorMethodType.byEntity;
    Item.ItemEntities.SolidEntity.Add(entity);
    Item.SizeItem.Width = entity.BoxMax.X - entity.BoxMin.X;
    Item.SizeItem.Height = entity.BoxMax.Y - entity.BoxMin.Y;
    Item.SizeItem.Depth = entity.BoxMax.Z - entity.BoxMin.Z;
    Item.SizeItem.MinPoint = buVector5.ToPoint3D(entity.BoxMin);
    Item.SizeItem.MaxPoint = buVector5.ToPoint3D(entity.BoxMax);
    Item.SizeItem.MidPoint = clsInit.cVector5.MiddlePointOfLine(Item.SizeItem.MinPoint, Item.SizeItem.MaxPoint);
  }

  public void doAddItemVerHorMainForm(
    Point3D refPoint,
    double AngleC,
    double Length,
    bool isFinished = false)
  {
    string str1 = "doAddItemVerHorV3";
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (refPoint == (Point3D) null)
      {
        MarbleTempVars.HorizontalStartPos.X = buMarbleForms.frmHorizontal.spn_xoffset.Value;
        MarbleTempVars.HorizontalStartPos.Y = buMarbleForms.frmHorizontal.spn_yoffset.Value;
        MarbleTempVars.VerticalStartPos.X = buMarbleForms.frmVertical.spn_xoffset.Value;
        MarbleTempVars.VerticalStartPos.Y = buMarbleForms.frmVertical.spn_yoffset.Value;
      }
      else
      {
        MarbleTempVars.HorizontalStartPos.X = refPoint.X;
        MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
        MarbleTempVars.VerticalStartPos.X = refPoint.X;
        MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
      }
      this.activeJob.CamCalculated = false;
      List<string> stringList1 = new List<string>();
      MarbleTempVars.listHorizontalItems.Clear();
      MarbleTempVars.listHorizontalItems = new List<marbleCuttingItems>();
      if (MarbleTempVars.isHorizontal)
        this.ItemListAnalyse(MarbleTempVars.cutItemsHor, ref MarbleTempVars.listHorizontalItems, -1.0, -1.0);
      if (MarbleTempVars.listHorizontalItems.Count > 0)
      {
        if (buMarbleCalc.varMarbleRunSettings.HorCornerType == MarbleCorners.LeftTop)
        {
          for (int index = 0; index <= MarbleTempVars.listHorizontalItems.Count - 1; ++index)
            MarbleTempVars.listHorizontalItems[index].Length = -MarbleTempVars.listHorizontalItems[index].Length;
        }
        if (buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal <= 0.0)
          stringList1.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
        if (MarbleTempVars.HorizontalStartPos.C > 45.0 & MarbleTempVars.HorizontalStartPos.C < 135.0 | MarbleTempVars.HorizontalStartPos.C > 225.0 & MarbleTempVars.HorizontalStartPos.C < 315.0)
          buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.ThisCanBeVerticalCut);
      }
      MarbleTempVars.listVerticalItems.Clear();
      MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
      if (!MarbleTempVars.isHorizontal)
        this.ItemListAnalyse(MarbleTempVars.cutItemsVer, ref MarbleTempVars.listVerticalItems, -1.0, -1.0);
      if (MarbleTempVars.listVerticalItems.Count > 0)
      {
        if (buMarbleCalc.varMarbleRunSettings.VerCornerType == MarbleCorners.LeftTop)
        {
          for (int index = 0; index <= MarbleTempVars.listVerticalItems.Count - 1; ++index)
            MarbleTempVars.listVerticalItems[index].Length = -MarbleTempVars.listVerticalItems[index].Length;
        }
        if (buMarbleCalc.varMarbleRunSettings.CutLengthVertical <= 0.0)
          stringList1.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
      }
      int num1;
      for (int index = 0; index <= MarbleTempVars.listHorizontalItems.Count - 1; ++index)
      {
        if (Math.Abs(MarbleTempVars.listHorizontalItems[index].StartAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
        {
          List<string> stringList2 = stringList1;
          string[] strArray = new string[9];
          strArray[0] = buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit;
          strArray[1] = " - [";
          num1 = index + 1;
          strArray[2] = num1.ToString();
          strArray[3] = "] ";
