        for (int index = 0; index <= MarbleTempVars.listHorizontalItems.Count - 1; ++index)
          MarbleTempVars.listHorizontalItems[index].Length = -MarbleTempVars.listHorizontalItems[index].Length;
      }
      if (buMarbleCalc.varMarbleRunSettings.HorVerHorCornerType == MarbleCorners.LeftBottom & buMarbleCalc.varMarbleRunSettings.HorVerVerCornerType == MarbleCorners.LeftTop)
        ;
      if (MarbleTempVars.listHorizontalItems.Count > 0)
      {
        if (buMarbleCalc.varMarbleRunSettings.CutLengthHorVerHorizontal <= 0.0)
          stringList.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
        if (MarbleTempVars.HorizontalStartPos.C > 45.0 & MarbleTempVars.HorizontalStartPos.C < 135.0 | MarbleTempVars.HorizontalStartPos.C > 225.0 & MarbleTempVars.HorizontalStartPos.C < 315.0)
          buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.ThisCanBeVerticalCut);
      }
      MarbleTempVars.listVerticalItems.Clear();
      MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
      this.ItemListAnalyse(MarbleTempVars.cutItemsHorVerVer, ref MarbleTempVars.listVerticalItems, -1.0, -1.0);
      if (buMarbleCalc.varMarbleRunSettings.HorVerVerCornerType == MarbleCorners.LeftTop)
      {
        for (int index = 0; index <= MarbleTempVars.listVerticalItems.Count - 1; ++index)
          MarbleTempVars.listVerticalItems[index].Length = -MarbleTempVars.listVerticalItems[index].Length;
      }
      if (MarbleTempVars.listVerticalItems.Count > 0)
      {
        if (buMarbleCalc.varMarbleRunSettings.CutLengthHorVerVertical <= 0.0)
          stringList.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
        if (!MarbleTempVars.VerticalSetStartPositionDone)
          ;
      }
      if (buMarbleCalc.varOperation.settingMarbleCam.TargetZ >= buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
        stringList.Add(buLangTranslate.preSentencesMarble.DepthValueCantBeBiggerThenMAterialThickness);
      for (int index = 0; index <= MarbleTempVars.listHorizontalItems.Count - 1; ++index)
      {
        if (Math.Abs(MarbleTempVars.listHorizontalItems[index].StartAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
          stringList.Add($"{buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit} - [{(index + 1).ToString()}] {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.StartAngle} {MarbleTempVars.listHorizontalItems[index].StartAngle.ToString()}");
        if (Math.Abs(MarbleTempVars.listHorizontalItems[index].EndAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
          stringList.Add($"{buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit} - [{(index + 1).ToString()}] {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.EndAngle} {MarbleTempVars.listHorizontalItems[index].EndAngle.ToString()}");
      }
      for (int index = 0; index <= MarbleTempVars.listVerticalItems.Count - 1; ++index)
      {
        if (Math.Abs(MarbleTempVars.listVerticalItems[index].StartAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
          stringList.Add($"{buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit} - [{(index + 1).ToString()}] {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.StartAngle} {MarbleTempVars.listVerticalItems[index].StartAngle.ToString()}");
        if (Math.Abs(MarbleTempVars.listVerticalItems[index].EndAngle) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
          stringList.Add($"{buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit} - [{(index + 1).ToString()}] {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.EndAngle} {MarbleTempVars.listVerticalItems[index].EndAngle.ToString()}");
      }
      this.activeJob.CamCalculated = false;
      if (LengthHor <= 0.0 & MarbleTempVars.listHorizontalItems.Count > 0)
        stringList.Add($"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preSentencesMarble.CuttingLengthis0} = {LengthHor.ToString("f1")}");
      if (LengthHor > buMarbleCalc.varOperation.settingSliceCut.MaxSliceLength & MarbleTempVars.listHorizontalItems.Count > 0)
        stringList.Add($"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preSentencesMarble.LengthisNotSuitable} = {LengthHor.ToString("f1")}");
      if (LengthVer <= 0.0 & MarbleTempVars.listVerticalItems.Count > 0)
        stringList.Add($"{buLangTranslate.preDef.Vertical} {buLangTranslate.preSentencesMarble.CuttingLengthis0} = {LengthHor.ToString("f1")}");
      if (LengthVer > buMarbleCalc.varOperation.settingSliceCut.MaxSliceLength & MarbleTempVars.listHorizontalItems.Count > 0)
        stringList.Add($"{buLangTranslate.preDef.Vertical} {buLangTranslate.preSentencesMarble.LengthisNotSuitable} = {LengthVer.ToString("f1")}");
      if (stringList.Count > 0)
      {
        DialogBoxList dialogBoxList = new DialogBoxList();
        dialogBoxList.Caption = $"{buLangTranslate.preDef.Marble} {buLangTranslate.preDef.Error}";
        dialogBoxList.Width = 700;
        for (int index = 0; index <= stringList.Count - 1; ++index)
          dialogBoxList.Items.Add(stringList[index]);
        dialogBoxList.Init("", 0);
        int num = (int) dialogBoxList.ShowDialog();
      }
      else
      {
        if (AngleC > -45.0 & AngleC < 45.0)
          MarbleTempVars.HorizontalStartPos.C = -AngleC;
        else if (AngleC > 135.0 & AngleC < 225.0)
          MarbleTempVars.HorizontalStartPos.C = AngleC;
        else
          stringList.Add("C Angle is not Suitable");
        if (buMarbleCalc.varMarbleRunSettings.HorVerVerCornerType == MarbleCorners.LeftTop)
          MarbleTempVars.VerticalStartPos.C = -MarbleTempVars.HorizontalStartPos.C - 90.0;
        if (buMarbleCalc.varMarbleRunSettings.HorVerVerCornerType == MarbleCorners.LeftBottom)
          MarbleTempVars.VerticalStartPos.C = -MarbleTempVars.HorizontalStartPos.C + 90.0;
        MarbleTempVars.ItemsSlice.Clear();
        buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
        clsInit.cMarble.doMultiCut(MarbleTempVars.HorizontalStartPos, MarbleTempVars.VerticalStartPos, buMarbleCalc.activeToolSaw, MarbleTempVars.listHorizontalItems, MarbleTempVars.listVerticalItems, buMarbleCalc.varOperation, clsMarble.activeKinematic, new EntitiesResolution(), ref MarbleTempVars.ItemsSlice, MarbleSliceType.HorizontalVertical, buMarbleCalc.varMarbleRunSettings.CutLengthHorVerHorizontal, buMarbleCalc.varMarbleRunSettings.CutLengthHorVerVertical, isFinished);
        double num1 = 0.0;
        double num2 = 0.0;
        if (buMarbleCalc.varMarbleRunSettings.HorVerHorCornerType == MarbleCorners.LeftTop & buMarbleCalc.varOperation.settingSliceCut.MoveLeftTopCornerToTopYPosition)
        {
          for (int index1 = 0; index1 <= MarbleTempVars.ItemsSlice.Count - 1; ++index1)
          {
            MarbleTempVars.ItemsSlice[index1].ItemEntities.TextEntities = new List<buEntity>();
            for (int index2 = 0; index2 <= MarbleTempVars.ItemsSlice[index1].ItemEntities.SolidEntity.Count - 1; ++index2)
            {
              if (MarbleTempVars.ItemsSlice[index1].ItemEntities.SolidEntity[index2].BoxMin == (Point3D) null)
                MarbleTempVars.ItemsSlice[index1].ItemEntities.SolidEntity[index2].Regen(0.1);
              if (MarbleTempVars.ItemsSlice[index1].ItemEntities.SolidEntity[index2].BoxMin.Y < num2)
                num2 = MarbleTempVars.ItemsSlice[index1].ItemEntities.SolidEntity[index2].BoxMin.Y;
            }
          }
          num2 -= refPointHor.Y;
        }
        if (!isFinished)
        {
          buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
          buEyeItems.viewportDialogs.Entities.Clear();
          if (buMarbleForms.frmHorVerDialog.Visible)
          {
            for (int index3 = 0; index3 <= MarbleTempVars.ItemsSlice.Count - 1; ++index3)
            {
              MarbleItem marbleItem = MarbleTempVars.ItemsSlice[index3];
              for (int index4 = 0; index4 <= marbleItem.ItemEntities.SolidEntity.Count - 1; ++index4)
              {
                Entity copiedEntity = (Entity) null;
                buEntity.Copy(marbleItem.ItemEntities.SolidEntity[index4], ref copiedEntity);
                if (copiedEntity != null)
                {
                  copiedEntity.Regen(0.1);
                  ((CustomData) copiedEntity.EntityData).ActionName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).EntityName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
                  ((CustomData) copiedEntity.EntityData).ID = marbleItem.ID.ToString();
                  ((CustomData) copiedEntity.EntityData).Tags = "Solid";
                  copiedEntity.LayerName = "Default";
                  copiedEntity.ColorMethod = colorMethodType.byEntity;
                  copiedEntity.Color = Color.WhiteSmoke;
                  buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
                }
              }
            }
            buEyeItems.viewportDialogs.SetView(viewType.Top);
            buEyeItems.viewportDialogs.ZoomFit();
            buEyeItems.viewportDialogs.Invalidate();
          }
        }
        else if (MarbleTempVars.ItemsSlice.Count > 0)
        {
          TpPnt9D LastP9 = (TpPnt9D) null;
          this.AddOperationBeforeThings();
          for (int index5 = 0; index5 <= 1; ++index5)
          {
            for (int index6 = 0; index6 <= MarbleTempVars.ItemsSlice.Count - 1; ++index6)
            {
              bool flag = false;
              if (index5 == 0)
              {
                if (buMarbleCalc.varOperation.settingSliceCut.HorizontalVerticalSequence == HorizontalVertical.Horizontal)
                {
                  if (MarbleTempVars.ItemsSlice[index6].ItemType == MarbleItemType.HorizontalCut)
                    flag = true;
                }
                else if (MarbleTempVars.ItemsSlice[index6].ItemType == MarbleItemType.VerticalCut)
                  flag = true;
              }
              if (index5 == 1)
              {
                if (buMarbleCalc.varOperation.settingSliceCut.HorizontalVerticalSequence == HorizontalVertical.Horizontal)
                {
                  if (MarbleTempVars.ItemsSlice[index6].ItemType == MarbleItemType.VerticalCut)
                    flag = true;
                }
                else if (MarbleTempVars.ItemsSlice[index6].ItemType == MarbleItemType.HorizontalCut)
                  flag = true;
              }
              if (flag)
              {
                MarbleItem MI = new MarbleItem(MarbleTempVars.ItemsSlice[index6]);
                clsInit.cVector5.Move(-num1, -num2, 0.0, ref MI.ItemEntities.DrawWireEntities);
                clsInit.cVector5.Move(-num1, -num2, 0.0, ref MI.ItemEntities.WireEntities);
                clsInit.cVector5.Move(-num1, -num2, 0.0, ref MI.ItemEntities.SolidEntity);
                clsInit.cVector5.Move(-num1, -num2, 0.0, ref MI.EntGroup);
                MI.ItemEntities.TextEntities = new List<buEntity>();
                MI.ItemEntities.EdgeEntities = new List<buEntity>();
                MI.ItemEntities.DrawWireEntities = new List<buEntity>();
                MI.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
                MI.ItemEntities.ExtensionEntities = new List<buEntity>();
                if (MI.EntGroup == null)
                  MI.EntGroup = new buEntitiesGroup();
                clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
                MI.ID = MarbleTempVars.ItemID;
                ++MarbleTempVars.ItemID;
                MarbleItemCam marbleCam = new MarbleItemCam();
                buEntity.Copy(MI.ItemEntities.WireEntities, ref marbleCam.WireEntities);
                marbleCam.ID = MarbleTempVars.MarbleCamID;
                if (!MarbleTempVars.isHorizontal)
                {
                  marbleCam.CamName = $"{buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Cutting} [{buLangTranslate.preDef.Saw}]";
                  marbleCam.CamMarbleType = MarbleCamType.VerticalSawCutting;
                }
                else
                {
                  marbleCam.CamName = $"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Cutting} [{buLangTranslate.preDef.Saw}]";
                  marbleCam.CamMarbleType = MarbleCamType.HorizontalSawCutting;
                }
                marbleCam.CamMode = MarbleCamMode.Contour;
                marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
                marbleCam.ToolType = MarbleToolType.Saw;
                marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
                marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
                marbleCam.CamType = CamType.Contour;
                marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
                marbleCam.isCamCalculated = true;
                clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
                MI.CamList.Add(marbleCam);
                MI.ToolType = MarbleToolType.Saw;
                MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
                MI.CamPoint = MarbleTempVars.isHorizontal ? new Pnt6D(MarbleTempVars.HorizontalStartPos) : new Pnt6D(MarbleTempVars.VerticalStartPos);
                bool isLast = false;
                if (index6 == MarbleTempVars.ItemsSlice.Count - 1)
                  isLast = true;
                clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, clsMarble.activeKinematic, this.activeJob, index6, isLast, LastP9, MI, ref marbleCam);
                if (marbleCam.CamBase != null)
                {
                  marbleCam.CamBase.Obj1 = (object) MI;
                  marbleCam.CamBase.Obj2 = (object) marbleCam;
                }
                clsInit.cMarble.GetLastCamPointOfItem(MI, ref LastP9);
                if (MI.ItemEntities.SolidEntity != null)
                {
                  for (int index7 = 0; index7 <= MI.ItemEntities.SolidEntity.Count - 1; ++index7)
                  {
                    if (MarbleTempVars.isHorizontal)
                    {
                      MI.ItemEntities.SolidEntity[index7].ColorMethod = colorMethodType.byEntity;
                      MI.ItemEntities.SolidEntity[index7].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
                    }
                    else
                    {
                      MI.ItemEntities.SolidEntity[index7].ColorMethod = colorMethodType.byEntity;
                      MI.ItemEntities.SolidEntity[index7].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
                    }
                  }
                  clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
                  ObjectSize3D.CalculateSize(ref MI.SizeItem);
                  buText buText = new buText(new Point3D(MI.SizeItem.MidPoint.X, MI.SizeItem.MidPoint.Y, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 0.2), (this.activeJob.Items.Count + 1).ToString(), 50.0);
                }
                this.doAddItemToJob(MI, false, true);
              }
            }
          }
        }
      }
      this.activeJob.CamCalculated = false;
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemSingleCut(
    Point3D refPoint,
    double AngleA,
    double AngleC,
    bool isFinished = false,
    int AddIndex = -1,
    bool isVacuum = false)
  {
    string str = nameof (doAddItemSingleCut);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      List<string> stringList = new List<string>();
      MarbleTempVars.listVerticalItems.Clear();
      MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
      if (!MarbleTempVars.isHorizontal)
        this.ItemListAnalyse(MarbleTempVars.cutItemsVer, ref MarbleTempVars.listVerticalItems);
      if (MarbleTempVars.listVerticalItems.Count > 0)
      {
        if (buMarbleCalc.varOperation.settingSliceCut.CutLengthSingle <= 0.0)
          stringList.Add(buLangTranslate.preSentencesMarble.CuttingLengthis0);
        if (!MarbleTempVars.VerticalSetStartPositionDone)
          ;
      }
      if (buMarbleCalc.varOperation.settingMarbleCam.TargetZ >= buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
        stringList.Add(buLangTranslate.preSentencesMarble.DepthValueCantBeBiggerThenMAterialThickness);
      this.activeJob.CamCalculated = false;
      if (stringList.Count > 0)
      {
        DialogBoxList dialogBoxList = new DialogBoxList();
        dialogBoxList.Caption = "Marble Errors";
        dialogBoxList.Width = 500;
        for (int index = 0; index <= stringList.Count - 1; ++index)
          dialogBoxList.Items.Add(stringList[index]);
        dialogBoxList.Init("", 0);
        int num = (int) dialogBoxList.ShowDialog();
      }
      else
      {
        MarbleTempVars.SingleCutPos.X = refPoint.X;
        MarbleTempVars.SingleCutPos.Y = refPoint.Y;
        MarbleTempVars.SingleCutPos.A = AngleA;
        MarbleTempVars.SingleCutPos.C = AngleC;
        MarbleTempVars.ItemsSlice.Clear();
        buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
        clsInit.cMarble.doSingleCut(MarbleTempVars.SingleCutPos, buMarbleCalc.activeToolSaw, buMarbleCalc.varOperation, clsMarble.activeKinematic, new EntitiesResolution(), ref MarbleTempVars.ItemsSlice, MarbleSliceType.HorizontalVertical, isFinished);
        if (!isFinished)
        {
          buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
          buEyeItems.viewportDialogs.Entities.Clear();
          if (buMarbleForms.frmSingle.Visible)
          {
            for (int index1 = 0; index1 <= MarbleTempVars.ItemsSlice.Count - 1; ++index1)
            {
              MarbleItem marbleItem = MarbleTempVars.ItemsSlice[index1];
              for (int index2 = 0; index2 <= marbleItem.ItemEntities.SolidEntity.Count - 1; ++index2)
              {
                Entity copiedEntity = (Entity) null;
                buEntity.Copy(marbleItem.ItemEntities.SolidEntity[index2], ref copiedEntity);
                if (copiedEntity != null)
                {
                  ((CustomData) copiedEntity.EntityData).ActionName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).EntityName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
                  ((CustomData) copiedEntity.EntityData).ID = marbleItem.ID.ToString();
                  ((CustomData) copiedEntity.EntityData).Tags = "Solid";
                  copiedEntity.LayerName = MarbleTempVars.layerMarblePart.Name;
                  buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
                }
              }
            }
            Entity entWood = (Entity) null;
            if (buMarbleCalc.varMarbleSettings.DrawWoodBase)
            {
              this.CreateWoodMaterial(buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight, buMarbleCalc.varMarbleMachineSettings.BaseWoodThickness, buMarbleCalc.varMarbleMachineSettings.BaseWoodZOffset + buMarbleCalc.varOperation.settingMarbleCam.TargetZ, true, buEyeItems.viewportCadCam.Layers[MarbleTempVars.layerWood.Index].Name, ref entWood);
              entWood.Selectable = false;
              buEyeItems.viewportDialogs.Entities.Add(entWood);
            }
            buEyeItems.viewportDialogs.Entities.Regen();
            buEyeItems.viewportDialogs.SetView(viewType.vcFrontFaceTop);
            buEyeItems.viewportDialogs.ZoomFit();
            buEyeItems.viewportDialogs.Invalidate();
          }
        }
        else
        {
          if (MarbleTempVars.ItemsSlice.Count > 0)
          {
            this.AddOperationBeforeThings();
            TpPnt9D LastP9 = (TpPnt9D) null;
            for (int index3 = 0; index3 <= MarbleTempVars.ItemsSlice.Count - 1; ++index3)
            {
              MarbleItem MI = new MarbleItem(MarbleTempVars.ItemsSlice[index3]);
              MI.isVacuumCut = isVacuum;
              MI.ItemEntities.EdgeEntities = new List<buEntity>();
              MI.ItemEntities.DrawWireEntities = new List<buEntity>();
              MI.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
              MI.ItemEntities.ExtensionEntities = new List<buEntity>();
              clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
              MI.ID = MarbleTempVars.ItemID;
              MI.EntGroup = new buEntitiesGroup();
              MI.DontCheckPartLimits = true;
              MarbleItemCam marbleCam = new MarbleItemCam();
              buEntity.Copy(MarbleTempVars.ItemsSlice[index3].ItemEntities.WireEntities, ref marbleCam.WireEntities);
              marbleCam.ID = MarbleTempVars.MarbleCamID;
              if (clsInit.cMarble.isVertical(AngleC))
              {
                marbleCam.CamName = $"{buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Single} {buLangTranslate.preDef.Cutting} [{buLangTranslate.preDef.Saw}]";
                marbleCam.CamMarbleType = MarbleCamType.VerticalSawSingleCutting;
              }
              else
              {
                marbleCam.CamName = $"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Single} {buLangTranslate.preDef.Cutting} [{buLangTranslate.preDef.Saw}]";
                marbleCam.CamMarbleType = MarbleCamType.HorizontalSawSingleCutting;
              }
              marbleCam.CamMode = MarbleCamMode.Contour;
              marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
              marbleCam.ToolType = MarbleToolType.Saw;
              marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
              marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
              marbleCam.CamType = CamType.Contour;
              marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
              clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
              MI.CamList.Add(marbleCam);
              MI.ToolType = MarbleToolType.Saw;
              MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
              MI.CamPoint = MarbleTempVars.isHorizontal ? new Pnt6D(MarbleTempVars.HorizontalStartPos) : new Pnt6D(MarbleTempVars.VerticalStartPos);
              bool isLast = false;
              if (index3 == MarbleTempVars.ItemsSlice.Count - 1)
                isLast = true;
              clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, clsMarble.activeKinematic, this.activeJob, index3, isLast, LastP9, MI, ref marbleCam);
              if (marbleCam.CamBase != null)
              {
                marbleCam.CamBase.Obj1 = (object) MI;
                marbleCam.CamBase.Obj2 = (object) marbleCam;
                if (MI.isVacuumCut)
                  marbleCam.CamBase.MaterialIndex = this.activeJob.VacuumCuts.Count - 1;
              }
              clsInit.cMarble.GetLastCamPointOfItem(MI, ref LastP9);
              if (MI.ItemEntities.SolidEntity != null)
              {
                for (int index4 = 0; index4 <= MI.ItemEntities.SolidEntity.Count - 1; ++index4)
                {
                  if (MarbleTempVars.isHorizontal)
                  {
                    MI.ItemEntities.SolidEntity[index4].ColorMethod = colorMethodType.byEntity;
                    MI.ItemEntities.SolidEntity[index4].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
                  }
                  else
                  {
                    MI.ItemEntities.SolidEntity[index4].ColorMethod = colorMethodType.byEntity;
                    MI.ItemEntities.SolidEntity[index4].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
                  }
                }
                clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
                ObjectSize3D.CalculateSize(ref MI.SizeItem);
              }
              this.doAddItemToJob(MI, false, true, AddIndex);
            }
          }
          this.AddOperationAfterThings();
        }
      }
      this.activeJob.CamCalculated = false;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemSlice(Point3D refPoint, double AngleC, bool isFinished = false)
  {
    string str = nameof (doAddItemSlice);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      List<string> stringList = new List<string>();
      if (MarbleTempVars.listHorizontalItems == null)
        MarbleTempVars.listHorizontalItems = new List<marbleCuttingItems>();
      if (MarbleTempVars.listVerticalItems == null)
        MarbleTempVars.listVerticalItems = new List<marbleCuttingItems>();
      this.activeJob.CamCalculated = false;
      if (stringList.Count > 0)
      {
        DialogBoxList dialogBoxList = new DialogBoxList();
        dialogBoxList.Caption = "Marble Errors";
        dialogBoxList.Width = 500;
        for (int index = 0; index <= stringList.Count - 1; ++index)
          dialogBoxList.Items.Add(stringList[index]);
        dialogBoxList.Init("", 0);
        int num = (int) dialogBoxList.ShowDialog();
      }
      else
      {
        if (!isFinished)
        {
          if (refPoint == (Point3D) null)
          {
            MarbleTempVars.HorizontalStartPos.X = 0.0;
            MarbleTempVars.HorizontalStartPos.Y = 0.0;
            MarbleTempVars.VerticalStartPos.X = 0.0;
            MarbleTempVars.VerticalStartPos.Y = 0.0;
          }
          else
          {
            MarbleTempVars.HorizontalStartPos.X = refPoint.X;
            MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
            MarbleTempVars.VerticalStartPos.X = refPoint.X;
            MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
          }
        }
        else
        {
          MarbleTempVars.HorizontalStartPos.X = refPoint.X;
          MarbleTempVars.HorizontalStartPos.Y = refPoint.Y;
          MarbleTempVars.VerticalStartPos.X = refPoint.X;
          MarbleTempVars.VerticalStartPos.Y = refPoint.Y;
        }
        MarbleTempVars.listHorizontalItems.Clear();
        MarbleTempVars.listVerticalItems.Clear();
        buMarbleCalc.varMarbleRunSettings.SliceWidth = buMarbleForms.frmSlice.spn_itemwidth.Value;
        buMarbleCalc.varMarbleRunSettings.SliceLength = buMarbleForms.frmSlice.spn_itemlength.Value;
        buMarbleCalc.varMarbleRunSettings.SliceStartAngle = buMarbleForms.frmSlice.spn_itemSA.Value;
        buMarbleCalc.varMarbleRunSettings.SliceEndAngle = buMarbleForms.frmSlice.spn_itemEA.Value;
        buMarbleCalc.varMarbleRunSettings.SliceCount = (int) buMarbleForms.frmSlice.spn_itemcount.Value;
        if (buMarbleForms.frmSlice.chk_horizontal.Check)
        {
          buMarbleCalc.varMarbleRunSettings.SliceType = HorizontalVertical.Horizontal;
          MarbleTempVars.isHorizontal = true;
        }
        else
        {
          buMarbleCalc.varMarbleRunSettings.SliceType = HorizontalVertical.Vertical;
          MarbleTempVars.isHorizontal = false;
        }
        MarbleSliceType SliceType;
        if (buMarbleCalc.varMarbleRunSettings.SliceType == HorizontalVertical.Vertical)
        {
          SliceType = MarbleSliceType.Vertical;
          MarbleTempVars.listVerticalItems.Add(new marbleCuttingItems(buMarbleCalc.varMarbleRunSettings.SliceWidth, buMarbleCalc.varMarbleRunSettings.SliceCount, buMarbleCalc.varMarbleRunSettings.SliceStartAngle, buMarbleCalc.varMarbleRunSettings.SliceEndAngle));
          MarbleTempVars.VerticalStartPos.C = 90.0;
          buMarbleCalc.varMarbleRunSettings.CutLengthVertical = buMarbleCalc.varMarbleRunSettings.SliceLength;
        }
        else
        {
          SliceType = MarbleSliceType.Horizontal;
          MarbleTempVars.listHorizontalItems.Add(new marbleCuttingItems(buMarbleCalc.varMarbleRunSettings.SliceWidth, buMarbleCalc.varMarbleRunSettings.SliceCount, buMarbleCalc.varMarbleRunSettings.SliceStartAngle, buMarbleCalc.varMarbleRunSettings.SliceEndAngle));
          MarbleTempVars.VerticalStartPos.C = 0.0;
          buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal = buMarbleCalc.varMarbleRunSettings.SliceLength;
        }
        MarbleTempVars.ItemsSlice.Clear();
        buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool = MarbleToolType.Saw;
        clsInit.cMarble.doMultiCut(MarbleTempVars.HorizontalStartPos, MarbleTempVars.VerticalStartPos, buMarbleCalc.activeToolSaw, MarbleTempVars.listHorizontalItems, MarbleTempVars.listVerticalItems, buMarbleCalc.varOperation, clsMarble.activeKinematic, new EntitiesResolution(), ref MarbleTempVars.ItemsSlice, SliceType, buMarbleCalc.varMarbleRunSettings.CutLengthHorizontal, buMarbleCalc.varMarbleRunSettings.CutLengthVertical, isFinished);
        if (!isFinished)
        {
          buEyeItems.viewportDialogs.ActiveViewport.DisplayMode = displayType.Rendered;
          buEyeItems.viewportDialogs.Entities.Clear();
          if (buMarbleForms.frmSlice.Visible)
          {
            for (int index1 = 0; index1 <= MarbleTempVars.ItemsSlice.Count - 1; ++index1)
            {
              MarbleItem marbleItem = MarbleTempVars.ItemsSlice[index1];
              for (int index2 = 0; index2 <= marbleItem.ItemEntities.SolidEntity.Count - 1; ++index2)
              {
                Entity copiedEntity = (Entity) null;
                buEntity.Copy(marbleItem.ItemEntities.SolidEntity[index2], ref copiedEntity);
                if (copiedEntity != null)
                {
                  copiedEntity.Regen(0.1);
                  ((CustomData) copiedEntity.EntityData).ActionName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).EntityName = $"{marbleItem.ItemType.ToString()}{marbleItem.ID.ToString()}-Solid";
                  ((CustomData) copiedEntity.EntityData).typeDefination = entityTypeDefination.MarbleItem;
                  ((CustomData) copiedEntity.EntityData).ID = marbleItem.ID.ToString();
                  ((CustomData) copiedEntity.EntityData).Tags = "Solid";
                  copiedEntity.LayerName = "Default";
                  copiedEntity.ColorMethod = colorMethodType.byEntity;
                  copiedEntity.Color = Color.WhiteSmoke;
                  buEyeItems.viewportDialogs.Entities.Add(copiedEntity);
                }
              }
            }
            buEyeItems.viewportDialogs.SetView(viewType.Top);
            buEyeItems.viewportDialogs.ZoomFit();
            buEyeItems.viewportDialogs.Invalidate();
          }
        }
        else
        {
          if (MarbleTempVars.ItemsSlice.Count > 0)
          {
            this.AddOperationBeforeThings();
            TpPnt9D LastP9 = (TpPnt9D) null;
            for (int index3 = 0; index3 <= MarbleTempVars.ItemsSlice.Count - 1; ++index3)
            {
              MarbleItem MI = new MarbleItem(MarbleTempVars.ItemsSlice[index3]);
              MI.ItemEntities.EdgeEntities = new List<buEntity>();
              if (MI.ItemEntities.DrawWireEntities == null)
                MI.ItemEntities.DrawWireEntities = new List<buEntity>();
              MI.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
              MI.ItemEntities.ExtensionEntities = new List<buEntity>();
              MI.EntGroup = new buEntitiesGroup();
              EntitiesCopySettings entitiesCopySettings = new EntitiesCopySettings(false, false, true, true, true, true, true, buMarbleCalc.varOperation.settingMarbleCam.RegenDeviation, 0.0);
              buEntity.Copy(MI.ItemEntities.DrawWireEntities, ref MI.EntGroup.Outside.Entities);
              clsInit.cMarble.ItemClockDirectionCheck(ref MI, buMarbleCalc.varOperation.settingMarbleCam.ContourDirection);
              clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
              MI.ID = MarbleTempVars.ItemID;
              MarbleItemCam marbleCam = new MarbleItemCam();
              buEntity.Copy(MarbleTempVars.ItemsSlice[index3].ItemEntities.WireEntities, ref marbleCam.WireEntities);
              marbleCam.ID = MarbleTempVars.MarbleCamID;
              marbleCam.CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Slice} {buLangTranslate.preDef.Cut}";
              marbleCam.CamMarbleType = MarbleCamType.Slices;
              marbleCam.CamMode = MarbleCamMode.Contour;
              marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
              marbleCam.ToolType = MarbleToolType.Saw;
              marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
              marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
              marbleCam.CamType = CamType.Contour;
              marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
              clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
              MI.CamList.Add(marbleCam);
              MI.ToolType = MarbleToolType.Saw;
              MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
              MI.CamPoint = MarbleTempVars.isHorizontal ? new Pnt6D(MarbleTempVars.HorizontalStartPos) : new Pnt6D(MarbleTempVars.VerticalStartPos);
              bool isLast = false;
              if (index3 == MarbleTempVars.ItemsSlice.Count - 1)
                isLast = true;
              clsInit.cMarble.MarblecalcItemCam(marbleCam.ToolSelected, clsMarble.activeKinematic, this.activeJob, index3, isLast, LastP9, MI, ref marbleCam);
              clsInit.cMarble.GetLastCamPointOfItem(MI, ref LastP9);
              if (MI.ItemEntities.SolidEntity != null)
              {
                for (int index4 = 0; index4 <= MI.ItemEntities.SolidEntity.Count - 1; ++index4)
                {
                  if (MarbleTempVars.isHorizontal)
                  {
                    MI.ItemEntities.SolidEntity[index4].ColorMethod = colorMethodType.byEntity;
                    MI.ItemEntities.SolidEntity[index4].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesHorizontal.Color);
                  }
                  else
                  {
                    MI.ItemEntities.SolidEntity[index4].ColorMethod = colorMethodType.byEntity;
                    MI.ItemEntities.SolidEntity[index4].Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSlicesVertical.Color);
                  }
                }
                clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
                ObjectSize3D.CalculateSize(ref MI.SizeItem);
              }
              this.doAddItemToJob(MI, false, true);
              if (buMarbleCalc.varMarbleSettings.AutoMagnet)
                buMarbleCalc.SelectedItem.SelectionItems.Add(new MarbleSelectionItems()
                {
                  ItemID = MI.ID,
                  indexItem = this.activeJob.Items.Count - 1,
                  pntMin = buVector5.ToPoint3D(MI.SizeItem.MinPoint),
                  pntMax = buVector5.ToPoint3D(MI.SizeItem.MaxPoint),
                  MI = MI
                });
            }
            if (buMarbleCalc.varMarbleSettings.AutoMagnet)
              this.doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
          }
          this.AddOperationAfterThings();
        }
      }
      this.activeJob.CamCalculated = false;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemPointList(List<Pnt6D> PointList, bool isFinished = false)
  {
    string str = nameof (doAddItemPointList);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      this.activeJob.Items.Clear();
      List<string> stringList = new List<string>();
      MarbleItem marbleItem = new MarbleItem();
      marbleItem.ItemEntities.EdgeEntities = new List<buEntity>();
      marbleItem.ItemEntities.DrawWireEntities = new List<buEntity>();
      marbleItem.ItemEntities.ConcaveEntities = new List<List<buEntity>>();
      marbleItem.ItemEntities.ExtensionEntities = new List<buEntity>();
      clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
      marbleItem.ID = MarbleTempVars.ItemID;
      marbleItem.EntGroup = new buEntitiesGroup();
      MarbleItemCam marbleItemCam = new MarbleItemCam()
      {
        ID = MarbleTempVars.MarbleCamID,
        CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Point} {buLangTranslate.preDef.Cut}",
        CamMarbleType = MarbleCamType.PointList,
        CamMode = MarbleCamMode.Contour,
        setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar),
        ToolType = MarbleToolType.Saw,
        WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
        MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
        CamType = CamType.Contour
      };
      marbleItemCam.ToolSelected = this.FindToolFromType(marbleItemCam.ToolType);
      clsInit.cMarble.GetCamID(this.activeJob, ref marbleItemCam.CamID);
      marbleItem.CamList.Add(marbleItemCam);
      marbleItem.ToolType = MarbleToolType.Saw;
      marbleItem.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      List<Pnt6D> calcPoints = new List<Pnt6D>();
      clsInit.cMarble.CalculatePointsWithKinematic(PointList, clsMarble.activeKinematic, marbleItemCam.ToolSelected, ref calcPoints);
      camTpPoint camTpPoint = new camTpPoint();
      if (calcPoints.Count > 0)
      {
        marbleItemCam.CamBase = new camTp();
        marbleItemCam.CamBase.TypeCam = CamType.SawCut;
        for (int index = 0; index <= calcPoints.Count - 1; ++index)
        {
          double feed = 20.0;
          TpPnt9D tpPnt9D = new TpPnt9D(calcPoints[index], feed, 0);
          camTpPoint.Points.Add(tpPnt9D);
        }
        camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
        this.activeJob.Items.Add(marbleItem);
        marbleItemCam.CamBase.CamPoints.Add(camTpPoint);
      }
      this.activeJob.CamCalculated = false;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemLathe(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemLathe);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForLathe.Count == 0)
        return;
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.SourceEntities = new List<buEntity>();
      Entity entSurface = (Entity) null;
      MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      this.doLatheCut(this.entitiesForLathe, ref entSurface, ref MI);
      MI.ItemType = MarbleItemType.LatheHorizontal;
      MI.ToolType = MarbleToolType.Saw;
      if (isFinsihed)
      {
        MI.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
        MI.BasePoint = buVector5.ToPoint3D(refPoint);
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset);
      }
      if (MI.ItemEntities.SourceEntities != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          buEntity sourceEntity = MI.ItemEntities.SourceEntities[index];
          sourceEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheZOffset);
          sourceEntity.Marble = new MarbleInfo();
        }
      }
      if (isFinsihed)
      {
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
        {
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is buMachinePart)
          {
            buMachinePart entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] as buMachinePart;
            if ((entity.EntityData == null ? 0 : (entity.EntityData is CustomData ? 1 : 0)) != 0)
            {
              CustomData entityData = entity.EntityData as CustomData;
              if ((entityData.ActionName == null ? 0 : (entityData.ActionName == "Lathe" & entity.XMove ? 1 : 0)) != 0)
                entity.xPos = buMarbleCalc.varMarbleRunSettings.LathePartLength - buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheLeftRightSideDistance;
            }
          }
        }
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
        ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
        this.AddOperationBeforeThings();
        clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
        MI.ID = MarbleTempVars.ItemID;
        this.doAddItemCommonProps(ref MI);
        MarbleItemCam marbleCam = new MarbleItemCam()
        {
          ID = MarbleTempVars.MarbleCamID,
          CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Cut}",
          CamMarbleType = MarbleCamType.Lathe,
          CamMode = MarbleCamMode.Contour,
          ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
          WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
          MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
          CamType = CamType.Contour
        };
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleLatheHor.buPar);
        marbleCam.isFinish = true;
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        MI.CamList.Add(marbleCam);
        if (isCamCalc)
          this.doLatheCamCalcCut(ref MI, ref marbleCam);
        this.doAddItemToJob(MI, true, true);
      }
      else
        MarbleTempVars.ItemsLathe.Add(MI);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemLatheVertical(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemLatheVertical);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForLathe.Count == 0)
        return;
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.SourceEntities = new List<buEntity>();
      Entity entSurface = (Entity) null;
      MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      this.doLatheVerticalCut(this.entitiesForLathe, ref entSurface, ref MI);
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.ItemType = MarbleItemType.LatheVertical;
      MI.isVerticalItem = true;
      if (isFinsihed)
      {
        this.doAddItemCommonProps(ref MI);
        MI.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z);
      }
      if (MI.ItemEntities.SourceEntities != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          buEntity sourceEntity = MI.ItemEntities.SourceEntities[index];
          sourceEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z);
          sourceEntity.Marble = new MarbleInfo();
        }
      }
      if (isFinsihed)
      {
        if (MI.ItemEntities.SolidEntity != null)
        {
          clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
          ObjectSize3D.CalculateSize(ref MI.SizeItem);
        }
        this.AddOperationBeforeThings();
        if (MI.Settings.settingLatheVerticalCut.LatheBaseHeight > 0.0 && MI.SizeItem.Width > 0.0 & MI.SizeItem.Height > 0.0 & MI.SizeItem.Depth > 0.0)
        {
          Brep box = Brep.CreateBox(MI.SizeItem.Width, MI.SizeItem.Height, MI.Settings.settingLatheVerticalCut.LatheBaseHeight);
          box.Regen(0.1);
          Mesh mesh = box.ConvertToMesh();
          if (mesh != null)
          {
            mesh.Translate(MI.SizeItem.MidPoint.X - MI.SizeItem.Width / 2.0, MI.SizeItem.MidPoint.Y - MI.SizeItem.Height / 2.0);
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy((Entity) mesh, ref copiedEntity);
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
            MI.ItemEntities.BaseEntities = new List<buEntity>();
            MI.ItemEntities.BaseEntities.Add(copiedEntity);
          }
        }
        MarbleItemCam marbleCam = new MarbleItemCam()
        {
          CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Cut}",
          CamMarbleType = MarbleCamType.Lathe,
          CamMode = MarbleCamMode.Contour,
          setCam = new camParameters5(buMWMarbleVars.varCamMarbleColumns.buPar),
          ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
          WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
          MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
          CamType = CamType.Contour
        };
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.isFinish = true;
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        MI.CamList.Add(marbleCam);
        if (isCamCalc)
          this.doLatheVerticalCamCalcCut(ref MI, ref marbleCam);
        this.doAddItemToJob(MI, true, true);
      }
      else
        MarbleTempVars.ItemsLathe.Add(MI);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doLatheCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
  {
    string str = nameof (doLatheCut);
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D point3D = new Point3D();
      if (RefEntities.Count <= 0)
        return;
      clsInit.cVector5.BoxSizeCalculate(RefEntities, ref MinPoint, ref MaxPoint);
      buMarbleCalc.varMarbleRunSettings.LathePartLength = MaxPoint.X - MinPoint.X;
      clsInit.cVector5.Move(-MaxPoint.X, 0.0, 0.0, ref RefEntities);
      List<Point3D> Points1 = new List<Point3D>();
      for (int index = 0; index <= RefEntities.Count - 1; ++index)
      {
        List<Point3D> Points2 = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[index], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points2);
        Points1.AddRange((IEnumerable<Point3D>) Points2);
        buEntity buEntity = (buEntity) null;
        buEntity.Copy(RefEntities[index], ref buEntity);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref buEntity);
        Item.ItemEntities.SourceEntities.Add(buEntity);
      }
      clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points1);
      Entity entTop = (Entity) null;
      Entity entBottom = (Entity) null;
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) Points1);
      linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
      CompositeCurve refCurve = new CompositeCurve((ICurve) linearPath);
      clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisX, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
      entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheHorizontal.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheHorizontal.Color);
      entSurface.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity = new List<Entity>();
      Item.ItemEntities.SolidEntity.Add(entSurface);
      entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
      entTop.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity.Add(entTop);
      entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
      entBottom.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity.Add(entBottom);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doLatheVerticalCut(
    List<buEntity> RefEntities,
    ref Entity entSurface,
    ref MarbleItem Item)
  {
    string str = nameof (doLatheVerticalCut);
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      if (RefEntities.Count <= 0)
        return;
      List<Point3D> Points1 = new List<Point3D>();
      for (int index = 0; index <= RefEntities.Count - 1; ++index)
      {
        List<Point3D> Points2 = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[index], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points2);
        Points1.AddRange((IEnumerable<Point3D>) Points2);
        buEntity buEntity = (buEntity) null;
        buEntity.Copy(RefEntities[index], ref buEntity);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref buEntity);
        buEntity.Translate(0.0, 0.0, Item.Settings.settingLatheVerticalCut.LatheBaseHeight);
        Item.ItemEntities.SourceEntities.Add(buEntity);
      }
      clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points1);
      LinearPath linearPath = new LinearPath((ICollection<Point3D>) Points1);
      linearPath.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisX);
      linearPath.Translate(0.0, 0.0, Item.Settings.settingLatheVerticalCut.LatheBaseHeight);
      linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
      Entity entTop = (Entity) null;
      Entity entBottom = (Entity) null;
      CompositeCurve refCurve = new CompositeCurve((ICurve) linearPath);
      clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisZ, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
      Item.ItemEntities.SolidEntity = new List<Entity>();
      entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
      entSurface.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity.Add(entSurface);
      entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
      entTop.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity.Add(entTop);
      entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
      entBottom.ColorMethod = colorMethodType.byEntity;
      Item.ItemEntities.SolidEntity.Add(entBottom);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doLatheCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doLatheCamCalcCut);
    try
    {
      clsMW.Containment2DEntities.Clear();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D MidPoint = new Point3D();
      Entity entSureface = (Entity) null;
      List<Point3D> point3DList = new List<Point3D>();
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
      {
        List<Point3D> Points = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[index], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points);
        point3DList.AddRange((IEnumerable<Point3D>) Points);
      }
      clsInit.cVector5.SurfaceExturudeByPoints(point3DList, Vector3D.AxisY, marbleCam.ToolSelected.Geometry.Thickness / 2.0, ref entSureface);
      clsInit.cVector5.BoxSizeCalculate(point3DList, ref MinPoint, ref MaxPoint);
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.isRough = true;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.AddToCamListInMWCalculation = false;
      MWCalcOptions.DontShowbuDialogBox = true;
      ToolBase5 ToolSelected = new ToolBase5();
      ToolSelected.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
      ToolSelected.Geometry.Length = 500.0;
      ToolSelected.Geometry.GeometryType = buClass.ToolType.Flat;
      clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, buMWMarbleVars.varCamMarbleMeshParelelCut.buPar, out clsMW.varbuCamMeshParallelPars);
      clsMW.varMWCamMeshParalelPars.MachParam.ParallelMachAngleInYX = 90.0;
      clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
      clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
      clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
      clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + 50.0;
      clsMW.varMWCamMeshParalelPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness;
      clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
      clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
      clsMW.varMWCamMeshParalelPars.MachParam.DistanceFlag = true;
      clsMW.varMWCamMeshParalelPars.MachParam.Distance = 20.0;
      clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
      clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
      clsMW.CamEntities.Clear();
      if (entSureface is Brep)
        clsMW.CamEntities.Add((Entity) ((Brep) entSureface).ConvertToMesh(0.1));
      else
        clsMW.CamEntities.Add(entSureface);
      MWCalcOptions.DontShowDialogBox = true;
      camTp Cam = new camTp();
      camResult Result = new camResult();
      clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      List<Point3D> refPoints = new List<Point3D>();
      List<Point3D> points1 = new List<Point3D>();
      List<Point3D> points2 = new List<Point3D>();
      if (Cam.CamPoints.Count == 1)
      {
        if (Cam.EntitiesG1Orj.Count > 0)
        {
          for (int index1 = 0; index1 <= Cam.EntitiesG1Orj.Count - 1; ++index1)
          {
            for (int index2 = 0; index2 <= Cam.EntitiesG1Orj[index1].Vertices.Length - 1; ++index2)
              refPoints.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[index1].Vertices[index2]));
          }
        }
      }
      else if (Cam.CamPoints.Count > 1)
        ;
      if (refPoints.Count == 0)
        return;
      marbleCam.isCamCalculated = true;
      clsInit.cVector5.BoxSizeCalculate(refPoints, ref MinPoint, ref MidPoint, ref MaxPoint);
      clsInit.cVector5.Move(0.0, buMarbleCalc.varMarbleMachineSettings.LatheSettings.LatheYOffset - MinPoint.Y, 0.0, ref refPoints);
      if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MaxToMin)
        refPoints.Reverse();
      if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToLeftThenRight | Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToRightThenLEft)
      {
        int num = -1;
        for (int index = 0; index <= refPoints.Count - 1; ++index)
        {
          if (refPoints[index].X > MidPoint.X)
          {
            num = index;
            index = refPoints.Count;
          }
        }
        if (num >= 0)
        {
          for (int index = 0; index <= num; ++index)
            points1.Add(buVector5.ToPoint3D(refPoints[index]));
          for (int index = num; index <= refPoints.Count - 1; ++index)
            points2.Add(buVector5.ToPoint3D(refPoints[index]));
        }
      }
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      List<buEntity> buEntityList = new List<buEntity>();
      if (points1.Count > 0 & points2.Count > 0)
      {
        if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToLeftThenRight)
        {
          points1.Reverse();
          buLinearPath buLinearPath1 = new buLinearPath(points1);
          buEntityList.Add((buEntity) buLinearPath1);
          Item.ItemEntities.WireEntities.Add(buEntityList);
          buLinearPath buLinearPath2 = new buLinearPath(points2);
          buEntityList = new List<buEntity>();
          buEntityList.Add((buEntity) buLinearPath2);
          Item.ItemEntities.WireEntities.Add(buEntityList);
        }
        if (Item.Settings.settingLatheCut.LatheDirection == MarbleLatheDirection.MidToRightThenLEft)
        {
          buLinearPath buLinearPath3 = new buLinearPath(points2);
          buEntityList.Add((buEntity) buLinearPath3);
          Item.ItemEntities.WireEntities.Add(buEntityList);
          points1.Reverse();
          buLinearPath buLinearPath4 = new buLinearPath(points1);
          Item.ItemEntities.WireEntities.Add(new List<buEntity>()
          {
            (buEntity) buLinearPath4
          });
        }
      }
      else
      {
        buLinearPath buLinearPath = new buLinearPath(refPoints);
        buEntityList.Add((buEntity) buLinearPath);
        Item.ItemEntities.WireEntities.Add(buEntityList);
      }
      Item.Settings.settingMarbleCam.DontCheckZValues = true;
      Item.Settings.settingMarbleCam.OffsetAngleC = 90.0;
      Item.Settings.settingMarbleCam.SawSafeDistance = !Item.Settings.settingLatheCut.LatheZSafeDistanceFromTopSurface ? Item.Settings.settingLatheCut.LatheSafeDistance : MaxPoint.Z + Item.Settings.settingLatheCut.LatheSafeDistance;
      Item.Settings.settingMarbleCam.SawPlungeVelocity = Item.Settings.settingLatheCut.LathePlungeFeed;
      Item.Settings.settingMarbleCam.SawForwardCuttingVelocity = Item.Settings.settingLatheCut.LatheCutFeed;
      Item.Settings.settingMarbleCam.SawBackwardCuttingVelocity = Item.Settings.settingLatheCut.LatheCutFeed;
      Item.Settings.settingMarbleCam.AlwaysSafeDistance = true;
      Item.Settings.settingMarbleCam.NoAngleCAxisCheck = true;
      marbleCam.setCam.Strategy.UseTangentLimit = true;
      marbleCam.setCam.Options.AxesLimit.MaxLimit.C = 370.0;
      marbleCam.setCam.Options.AxesLimit.MinLimit.C = -370.0;
      marbleCam.setCam.Speeds.Feed = Item.Settings.settingLatheCut.LatheCutFeed;
      marbleCam.setCam.Speeds.Plunge = Item.Settings.settingLatheCut.LathePlungeFeed;
      marbleCam.setCam.Distances.Safe = Item.Settings.settingLatheCut.LatheSafeDistance;
      if (!Item.Settings.settingLatheCut.LatheCAxisFollowDirection)
      {
        Item.Settings.settingMarbleCam.UseConstantCAngle = true;
        Item.Settings.settingMarbleCam.ConstantAngleC = 270.0;
      }
      else
        Item.Settings.settingMarbleCam.UseConstantCAngle = false;
      if ((Item.ItemEntities.WireEntities == null ? 0 : (Item.ItemEntities.WireEntities.Count > 0 ? 1 : 0)) != 0)
      {
        marbleCam.WireEntities = new List<List<buEntity>>();
        for (int index = 0; index <= Item.ItemEntities.WireEntities.Count - 1; ++index)
        {
          List<buEntity> copiedEntities = new List<buEntity>();
          buEntity.Copy(Item.ItemEntities.WireEntities[index], ref copiedEntities);
          marbleCam.WireEntities.Add(copiedEntities);
        }
      }
      clsInit.cMarble.CalculateMarbleWireFrameWithSaw(clsMarble.activeKinematic, marbleCam.ToolSelected, this.activeJob, 0, true, (TpPnt9D) null, ref Item, ref marbleCam);
      if ((marbleCam.CamBase == null ? 0 : (marbleCam.CamBase.CamPoints.Count > 0 ? 1 : 0)) != 0)
      {
        for (int index = 0; index <= marbleCam.CamBase.CamPoints.Count - 1; ++index)
        {
          if (!Item.Settings.settingLatheCut.LatheZSafeDistanceFromTopSurface && marbleCam.CamBase.CamPoints[index].Points.Count > 0)
          {
            TpPnt9D point1 = marbleCam.CamBase.CamPoints[index].Points[0];
            TpPnt9D point2 = marbleCam.CamBase.CamPoints[index].Points[marbleCam.CamBase.CamPoints[index].Points.Count - 1];
            TpPnt9D point3 = marbleCam.CamBase.CamPoints[index].Points[marbleCam.CamBase.CamPoints[index].Points.Count - 2];
            if (point2.P9.Z - point1.P9.Z > 5.0 && buCompare5.EQ(point3.P9.Z, point1.P9.Z, 1.0))
              marbleCam.CamBase.CamPoints[index].Points.RemoveAt(marbleCam.CamBase.CamPoints[index].Points.Count - 1);
          }
        }
      }
      if (marbleCam.CamBase == null)
        return;
      marbleCam.isCamCalculated = true;
      camTp camBase = marbleCam.CamBase;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.ContourClosedOutside;
      camBase.AxisCount = 5;
      camBase.Explanation = $"{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Cutting}";
      camBase.Name = $"{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Cutting}";
      camBase.CamID = Item.ID;
      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.Post.RepetitionDef.Tool = false;
      camBase.UsedCamPost = true;
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Post.ToolDef.ToolData.PreCode.Clear();
      if (marbleCam.ToolSelected.Purpose == ToolPurpose.Saw)
      {
        camBase.Post.SpindleDef.UseSpindle = false;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      else
      {
        camBase.Post.SpindleDef.UseSpindle = true;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      if (buSystem.Canceled)
        return;
      camBase.Name = $"Lathe Cut ({marbleCam.ToolSelected.Purpose.ToString()}) - [Marble]";
      if (marbleCam.ToolSelected.Purpose == ToolPurpose.Saw)
        ;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doLatheVerticalCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doLatheVerticalCamCalcCut);
    try
    {
      clsMW.Containment2DEntities.Clear();
      Entity entSureface = (Entity) null;
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D point3D = new Point3D();
      List<Point3D> Points1 = new List<Point3D>();
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
      {
        List<Point3D> Points2 = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[index], buMarbleCalc.varMarbleEntitiesSettings.LatheDeviationResolution, ref Points2);
        Points1.AddRange((IEnumerable<Point3D>) Points2);
      }
      if (Points1.Count > 0)
        clsInit.cVector5.Rotate(Item.BasePoint, 90.0, Plane.XZ, ref Points1);
      clsInit.cVector5.SurfaceExturudeByPoints(Points1, Vector3D.AxisY, 2.0, ref entSureface);
      clsInit.cVector5.BoxSizeCalculate(Points1, ref MinPoint, ref MaxPoint);
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.isRough = true;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.AddToCamListInMWCalculation = false;
      MWCalcOptions.DontShowbuDialogBox = true;
      ToolBase5 ToolSelected = new ToolBase5();
      ToolSelected.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
      ToolSelected.Geometry.Length = 500.0;
      ToolSelected.Geometry.GeometryType = buClass.ToolType.Flat;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + 50.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness / 2.0;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.DistanceFlag = true;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.Distance = marbleCam.ToolSelected.Geometry.Thickness * 0.8;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
      buMWMarbleVars.varCamMarbleLatheVer.mwPar.MachParam.CutTolerance = 0.1;
      clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleLatheVer.mwPar, buMWMarbleVars.varCamMarbleLatheVer.buPar, out clsMW.varbuCamMeshParallelPars);
      clsMW.CamEntities.Clear();
      if (entSureface is Brep)
        clsMW.CamEntities.Add((Entity) ((Brep) entSureface).ConvertToMesh(0.1));
      else
        clsMW.CamEntities.Add(entSureface);
      MWCalcOptions.DontShowDialogBox = true;
      camTp Cam = new camTp();
      camResult Result = new camResult();
      clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      List<Point3D> Points3 = new List<Point3D>();
      if (Cam.CamPoints.Count == 1)
      {
        if (Cam.EntitiesG1Orj.Count > 0)
        {
          for (int index1 = 0; index1 <= Cam.EntitiesG1Orj.Count - 1; ++index1)
          {
            for (int index2 = 0; index2 <= Cam.EntitiesG1Orj[index1].Vertices.Length - 1; ++index2)
              Points3.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[index1].Vertices[index2]));
          }
        }
      }
      else if (Cam.CamPoints.Count > 1)
        ;
      if (Points3.Count == 0)
        return;
      clsInit.cVector5.Rotate(Item.BasePoint, -90.0, Plane.XZ, ref Points3);
      Points3.Insert(0, new Point3D(Points3[0].X + Item.Settings.settingLatheVerticalCut.LatheSafeDistance, Points3[0].Y, Points3[0].Z));
      Points3.Add(new Point3D(Points3[Points3.Count - 1].X + Item.Settings.settingLatheVerticalCut.LatheSafeDistance, Points3[Points3.Count - 1].Y, Points3[Points3.Count - 1].Z));
      clsInit.cVector5.BoxSizeCalculate(Points3, ref MinPoint, ref MaxPoint);
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      List<buEntity> buEntityList = new List<buEntity>();
      buLinearPath buLinearPath = new buLinearPath(Points3);
      buLinearPath.Orientation.A = 90.0;
      buEntityList.Add((buEntity) buLinearPath);
      Item.ItemEntities.WireEntities.Add(buEntityList);
      marbleCam.CamBase = new camTp();
      camTpPoint camTpPoint = new camTpPoint();
      List<Point3D> points1 = new List<Point3D>();
      List<Point3D> points2 = new List<Point3D>();
      List<Point3D> points3 = new List<Point3D>();
      for (int index3 = 0; index3 <= Points3.Count - 1; ++index3)
      {
        List<Pnt6D> refPoints = new List<Pnt6D>();
        double Length = clsInit.cVector5.Length3D(Item.BasePoint, Points3[index3], Plane.XY);
        Point3D EndPnt = new Point3D();
        clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length, 0.0, ref EndPnt);
        refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 90.0));
        if (index3 <= 1)
        {
          points3.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          if (index3 == 1)
            points1.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
        }
        else if (index3 == Points3.Count - 1)
        {
          if (points1.Count > 0)
            points2.Add(new Point3D(points1[points1.Count - 1].X, points1[points1.Count - 1].Y, points1[points1.Count - 1].Z));
          points2.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
        }
        else
          points1.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
        List<Pnt6D> calcPoints = new List<Pnt6D>();
        clsInit.cMarble.CalculatePointsWithKinematic(refPoints, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoints);
        for (int index4 = 0; index4 <= calcPoints.Count - 1; ++index4)
        {
          TpPnt9D tpPnt9D = new TpPnt9D(calcPoints[index4], 20.0, 1);
          camTpPoint.Points.Add(tpPnt9D);
        }
      }
      camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
      if (points1.Count > 0)
      {
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) points1);
        marbleCam.CamBase.EntitiesG1.Add((Entity) linearPath);
      }
      if (points2.Count > 0)
      {
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) points2);
        marbleCam.CamBase.EntitiesLeave.Add((Entity) linearPath);
      }
      if (points3.Count > 0)
      {
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) points3);
        marbleCam.CamBase.EntitiesPlunge.Add((Entity) linearPath);
      }
      marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
      marbleCam.CamBase.CamPoints.Add(camTpPoint);
      if (marbleCam.CamBase == null)
        return;
      marbleCam.isCamCalculated = true;
      camTp camBase = marbleCam.CamBase;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.ContourClosedOutside;
      camBase.AxisCount = 5;
      camBase.Explanation = $"{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Cutting}";
      camBase.Name = $"{buLangTranslate.preDef.Lathe} {buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Cutting}";
      camBase.CamID = Item.ID;
      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.Post.RepetitionDef.Tool = false;
      camBase.UsedCamPost = true;
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Post.ToolDef.ToolData.PreCode.Clear();
      if (marbleCam.ToolSelected.Purpose == ToolPurpose.Saw)
      {
        camBase.Post.SpindleDef.UseSpindle = false;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      else
      {
        camBase.Post.SpindleDef.UseSpindle = true;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      if (buSystem.Canceled || marbleCam.ToolSelected.Purpose == ToolPurpose.Saw)
        ;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemColumns(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemColumns);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForColumns.Count == 0)
        return;
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.SourceEntities = new List<buEntity>();
      Entity entSurface = (Entity) null;
      MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      this.doColumnsCut(this.entitiesForColumns, ref entSurface, ref MI);
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.ItemType = MarbleItemType.Columns;
      MI.BaseHeight = MI.Settings.settingColoumnsCut.ColoumsBaseHeight;
      MI.isVerticalItem = true;
      if (isFinsihed)
      {
        this.doAddItemCommonProps(ref MI);
        MI.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z);
      }
      if (MI.ItemEntities.SourceEntities != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          buEntity sourceEntity = MI.ItemEntities.SourceEntities[index];
          sourceEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z);
          sourceEntity.Marble = new MarbleInfo();
        }
      }
      if (isFinsihed)
      {
        if (MI.ItemEntities.SolidEntity != null)
        {
          clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
          ObjectSize3D.CalculateSize(ref MI.SizeItem);
        }
        if (MI.Settings.settingColoumnsCut.ColoumsBaseHeight > 0.0 && MI.SizeItem.Width > 0.0 & MI.SizeItem.Height > 0.0 & MI.SizeItem.Depth > 0.0)
        {
          Brep box = Brep.CreateBox(MI.SizeItem.Width, MI.SizeItem.Height, MI.Settings.settingColoumnsCut.ColoumsBaseHeight);
          box.Regen(0.1);
          Mesh mesh = box.ConvertToMesh();
          if (mesh != null)
          {
            mesh.Translate(MI.SizeItem.MidPoint.X - MI.SizeItem.Width / 2.0, MI.SizeItem.MidPoint.Y - MI.SizeItem.Height / 2.0);
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy((Entity) mesh, ref copiedEntity);
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
            MI.ItemEntities.BaseEntities = new List<buEntity>();
            MI.ItemEntities.BaseEntities.Add(copiedEntity);
          }
        }
        MarbleItemCam marbleCam = new MarbleItemCam()
        {
          CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Columns} {buLangTranslate.preDef.Cut}",
          CamMarbleType = MarbleCamType.Columns,
          CamMode = MarbleCamMode.Contour,
          setCam = new camParameters5(buMWMarbleVars.varCamMarbleColumns.buPar),
          ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
          WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
          MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
          CamType = CamType.Contour
        };
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.isFinish = true;
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        MI.CamList.Add(marbleCam);
        this.AddOperationBeforeThings();
        if (isCamCalc)
          this.doColumnsCamCalcCut(ref MI, ref marbleCam);
        MI.ID = MarbleTempVars.ItemID;
        this.doAddItemToJob(MI, true, true);
      }
      else
        MarbleTempVars.ItemsColumns.Add(MI);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doColumnsCut(List<buEntity> RefEntities, ref Entity entSurface, ref MarbleItem Item)
  {
    string str = nameof (doColumnsCut);
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      if (RefEntities.Count > 0)
      {
        List<Point3D> Points1 = new List<Point3D>();
        for (int index = 0; index <= RefEntities.Count - 1; ++index)
        {
          List<Point3D> Points2 = new List<Point3D>();
          clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[index], buMarbleCalc.varMarbleEntitiesSettings.ColumnsDeviationResolution, ref Points2);
          Points1.AddRange((IEnumerable<Point3D>) Points2);
          buEntity buEntity = (buEntity) null;
          buEntity.Copy(RefEntities[index], ref buEntity);
          clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref buEntity);
          buEntity.Translate(0.0, 0.0, Item.Settings.settingColoumnsCut.ColoumsBaseHeight);
          Item.ItemEntities.SourceEntities.Add(buEntity);
        }
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points1);
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) Points1);
        linearPath.Rotate(buConversion5.DegreeToRadian(90.0), Vector3D.AxisX);
        linearPath.Translate(0.0, 0.0, Item.Settings.settingColoumnsCut.ColoumsBaseHeight);
        linearPath.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
        Entity entTop = (Entity) null;
        Entity entBottom = (Entity) null;
        CompositeCurve refCurve = new CompositeCurve((ICurve) linearPath);
        clsInit.cVector5.surfaceRevolveByPath(refCurve, Vector3D.AxisZ, new Point3D(), 0.0, 360.0, ref entSurface, ref entTop, ref entBottom);
        entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemColumn.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemColumn.Color);
        entSurface.ColorMethod = colorMethodType.byEntity;
        Item.ItemEntities.SolidEntity = new List<Entity>();
        Item.ItemEntities.SolidEntity.Add(entSurface);
        entTop.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
        entTop.ColorMethod = colorMethodType.byEntity;
        Item.ItemEntities.SolidEntity.Add(entTop);
        entBottom.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemLatheVertical.Color);
        entBottom.ColorMethod = colorMethodType.byEntity;
        Item.ItemEntities.SolidEntity.Add(entBottom);
      }
      else
        clsInit.appCommand.Reset(ReDraw: true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doColumnsCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doColumnsCamCalcCut);
    try
    {
      clsMW.Containment2DEntities.Clear();
      Entity entSureface = (Entity) null;
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D point3D = new Point3D();
      List<Point3D> Points1 = new List<Point3D>();
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
      {
        List<Point3D> Points2 = new List<Point3D>();
        clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.ItemEntities.SourceEntities[index], buMarbleCalc.varMarbleEntitiesSettings.ColumnsDeviationResolution, ref Points2);
        Points1.AddRange((IEnumerable<Point3D>) Points2);
      }
      if (Points1.Count > 0)
        clsInit.cVector5.Rotate(Item.BasePoint, 90.0, Plane.XZ, ref Points1);
      clsInit.cVector5.SurfaceExturudeByPoints(Points1, Vector3D.AxisY, 2.0, ref entSureface);
      clsInit.cVector5.BoxSizeCalculate(Points1, ref MinPoint, ref MaxPoint);
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.isRough = true;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.AddToCamListInMWCalculation = false;
      MWCalcOptions.DontShowbuDialogBox = true;
      ToolBase5 ToolSelected = new ToolBase5();
      ToolSelected.Geometry.Diameter = marbleCam.ToolSelected.Geometry.Thickness;
      ToolSelected.Geometry.Length = 500.0;
      ToolSelected.Geometry.GeometryType = buClass.ToolType.Flat;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance = Item.Settings.settingColoumnsCut.ColoumsZStep;
      if (buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance > marbleCam.ToolSelected.Geometry.Thickness)
        buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.DistanceFlag = true;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.Distance = buMarbleCalc.activeToolSaw.Geometry.Thickness * 0.8;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = false;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.CutTolerance = 0.1;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
      buMWMarbleVars.varCamMarbleColumns.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
      clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleColumns.mwPar, buMWMarbleVars.varCamMarbleColumns.buPar, out clsMW.varbuCamMeshParallelPars);
      clsMW.CamEntities.Clear();
      if (entSureface is Brep)
        clsMW.CamEntities.Add((Entity) ((Brep) entSureface).ConvertToMesh(0.1));
      else
        clsMW.CamEntities.Add(entSureface);
      MWCalcOptions.DontShowDialogBox = true;
      camTp Cam = new camTp();
      camResult Result = new camResult();
      clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      List<Point3D> Points3 = new List<Point3D>();
      if (Cam.CamPoints.Count == 1)
      {
        if (Cam.EntitiesG1Orj.Count > 0)
        {
          for (int index1 = 0; index1 <= Cam.EntitiesG1Orj.Count - 1; ++index1)
          {
            for (int index2 = 0; index2 <= Cam.EntitiesG1Orj[index1].Vertices.Length - 1; ++index2)
              Points3.Add(buVector5.ToPoint3D(Cam.EntitiesG1Orj[index1].Vertices[index2]));
          }
        }
      }
      else if (Cam.CamPoints.Count > 1)
        ;
      if (Points3.Count == 0)
        return;
      clsInit.cVector5.Rotate(Item.BasePoint, -90.0, Plane.XZ, ref Points3);
      clsInit.cVector5.BoxSizeCalculate(Points3, ref MinPoint, ref MaxPoint);
      Item.ItemEntities.WireEntities = new List<List<buEntity>>();
      Item.ItemEntities.WireEntities.Add(new List<buEntity>()
      {
        (buEntity) new buLinearPath(Points3)
      });
      Item.Settings.settingMarbleCam.OffsetAngleC = 0.0;
      Item.Settings.settingMarbleCam.SawSafeDistance = MaxPoint.Z + Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
      Item.Settings.settingMarbleCam.SawPlungeVelocity = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
      Item.Settings.settingMarbleCam.SawForwardCuttingVelocity = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
      Item.Settings.settingMarbleCam.SawBackwardCuttingVelocity = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
      marbleCam.setCam.Strategy.UseTangentLimit = true;
      marbleCam.setCam.Options.AxesLimit.MaxLimit.C = Item.Settings.settingMarbleCam.AngleCMax;
      marbleCam.setCam.Options.AxesLimit.MinLimit.C = Item.Settings.settingMarbleCam.AngleCMin;
      marbleCam.setCam.Speeds.Feed = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
      marbleCam.setCam.Speeds.Plunge = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
      marbleCam.setCam.Distances.Safe = Item.Settings.settingColoumnsCut.ColoumsSafeDistance;
      marbleCam.isCamCalculated = true;
      marbleCam.CamBase = new camTp();
      int num1 = 0;
      for (int index3 = 0; index3 <= Points3.Count - 1; ++index3)
      {
        if (Points3[index3].Z < MaxPoint.Z - 0.1 & Points3[index3].Z > MinPoint.Z + 0.1)
        {
          List<Pnt6D> refPoints = new List<Pnt6D>();
          double Length = clsInit.cVector5.Length3D(Item.BasePoint, Points3[index3], Plane.XY);
          List<Point3D> points = new List<Point3D>();
          List<Point3D> point3DList1 = new List<Point3D>();
          List<Point3D> point3DList2 = new List<Point3D>();
          Point3D EndPnt = new Point3D();
          clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length + Item.Settings.settingColoumnsCut.ColoumsSafeDistance, -90.0, ref EndPnt);
          refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 0.0));
          points.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          if (Item.Settings.settingColoumnsCut.ColoumsZigzagMode)
          {
            if (num1 % 2 == 0)
            {
              for (double num2 = 0.0; num2 <= 360.0; num2 += Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
              {
                EndPnt = new Point3D();
                clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length, num2 - 90.0, ref EndPnt);
                refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num2 + 0.0));
                points.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
              }
            }
            else
            {
              for (double num3 = 360.0; num3 >= 0.0; num3 -= Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
              {
                EndPnt = new Point3D();
                clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length, num3 - 90.0, ref EndPnt);
                refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num3 + 0.0));
                points.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
              }
            }
          }
          else
          {
            for (double num4 = 0.0; num4 <= 360.0; num4 += Item.Settings.settingColoumnsCut.ColoumsCRotationStep)
            {
              EndPnt = new Point3D();
              clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length, num4 - 90.0, ref EndPnt);
              refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, num4 + 0.0));
              points.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
            }
          }
          EndPnt = new Point3D();
          clsInit.cVector5.LineWithLengthAndAngle(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Points3[index3].Z), Length + Item.Settings.settingColoumnsCut.ColoumsSafeDistance, 270.0, ref EndPnt);
          refPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 90.0, 0.0, 360.0));
          points.Add(new Point3D(EndPnt.X, EndPnt.Y, EndPnt.Z));
          List<Pnt6D> calcPoints = new List<Pnt6D>();
          clsInit.cMarble.CalculatePointsWithKinematic(refPoints, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoints);
          camTpPoint camTpPoint = new camTpPoint();
          for (int index4 = 0; index4 <= calcPoints.Count - 1; ++index4)
          {
            int type = 1;
            double feed = Item.Settings.settingColoumnsCut.ColoumsCutFeed;
            if (index4 == 0 | index4 == calcPoints.Count - 1)
              type = 0;
            if (index4 == 1)
              feed = Item.Settings.settingColoumnsCut.ColoumsPlungeFeed;
            TpPnt9D tpPnt9D = new TpPnt9D(calcPoints[index4], feed, type);
            camTpPoint.Points.Add(tpPnt9D);
          }
          camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
          LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
          marbleCam.CamBase.EntitiesG1.Add((Entity) linearPath);
          marbleCam.CamBase.CamPoints.Add(camTpPoint);
          ++num1;
        }
      }
      marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
      if (marbleCam.CamBase == null)
        return;
      marbleCam.isCamCalculated = true;
      camTp camBase = marbleCam.CamBase;
      camBase.CamID = Item.ID;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.ContourClosedOutside;
      camBase.AxisCount = 5;
      camBase.Explanation = $"{buLangTranslate.preDef.Columns} {buLangTranslate.preDef.Cutting}";
      camBase.Name = $"{buLangTranslate.preDef.Columns} {buLangTranslate.preDef.Cutting}";
      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.Post.RepetitionDef.Tool = false;
      camBase.UsedCamPost = true;
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Post.ToolDef.ToolData.PreCode.Clear();
      if (marbleCam.ToolSelected.Purpose == ToolPurpose.Saw)
      {
        camBase.Post.SpindleDef.UseSpindle = false;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      else
      {
        camBase.Post.SpindleDef.UseSpindle = true;
        camBase.Post.AxesUsing.Z = true;
        camBase.Post.AxesUsing.A = true;
        camBase.Post.AxesUsing.C = true;
      }
      if (!buSystem.Canceled)
        ;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemEngraving(
    Point3D refPoint,
    List<Entity> Entities,
    bool isText = false,
    bool isCamCalc = false)
  {
    string str = nameof (doAddItemEngraving);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.EngravingEntities = new List<buEntity>();
      MI.ItemType = MarbleItemType.Engraving;
      if (isText)
        MI.ItemType = MarbleItemType.Text3D;
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (Entities[index] is Brep)
        {
          buEntity copiedEntity = (buEntity) null;
          Brep entity = (Brep) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is Mesh)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is devDept.Eyeshot.Entities.Surface)
        {
          buEntity copiedEntity = (buEntity) null;
          devDept.Eyeshot.Entities.Surface entity = (devDept.Eyeshot.Entities.Surface) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
      }
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (clsInit.cVector5.isEntitySolid(Entities[index]))
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          if (copiedEntity != null)
          {
            if (MI.ItemEntities.SolidEntity == null)
              MI.ItemEntities.SolidEntity = new List<Entity>();
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
            copiedEntity.ColorMethod = colorMethodType.byEntity;
            MI.ItemEntities.SolidEntity.Add(copiedEntity);
          }
        }
      }
      for (int index = 0; index <= MI.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        buEntity engravingEntity = MI.ItemEntities.EngravingEntities[index];
        engravingEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        engravingEntity.Marble = new MarbleInfo();
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
        ObjectSize3D.CalculateSize(ref MI.SizeItem);
      }
      if ((MI.ItemEntities.SolidEntity == null ? 0 : (MI.BaseHeight > 0.0 ? 1 : 0)) != 0)
      {
        Entity surfaceEntity = (Entity) null;
        clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
        if (surfaceEntity != null)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(surfaceEntity, ref copiedEntity);
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
          MI.ItemEntities.BaseEntities = new List<buEntity>();
          MI.ItemEntities.BaseEntities.Add(copiedEntity);
        }
      }
      for (int index = 0; index <= 1; ++index)
      {
        MarbleItemCam marbleCam = new MarbleItemCam();
        marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
        switch (index)
        {
          case 0:
            marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
            break;
          case 1:
            marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType2;
            break;
        }
        if (marbleCam.MeshType == CamTriangularMeshType.Rough)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
          marbleCam.CamType = CamType.Rough;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingRough3D;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.ParallelCuts)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
          marbleCam.CamType = CamType.ParallelCut;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.ParalelCuts} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingParallelCut3D;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.ConstantZ)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
          marbleCam.CamType = CamType.ConstantZ;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.ConstantZ} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingContantZ3D;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.Flatlands)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshFlatland.buPar);
          marbleCam.CamType = CamType.Flatlands;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.Flatlands} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingFlatland3D;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.Pencil)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshPencil.buPar);
          marbleCam.CamType = CamType.Pencil;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.Pencil} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingPencil3D;
        }
        marbleCam.CamMode = MarbleCamMode.Rough;
        marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
        if (marbleCam.ToolType == MarbleToolType.Saw | marbleCam.ToolType == MarbleToolType.WaterJet)
          marbleCam.ToolType = MarbleToolType.Milling;
        marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        if (marbleCam.MeshType != CamTriangularMeshType.None)
          MI.CamList.Add(marbleCam);
        if (isCamCalc)
        {
          if (marbleCam.MeshType != CamTriangularMeshType.None)
          {
            this.doEngraveCamCalc(new MWCalculationOptions()
            {
              NumberofAxis = 3,
              CamWireframeType = CamWireFrameType.Contour,
              CamTriMeshType = marbleCam.MeshType,
              Mode = CamMode.TriangularMesh,
              DontApplyReset = true,
              isBuWireframeCalculation = false,
              AddToCamListInLocalCalculation = false,
              ShowLeadInOutPage = false,
              DontShowDialogBox = true,
              DontShowbuDialogBox = true
            }, MI, ref marbleCam);
            marbleCam.isCamCalculated = true;
          }
        }
        else
        {
          marbleCam.isCamCalculated = false;
          this.activeJob.CamCalculated = false;
        }
      }
      this.AddOperationBeforeThings();
      MI.ID = MarbleTempVars.ItemID;
      this.doAddItemToJob(MI, true, true);
      if (!buMarbleCalc.varMarbleSettings.AutoMagnet)
        return;
      this.doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doEngravingCamAdd(
    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    if (ShowDialog)
    {
      if (buMarbleForms.frmTriMeshSet == null)
        buMarbleForms.frmTriMeshSet = new F_CamTriMeshSettings();
      buMarbleForms.frmTriMeshSet.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmTriMeshSet.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      if (CamType == MarbleCamType.MillingRough3D | CamType == MarbleCamType.Rough3Plus2Front | CamType == MarbleCamType.Rough3Plus2Back)
      {
        buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
        buMarbleForms.frmTriMeshSet.Init(CamType.Rough, false);
      }
      else
      {
        switch (CamType)
        {
          case MarbleCamType.MillingParallelCut3D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.ParallelCut, false);
            break;
          case MarbleCamType.MillingContantZ3D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.ConstantZ, false);
            break;
          case MarbleCamType.MillingFlatland3D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshFlatland.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.Flatlands, false);
            break;
          case MarbleCamType.MillingPencil3D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshPencil.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.Pencil, false);
            break;
          case MarbleCamType.MillingParallelCut5D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DParelelCut.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.ParallelCut, false);
            break;
          case MarbleCamType.MillingContantZ5D:
