            buMarbleForms.frmTriMeshSet.Init(CamType.ConstantZ, false);
            break;
          case MarbleCamType.ProjectionRoundRough:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundRough.buPar);
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineX = Item.SizeItem.MidPoint.X;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineY = Item.SizeItem.MidPoint.Y;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineZ = Item.SizeItem.MinPoint.Z;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.CylinderRadiusAroundLine = Item.SizeItem.Width <= Item.SizeItem.Height ? Item.SizeItem.Height : Item.SizeItem.Width;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionEndHeight = Item.SizeItem.MaxPoint.Z - Item.SizeItem.MinPoint.Z;
            buMarbleForms.frmTriMeshSet.Init(CamType.Projection, false);
            break;
          case MarbleCamType.ProjectionRoundFinish:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundFinish.buPar);
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineX = Item.SizeItem.MidPoint.X;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineY = Item.SizeItem.MidPoint.Y;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionLineZ = Item.SizeItem.MinPoint.Z;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.CylinderRadiusAroundLine = Item.SizeItem.Width <= Item.SizeItem.Height ? Item.SizeItem.Height : Item.SizeItem.Width;
            buMarbleForms.frmTriMeshSet.Settings.Strategy.ProjectionEndHeight = Item.SizeItem.MaxPoint.Z - Item.SizeItem.MinPoint.Z;
            buMarbleForms.frmTriMeshSet.Init(CamType.Projection, false);
            break;
          case MarbleCamType.MillingGeodesic5D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DGeodesic.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.Geodesic, false);
            break;
          case MarbleCamType.MillingContantCusp3D:
            buMarbleForms.frmTriMeshSet.Settings = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantCusp.buPar);
            buMarbleForms.frmTriMeshSet.Init(CamType.ConstantCusp, false);
            break;
        }
      }
      int num = (int) buMarbleForms.frmTriMeshSet.ShowDialog();
      if (buMarbleForms.frmTriMeshSet.PropertiesForm.Result != DialogResult.OK)
        return;
      if (CamType == MarbleCamType.MillingRough3D | CamType == MarbleCamType.Rough3Plus2Back | CamType == MarbleCamType.Rough3Plus2Front)
      {
        buMWMarbleVars.varCamMarbleMeshRough.buPar = new camParameters5(buMarbleForms.frmTriMeshSet.Settings);
      }
      else
      {
        switch (CamType)
        {
          case MarbleCamType.MillingParallelCut3D:
