          case MarbleCamType.MillingContantZ5D:
            buMWMarbleVars.varCamMarbleMesh5DConstantZ.buPar = new camParameters5(buMarbleForms.frmTriMeshSet.Settings);
            break;
          case MarbleCamType.ProjectionRoundRough:
