            break;
          case MarbleCamType.ProjectionRoundFinish:
            buMWMarbleVars.varCamMarbleMeshProjectionAroundFinish.buPar = new camParameters5(buMarbleForms.frmTriMeshSet.Settings);
            break;
          case MarbleCamType.MillingGeodesic5D:
