            break;
          case MarbleCamType.MillingContantCusp3D:
            buMWMarbleVars.varCamMarbleMeshConstantCusp.buPar = new camParameters5(buMarbleForms.frmTriMeshSet.Settings);
            break;
        }
      }
    }
    this.SaveMarbleFile();
    if (marbleCam == null | !Edit)
      marbleCam = new MarbleItemCam();
    marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
    if (CamType == MarbleCamType.MillingRough3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.Rough;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
    }
    if (CamType == MarbleCamType.Rough3Plus2Front | CamType == MarbleCamType.Rough3Plus2Back)
    {
      marbleCam.MeshType = CamTriangularMeshType.Rough3Plus2;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut} 3 + 2";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
    }
    if (CamType == MarbleCamType.MillingParallelCut3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.ParalelCuts} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.ParallelCut;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
    }
    if (CamType == MarbleCamType.MillingParallelCut5D)
    {
      marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} 5X {buLangTranslate.preDef.ParalelCuts} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.ParallelCut;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DParelelCut.buPar);
    }
    if (CamType == MarbleCamType.MillingContantZ3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.ConstantZ;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.ConstantZ} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.ConstantZ;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
    }
    if (CamType == MarbleCamType.MillingContantZ5D)
    {
      marbleCam.MeshType = CamTriangularMeshType.ConstantZ;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} 5X {buLangTranslate.preDef.ConstantZ} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.ConstantZ;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DConstantZ.buPar);
    }
    if (CamType == MarbleCamType.MillingFlatland3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.Flatlands;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.Flatlands} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Flatlands;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshFlatland.buPar);
    }
    if (CamType == MarbleCamType.MillingPencil3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.Pencil;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.Pencil} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Pencil;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshPencil.buPar);
    }
    if (CamType == MarbleCamType.MillingContantCusp3D)
    {
      marbleCam.MeshType = CamTriangularMeshType.ConstantCusp;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} {buLangTranslate.preDef.ConstantCusp} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.ConstantCusp;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantCusp.buPar);
    }
    if (CamType == MarbleCamType.ProjectionRoundFinish)
    {
      marbleCam.MeshType = CamTriangularMeshType.ProjectionAround;
      marbleCam.CamName = $"{buLangTranslate.preDef.Projection} {buLangTranslate.preDef.Around} {buLangTranslate.preDef.Finish} {buLangTranslate.preDef.Cut} 3 + 2";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Finish;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundFinish.buPar);
    }
    if (CamType == MarbleCamType.ProjectionRoundRough)
    {
      marbleCam.MeshType = CamTriangularMeshType.ProjectionAround;
      marbleCam.CamName = $"{buLangTranslate.preDef.Projection} {buLangTranslate.preDef.Around} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut} 3 + 2";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshProjectionAroundRough.buPar);
    }
    if (CamType == MarbleCamType.MillingGeodesic5D)
    {
      marbleCam.MeshType = CamTriangularMeshType.Geodesic;
      marbleCam.CamName = $"{buLangTranslate.preDef.Engrave} 5X {buLangTranslate.preDef.Geodesic} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Geodesic;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMesh5DGeodesic.buPar);
    }
    MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
    MWCalcoptions.NumberofAxis = 3;
    MWCalcoptions.CamTriMeshType = marbleCam.MeshType;
    MWCalcoptions.Mode = CamMode.TriangularMesh;
    MWCalcoptions.DontApplyReset = true;
    MWCalcoptions.isBuWireframeCalculation = false;
    MWCalcoptions.AddToCamListInLocalCalculation = false;
    MWCalcoptions.ShowLeadInOutPage = false;
    MWCalcoptions.DontShowDialogBox = true;
    MWCalcoptions.DontShowbuDialogBox = true;
    clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
    if (Item.ItemEntities.EngravingEntities == null)
      Item.ItemEntities.EngravingEntities = new List<buEntity>();
    if (Item.ItemEntities.EngravingEntities.Count == 0 && (Item.ItemEntities.SolidEntity == null ? 0 : (Item.ItemEntities.SolidEntity.Count > 0 ? 1 : 0)) != 0)
      buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
    int num1 = !(CamType == MarbleCamType.MillingParallelCut5D | CamType == MarbleCamType.MillingContantZ5D | CamType == MarbleCamType.MillingGeodesic5D) ? this.doEngraveCamCalc(MWCalcoptions, Item, ref marbleCam) : this.doEngrave5DCamCalc(MWCalcoptions, Item, ref marbleCam);
    if (!Edit & num1 > 0)
      Item.CamList.Add(marbleCam);
    this.AddOperationAfterThings();
  }

  public int doEngraveCamCalc(
    MWCalculationOptions MWCalcoptions,
    MarbleItem Item,
    ref MarbleItemCam marbleCam,
    bool isText = false)
  {
    string str = nameof (doEngraveCamCalc);
    try
    {
      clsMW.Containment2DEntities.Clear();
      clsMW.StockEntities.Clear();
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      if (this.activeJob.Material.Enable & this.activeJob.Material.Points.Count > 0)
      {
        List<Point3D> copiedPoint = new List<Point3D>();
        buVector5.Copy(this.activeJob.Material.Points, ref copiedPoint);
        LinearPath outer = new LinearPath((ICollection<Point3D>) copiedPoint);
        outer.Translate(0.0, 0.0, Item.SizeItem.Depth + buMarbleCalc.varOperation.settingSurfaceClean.ZOffset);
        Entity entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) outer).ExtrudeAsMesh(0.1, 0.01, Mesh.natureType.RichSmooth);
        clsMW.StockEntities.Add(entity);
      }
