            if (marbleCam.CamMarbleType == MarbleCamType.Rough3Plus2Front)
              point.P9.C = 0.0;
            if (marbleCam.CamMarbleType == MarbleCamType.Rough3Plus2Back)
              point.P9.C = 180.0;
          }
        }
      }
      else if (MWCalcoptions.CamTriMeshType == CamTriangularMeshType.ProjectionAround)
      {
        Cam.TypeCam = CamType.MillingCut;
        marbleCam.CamBase = new camTp(Cam);
        for (int index3 = 0; index3 <= marbleCam.CamBase.CamPoints.Count - 1; ++index3)
        {
          for (int index4 = 0; index4 <= marbleCam.CamBase.CamPoints[index3].Points.Count - 1; ++index4)
          {
            TpPnt9D point1 = marbleCam.CamBase.CamPoints[index3].Points[index4];
            point1.P9.C = clsInit.cVector5.PointAngle(new Point3D(point1.P9.A, point1.P9.B, 0.0), new Point3D(), Plane.XY) + 90.0;
            if (index4 > 0)
            {
              TpPnt9D point2 = marbleCam.CamBase.CamPoints[index3].Points[index4 - 1];
              double num5 = point1.P9.C - point2.P9.C;
              if (Math.Abs(num5) > 180.0)
              {
                if (num5 > 0.0)
                  point1.P9.C -= 360.0;
                else
                  point1.P9.C += 360.0;
              }
            }
            point1.P9.A = 90.0;
          }
        }
      }
      else
        marbleCam.CamBase = new camTp(Cam);
      marbleCam.CamBase.Obj1 = (object) Item;
      marbleCam.CamBase.Obj2 = (object) marbleCam;
      marbleCam.CamBase.Name = marbleCam.CamName;
      marbleCam.isCamCalculated = true;
      marbleMillingAnalyzePars AnalyzeSet = new marbleMillingAnalyzePars();
      if (marbleCam.ToolType == MarbleToolType.MillingHead)
        AnalyzeSet.Apply90DegreeToMillingHead = true;
      this.AnalyzeMillingCam(AnalyzeSet, ref marbleCam.CamBase);
      marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      marbleCam.isCamCalculated = true;
      Item.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

