  public void doAddItemSawMilling(
    Point3D refPoint,
    List<Entity> Entities,
    bool isHorizontal,
    bool isRough,
    bool isCamCalc = false)
  {
    string str = nameof (doAddItemSawMilling);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      MarbleItem MI = new MarbleItem();
      MI.ItemType = MarbleItemType.Shape3D;
      MI.ItemEntities.EngravingEntities = new List<buEntity>();
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (Entities[index] is Brep)
        {
          buEntity copiedEntity = (buEntity) null;
          Brep entity = (Brep) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is Mesh)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is devDept.Eyeshot.Entities.Surface)
        {
          buEntity copiedEntity = (buEntity) null;
          devDept.Eyeshot.Entities.Surface entity = (devDept.Eyeshot.Entities.Surface) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
      }
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (clsInit.cVector5.isEntitySolid(Entities[index]))
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          if (copiedEntity != null)
          {
            if (MI.ItemEntities.SolidEntity == null)
              MI.ItemEntities.SolidEntity = new List<Entity>();
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
            copiedEntity.ColorMethod = colorMethodType.byEntity;
            MI.ItemEntities.SolidEntity.Add(copiedEntity);
          }
        }
      }
      for (int index = 0; index <= MI.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        buEntity engravingEntity = MI.ItemEntities.EngravingEntities[index];
        engravingEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        engravingEntity.Marble = new MarbleInfo();
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
        ObjectSize3D.CalculateSize(ref MI.SizeItem);
      }
      if ((MI.ItemEntities.SolidEntity == null ? 0 : (MI.BaseHeight > 0.0 ? 1 : 0)) != 0)
      {
        Entity surfaceEntity = (Entity) null;
        clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
        if (surfaceEntity != null)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(surfaceEntity, ref copiedEntity);
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
          MI.ItemEntities.BaseEntities = new List<buEntity>();
          MI.ItemEntities.BaseEntities.Add(copiedEntity);
        }
      }
      this.AddOperationBeforeThings();
      this.doAddItemToJob(MI, true, true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doSawMillingCamAdd(
    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    if (ShowDialog)
    {
      if (buMarbleForms.frmSawMillingCam == null)
        buMarbleForms.frmSawMillingCam = new F_MarbleSawMillingCam();
      buMarbleForms.frmSawMillingCam.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmSawMillingCam.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmSawMillingCam.varSettings = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
      buMarbleForms.frmSawMillingCam.Init(CamType);
      int num = (int) buMarbleForms.frmSawMillingCam.ShowDialog();
      if (buMarbleForms.frmSawMillingCam.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingCam.varSettings);
    }
    AppBool.SaveByTick = true;
    if (marbleCam == null | !Edit)
      marbleCam = new MarbleItemCam();
    if (Item.ItemEntities.EngravingEntities == null)
      Item.ItemEntities.EngravingEntities = new List<buEntity>();
    Item.ItemEntities.EngravingEntities.Clear();
    Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
    buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
    marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
    marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
    if (CamType == MarbleCamType.SawMillingVerticalFinish | CamType == MarbleCamType.SawMillingVerticalRough)
    {
      if (CamType == MarbleCamType.SawMillingVerticalRough)
      {
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
        marbleCam.setCam.Steps.DepthStep = buMarbleForms.frmSawMillingCam.varSettings.SawMillingRoughVerZDownStep;
        marbleCam.CamMarbleType = CamType;
        marbleCam.CamName = $"{buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Rough}";
        marbleCam.CamType = CamType.Rough;
        marbleCam.CamMode = MarbleCamMode.Rough;
      }
      else
      {
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalFinish.buPar);
        marbleCam.CamMarbleType = CamType;
        marbleCam.CamName = $"{buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Finish}";
        marbleCam.CamType = CamType.Finish;
        marbleCam.CamMode = MarbleCamMode.Finish;
      }
      marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolSaw);
      clsInit.appMarble.doSawMillingVerticalCamCalc(ref Item, ref marbleCam);
    }
    else
    {
      if (CamType == MarbleCamType.SawMillingHorizontalRough)
      {
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
        marbleCam.CamMarbleType = CamType;
        marbleCam.CamName = $"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Rough}";
        marbleCam.CamType = CamType.Rough;
        marbleCam.CamMode = MarbleCamMode.Rough;
      }
      else
      {
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalFinish.buPar);
        marbleCam.CamMarbleType = CamType;
        marbleCam.CamName = $"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Finish}";
        marbleCam.CamType = CamType.Finish;
        marbleCam.CamMode = MarbleCamMode.Finish;
      }
      marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolSaw);
      clsInit.appMarble.doSawMillingHorizontalCamCalc(ref Item, ref marbleCam);
    }
    marbleCam.isCamCalculated = true;
    clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
    Item.CamList.Add(marbleCam);
    this.AddOperationAfterThings();
  }

  public int doSawMillingVerticalCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doSawMillingVerticalCamCalc);
    try
    {
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamWireframeType = CamWireFrameType.Contour;
      MWCalcOptions.CamTriMeshType = marbleCam.MeshType;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.isBuWireframeCalculation = false;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.ShowLeadInOutPage = false;
      MWCalcOptions.DontShowDialogBox = true;
      MWCalcOptions.DontShowbuDialogBox = true;
      clsMW.Containment2DEntities.Clear();
      camTp Cam = new camTp();
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      bool flag;
      if (marbleCam.CamMarbleType == MarbleCamType.SawMillingVerticalRough)
      {
        flag = true;
      }
      else
      {
        if (marbleCam.CamMarbleType != MarbleCamType.SawMillingVerticalFinish)
          return -2;
        flag = false;
      }
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint, ref MaxPoint);
      for (int index = 0; index <= Item.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(Item.ItemEntities.EngravingEntities[index], ref copiedEntity);
        clsMW.CamEntities.Add(copiedEntity);
      }
      if (flag)
      {
        devDept.Eyeshot.Entities.Region rectangle = devDept.Eyeshot.Entities.Region.CreateRectangle(Item.SizeItem.Width, Item.SizeItem.Height);
        rectangle.Translate(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y, Item.SizeItem.MaxPoint.Z);
        Mesh mesh = rectangle.ExtrudeAsMesh(new Vector3D(0.0, 0.0, 0.1), 0.1, Mesh.natureType.RichSmooth);
        clsMW.CamEntities.Add((Entity) mesh);
      }
      if (clsMW.CamEntities.Count == 0)
        return -2;
      ToolBase5 ToolSelected = new ToolBase5(marbleCam.ToolSelected);
      if (marbleCam.setCam.Distances.Safe < MaxPoint.Z)
        marbleCam.setCam.Distances.Safe = MaxPoint.Z + marbleCam.setCam.Distances.Rapid;
      if (flag)
      {
        marbleCam.setCam.Steps.DepthStepMode = CamStepDepthMode.ConstantDepthStep;
        marbleCam.setCam.Steps.StartValue = MaxPoint.Z - Item.Settings.settingSawMilling.SawMillingRoughVerTopOffset;
        marbleCam.setCam.Steps.EndValue = MinPoint.Z + Item.Settings.settingSawMilling.SawMillingRoughVerBottomOffset;
        clsMW.varMWCamMeshContantZPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshConstantZPars);
        clsMW.varMWCamMeshContantZPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshContantZPars, marbleCam.setCam);
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.FirstEntry.Type = FirstEntryType.Direct;
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.LastExit.Type = LastExitType.Direct;
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.GapsAlongCut.LargeMoveHandling.Action = MoveHandlingAction.ActionGapDirect;
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.LinkBetweenPasses.LargeMoveHandling.Action = MoveHandlingAction.ActionGapDirect;
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.LinkBetweenSlices.LargeMoveHandling.Action = MoveHandlingAction.ActionGapDirect;
        clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = false;
        clsMW.varMWCamMeshContantZPars.MachParam.Containment2dParams.IsUsedFlg = false;
        clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = true;
        clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.Type = MachiningAreaUndercutsParamsType.Tp3Axis;
        clsMW.varMWCamMeshContantZPars.MachParam.LinkParams.LinkBetweenPasses.LargeMoveHandling.Action = MoveHandlingAction.ActionGapStep;
        clsMW.varMWCamMeshContantZPars.MachParam.CutTolerance = Item.Settings.settingSawMilling.SawMillingRoughVerCutTolerance;
        clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaRoughingParams.DepthStep = Item.Settings.settingSawMilling.SawMillingRoughVerZDownStep;
        clsMW.varMWCamMeshContantZPars.MachParam.DistanceFlag = false;
        clsMW.varMWCamMeshContantZPars.MachParam.Distance = 10.0;
        if (clsMW.varMWCamMeshContantZPars.MachParam.CutTolerance <= 0.0)
          clsMW.varMWCamMeshContantZPars.MachParam.CutTolerance = 0.1;
        ToolSelected.Geometry.CornerRadiusType = ToolCornerRadiusType.None;
        ToolSelected.Geometry.GeometryType = buClass.ToolType.Slot;
        ToolSelected.Geometry.LengthDiameter = ToolSelected.Geometry.Diameter * 0.1;
        ToolSelected.Geometry.Diameter = buMarbleCalc.activeToolSaw.Geometry.Diameter;
        ToolSelected.Geometry.Length = marbleCam.ToolSelected.Geometry.Length;
        ToolSelected.Geometry.ShoulderDiameter = marbleCam.ToolSelected.Geometry.Diameter * 0.1;
        ToolSelected.Geometry.ShoulderLength = marbleCam.ToolSelected.Geometry.Length;
        ToolSelected.Geometry.CutLength = marbleCam.ToolSelected.Geometry.Thickness;
        MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ConstantZ;
      }
      if (marbleCam.MeshType == CamTriangularMeshType.ParallelCuts & buMarbleCalc.varMarbleRunSettings.selectedEngraving5AxisMilling)
      {
        buMWCalcs.varCamSurfacePars = new MWParameters();
        buMWCalcs.varCamSurfacePars.mwPar = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, buMWMarbleVars.varCamMarbleMeshParelelCut.buPar, out buMWCalcs.varCamSurfacePars.buPar);
      }
      clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
      clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
      clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
      clsMW.varMWCamMeshFlatlandPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
      clsMW.varMWCamMeshPencilPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
      camResult Result = (camResult) null;
      if (clsMW.CamEntities.Count > 0)
      {
        clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshParallelPars.Pockets.StepOverPersentage / 100.0;
        clsMW.varMWCamMeshRoughPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshRoughPars.Pockets.StepOverPersentage / 100.0;
        clsMW.varMWCamMeshContantZPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshConstantZPars.Pockets.StepOverPersentage / 100.0;
        clsMW.varMWCamMeshParalelPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
        clsMW.varMWCamMeshParalelPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Thickness;
        clsMW.varMWCamMeshParalelPars.MachParam.ParallelMachAngleInYX = 90.0;
        if (flag & marbleCam.CamMarbleType == MarbleCamType.SawMillingVerticalRough)
          clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
