          Item.ItemEntities.DrawWireEntities = new List<buEntity>();
          for (int index1 = 0; index1 <= Cam.CamPoints.Count - 1; ++index1)
          {
            Point3DList point3Dlist = new Point3DList();
            int index2 = Cam.CamPoints[index1].Points.Count / 2;
            double z = Cam.CamPoints[index1].Points[index2].P9.Z;
            for (int index3 = 0; index3 <= Cam.CamPoints[index1].Points.Count - 1; ++index3)
            {
              Pnt9D p9 = Cam.CamPoints[index1].Points[index3].P9;
              if (buCompare5.EQ(p9.Z, z, 0.001))
                point3Dlist.Points.Add(new Point3D(p9.X, p9.Y, p9.Z));
            }
            if (point3Dlist.Points.Count > 0)
            {
              if (!clsInit.cVector5.IsClosed(point3Dlist.Points))
              {
                if (buCompare5.EQ(point3Dlist.Points[0], point3Dlist.Points[point3Dlist.Points.Count - 2]))
                  point3Dlist.Points.RemoveAt(point3Dlist.Points.Count - 1);
                else if (buCompare5.EQ(point3Dlist.Points[0], point3Dlist.Points[point3Dlist.Points.Count - 3]))
                {
                  point3Dlist.Points.RemoveAt(point3Dlist.Points.Count - 1);
                  point3Dlist.Points.RemoveAt(point3Dlist.Points.Count - 1);
                }
                else
                  point3Dlist.Points.Add(buVector5.ToPoint3D(point3Dlist.Points[0]));
              }
              PLL3D.Add(point3Dlist);
            }
          }
          List<Point3D> point3DList1 = new List<Point3D>();
          List<Point3D> point3DList2 = new List<Point3D>();
          clsInit.cMarble.SawMillingVerticalToolPointCamCalc(ref Item, ref marbleCam, ref isReverse, new MarbleSawCalcParameters()
          {
            DevideLength = 10.0,
            ShiftPoint = new Point3D((MinPoint.X + MaxPoint.X) / 2.0, MinPoint.Y, MinPoint.Z),
