            SplineEnable = Item.Settings.settingSawMilling.SawMillingVerCornerSplineEnable,
            UseKinematic = false
          }, PLL3D, clsMarble.activeKinematic);
          buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
          Cam.TypeCam = CamType.ConstantZ;
        }
        else
        {
          MeshToSurfacePointsSettings Settings = new MeshToSurfacePointsSettings();
          Settings.RotationStep = Item.Settings.settingSawMilling.SawMillingFinishVerAngleStep;
          Settings.isInside = false;
          Settings.CheckIsClosedContour = false;
          Settings.RotationStartAngle = -90.0;
          List<Point3DList> Outside = new List<Point3DList>();
          List<List<Point3DList>> Insides = new List<List<Point3DList>>();
          clsInit.cVector5.GetMeshSurfacePointsFromDepth(clsMW.CamEntities, Item.Settings.settingSawMilling.SawMillingFinishVerTopOffset, Item.Settings.settingSawMilling.SawMillingFinishVerBottomOffset, Item.Settings.settingSawMilling.SawMillingFinishVerZDownStep, Plane.XY, Settings, ref Outside, ref Insides);
          clsInit.cMarble.SawMillingVerticalFinish(ref Item, ref marbleCam, Outside, clsMarble.activeKinematic);
        }
      }
      if ((Result == null ? 0 : (Result.Errors.Count > 0 ? 1 : 0)) != 0)
      {
        F_ErrorList fErrorList = new F_ErrorList();
        fErrorList.Init(Result.Errors);
        int num = (int) fErrorList.ShowDialog();
        clsInit.appCommand.Reset();
        return -2;
      }
      if (flag)
        buMWMarbleVars.varCamMarbleSawMillingVerticalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
      marbleCam.CamBase.TypeCam = CamType.SawCut;
      if (marbleCam.CamBase.CamPoints.Count > 0)
      {
        this.AnalyzeSawCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
        marbleCam.isCamCalculated = true;
      }
      Item.ToolType = MarbleToolType.Saw;
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

