  public int doSawMillingCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doSawMillingCamCalc);
    try
    {
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamWireframeType = CamWireFrameType.Contour;
      MWCalcOptions.CamTriMeshType = marbleCam.MeshType;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.isBuWireframeCalculation = false;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.ShowLeadInOutPage = false;
      MWCalcOptions.DontShowDialogBox = true;
      MWCalcOptions.DontShowbuDialogBox = true;
      clsMW.Containment2DEntities.Clear();
      camTp Cam = new camTp();
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      bool flag1;
      bool flag2;
      if (marbleCam.CamMarbleType == MarbleCamType.SawMillingVerticalRough)
      {
        flag1 = false;
        flag2 = true;
      }
      else if (marbleCam.CamMarbleType == MarbleCamType.SawMillingVerticalFinish)
      {
        flag1 = false;
        flag2 = false;
      }
      else if (marbleCam.CamMarbleType == MarbleCamType.SawMillingHorizontalRough)
      {
        flag1 = true;
        flag2 = true;
      }
      else
      {
        if (marbleCam.CamMarbleType != MarbleCamType.SawMillingHorizontalFinish)
          return -2;
        flag1 = true;
        flag2 = false;
      }
      Point3D MinPoint1 = new Point3D();
      Point3D MaxPoint1 = new Point3D();
      Point3D MinPoint2 = new Point3D();
      Point3D MaxPoint2 = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint1, ref MaxPoint1);
      if (flag1)
      {
        if (flag2)
        {
          for (int index = 0; index <= Item.ItemEntities.EngravingEntities.Count - 1; ++index)
          {
            Entity copiedEntity = (Entity) null;
            buEntity.Copy(Item.ItemEntities.EngravingEntities[index], ref copiedEntity);
            clsMW.CamEntities.Add(copiedEntity);
          }
          clsInit.cVector5.Rotate(MaxPoint1, -90.0, Vector3D.AxisX, ref clsMW.CamEntities);
          clsInit.cVector5.RegenEntities(0.1, ref clsMW.CamEntities);
          clsInit.cVector5.BoxSizeCalculate(clsMW.CamEntities, ref MinPoint2, ref MaxPoint2);
        }
      }
