        clsMW.varMWCamMeshRoughPars.MachParam.LinkParams.ClearancePlaneHeight = Item.SizeItem.MaxPoint.Z + 50.0;
        clsMW.varMWCamMeshRoughPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
        clsMW.varMWCamMeshRoughPars.MachParam.MaxStepoverDistance = 4.0;
        clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
        clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = false;
        clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
        clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
        clsMW.varMWCamMeshParalelPars.MachParam.StockRemainType = MachiningParamsStockRemainType.SrtGlobal;
        clsMW.CamEntities.Clear();
        List<buEntity> OffsetEntities1 = new List<buEntity>();
        clsInit.appMW.GetOffsetOfMesh(Item.ItemEntities.SolidEntity, 10.0, 10.0, 1.0, 1.0, 0.1, ref OffsetEntities1);
        clsMW.CamEntities.Clear();
        List<buEntity> OffsetEntities2 = new List<buEntity>();
        List<Point3D> copiedPoint1 = new List<Point3D>();
        buVector5.Copy(this.activeJob.Material.Points, ref copiedPoint1);
        List<Entity> refEntities = new List<Entity>();
        refEntities.Add((Entity) new LinearPath((ICollection<Point3D>) copiedPoint1));
        for (int index = 0; index <= OffsetEntities1.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(OffsetEntities1[index], ref copiedEntity);
          refEntities.Add(copiedEntity);
        }
        clsInit.appMW.GetPocketOfParalelEntities(refEntities, 30.0, 1.0, 0.1, ref OffsetEntities2);
        clsInit.cVector5.EntitiesToPointsWithCamDirection(OffsetEntities1, 0.1, ref Points);
        if (OffsetEntities2.Count > 0)
        {
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
          if (Points.Count > 0)
          {
            Item.Settings.settingMarbleCam.OffsetAngleC = 0.0;
            marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
            camTp data = new camTp();
            int num = 0;
            bool flag = false;
            TpPnt9D tpPnt9D1 = (TpPnt9D) null;
            List<List<Pnt6D>> pnt6DListList1 = new List<List<Pnt6D>>();
            List<List<Point3D>> point3DListList1 = new List<List<Point3D>>();
            List<List<Pnt6D>> pnt6DListList2 = new List<List<Pnt6D>>();
            List<Pnt6D> pnt6DList1 = new List<Pnt6D>();
            for (int index1 = 0; index1 <= OffsetEntities2.Count - 1; ++index1)
            {
              List<Pnt6D> pnt6DList2 = new List<Pnt6D>();
              for (int index2 = 0; index2 <= OffsetEntities2[index1].Vertices.Count - 1; ++index2)
              {
                double c = index2 != 0 ? clsInit.cVector5.PointAngle(OffsetEntities2[index1].Vertices[index2], OffsetEntities2[index1].Vertices[index2 - 1]) : clsInit.cVector5.PointAngle(OffsetEntities2[index1].Vertices[index2 + 1], OffsetEntities2[index1].Vertices[index2]);
                pnt6DList2.Add(new Pnt6D(OffsetEntities2[index1].Vertices[index2].X, OffsetEntities2[index1].Vertices[index2].Y, OffsetEntities2[index1].Vertices[index2].Z, 0.0, 0.0, c));
              }
              pnt6DListList1.Add(pnt6DList2);
            }
            if (Item.Settings.settingProfileCurveCut.RoughReverseCAngle)
              ;
            if (pnt6DListList1.Count > 0)
            {
              List<List<Point3D>> point3DListList2 = new List<List<Point3D>>();
              List<List<Pnt6D>> pnt6DListList3 = new List<List<Pnt6D>>();
              List<List<Pnt6D>> pnt6DListList4 = new List<List<Pnt6D>>();
              for (int index3 = 0; index3 <= pnt6DListList1.Count - 1; ++index3)
              {
                List<Point3D> point3DList2 = new List<Point3D>();
                for (int index4 = 0; index4 <= pnt6DListList1[index3].Count - 1; ++index4)
                  point3DList2.Add(buVector5.ToPoint3D(pnt6DListList1[index3][index4]));
                point3DListList2.Add(point3DList2);
              }
              for (int index5 = 0; index5 <= pnt6DListList1.Count - 1; ++index5)
              {
                camTpPoint camTpPoint = new camTpPoint();
                List<Pnt6D> CopiedPnt = new List<Pnt6D>();
                Pnt6D.Copy(pnt6DListList1[index5], ref CopiedPnt);
                List<Point3D> copiedPoint2 = new List<Point3D>();
                buVector5.Copy(point3DListList2[index5], ref copiedPoint2);
                if (CopiedPnt.Count > 0)
                {
                  Pnt6D refPoint1 = new Pnt6D(pnt6DListList1[index5][0]);
                  Pnt6D calcPoint1 = new Pnt6D();
                  refPoint1.Z = Item.Settings.settingProfileCurveCut.RoughSafeDis;
                  clsInit.cMarble.CalculatePointsWithKinematic(refPoint1, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoint1);
                  if (flag)
                    CopiedPnt.Reverse();
                  if (!Item.Settings.settingProfileCurveCut.RoughZigzagMode)
                    camTpPoint.Points.Add(tpPnt9D1);
                  else if (num == 0)
                  {
                    TpPnt9D tpPnt9D2 = new TpPnt9D(calcPoint1, 100.0, 0);
                    camTpPoint.Points.Add(tpPnt9D2);
                  }
                  if (!Item.Settings.settingProfileCurveCut.RoughZigzagMode)
                  {
                    TpPnt9D tpPnt9D3 = new TpPnt9D(CopiedPnt[0], 100.0, 0);
                    tpPnt9D3.P9.Z = Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCurveCut.RoughSafeDis;
                    camTpPoint.Points.Add(tpPnt9D3);
                  }
                  TpPnt9D tpPnt9D4 = new TpPnt9D(CopiedPnt[0], 100.0, 0);
                  tpPnt9D4.P9.Z += Item.Settings.settingProfileCurveCut.RoughRapid;
                  camTpPoint.Points.Add(tpPnt9D4);
                  TpPnt9D tpPnt9D5 = new TpPnt9D(CopiedPnt[0], Item.Settings.settingProfileCurveCut.RoughPlungeFeed, 1);
                  camTpPoint.Points.Add(tpPnt9D5);
                  for (int index6 = 1; index6 <= CopiedPnt.Count - 1; ++index6)
                  {
                    double feed = Item.Settings.settingProfileCurveCut.RoughCutForwardFeed;
                    if (flag)
                      feed = Item.Settings.settingProfileCurveCut.RoughCutBackwardFeed;
                    TpPnt9D tpPnt9D6 = new TpPnt9D(CopiedPnt[index6], feed, 1);
                    camTpPoint.Points.Add(tpPnt9D6);
                  }
                  if (Item.Settings.settingProfileCurveCut.RoughZigzagMode)
                  {
                    if (index5 == pnt6DListList1[0].Count - 1)
                    {
                      Pnt6D refPoint2 = new Pnt6D(pnt6DListList1[index5][pnt6DListList1[index5].Count - 1]);
                      Pnt6D calcPoint2 = new Pnt6D();
                      refPoint2.Z = Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCurveCut.RoughSafeDis;
                      clsInit.cMarble.CalculatePointsWithKinematic(refPoint2, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoint2);
                      tpPnt9D1 = new TpPnt9D(calcPoint2, 100.0, 0);
                      camTpPoint.Points.Add(tpPnt9D1);
                    }
                    else
                    {
                      tpPnt9D1 = new TpPnt9D(CopiedPnt[CopiedPnt.Count - 1], 100.0, 0);
                      refPoint1.Z = Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCurveCut.RoughSafeDis;
                      camTpPoint.Points.Add(tpPnt9D1);
                    }
                    flag = !flag;
                  }
                  else
                  {
                    Pnt6D refPoint3 = new Pnt6D(pnt6DListList4[index5][pnt6DListList4[index5].Count - 1]);
                    Pnt6D calcPoint3 = new Pnt6D();
                    refPoint3.Z = Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCurveCut.RoughSafeDis;
                    clsInit.cMarble.CalculatePointsWithKinematic(refPoint3, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoint3);
                    tpPnt9D1 = new TpPnt9D(calcPoint3, 100.0, 0);
                    camTpPoint.Points.Add(tpPnt9D1);
                    flag = false;
                  }
                  camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
                  LinearPath linearPath = new LinearPath((ICollection<Point3D>) copiedPoint2);
                  data.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
                  data.EntitiesG1.Add((Entity) linearPath);
                  data.CamPoints.Add(camTpPoint);
                  ++num;
                }
              }
            }
            data.Mode = CamMode.WireFrame;
            data.CamWireframeType = marbleCam.WireType;
            data.CamTriMeshType = marbleCam.MeshType;
            data.NumberOfAxis = 5;
            data.TypeCam = CamType.Rough;
            data.Explanation = marbleCam.CamName;
            marbleCam.CamBase = new camTp(data);
            marbleCam.isCamCalculated = true;
            clsInit.cVector5.BoxSizeCalculate(marbleCam.CamBase, ref marbleCam.SizeCamItem.MinPoint, ref marbleCam.SizeCamItem.MaxPoint);
          }
        }
      }
      marbleCam.CamBase.TypeCam = CamType.SawCut;
      this.doCamPointsOffsets(ref marbleCam);
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

  public void doSawMillingRoughCamAdd(
    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    if (ShowDialog)
    {
      if (buMarbleForms.frmSawMillingRough == null)
        buMarbleForms.frmSawMillingRough = new F_MarbleSawMillingRough();
      buMarbleForms.frmSawMillingRough.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmSawMillingRough.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmSawMillingRough.varSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
      buMarbleForms.frmSawMillingRough.Init();
      int num = (int) buMarbleForms.frmSawMillingRough.ShowDialog();
      if (buMarbleForms.frmSawMillingRough.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingRough.varSawMilling);
      Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
    }
    if (marbleCam == null | !Edit)
      marbleCam = new MarbleItemCam();
    marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
    if (CamType == MarbleCamType.SawMillingRoughOutside)
    {
      marbleCam.CamName = $"{buLangTranslate.preDef.Saw} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
      clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
      if (!Edit)
        Item.CamList.Add(marbleCam);
    }
    this.doSawMillingRoughtOutsideCamCalc(ref Item, ref marbleCam);
    this.AddOperationAfterThings();
  }

  public void doCornerCleaningCamAdd(
    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    string str = nameof (doCornerCleaningCamAdd);
    try
    {
      if (ShowDialog)
      {
        if (CuttingToolType != MarbleToolType.Saw)
          return;
        switch (CamType)
        {
          case MarbleCamType.SawMillingHorizontalRough:
            if (buMarbleForms.frmSawMillingCam == null)
              buMarbleForms.frmSawMillingCam = new F_MarbleSawMillingCam();
            buMarbleForms.frmSawMillingCam.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
            buMarbleForms.frmSawMillingCam.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
            buMarbleForms.frmSawMillingCam.varSettings = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
            buMarbleForms.frmSawMillingCam.Init(CamType);
            int num1 = (int) buMarbleForms.frmSawMillingCam.ShowDialog();
            if (buMarbleForms.frmSawMillingCam.PropertiesForm.Result != DialogResult.OK)
              return;
            buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingCam.varSettings);
            break;
          case MarbleCamType.SawMillingVerticalRough:
            if (buMarbleForms.frmSawMillingCam == null)
              buMarbleForms.frmSawMillingCam = new F_MarbleSawMillingCam();
            buMarbleForms.frmSawMillingCam.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
            buMarbleForms.frmSawMillingCam.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
            buMarbleForms.frmSawMillingCam.varSettings = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
            buMarbleForms.frmSawMillingCam.Init(CamType);
            int num2 = (int) buMarbleForms.frmSawMillingCam.ShowDialog();
            if (buMarbleForms.frmSawMillingCam.PropertiesForm.Result != DialogResult.OK)
              return;
            buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmSawMillingCam.varSettings);
            break;
          case MarbleCamType.CornerCleaning:
            if (buMarbleForms.frmCornerCleanBySaw == null)
              buMarbleForms.frmCornerCleanBySaw = new F_MarbleSawCornerClean();
            buMarbleForms.frmCornerCleanBySaw.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
            buMarbleForms.frmCornerCleanBySaw.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
            buMarbleForms.frmCornerCleanBySaw.varSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
            buMarbleForms.frmCornerCleanBySaw.Init(FormStartPosition.Manual);
            int num3 = (int) buMarbleForms.frmCornerCleanBySaw.ShowDialog();
            if (buMarbleForms.frmCornerCleanBySaw.PropertiesForm.Result != DialogResult.OK)
              return;
            buMarbleCalc.varOperation.settingSawMilling = new marbleSawMillingPars(buMarbleForms.frmCornerCleanBySaw.varSawMilling);
            break;
          default:
            return;
        }
      }
      AppBool.SaveByTick = true;
      if (marbleCam == null | !Edit)
        marbleCam = new MarbleItemCam();
      if (Item.ItemEntities.EngravingEntities == null)
        Item.ItemEntities.EngravingEntities = new List<buEntity>();
      Item.ItemEntities.EngravingEntities.Clear();
      Item.Settings.settingSawMilling = new marbleSawMillingPars(buMarbleCalc.varOperation.settingSawMilling);
      buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
      marbleCam.ToolType = CuttingToolType;
      marbleCam.WireType = CamWireFrameType.None;
      marbleCam.MeshType = CamTriangularMeshType.None;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      switch (CamType)
      {
        case MarbleCamType.SawMillingHorizontalRough:
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
          marbleCam.CamMarbleType = CamType;
          marbleCam.CamName = $"{buLangTranslate.preDef.Horizontal} {buLangTranslate.preDef.Rough}";
          marbleCam.CamType = CamType.Rough;
          marbleCam.CamMode = MarbleCamMode.Rough;
          clsInit.appMarble.doSawMillingHorizontalCamCalc(ref Item, ref marbleCam);
          break;
        case MarbleCamType.SawMillingVerticalRough:
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
          marbleCam.CamMarbleType = CamType;
          marbleCam.CamName = $"{buLangTranslate.preDef.Vertical} {buLangTranslate.preDef.Rough}";
          marbleCam.CamType = CamType.Rough;
          marbleCam.CamMode = MarbleCamMode.Rough;
          clsInit.appMarble.doSawMillingVerticalCamCalc(ref Item, ref marbleCam);
          break;
        case MarbleCamType.CornerCleaning:
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSawCornerCleaning.buPar);
          marbleCam.CamMarbleType = CamType;
          marbleCam.CamName = $"{buLangTranslate.preDef.Corner} {buLangTranslate.preDef.Cleaning}";
          marbleCam.CamType = CamType.Rough;
          marbleCam.CamMode = MarbleCamMode.Rough;
          clsInit.appMarble.doCornerCleaningCamCalc(ref Item, ref marbleCam);
          break;
      }
      marbleCam.isCamCalculated = true;
      clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
      Item.CamList.Add(marbleCam);
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public int doCornerCleaningCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = "doDrillPocketCamCalc";
    try
    {
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      if (Item.Settings.settingSawMilling.SawMillingVerCornerZDownStep <= 0.0)
        Item.Settings.settingSawMilling.SawMillingVerCornerZDownStep = 5.0;
      clsMW.Containment2DEntities.Clear();
      camTp camTp = new camTp();
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      Point3D MinPoint1 = new Point3D();
      Point3D MaxPoint1 = new Point3D();
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint1, ref MaxPoint1);
      bool isReverse = false;
      marbleCam.CamBase = new camTp();
      marbleCam.WireEntities = new List<List<buEntity>>();
      marbleCam.WireEntities.Clear();
      marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      clsMW.CamEntities.Clear();
      List<buEntity> OffsetEntities = new List<buEntity>();
      clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.UndercutsFlg = true;
      clsMW.varMWCamMeshContantZPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaUndercutsParams.Type = MachiningAreaUndercutsParamsType.Tp3Axis;
      clsMW.varMWCamMeshContantZPars.MachParam.CutTolerance = Item.Settings.settingSawMilling.SawMillingVerCornerCutTolerance;
      List<Entity> Meshes = new List<Entity>();
      Meshes.AddRange((IEnumerable<Entity>) Item.ItemEntities.SolidEntity);
      devDept.Eyeshot.Entities.Region rectangle1 = devDept.Eyeshot.Entities.Region.CreateRectangle(Item.SizeItem.Width, Item.SizeItem.Height);
      rectangle1.Translate(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y, Item.SizeItem.MaxPoint.Z);
      Mesh mesh = rectangle1.ExtrudeAsMesh(new Vector3D(0.0, 0.0, 0.1), 0.1, Mesh.natureType.RichSmooth);
      Meshes.Add((Entity) mesh);
      clsInit.appMW.GetOffsetOfMesh(Meshes, marbleCam.ToolSelected.Geometry.Diameter / 2.0, Item.SizeItem.Depth - Item.Settings.settingSawMilling.SawMillingVerCornerTopOffset, Item.SizeItem.MinPoint.Z + Item.Settings.settingSawMilling.SawMillingVerCornerBottomOffset, Item.Settings.settingSawMilling.SawMillingVerCornerZDownStep, 0.01, ref OffsetEntities);
      List<buEntity> buEntityList1 = new List<buEntity>();
      List<List<Point3D>> point3DListList1 = new List<List<Point3D>>();
      List<buEntity> buEntityList2 = new List<buEntity>();
      if (clsItem.FrmProgress != null)
        clsItem.FrmProgress.Visible = true;
      for (int index = 0; index <= OffsetEntities.Count - 1; ++index)
      {
        List<Point3D> point3DList = new List<Point3D>();
        buVector5.Copy(OffsetEntities[index].Vertices, ref point3DList);
        if (clsInit.cVector5.GetClockDirection(point3DList) == ClockDirectionType.CW)
          point3DList.Reverse();
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(0.1, ref point3DList);
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) point3DList);
        List<List<Point3D>> OffsetedPoints = new List<List<Point3D>>();
        clsInit.cVector5.OffsetContour(point3DList, -marbleCam.ToolSelected.Geometry.Diameter / 2.0, OffsetCornerType.Line, CamOpenContourType.Center, Plane.XY, 0.0, ref OffsetedPoints);
        if (OffsetedPoints.Count > 0)
          point3DListList1.Add(OffsetedPoints[0]);
      }
      if (point3DListList1.Count > 0)
      {
        Entity rectangle2 = (Entity) CompositeCurve.CreateRectangle(Plane.XY, MaxPoint1.X - MinPoint1.X, MaxPoint1.Y - MinPoint1.Y);
        rectangle2.Translate(MinPoint1.X, MinPoint1.Y);
        rectangle2.Regen(0.1);
        int CntZ = 0;
        int num1 = 0;
        int num2 = point3DListList1.Count - 1;
        if (Item.Settings.settingSawMilling.SawMillingVerCornerUseSingleLayer)
        {
          double num3 = double.MaxValue;
          for (int index = 0; index <= point3DListList1.Count - 1; ++index)
          {
            double num4 = Math.Abs(point3DListList1[index][0].Z - Item.Settings.settingSawMilling.SawMillingVerCornerSingleLayerDepth);
            if (num4 < num3)
            {
              num3 = num4;
              num1 = index;
              num2 = index;
            }
          }
        }
        for (int index1 = num1; index1 <= num2; ++index1)
        {
          if (Item.Settings.settingSawMilling.SawMillingVerCornerMode == MarbleSawCornerCleanMode.FitLine)
          {
            isReverse = false;
            if (CntZ % 2 == 1)
              isReverse = true;
          }
          List<Point3DList> PLLFill = new List<Point3DList>();
          List<Point3D> point3DList1 = new List<Point3D>();
          buVector5.Copy(point3DListList1[index1], ref point3DList1);
          Point3D MinPoint2 = new Point3D();
          Point3D MidPoint = new Point3D();
          Point3D MaxPoint2 = new Point3D();
          clsInit.cVector5.BoxSizeCalculate(point3DList1, ref MinPoint2, ref MidPoint, ref MaxPoint2);
          Entity rectangle3 = (Entity) CompositeCurve.CreateRectangle(Plane.XY, MaxPoint2.X - MinPoint2.X, MaxPoint2.Y - MinPoint2.Y);
          rectangle3.Translate(MinPoint2.X, MinPoint2.Y, point3DListList1[index1][0].Z);
          rectangle3.Regen(0.1);
          if (Item.Settings.settingSawMilling.SawMillingVerCornerUseLastContour && Item.Settings.settingSawMilling.SawMillingVerCornerMode != MarbleSawCornerCleanMode.FitLine)
          {
            if (Item.Settings.settingSawMilling.SawMillingVerCornerCurvatureDegree <= 1)
            {
              Point3DList point3Dlist = new Point3DList();
              point3Dlist.Points.AddRange((IEnumerable<Point3D>) point3DList1);
              PLLFill.Add(point3Dlist);
            }
            else
            {
              List<Point3D> copiedPoint = new List<Point3D>();
              buVector5.Copy(point3DList1, ref copiedPoint);
              devDept.Eyeshot.Entities.Curve curve = new devDept.Eyeshot.Entities.Curve(Item.Settings.settingSawMilling.SawMillingVerCornerCurvatureDegree, (IList<Point3D>) copiedPoint);
              curve.Regen(Item.Settings.settingSawMilling.SawMillingVerCornerSplineDt);
              List<Point3D> collection = new List<Point3D>();
              collection.AddRange((IEnumerable<Point3D>) ((IEnumerable<Point3D>) curve.Vertices).ToArray<Point3D>());
              Point3DList point3Dlist = new Point3DList();
              point3Dlist.Points.AddRange((IEnumerable<Point3D>) collection);
              PLLFill.Add(point3Dlist);
            }
          }
          int num5 = 10;
          if (Item.Settings.settingSawMilling.SawMillingVerCornerMode == MarbleSawCornerCleanMode.FitLine)
          {
            num5 = 0;
            clsInit.cMarble.SawCornerLine(rectangle2, point3DList1, Item.Settings.settingSawMilling.SawMillingVerCornerXYAproachStep, Item.Settings.settingSawMilling.SawMillingVerCornerSafeDistanceXY, point3DListList1[index1][0].Z, isReverse, CntZ, ref PLLFill);
          }
          for (int index2 = 1; index2 <= num5; ++index2)
          {
            clsInit.cVector5.CheckDuplicatedPointsWithPrevious(0.1, ref point3DList1);
            if (clsInit.cVector5.GetClockDirection(point3DList1) == ClockDirectionType.CW)
              point3DList1.Reverse();
            List<List<Point3D>> OffsetedPoints = new List<List<Point3D>>();
            if (Item.Settings.settingSawMilling.SawMillingVerCornerMode == MarbleSawCornerCleanMode.FitCircular)
            {
              double num6 = (MaxPoint2.X - MinPoint2.X) / 2.0;
              double num7 = (MaxPoint2.Y - MinPoint2.Y) / 2.0;
              Circle circle = num6 <= num7 ? new Circle(Plane.XY, new Point3D(MidPoint.X, MidPoint.Y, point3DList1[0].Z), num7 + (double) index2 * Item.Settings.settingSawMilling.SawMillingVerCornerXYAproachStep) : new Circle(Plane.XY, new Point3D(MidPoint.X, MidPoint.Y, point3DList1[0].Z), num6 + (double) index2 * Item.Settings.settingSawMilling.SawMillingVerCornerXYAproachStep);
              circle.Regen(Item.Settings.settingSawMilling.SawMillingVerCornerCutTolerance);
              List<Point3D> copiedPoint = new List<Point3D>();
              buVector5.Copy(circle.Vertices, ref copiedPoint);
              OffsetedPoints.Add(copiedPoint);
            }
            else
              clsInit.cVector5.OffsetContour(point3DList1, Item.Settings.settingSawMilling.SawMillingVerCornerXYAproachStep, OffsetCornerType.Line, CamOpenContourType.Center, Plane.XY, 0.0, ref OffsetedPoints);
            if (OffsetedPoints.Count > 0)
            {
              Point3D MinPoint3 = new Point3D();
              Point3D MaxPoint3 = new Point3D();
              if (OffsetedPoints[0].Count > 0)
              {
                clsInit.cVector5.BoxSizeCalculate(OffsetedPoints[0], ref MinPoint3, ref MaxPoint3);
                CompositeCurve rectangle4 = CompositeCurve.CreateRectangle(MaxPoint1.X - MinPoint1.X, MaxPoint1.Y - MinPoint1.Y);
                rectangle4.Translate(MinPoint1.X, MinPoint1.Y, MinPoint3.Z);
                LinearPath linearPath = new LinearPath((ICollection<Point3D>) OffsetedPoints[0]);
                Point3D[] source = linearPath.IntersectWith((ICurve) rectangle4, 0.0, true);
                ICurve[] segments = (ICurve[]) null;
                linearPath.SplitBy((IList<Point3D>) ((IEnumerable<Point3D>) source).ToList<Point3D>(), out segments);
                if (clsInit.cVector5.IsPointInsideBoxsize(OffsetedPoints[0], MinPoint1, MaxPoint1, Plane.XY))
                {
                  List<Point3D> copiedPoint = new List<Point3D>();
                  buVector5.Copy(OffsetedPoints[0], ref copiedPoint, 3);
                  Point3DList point3Dlist = new Point3DList();
                  point3Dlist.Points.AddRange((IEnumerable<Point3D>) copiedPoint);
                  PLLFill.Add(point3Dlist);
                }
                else
                {
                  if (segments.Length != 0 & !Item.Settings.settingSawMilling.SawMillingVerCornerTrimToBorder)
                  {
                    List<Point3D> copiedPoint = new List<Point3D>();
                    buVector5.Copy(OffsetedPoints[0], ref copiedPoint, 3);
                    Point3DList point3Dlist = new Point3DList();
                    point3Dlist.Points.AddRange((IEnumerable<Point3D>) copiedPoint);
                    PLLFill.Add(point3Dlist);
                  }
                  if (segments.Length != 0 & Item.Settings.settingSawMilling.SawMillingVerCornerTrimToBorder)
                  {
                    List<List<Point3D>> point3DListList2 = new List<List<Point3D>>();
                    for (int index3 = 0; index3 <= segments.Length - 1; ++index3)
                    {
                      List<Point3D> copiedPoint = new List<Point3D>();
                      buVector5.Copy(((Entity) segments[index3]).Vertices, ref copiedPoint, 3);
                      if (clsInit.cVector5.IsPointInsideBoxsize(copiedPoint, MinPoint1, MaxPoint1, Plane.XY))
                        point3DListList2.Add(copiedPoint);
                    }
                    if (point3DListList2.Count > 0)
                    {
                      if (point3DListList2.Count >= 2)
                      {
                        Point3D point3D3 = point3DListList2[0][0];
                        Point3D point3D4 = point3DListList2[0][point3DListList2[0].Count - 1];
                        if (!buCompare5.EQ(point3D3.X, MinPoint1.X) & !buCompare5.EQ(point3D3.X, MaxPoint1.X) & !buCompare5.EQ(point3D3.Y, MinPoint1.Y) & !buCompare5.EQ(point3D3.Y, MaxPoint1.Y))
                        {
                          Point3D point3D5 = point3DListList2[point3DListList2.Count - 1][point3DListList2[point3DListList2.Count - 1].Count - 1];
                          if (!buCompare5.EQ(point3D5.X, MinPoint1.X) & !buCompare5.EQ(point3D5.X, MaxPoint1.X) & !buCompare5.EQ(point3D5.Y, MinPoint1.Y) & !buCompare5.EQ(point3D5.Y, MaxPoint1.Y))
                          {
                            List<Point3D> collection = new List<Point3D>();
                            collection.AddRange((IEnumerable<Point3D>) point3DListList2[0]);
                            point3DListList2[point3DListList2.Count - 1].AddRange((IEnumerable<Point3D>) collection);
                            point3DListList2.RemoveAt(0);
                          }
                        }
                        else if (!buCompare5.EQ(point3D4.X, MinPoint1.X) & !buCompare5.EQ(point3D4.X, MaxPoint1.X) & !buCompare5.EQ(point3D4.Y, MinPoint1.Y) & !buCompare5.EQ(point3D4.Y, MaxPoint1.Y))
                        {
                          Point3D point3D6 = point3DListList2[point3DListList2.Count - 1][0];
                          if (!buCompare5.EQ(point3D6.X, MinPoint1.X) & !buCompare5.EQ(point3D6.X, MaxPoint1.X) & !buCompare5.EQ(point3D6.Y, MinPoint1.Y) & !buCompare5.EQ(point3D6.Y, MaxPoint1.Y))
                          {
                            List<Point3D> collection = new List<Point3D>();
                            collection.AddRange((IEnumerable<Point3D>) point3DListList2[0]);
                            point3DListList2[0].AddRange((IEnumerable<Point3D>) collection);
                            point3DListList2.RemoveAt(point3DListList2.Count - 1);
                          }
                        }
                      }
                      List<Point3D> point3DList2 = new List<Point3D>();
                      clsInit.cMarble.SawCornerCurvature(point3DListList1[index1], point3DListList2[0], Item.Settings.settingSawMilling.SawMillingVerCornerCurvatureDegree, Item.Settings.settingSawMilling.SawMillingVerCornerMode, Item.Settings.settingSawMilling.SawMillingVerCornerCutTolerance, ref point3DList2);
                      for (int index4 = 1; index4 <= point3DListList2.Count - 1; ++index4)
                      {
                        Point3D lastP = point3DList2[point3DList2.Count - 1];
                        Point3D firstP = point3DListList2[index4][0];
                        if (buCompare5.EQ(lastP.X, firstP.X) | buCompare5.EQ(lastP.Y, firstP.Y))
                        {
                          clsInit.cMarble.SawCornerCurvature(point3DListList1[index1], point3DListList2[index4], Item.Settings.settingSawMilling.SawMillingVerCornerCurvatureDegree, Item.Settings.settingSawMilling.SawMillingVerCornerMode, Item.Settings.settingSawMilling.SawMillingVerCornerCutTolerance, ref point3DList2);
                        }
                        else
                        {
                          clsInit.cMarble.SawCornerConnect(MinPoint1, MaxPoint1, firstP, lastP, false, ref point3DList2);
                          Point3D point3D7 = point3DList2[point3DList2.Count - 1];
                          if (buCompare5.EQ(point3D7.X, firstP.X) | buCompare5.EQ(point3D7.Y, firstP.Y))
                            clsInit.cMarble.SawCornerCurvature(point3DListList1[index1], point3DListList2[index4], Item.Settings.settingSawMilling.SawMillingVerCornerCurvatureDegree, Item.Settings.settingSawMilling.SawMillingVerCornerMode, Item.Settings.settingSawMilling.SawMillingVerCornerCutTolerance, ref point3DList2);
                        }
                      }
                      if (!clsInit.cVector5.IsClosed(point3DList2))
                      {
                        Point3D lastP = point3DList2[point3DList2.Count - 1];
                        Point3D firstP = point3DList2[0];
                        if (buCompare5.EQ(lastP.X, firstP.X) | buCompare5.EQ(lastP.Y, firstP.Y))
                          point3DList2.Add(buVector5.ToPoint3D(point3DList2[0]));
                        else
                          clsInit.cMarble.SawCornerConnect(MinPoint1, MaxPoint1, firstP, lastP, true, ref point3DList2);
                      }
                      if (point3DList2.Count > 0)
                      {
                        Point3DList point3Dlist = new Point3DList();
                        point3Dlist.Points.AddRange((IEnumerable<Point3D>) point3DList2);
                        PLLFill.Add(point3Dlist);
                      }
                    }
                  }
                }
                if ((index2 != 1 ? 0 : (PLLFill.Count == 0 ? 1 : 0)) != 0)
                {
                  List<Point3D> copiedPoint = new List<Point3D>();
                  buVector5.Copy(OffsetedPoints[0], ref copiedPoint, 3);
                  Point3DList point3Dlist = new Point3DList();
                  point3Dlist.Points.AddRange((IEnumerable<Point3D>) copiedPoint);
                  PLLFill.Add(point3Dlist);
                  index2 = num5;
                }
                point3DList1 = new List<Point3D>();
                buVector5.Copy(OffsetedPoints[0], ref point3DList1);
              }
            }
          }
          MarbleSawCalcParameters sawCalcParameters = new MarbleSawCalcParameters();
          sawCalcParameters.DevideLength = 100.0;
          sawCalcParameters.ShiftPoint = new Point3D((MinPoint1.X + MaxPoint1.X) / 2.0, MinPoint1.Y, MinPoint1.Z);
          sawCalcParameters.ShiftEnable = false;
          sawCalcParameters.SplineEnable = Item.Settings.settingSawMilling.SawMillingVerCornerSplineEnable;
          if (PLLFill.Count > 0)
          {
            PLLFill.Reverse();
            if (index1 == 0)
            {
              PLLFill[0].Settings = (object) new MarbleSawCalcParameters(sawCalcParameters);
              ((MarbleSawCalcParameters) PLLFill[0].Settings).MoveSafeZDistance = true;
            }
            if (Item.Settings.settingSawMilling.SawMillingVerCornerMode == MarbleSawCornerCleanMode.FitLine)
              clsInit.cMarble.SawMillingVerticalToolPointCamCenterCalc(ref Item, ref marbleCam, sawCalcParameters, PLLFill, clsMarble.activeKinematic);
            else
              clsInit.cMarble.SawMillingVerticalToolPointCamCalc(ref Item, ref marbleCam, ref isReverse, sawCalcParameters, PLLFill, clsMarble.activeKinematic);
          }
          ++CntZ;
        }
      }
      AppBool.SaveByTick = true;
      if (clsItem.FrmProgress != null)
        clsItem.FrmProgress.Visible = false;
      return 1;
    }
    catch (Exception ex)
    {
      if (clsItem.FrmProgress != null)
        clsItem.FrmProgress.Visible = false;
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

  public void doAddItemMilling5AxisRotary(Point3D refPoint, List<Entity> Entities, bool isCamCalc = false)
  {
    string str = nameof (doAddItemMilling5AxisRotary);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.EngravingEntities = new List<buEntity>();
      MI.ItemType = MarbleItemType.Milling5AxisRotary;
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (Entities[index] is Brep)
        {
          buEntity copiedEntity = (buEntity) null;
          Brep entity = (Brep) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is Mesh)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
        else if (Entities[index] is devDept.Eyeshot.Entities.Surface)
        {
          buEntity copiedEntity = (buEntity) null;
          devDept.Eyeshot.Entities.Surface entity = (devDept.Eyeshot.Entities.Surface) Entities[index];
          entity.Regen(0.05);
          buEntity.Copy((Entity) entity.ConvertToMesh(), ref copiedEntity);
          MI.ItemEntities.EngravingEntities.Add(copiedEntity);
        }
      }
      for (int index = 0; index <= Entities.Count - 1; ++index)
      {
        if (clsInit.cVector5.isEntitySolid(Entities[index]))
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Entities[index], ref copiedEntity);
          if (copiedEntity != null)
          {
            if (MI.ItemEntities.SolidEntity == null)
              MI.ItemEntities.SolidEntity = new List<Entity>();
            copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemEngrave.Color);
            copiedEntity.ColorMethod = colorMethodType.byEntity;
            MI.ItemEntities.SolidEntity.Add(copiedEntity);
          }
        }
      }
      for (int index = 0; index <= MI.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        buEntity engravingEntity = MI.ItemEntities.EngravingEntities[index];
        engravingEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        engravingEntity.Marble = new MarbleInfo();
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
        ObjectSize3D.CalculateSize(ref MI.SizeItem);
      }
      if ((MI.ItemEntities.SolidEntity == null ? 0 : (MI.BaseHeight > 0.0 ? 1 : 0)) != 0)
      {
        Entity surfaceEntity = (Entity) null;
        clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
        if (surfaceEntity != null)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(surfaceEntity, ref copiedEntity);
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
          MI.ItemEntities.BaseEntities = new List<buEntity>();
          MI.ItemEntities.BaseEntities.Add(copiedEntity);
        }
      }
      for (int index = 0; index <= 1; ++index)
      {
        MarbleItemCam marbleCam = new MarbleItemCam();
        marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
        marbleCam.AxesNumber = MarbleTempVars.AxesNumber;
        switch (index)
        {
          case 0:
            marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMesh5AxisType;
            break;
          case 1:
            marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMesh5AxisType2;
            break;
        }
        if (marbleCam.MeshType == CamTriangularMeshType.Rough)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshRough.buPar);
          marbleCam.CamType = CamType.Rough;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingRough3D;
          marbleCam.CamMode = MarbleCamMode.Rough;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.ParallelCuts)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
          marbleCam.CamType = CamType.ParallelCut;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.ParalelCuts} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingParallelCut3D;
          marbleCam.CamMode = MarbleCamMode.Finish;
        }
        else if (marbleCam.MeshType == CamTriangularMeshType.ConstantZ)
        {
          this.doAddItemCommonProps(ref MI);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
          marbleCam.CamType = CamType.ConstantZ;
          marbleCam.CamName = $"{buLangTranslate.preDef.Engraving} {buLangTranslate.preDef.ConstantZ} {buLangTranslate.preDef.Cut}";
          marbleCam.CamMarbleType = MarbleCamType.MillingContantZ3D;
          marbleCam.CamMode = MarbleCamMode.Finish;
        }
        marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
        if (marbleCam.ToolType == MarbleToolType.Saw | marbleCam.ToolType == MarbleToolType.WaterJet)
          marbleCam.ToolType = MarbleToolType.MillingHead;
        marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        if (marbleCam.MeshType != CamTriangularMeshType.None)
          MI.CamList.Add(marbleCam);
        if (isCamCalc)
        {
          if (marbleCam.MeshType != CamTriangularMeshType.None)
          {
            MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
            MWCalcoptions.NumberofAxis = 5;
            MWCalcoptions.CamTriMeshType = marbleCam.MeshType;
            MWCalcoptions.Mode = CamMode.TriangularMesh5AX;
            MWCalcoptions.DontApplyReset = true;
            MWCalcoptions.isBuWireframeCalculation = false;
            MWCalcoptions.AddToCamListInLocalCalculation = false;
            MWCalcoptions.ShowLeadInOutPage = false;
            MWCalcoptions.DontShowDialogBox = true;
            MWCalcoptions.DontShowbuDialogBox = true;
            if (MI.ItemType == MarbleItemType.Milling5AxisRotary & marbleCam.CamType == CamType.Rough)
            {
              if (marbleCam.AxesNumber == 3)
                this.doMilling3AxisRotaryCamCalc(MWCalcoptions, MI, ref marbleCam);
              if (marbleCam.AxesNumber == 4)
                this.doMilling4AxisRotaryCamCalc(MWCalcoptions, MI, ref marbleCam);
            }
            marbleCam.isCamCalculated = true;
          }
        }
        else
        {
          marbleCam.isCamCalculated = false;
          this.activeJob.CamCalculated = false;
        }
      }
      this.AddOperationBeforeThings();
      MI.ID = MarbleTempVars.ItemID;
      this.doAddItemToJob(MI, true, true);
      if (!buMarbleCalc.varMarbleSettings.AutoMagnet)
        return;
      this.doAlignment(MarbleCadCamCommands.MagnetLeftDown, 0.0);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public int doMilling3AxisRotaryCamCalc(
    MWCalculationOptions MWCalcoptions,
    MarbleItem Item,
    ref MarbleItemCam marbleCam)
  {
    string str = nameof (doMilling3AxisRotaryCamCalc);
    try
    {
      clsMW.Containment2DEntities.Clear();
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      Point3D MinPoint1 = new Point3D();
      Point3D MaxPoint1 = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint1, ref MaxPoint1);
      List<List<Entity>> refEntities = new List<List<Entity>>();
      List<Entity> entityList1 = new List<Entity>();
      MWCalcoptions.CamTriMesh5AXType = CamTriangularMesh5AxType.Rough;
      MWCalcoptions.CamTriMeshType = CamTriangularMeshType.Rough;
      for (int index = 0; index <= Item.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        Entity entity = (Entity) null;
        buEntity.Copy(Item.ItemEntities.EngravingEntities[index], ref entity);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref entity);
        entityList1.Add(entity);
      }
      refEntities.Add(entityList1);
      List<Entity> entityList2 = new List<Entity>();
      for (int index = 0; index <= Item.ItemEntities.EngravingEntities.Count - 1; ++index)
      {
        Entity entity = (Entity) null;
        buEntity.Copy(Item.ItemEntities.EngravingEntities[index], ref entity);
        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref entity);
        entityList2.Add(entity);
      }
      refEntities.Add(entityList2);
      Point3D MinPoint2 = new Point3D();
      Point3D MidPoint = new Point3D();
      Point3D MaxPoint2 = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint2, ref MidPoint, ref MaxPoint2);
      double num1 = MaxPoint2.Z - MidPoint.Z;
      double safe = buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Safe;
      if (marbleCam.setCam.Distances.Safe < MaxPoint2.Z)
        marbleCam.setCam.Distances.Safe = num1 + buMWMarbleVars.varCamMarbleMeshRough.buPar.Distances.Rapid;
      if (refEntities.Count == 0)
        return -2;
      marbleCam.setCam.Steps.DepthStepMode = CamStepDepthMode.ConstantDepthStep;
      marbleCam.setCam.Steps.StartValue = MaxPoint2.Z;
      marbleCam.setCam.Steps.EndValue = MidPoint.Z - 1.0;
      MWCalcoptions.NumberofAxis = 3;
      if (marbleCam.CamType == CamType.Rough)
      {
        clsMW.varMWCamMeshRoughPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshRough.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshRoughPars);
        clsMW.varMWCamMeshRoughPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshRoughPars, marbleCam.setCam);
        clsMW.varMWCamMeshRoughPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.UseAirMoveSafetyDistanceFlg = false;
        clsMW.varMWCamMeshRoughPars.MachParam.MaxStepoverDistance = marbleCam.ToolSelected.Geometry.Diameter * clsMW.varbuCamMeshRoughPars.Pockets.StepOverPersentage / 100.0;
      }
      if (marbleCam.CamType == CamType.ParallelCut)
      {
        clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar, marbleCam.setCam, out clsMW.varbuCamMeshParallelPars);
        clsMW.varMWCamMeshParalelPars = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(clsMW.varMWCamMeshParalelPars, marbleCam.setCam);
