        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref Cam.EntitiesG1);
        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref Cam.EntitiesG0);
        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref Cam.EntitiesLeave);
        clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisX, ref Cam.EntitiesPlunge);
        buMWMarbleVars.varCamMarbleMeshRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshRoughPars, clsMW.varbuCamMeshRoughPars, out buMWMarbleVars.varCamMarbleMeshRough.buPar);
        Cam.TypeCam = CamType.Rough;
      }
      if (MWCalcoptions.CamTriMeshType == CamTriangularMeshType.ParallelCuts)
      {
        buMWMarbleVars.varCamMarbleMeshParelelCut.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshParalelPars, clsMW.varbuCamMeshParallelPars, out buMWMarbleVars.varCamMarbleMeshParelelCut.buPar);
        Cam.TypeCam = CamType.ParallelCut;
      }
      if (MWCalcoptions.CamTriMeshType == CamTriangularMeshType.ConstantZ)
      {
        buMWMarbleVars.varCamMarbleMeshConstantZ.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleMeshConstantZ.buPar);
        Cam.TypeCam = CamType.ConstantZ;
      }
      Cam.Mode = MWCalcoptions.Mode;
      Cam.CamWireframeType = MWCalcoptions.CamWireframeType;
      Cam.CamTriMeshType = MWCalcoptions.CamTriMeshType;
      Cam.NumberOfAxis = MWCalcoptions.NumberofAxis;
      Cam.Tool = new ToolBase5(marbleCam.ToolSelected);
      if (!buMarbleCalc.varMarbleRunSettings.selectedEngraving5AxisMilling)
      {
        marbleCam.CamBase = new camTp(Cam);
      }
      else
      {
        int num1 = 0;
        double num2 = 0.0;
        marbleCam.CamBase = new camTp(Cam);
        for (int index3 = 0; index3 <= marbleCam.CamBase.CamPoints.Count - 1; ++index3)
        {
          for (int index4 = 0; index4 <= marbleCam.CamBase.CamPoints[index3].Points.Count - 1; ++index4)
          {
            TpPnt9D point = marbleCam.CamBase.CamPoints[index3].Points[index4];
            double double_0 = 0.0;
            double double_2 = 0.0;
            IJK ijk = new IJK(point.P9.A, point.P9.B, point.P9.C);
            Point3D MovePoint = new Point3D(point.P9.X, point.P9.Y, point.P9.Z);
            Pnt6D CalcPoint = new Pnt6D();
            double a = point.P9.A;
            double b = point.P9.B;
            double c = point.P9.C;
            Class5.smethod_185(ref double_0, b, ref double_2, a, c);
            OrientationAngle Orientation = new OrientationAngle(0.0, double_0, double_2);
            clsInit.cKinematic5.ForwardKinematix5AxMilling(marbleCam.CamBase.Tool.Geometry.Length, ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Y - ccVars.KinematicOrjinal.RotateCenterOffsetOfC.Y, ijk, Orientation, MovePoint, ref CalcPoint);
            point.P9.X = CalcPoint.X;
            point.P9.Y = CalcPoint.Y;
            point.P9.Z = CalcPoint.Z;
            point.P9.B = CalcPoint.A;
            point.P9.A = 90.0 - CalcPoint.B;
            point.P9.C = CalcPoint.C - 90.0;
            if (num1 > 0)
            {
              double num3 = num2 - point.P9.C;
              if (num3 > 180.0 | num3 < -180.0)
              {
                if (num3 < 0.0)
                  point.P9.C -= 360.0;
                else
                  point.P9.C += 360.0;
              }
            }
            num2 = point.P9.C;
            ++num1;
          }
        }
      }
      marbleCam.isCamCalculated = true;
      marbleMillingAnalyzePars millingAnalyzePars = new marbleMillingAnalyzePars();
      marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      Item.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

  public void doAddItemSweep(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemSweep);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForSweep.Count == 0)
        return;
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.DrawWireEntities = new List<buEntity>();
      MI.ItemEntities.SourceEntities = new List<buEntity>();
      Entity entSurface = (Entity) null;
      MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      this.doSweepCut(this.entitiesForSweep[0], isFinsihed, ref entSurface, ref MI);
      MI.ItemType = MarbleItemType.Sweep;
      MI.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
      MI.BaseHeight = 0.0;
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      if (isFinsihed)
      {
        this.doAddItemCommonProps(ref MI);
        if (MI.ItemEntities.SolidEntity != null)
        {
          for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
            MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z);
        }
        for (int index = 0; index <= MI.ItemEntities.DrawWireEntities.Count - 1; ++index)
          MI.ItemEntities.DrawWireEntities[index].Translate(refPoint.X, refPoint.Y, refPoint.Z);
        for (int index = 0; index <= MI.ItemEntities.SourceEntities.Count - 1; ++index)
          MI.ItemEntities.SourceEntities[index].Translate(refPoint.X, refPoint.Y, refPoint.Z);
        if (MI.ItemEntities.SolidEntity != null)
        {
          clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
          ObjectSize3D.CalculateSize(ref MI.SizeItem);
        }
        MarbleItemCam marbleCam = new MarbleItemCam()
        {
          CamName = $"{buLangTranslate.preDef.Sweep} {buLangTranslate.preDef.Cut}",
          CamMarbleType = MarbleCamType.Sweep,
          CamMode = MarbleCamMode.Contour,
          ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
          WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
          MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
          CamType = CamType.Contour
        };
        marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
        marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSweep.buPar);
        marbleCam.isRough = false;
        marbleCam.isFinish = true;
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        MI.CamList.Add(marbleCam);
        if (isCamCalc)
          this.doSweepCamCalc(ref MI, ref marbleCam);
        marbleCam.isCamCalculated = isCamCalc;
        this.AddOperationBeforeThings();
        MI.ID = MarbleTempVars.ItemID;
        this.doAddItemToJob(MI, true, true);
      }
      else
        MarbleTempVars.ItemsSweep.Add(MI);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doSweepCut(
    List<buEntity> refEntities,
    bool isFinished,
    ref Entity entSurface,
    ref MarbleItem Item)
  {
    string str = nameof (doSweepCut);
    try
    {
      buEntity SweepEntity = new buEntity();
      Item.ItemEntities.SourceEntities = new List<buEntity>();
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      if ((MarbleTempVars.SweepZFormEntities == null ? 0 : (Item.Settings.settingSweepCut.SawRampType == CamZRampType.FromFile & MarbleTempVars.SweepZFormEntities.Count > 0 ? 1 : 0)) != 0)
      {
        List<Point3D> Points1 = new List<Point3D>();
        for (int index = 0; index <= refEntities.Count - 1; ++index)
        {
          List<Point3D> pntDevided = new List<Point3D>();
          clsInit.cVector5.EntityDevideByCamDir(refEntities[index], 1.0, ref pntDevided);
          Points1.AddRange((IEnumerable<Point3D>) pntDevided);
        }
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points1);
        if (Points1.Count > 2)
        {
          double Length = 0.0;
          clsInit.cVector5.EntitiesLength(MarbleTempVars.SweepZFormEntities, ref Length);
          double DevideLength = Length / (double) Points1.Count;
          List<Point3D> Points2 = new List<Point3D>();
          Point3D MinPoint = new Point3D();
          Point3D MaxPoint = new Point3D();
          clsInit.cVector5.BoxSizeCalculate(MarbleTempVars.SweepZFormEntities, ref MinPoint, ref MaxPoint);
          clsInit.cVector5.Move(-MinPoint.X, -MinPoint.Y, -MinPoint.Z, ref MarbleTempVars.SweepZFormEntities);
          SortbuSettings Settings = new SortbuSettings();
          Settings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
          List<buEntity> SortedEntities = new List<buEntity>();
          clsInit.cVector5.SortEntitiesByRefPoint(new Point3D(), ref MarbleTempVars.SweepZFormEntities, Settings, ref SortedEntities);
          for (int index = 0; index <= SortedEntities.Count - 1; ++index)
          {
            List<Point3D> pntDevided = new List<Point3D>();
            clsInit.cVector5.EntityDevide(SortedEntities[index], DevideLength, ref pntDevided);
            if (SortedEntities[index].sortDirection == entitySortDirection.Reverse)
              pntDevided.Reverse();
            Points2.AddRange((IEnumerable<Point3D>) pntDevided);
          }
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points2);
          if (Points2.Count > 0)
          {
            if (Points2.Count > Points1.Count)
            {
              int num = Points2.Count - Points1.Count;
              int int32 = Convert.ToInt32((double) Points2.Count / ((double) num + 1.0));
              for (int index1 = num; index1 >= 1; --index1)
              {
                int index2 = index1 * int32;
                if (index2 >= 0 & index2 <= Points2.Count - 1)
                  Points2.RemoveAt(index2);
              }
            }
            else if (Points2.Count < Points1.Count)
              ;
            if (Points2.Count == Points1.Count)
            {
              for (int index = 0; index <= Points1.Count - 1; ++index)
                Points1[index].Z = Points2[index].Y;
            }
            if (Points1.Count > 0)
              SweepEntity = (buEntity) new buLinearPath(Points1);
          }
        }
      }
      else
        clsInit.cVector5.EntitiesToSweep(refEntities, buMarbleCalc.varOperation.settingSweepCut.SweepRampHeight, buMarbleCalc.varOperation.settingSweepCut.SweepRampWidth, buMarbleCalc.varOperation.settingSweepCut.SweepTargetZ, buMarbleCalc.varOperation.settingSweepCut.SawRampType, ref SweepEntity, buMarbleCalc.varOperation.settingSweepCut.SweepResolution);
      if (Item.Settings.settingSweepCut.SweepWidth == 0.0 | Item.Settings.settingSweepCut.SweepWidth < Item.Settings.settingSweepCut.SweepYStep)
      {
        Item.ItemEntities.SourceEntities.Add(SweepEntity);
        if (!(SweepEntity is buLinearPath))
          return;
        List<Point3D> points = new List<Point3D>();
        for (int index = 0; index <= SweepEntity.Vertices.Count - 1; ++index)
          points.Add(new Point3D(SweepEntity.Vertices[index].X, SweepEntity.Vertices[index].Y, 0.0));
        if (!isFinished)
          return;
        Mesh mesh = new LinearPath((ICollection<Point3D>) points).Inflate(20.0, 20.0, Utility.DegToRad(30.0), 80.0);
        entSurface = (Entity) mesh;
        entSurface.EntityData = (object) new CustomData();
        Item.ItemEntities.SolidEntity = new List<Entity>();
        entSurface.ColorMethod = colorMethodType.byEntity;
        entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
        Item.ItemEntities.SolidEntity.Add(entSurface);
        Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(SweepEntity));
      }
      else
      {
        double upper = buNumeric5.RoundToUpper(Item.Settings.settingSweepCut.SweepWidth / Item.Settings.settingSweepCut.SweepYStep);
        double num1 = Item.Settings.settingSweepCut.SweepWidth / upper;
        for (double num2 = 0.0; num2 <= upper - 1.0; ++num2)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(SweepEntity, ref copiedEntity);
          copiedEntity.Translate(0.0, num2 * num1, 0.0);
          Item.ItemEntities.SourceEntities.Add(copiedEntity);
          if (copiedEntity is buLinearPath)
            Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity));
        }
        if (!isFinished)
          return;
        List<Point3D> copiedPoint1 = new List<Point3D>();
        List<Point3D> copiedPoint2 = new List<Point3D>();
        if (Item.ItemEntities.SourceEntities.Count < 2)
          return;
        buVector5.Copy(Item.ItemEntities.SourceEntities[0].Vertices, ref copiedPoint1);
        buVector5.Copy(Item.ItemEntities.SourceEntities[Item.ItemEntities.SourceEntities.Count - 1].Vertices, ref copiedPoint2);
        List<Point3D> point3DList = new List<Point3D>();
        devDept.Eyeshot.Entities.Surface[] surfaceArray = devDept.Eyeshot.Entities.Surface.Loft((IList<ICurve>) new List<ICurve>()
        {
          (ICurve) new LinearPath((ICollection<Point3D>) copiedPoint1),
          (ICurve) new LinearPath((ICollection<Point3D>) copiedPoint2)
        }, 2);
        if (surfaceArray.Length == 0)
          return;
        entSurface = (Entity) surfaceArray[0].ConvertToMesh(0.2);
        entSurface.EntityData = (object) new CustomData();
        Item.ItemEntities.SolidEntity = new List<Entity>();
        entSurface.ColorMethod = colorMethodType.byEntity;
        entSurface.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
        Item.ItemEntities.SolidEntity.Add(entSurface);
      }
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doSweepCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doSweepCamCalc);
    try
    {
      clsMW.Containment2DEntities.Clear();
      Item.Settings.settingMarbleCam.UseCZero = false;
      if (marbleCam.ToolType == MarbleToolType.Saw)
      {
        Item.Settings.settingMarbleCam.UseTangentLimit = true;
        Item.Settings.settingMarbleCam.AngleCMax = buMarbleCalc.varOperation.settingMarbleCam.AngleCMax;
        Item.Settings.settingMarbleCam.AngleCMin = buMarbleCalc.varOperation.settingMarbleCam.AngleCMin;
        Item.Settings.settingMarbleCam.OffsetAngleC = Item.Settings.settingSweepCut.SweepFollowOffset;
        Item.Settings.settingMarbleCam.DontCheckZValues = true;
        if (Item.ItemEntities.SourceEntities.Count > 0)
        {
          marbleCam.WireEntities = new List<List<buEntity>>();
          Item.ItemEntities.WireEntities = new List<List<buEntity>>();
          for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
          {
            List<buEntity> buEntityList = new List<buEntity>();
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(Item.ItemEntities.SourceEntities[index], ref copiedEntity);
            buEntityList.Add(copiedEntity);
            marbleCam.WireEntities.Add(buEntityList);
          }
        }
        clsInit.cMarble.CalculateMarbleWireFrameWithSaw(clsMarble.activeKinematic, marbleCam.ToolSelected, this.activeJob, 0, true, (TpPnt9D) null, ref Item, ref marbleCam);
        if (marbleCam.CamBase != null)
        {
          camTp camBase = marbleCam.CamBase;
          camBase.CamID = Item.ID;
          camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
          camBase.TypeCam = CamType.SawCut;
          camBase.AxisCount = 5;
          camBase.Explanation = $"{buLangTranslate.preDef.Contour} {buLangTranslate.preDef.Cutting}";
          camBase.Parameter = new camParameters5(marbleCam.setCam);
          marbleCam.isCamCalculated = true;
        }
      }
      else
      {
        marbleCam.WireType = CamWireFrameType.Profile3Axis;
        MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
        MWCalcoptions.NumberofAxis = 3;
        MWCalcoptions.CamWireframeType = marbleCam.WireType;
        MWCalcoptions.CamTriMeshType = marbleCam.MeshType;
        MWCalcoptions.Mode = CamMode.WireFrame;
        MWCalcoptions.DontApplyReset = true;
        MWCalcoptions.isBuWireframeCalculation = false;
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        MWCalcoptions.ShowLeadInOutPage = false;
        MWCalcoptions.DontShowDialogBox = true;
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Item.ItemEntities.SourceEntities[index], ref copiedEntity);
          clsMW.CamEntities.Add(copiedEntity);
        }
        if (clsMW.CamEntities.Count > 0)
        {
          clsMW.varbuCamWFProfile3AxisPars.Distances.Safe = Item.Settings.settingSweepCut.SafeDistance;
          ToolBase5 Tool = marbleCam.ToolType != MarbleToolType.Milling ? (marbleCam.ToolType != MarbleToolType.MillingHead ? new ToolBase5(marbleCam.ToolSelected) : new ToolBase5(buMarbleCalc.activeToolMillingHead)) : new ToolBase5(buMarbleCalc.activeToolMilling);
          marbleCam.CamBase = (camTp) null;
          this.doWireframeCamCalc(MWCalcoptions, ref marbleCam, Tool, ref marbleCam.CamBase);
          if (marbleCam.CamBase != null)
          {
            marbleCam.CamBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
            marbleCam.CamBase.TypeCam = CamType.MillingCut;
            marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
          }
          this.AnalyzeMillingCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
          marbleCam.isCamCalculated = true;
        }
      }
      this.doCamPointsOffsets(ref marbleCam);
      AppBool.SaveByTick = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

