  public void doCavityCut(
    List<buEntity> refEntities,
    bool isFinished,
    ref Entity entSurface,
    ref MarbleItem Item)
  {
    string str = nameof (doCavityCut);
    try
    {
      buEntity buEntity = new buEntity();
      Item.ItemEntities.SourceEntities = new List<buEntity>();
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      if (isFinished)
      {
        if (Item.ItemEntities.SolidEntity == null)
          Item.ItemEntities.SolidEntity = new List<Entity>();
        Item.ItemEntities.SolidEntity.Clear();
        for (int index = 0; index <= refEntities.Count - 1; ++index)
        {
          if (refEntities[index] is buLine)
          {
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(refEntities[index], ref copiedEntity);
            copiedEntity.Translate(0.0, 0.0, Item.Settings.settingCavity.CavityDepth);
            Item.ItemEntities.SourceEntities.Add(copiedEntity);
            Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity));
          }
          else if (refEntities[index] is buCompositeCurve)
          {
            Entity copiedEntity = (Entity) null;
            buEntity.Copy(refEntities[index], ref copiedEntity);
            copiedEntity.Translate(0.0, 0.0, Item.Settings.settingCavity.CavityDepth);
            Entity entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) copiedEntity).ExtrudeAsMesh(Item.Settings.MaterialParameter.MaterialThickness, 9.1, Mesh.natureType.RichSmooth);
            entity.EntityData = (object) new CustomData();
            entity.ColorMethod = colorMethodType.byEntity;
            entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemSweep.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemSweep.Color);
            Item.ItemEntities.SolidEntity.Add(entity);
          }
        }
      }
      else
      {
        for (int index = 0; index <= refEntities.Count - 1; ++index)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(refEntities[index], ref copiedEntity);
          Item.ItemEntities.SourceEntities.Add(copiedEntity);
          Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity));
        }
      }
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doCavityCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doCavityCamCalc);
    try
    {
      clsMW.Containment2DEntities.Clear();
      Item.Settings.settingMarbleCam.UseCZero = false;
      if (marbleCam.ToolType == MarbleToolType.Saw)
      {
        Item.Settings.settingMarbleCam.UseTangentLimit = true;
        Item.Settings.settingMarbleCam.AngleCMax = buMarbleCalc.varOperation.settingMarbleCam.AngleCMax;
        Item.Settings.settingMarbleCam.AngleCMin = buMarbleCalc.varOperation.settingMarbleCam.AngleCMin;
        Item.Settings.settingMarbleCam.OffsetAngleC = Item.Settings.settingSweepCut.SweepFollowOffset;
        Item.Settings.settingMarbleCam.DontCheckZValues = true;
        if (Item.ItemEntities.SourceEntities.Count > 0)
        {
          marbleCam.WireEntities = new List<List<buEntity>>();
          Item.ItemEntities.WireEntities = new List<List<buEntity>>();
          for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
          {
            List<buEntity> buEntityList = new List<buEntity>();
            buEntity copiedEntity = (buEntity) null;
            buEntity.Copy(Item.ItemEntities.SourceEntities[index], ref copiedEntity);
            buEntityList.Add(copiedEntity);
            marbleCam.WireEntities.Add(buEntityList);
          }
        }
        clsInit.cMarble.CalculateMarbleWireFrameWithSaw(clsMarble.activeKinematic, marbleCam.ToolSelected, this.activeJob, 0, true, (TpPnt9D) null, ref Item, ref marbleCam);
        if (marbleCam.CamBase != null)
        {
          camTp camBase = marbleCam.CamBase;
          camBase.CamID = Item.ID;
          camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
          camBase.TypeCam = CamType.SawCut;
          camBase.AxisCount = 5;
          camBase.Explanation = $"{buLangTranslate.preDef.Contour} {buLangTranslate.preDef.Cutting}";
          camBase.Parameter = new camParameters5(marbleCam.setCam);
          marbleCam.isCamCalculated = true;
        }
      }
      else
      {
        marbleCam.WireType = CamWireFrameType.Profile3Axis;
        MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
        MWCalcoptions.NumberofAxis = 3;
        MWCalcoptions.CamWireframeType = marbleCam.WireType;
        MWCalcoptions.CamTriMeshType = marbleCam.MeshType;
        MWCalcoptions.Mode = CamMode.WireFrame;
        MWCalcoptions.DontApplyReset = true;
        MWCalcoptions.isBuWireframeCalculation = false;
        MWCalcoptions.AddToCamListInLocalCalculation = false;
        MWCalcoptions.ShowLeadInOutPage = false;
        MWCalcoptions.DontShowDialogBox = true;
        clsMW.CamEntities.Clear();
        clsMW.CamEntities = new List<Entity>();
        for (int index = 0; index <= Item.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Item.ItemEntities.SourceEntities[index], ref copiedEntity);
          clsMW.CamEntities.Add(copiedEntity);
        }
        if (clsMW.CamEntities.Count > 0)
        {
          clsMW.varbuCamWFProfile3AxisPars.Distances.Safe = Item.Settings.settingSweepCut.SafeDistance;
          ToolBase5 Tool = marbleCam.ToolType != MarbleToolType.Milling ? (marbleCam.ToolType != MarbleToolType.MillingHead ? new ToolBase5(marbleCam.ToolSelected) : new ToolBase5(buMarbleCalc.activeToolMillingHead)) : new ToolBase5(buMarbleCalc.activeToolMilling);
          marbleCam.CamBase = (camTp) null;
          this.doWireframeCamCalc(MWCalcoptions, ref marbleCam, Tool, ref marbleCam.CamBase);
          marbleCam.CamBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
          marbleCam.CamBase.TypeCam = CamType.MillingCut;
          marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
        }
        this.AnalyzeMillingCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
        marbleCam.isCamCalculated = true;
      }
      this.doCamPointsOffsets(ref marbleCam);
      AppBool.SaveByTick = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemProfiling(Point3D refPoint, bool isFinsihed = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemProfiling);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForProfiling.Count == 0)
        return;
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.SourceEntities = new List<buEntity>();
      Entity entSurface = (Entity) null;
      MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      this.doProfileCut(this.entitiesForProfiling, ref entSurface, ref MI);
      MI.ItemType = MarbleItemType.Profiling;
      MI.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
      MI.BaseHeight = 0.0;
      if (isFinsihed)
      {
        this.doAddItemCommonProps(ref MI);
        MI.Settings.MaterialParameter.MaterialThickness = entSurface.BoxMax.Z;
        MI.BasePoint = buVector5.ToPoint3D(refPoint);
      }
      if (MI.ItemEntities.SolidEntity != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SolidEntity.Count - 1; ++index)
          MI.ItemEntities.SolidEntity[index].Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
      }
      if (MI.ItemEntities.SourceEntities != null)
      {
        for (int index = 0; index <= MI.ItemEntities.SourceEntities.Count - 1; ++index)
        {
          buEntity sourceEntity = MI.ItemEntities.SourceEntities[index];
          sourceEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
          sourceEntity.Marble = new MarbleInfo();
        }
      }
      if (MI.ItemEntities.DrawWireEntities != null)
      {
        for (int index = 0; index <= MI.ItemEntities.DrawWireEntities.Count - 1; ++index)
        {
          buEntity drawWireEntity = MI.ItemEntities.DrawWireEntities[index];
          drawWireEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
          drawWireEntity.Marble = new MarbleInfo();
        }
      }
      if (isFinsihed)
      {
        clsInit.cMarble.GetIDs(this.activeJob, ref MarbleTempVars.ItemID, ref MarbleTempVars.MarbleCamID);
        MI.ID = MarbleTempVars.ItemID;
        MI.ItemEntities.ExtensionEntities = new List<buEntity>();
        if (MI.ToolType == MarbleToolType.Milling | MI.ToolType == MarbleToolType.MillingHead)
        {
