        }
        if (buMarbleCalc.varOperation.settingProfileCut.RoughEnable)
        {
          MarbleItemCam marbleCam = new MarbleItemCam()
          {
            CamName = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}",
