            CamType = CamType.Rough
          };
          marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
          marbleCam.isRough = buMarbleCalc.varOperation.settingProfileCut.RoughEnable;
          clsInit.cMarble.ProfileSettingToCamSetting(MI.Settings.settingProfileCut, false, ref marbleCam.setCam);
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
          MI.CamList.Add(marbleCam);
          if (isCamCalc)
            this.doProfilingCamCalc(ref MI, ref marbleCam);
