      {
        List<Point3D> point3DList2 = new List<Point3D>();
        for (int index = 0; index <= RefEntities.Count - 1; ++index)
        {
          List<Point3D> Points = new List<Point3D>();
          clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[index], buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, ref Points);
          point3DList2.AddRange((IEnumerable<Point3D>) Points);
          buEntity buEntity = (buEntity) null;
          buEntity.Copy(RefEntities[index], ref buEntity);
          clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref buEntity);
          clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisZ, ref buEntity);
          Item.ItemEntities.SourceEntities.Add(buEntity);
        }
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref point3DList2);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.YZ, ref point3DList2);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.XY, ref point3DList2);
        if (!clsInit.cVector5.IsClosed(point3DList2))
          point3DList2.Add(buVector5.ToPoint3D(point3DList2[0]));
        if (buMarbleCalc.varOperation.settingProfileCut.TwistEnable)
        {
          List<ICurve> curveList = new List<ICurve>();
          int int32 = Convert.ToInt32(Math.Abs(buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle - buMarbleCalc.varOperation.settingProfileCut.TwistEndAngle) / buMarbleCalc.varOperation.settingProfileCut.TwisStepAngle);
          Convert.ToInt32(buMarbleCalc.varOperation.settingProfileCut.Length / (double) int32);
          List<double> Values1 = new List<double>();
          List<double> Values2 = new List<double>();
          buNumeric5.DevideMinMaxValueByNumber(buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle, buMarbleCalc.varOperation.settingProfileCut.TwistEndAngle, int32 + 1, ref Values1);
          buNumeric5.DevideMinMaxValueByNumber(0.0, buMarbleCalc.varOperation.settingProfileCut.Length, int32 + 1, ref Values2);
          double twistStartAngle = buMarbleCalc.varOperation.settingProfileCut.TwistStartAngle;
          int index1 = 0;
          Point3D MinPoint = new Point3D();
          Point3D MidPoint = new Point3D();
          Point3D MaxPoint = new Point3D();
          clsInit.cVector5.BoxSizeCalculate(point3DList2, ref MinPoint, ref MidPoint, ref MaxPoint);
          Entity copiedEntity1 = (Entity) null;
          Entity copiedEntity2 = (Entity) null;
          for (int index2 = 0; index2 <= Values2.Count - 1; ++index2)
          {
            List<Point3D> copiedPoint = new List<Point3D>();
            buVector5.Copy(point3DList2, ref copiedPoint);
            LinearPath linearPath = new LinearPath((ICollection<Point3D>) copiedPoint);
            if (index1 <= Values1.Count - 1)
              twistStartAngle = Values1[index1];
            if (buMarbleCalc.varOperation.settingProfileCut.TwistEnable)
              linearPath.Rotate(Utility.DegToRad(twistStartAngle), Vector3D.AxisX, MidPoint);
            linearPath.Translate(Values2[index2], 0.0);
            curveList.Add((ICurve) linearPath);
            ++index1;
          }
          if (curveList.Count > 0)
          {
            buEntity.Copy((Entity) curveList[0], ref copiedEntity1);
            buEntity.Copy((Entity) curveList[curveList.Count - 1], ref copiedEntity2);
          }
          devDept.Eyeshot.Entities.Surface[] surfaceArray = devDept.Eyeshot.Entities.Surface.Loft((IList<ICurve>) curveList);
          entSurface = (Entity) surfaceArray[0];
          entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
          Entity mesh1 = (Entity) ((devDept.Eyeshot.Entities.Surface) entSurface).ConvertToMesh();
          if (entSurface.BoxMin == (Point3D) null)
            entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
          if (copiedEntity1 != null)
          {
            devDept.Eyeshot.Entities.Region region1 = new devDept.Eyeshot.Entities.Region((ICurve) copiedEntity1);
            devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region((ICurve) copiedEntity2);
            Mesh mesh2 = region1.ConvertToMesh();
            Mesh mesh3 = region2.ConvertToMesh();
            ((Mesh) mesh1).MergeWith(mesh2);
            ((Mesh) mesh1).MergeWith(mesh3);
          }
          Item.ItemEntities.DrawWireEntities = new List<buEntity>();
          Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity1));
          Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(copiedEntity2));
          Item.ItemEntities.SolidEntity = new List<Entity>();
          mesh1.ColorMethod = colorMethodType.byEntity;
          mesh1.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
          Item.ItemEntities.SolidEntity.Add(mesh1);
        }
        else
        {
          clsInit.cVector5.RoundPoints(ref point3DList2);
          clsInit.cVector5.SurfaceExturudeByPoints(point3DList2, Vector3D.AxisX, buMarbleCalc.varOperation.settingProfileCut.Length, ref entSurface, true);
          entSurface.Rotate(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCut.RotationAngle), Vector3D.AxisZ, new Point3D());
          entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(entSurface, ref copiedEntity);
          Item.ItemEntities.SolidEntity = new List<Entity>();
          copiedEntity.ColorMethod = colorMethodType.byEntity;
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
          Item.ItemEntities.SolidEntity.Add(copiedEntity);
        }
      }
      else
        clsInit.appCommand.Reset(ReDraw: true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doProfileCurveCut(
    List<buEntity> RefEntities,
    ref Entity entSurface,
    ref MarbleItem Item)
  {
    string str = nameof (doProfileCurveCut);
    try
    {
      List<Point3D> point3DList = new List<Point3D>();
      ToolBase5 toolBase5 = new ToolBase5(buMarbleCalc.activeToolSaw);
      if (toolBase5.Geometry.GeometryType != buClass.ToolType.Saw)
        toolBase5.Geometry.Thickness = toolBase5.Geometry.Diameter;
      if (RefEntities.Count > 0)
      {
        List<Point3D> Points1 = new List<Point3D>();
        for (int index = 0; index <= RefEntities.Count - 1; ++index)
        {
          List<Point3D> Points2 = new List<Point3D>();
          clsInit.cVector5.EntitiesToPointsWithCamDirection(RefEntities[index], buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, ref Points2);
          Points1.AddRange((IEnumerable<Point3D>) Points2);
          buEntity buEntity = (buEntity) null;
          buEntity.Copy(RefEntities[index], ref buEntity);
          clsInit.cVector5.Rotate(new Point3D(), 90.0, Vector3D.AxisX, ref buEntity);
          Item.ItemEntities.SourceEntities.Add(buEntity);
        }
        clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points1);
        clsInit.cVector5.Rotate(new Point3D(), 90.0, Plane.YZ, ref Points1);
        if (!clsInit.cVector5.IsClosed(Points1))
          Points1.Add(buVector5.ToPoint3D(Points1[0]));
        List<ICurve> curveList = new List<ICurve>();
        int int32 = Convert.ToInt32(buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle / buMarbleCalc.varOperation.settingProfileCurveCut.CurveAngleStep);
        double num1 = buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle / (double) int32;
        List<double> Values = new List<double>();
        buNumeric5.DevideMinMaxValueByNumber(buMarbleCalc.varOperation.settingProfileCurveCut.TwistStartAngle, buMarbleCalc.varOperation.settingProfileCurveCut.TwistEndAngle, int32 + 1, ref Values);
        double twistStartAngle = buMarbleCalc.varOperation.settingProfileCurveCut.TwistStartAngle;
        int index1 = 0;
        Point3D MinPoint = new Point3D();
        Point3D MidPoint = new Point3D();
        Point3D MaxPoint = new Point3D();
        clsInit.cVector5.BoxSizeCalculate(Points1, ref MinPoint, ref MidPoint, ref MaxPoint);
        Entity copiedEntity1 = (Entity) null;
        Entity copiedEntity2 = (Entity) null;
        for (int index2 = 0; index2 <= int32; ++index2)
        {
          List<Point3D> copiedPoint = new List<Point3D>();
          buVector5.Copy(Points1, ref copiedPoint);
          LinearPath linearPath = new LinearPath((ICollection<Point3D>) copiedPoint);
          if (index1 <= Values.Count - 1)
            twistStartAngle = Values[index1];
          double degrees = buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + (double) index2 * num1;
          if (buMarbleCalc.varOperation.settingProfileCurveCut.TwistEnable)
            linearPath.Rotate(Utility.DegToRad(twistStartAngle), Vector3D.AxisY, MidPoint);
          linearPath.Translate(Item.Settings.settingProfileCurveCut.Radius, 0.0);
          linearPath.Rotate(Utility.DegToRad(degrees), Vector3D.AxisZ, new Point3D(0.0, 0.0, 0.0));
          curveList.Add((ICurve) linearPath);
          ++index1;
        }
        if (curveList.Count > 0)
        {
          buEntity.Copy((Entity) curveList[0], ref copiedEntity1);
          buEntity.Copy((Entity) curveList[curveList.Count - 1], ref copiedEntity2);
        }
        devDept.Eyeshot.Entities.Surface[] surfaceArray = devDept.Eyeshot.Entities.Surface.Loft((IList<ICurve>) curveList);
        entSurface = (Entity) surfaceArray[0];
        entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
        Entity mesh1 = (Entity) ((devDept.Eyeshot.Entities.Surface) entSurface).ConvertToMesh();
        if (entSurface.BoxMin == (Point3D) null)
          entSurface.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
        if (copiedEntity1 != null)
        {
          devDept.Eyeshot.Entities.Region region1 = new devDept.Eyeshot.Entities.Region((ICurve) copiedEntity1);
          devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region((ICurve) copiedEntity2);
          Mesh mesh2 = region1.ConvertToMesh();
          Mesh mesh3 = region2.ConvertToMesh();
          ((Mesh) mesh1).MergeWith(mesh2);
          ((Mesh) mesh1).MergeWith(mesh3);
        }
        double num2 = buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Cos(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle));
        double x = buMarbleCalc.varOperation.settingProfileCurveCut.Radius - buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Cos(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle + buMarbleCalc.varOperation.settingProfileCurveCut.SweepAngle));
        double y = buMarbleCalc.varOperation.settingProfileCurveCut.Radius - buMarbleCalc.varOperation.settingProfileCurveCut.Radius * Math.Sin(buConversion5.DegreeToRadian(buMarbleCalc.varOperation.settingProfileCurveCut.StartAngle));
        Item.CalcMovePoint = new Point3D(x, y, -entSurface.BoxMin.Z);
        mesh1.Translate(-entSurface.BoxMin.X, -entSurface.BoxMin.Y, -entSurface.BoxMin.Z);
        Item.ItemEntities.SolidEntity = new List<Entity>();
        mesh1.ColorMethod = colorMethodType.byEntity;
        mesh1.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemProfile.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemProfile.Color);
        Item.ItemEntities.SolidEntity.Add(mesh1);
      }
      else
        clsInit.appCommand.Reset(ReDraw: true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

