    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    if (ShowDialog)
    {
      if (buMarbleForms.frmProfileCurveCam == null)
        buMarbleForms.frmProfileCurveCam = new F_MarbleProfileCurveCam();
      buMarbleForms.frmProfileCurveCam.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmProfileCurveCam.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmProfileCurveCam.varProfileCurveCut = new marbleProfileCurveCutPars(buMarbleCalc.varOperation.settingProfileCurveCut);
      switch (CamType)
      {
        case MarbleCamType.ProfileCurveRough:
          buMarbleForms.frmProfileCurveCam.Init(1);
          break;
        case MarbleCamType.ProfileCurveFinish:
          buMarbleForms.frmProfileCurveCam.Init(0);
          break;
        case MarbleCamType.ProfileOffset:
          buMarbleForms.frmProfileCurveCam.Init(2);
          break;
      }
      int num = (int) buMarbleForms.frmProfileCurveCam.ShowDialog();
      if (buMarbleForms.frmProfileCurveCam.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingProfileCurveCut = new marbleProfileCurveCutPars(buMarbleForms.frmProfileCurveCam.varProfileCurveCut);
      Item.Settings.settingProfileCurveCut = new marbleProfileCurveCutPars(buMarbleCalc.varOperation.settingProfileCurveCut);
    }
    if (marbleCam == null | !Edit)
      marbleCam = new MarbleItemCam();
    marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
    if (CamType == MarbleCamType.ProfileCurveRough)
    {
      marbleCam.CamName = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Curve} {buLangTranslate.preDef.Rough} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
      clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, false, ref marbleCam.setCam);
    }
    if (CamType == MarbleCamType.ProfileCurveFinish)
    {
      marbleCam.CamName = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Curve} {buLangTranslate.preDef.Finish} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Finish;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileFinish.buPar);
      clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, false, ref marbleCam.setCam);
    }
    if (CamType == MarbleCamType.ProfileOffset)
    {
      marbleCam.CamName = $"{buLangTranslate.preDef.Profile} {buLangTranslate.preDef.Curve} {buLangTranslate.preDef.Offset} {buLangTranslate.preDef.Cut}";
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamMode = MarbleCamMode.Finish;
      marbleCam.CamType = CamType.Finish;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileFinish.buPar);
      clsInit.cMarble.ProfileCurveSettingToCamSetting(Item.Settings.settingProfileCurveCut, false, ref marbleCam.setCam);
    }
    clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
    int num1 = this.doProfileCurveCamCalc(ref Item, ref marbleCam);
    if (!Edit & num1 > 0)
      Item.CamList.Add(marbleCam);
    this.AddOperationAfterThings();
  }

