  public int doProfilingCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doProfilingCamCalc);
    try
    {
      marbleCam.CamBase = new camTp();
      clsMW.Containment2DEntities.Clear();
      if (marbleCam.ToolType == MarbleToolType.Saw)
      {
        if (marbleCam.CamMarbleType == MarbleCamType.ProfileRough)
        {
          marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleProfileRough.buPar);
          List<Point3D> devidedPoints = new List<Point3D>();
          List<Point3D> refPoints = new List<Point3D>();
          List<Point3D> point3DList1 = new List<Point3D>();
          List<Pnt6DS> OrjPL6 = new List<Pnt6DS>();
          List<buEntity> copiedEntities = new List<buEntity>();
          CurveToSurfaceSettingsType Settings = new CurveToSurfaceSettingsType(Item.Settings.settingProfileCut.RoughSurfOffset, Item.Settings.settingProfileCut.RoughStepover, 0.0, true);
          Settings.MaxDistance = 3.0;
          Settings.isVertical = Item.Settings.settingProfileCut.VerticalCut;
          buEntity.Copy(Item.ItemEntities.SourceEntities, ref copiedEntities);
          Settings.MaxZ = Item.SizeItem.MaxPoint.Z + 0.1 - Item.Settings.settingProfileCut.RoughTopOffset;
          Settings.MinZ = Item.SizeItem.MinPoint.Z - 0.1 + Item.Settings.settingProfileCut.RoughBottomOffset;
          Settings.InsideOffset = Item.Settings.settingProfileCut.RoughInsideOffset;
          Settings.OutsideOffset = Item.Settings.settingProfileCut.RoughOutsideOffset;
          this.doCurveToSurfaceGetPoints(copiedEntities, buMarbleCalc.activeToolSaw, Settings, ref refPoints);
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref refPoints);
          devidedPoints.Clear();
