            double c = clsInit.cVector5.PointAngle(point3D2, point3D1);
            refPoints2.Add(new Pnt6D(point3D1.X, point3D1.Y, point3D1.Z, 0.0, 0.0, c));
            refPoints2.Add(new Pnt6D(point3D2.X, point3D2.Y, point3D2.Z, 0.0, 0.0, c));
            List<Pnt6D> calcPoints = new List<Pnt6D>();
            clsInit.cMarble.CalculatePointsWithKinematic(refPoints2, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoints);
            camTpPoint camTpPoint = new camTpPoint();
            if (calcPoints.Count > 0)
            {
              TpPnt9D tpPnt9D1 = new TpPnt9D(calcPoints[0], 100.0, 0);
              tpPnt9D1.P9.Z = tpPnt9D1.P9.Z + Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCut.RoughRapid;
              camTpPoint.Points.Add(tpPnt9D1);
              TpPnt9D tpPnt9D2 = new TpPnt9D(calcPoints[0], Item.Settings.settingProfileCut.RoughPlungeFeed, 1);
              camTpPoint.Points.Add(tpPnt9D2);
              for (int index4 = 1; index4 <= calcPoints.Count - 1; ++index4)
              {
                double roughCutForwardFeed = Item.Settings.settingProfileCut.RoughCutForwardFeed;
                TpPnt9D tpPnt9D3 = new TpPnt9D(calcPoints[index4], roughCutForwardFeed, 1);
                camTpPoint.Points.Add(tpPnt9D3);
              }
              TpPnt9D tpPnt9D4 = new TpPnt9D(calcPoints[calcPoints.Count - 1], 100.0, 0);
              tpPnt9D4.P9.Z = tpPnt9D4.P9.Z + Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCut.RoughRapid;
              camTpPoint.Points.Add(tpPnt9D4);
              camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
              marbleCam.CamBase.CamPoints.Add(camTpPoint);
              Line line = new Line(point3D1, point3D2);
              marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
              marbleCam.CamBase.EntitiesG1.Add((Entity) line);
            }
          }
          marbleCam.CamBase.Obj1 = (object) marbleCam;
          marbleCam.CamBase.Obj2 = (object) Item;
          marbleCam.CamBase.Name = marbleCam.CamName;
        }
        if (marbleCam.CamMarbleType == MarbleCamType.ProfileCurveEndCut)
        {
          List<Point3D> point3DList = new List<Point3D>();
          List<Point3D> refPoints3 = new List<Point3D>();
          List<buEntity> copiedEntities = new List<buEntity>();
          CurveToSurfaceSettingsType Settings = new CurveToSurfaceSettingsType(Item.Settings.settingProfileCurveCut.RoughSurfOffset, Item.Settings.settingProfileCurveCut.RoughStepover, 0.0, true);
          buEntity.Copy(Item.ItemEntities.SourceEntities, ref copiedEntities);
          this.doCurveToSurfaceGetPoints(copiedEntities, buMarbleCalc.activeToolSaw, Settings, ref refPoints3);
          clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref refPoints3);
          if (refPoints3[0].Z < 0.1)
            refPoints3.RemoveAt(0);
          clsInit.cMarble.DevideProfileCutPoints(refPoints3, Item.Settings.settingProfileCurveCut.RoughMinZ, Item.Settings.settingProfileCurveCut.RoughStepover, Item.Settings.settingProfileCurveCut.RoughVerticalDevideLen, true, false, ref point3DList);
          clsInit.cVector5.Rotate(Item.BasePoint, Item.Settings.settingProfileCurveCut.StartAngle + Item.Settings.settingProfileCurveCut.SweepAngle, Plane.XY, ref point3DList);
          camStep5 Steps = new camStep5();
          Steps.StepType = CamStepType.StartToEndByStep;
          Steps.StartValue = Item.SizeItem.MaxPoint.Z;
          Steps.EndValue = Item.SizeItem.MinPoint.Z;
          Steps.Step = Item.Settings.settingProfileCut.CutProfileDepthStep;
          Steps.Enable = true;
          List<double> CalcValues = new List<double>();
          clsInit.cCam5.CamStepCalculation(Steps, ref CalcValues);
          for (int index5 = 0; index5 <= CalcValues.Count - 1; ++index5)
          {
            Point3D point3D3 = new Point3D(point3DList[0].X, point3DList[0].Y, CalcValues[index5]);
            Point3D point3D4 = new Point3D(point3DList[point3DList.Count - 1].X, point3DList[point3DList.Count - 1].Y, CalcValues[index5]);
            List<Pnt6D> refPoints4 = new List<Pnt6D>();
            double c = clsInit.cVector5.PointAngle(point3D3, point3D4);
            refPoints4.Add(new Pnt6D(point3D4.X, point3D4.Y, point3D4.Z, 0.0, 0.0, c));
            refPoints4.Add(new Pnt6D(point3D3.X, point3D3.Y, point3D3.Z, 0.0, 0.0, c));
            List<Pnt6D> calcPoints = new List<Pnt6D>();
            clsInit.cMarble.CalculatePointsWithKinematic(refPoints4, clsMarble.activeKinematic, marbleCam.ToolSelected, ref calcPoints);
            camTpPoint camTpPoint = new camTpPoint();
            if (calcPoints.Count > 0)
            {
              TpPnt9D tpPnt9D5 = new TpPnt9D(calcPoints[0], 100.0, 0);
              tpPnt9D5.P9.Z = tpPnt9D5.P9.Z + Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCut.RoughRapid;
              camTpPoint.Points.Add(tpPnt9D5);
              TpPnt9D tpPnt9D6 = new TpPnt9D(calcPoints[0], Item.Settings.settingProfileCut.RoughPlungeFeed, 1);
              camTpPoint.Points.Add(tpPnt9D6);
              for (int index6 = 1; index6 <= calcPoints.Count - 1; ++index6)
              {
                double roughCutForwardFeed = Item.Settings.settingProfileCut.RoughCutForwardFeed;
                TpPnt9D tpPnt9D7 = new TpPnt9D(calcPoints[index6], roughCutForwardFeed, 1);
                camTpPoint.Points.Add(tpPnt9D7);
              }
              TpPnt9D tpPnt9D8 = new TpPnt9D(calcPoints[calcPoints.Count - 1], 100.0, 0);
              tpPnt9D8.P9.Z = tpPnt9D8.P9.Z + Item.SizeItem.MaxPoint.Z + Item.Settings.settingProfileCut.RoughRapid;
              camTpPoint.Points.Add(tpPnt9D8);
              camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolSaw);
              marbleCam.CamBase.CamPoints.Add(camTpPoint);
              Line line = new Line(point3D4, point3D3);
              marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
              marbleCam.CamBase.EntitiesG1.Add((Entity) line);
            }
          }
          marbleCam.CamBase.Obj1 = (object) marbleCam;
          marbleCam.CamBase.Obj2 = (object) Item;
          marbleCam.CamBase.Name = marbleCam.CamName;
        }
      }
      else
      {
        if (marbleCam.CamMode == MarbleCamMode.Rough)
        {
          marbleCam.MeshType = CamTriangularMeshType.Rough;
          this.doEngraveCamCalc(new MWCalculationOptions()
          {
            NumberofAxis = 3,
            CamTriMeshType = marbleCam.MeshType,
            Mode = CamMode.TriangularMesh,
            DontApplyReset = true,
            isBuWireframeCalculation = false,
            AddToCamListInLocalCalculation = false,
            ShowLeadInOutPage = false,
            DontShowDialogBox = true,
            DontShowbuDialogBox = true
          }, Item, ref marbleCam);
          marbleCam.isCamCalculated = true;
        }
        if (marbleCam.CamMode == MarbleCamMode.Finish)
        {
          marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
          this.doEngraveCamCalc(new MWCalculationOptions()
          {
            NumberofAxis = 3,
            CamTriMeshType = marbleCam.MeshType,
            Mode = CamMode.TriangularMesh,
            DontApplyReset = true,
            isBuWireframeCalculation = false,
            AddToCamListInLocalCalculation = false,
            ShowLeadInOutPage = false,
            DontShowDialogBox = true,
            DontShowbuDialogBox = true
          }, Item, ref marbleCam);
          marbleCam.isCamCalculated = true;
        }
      }
      this.doCamPointsOffsets(ref marbleCam);
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

  public void doDrillPocketCamAdd(
    ref MarbleItem Item,
    MarbleToolType CuttingToolType,
    MarbleCamType CamType,
    bool ShowDialog,
    bool Edit,
    ref MarbleItemCam marbleCam)
  {
    if (ShowDialog)
      ;
    if (ShowDialog)
    {
      if (buMarbleForms.frmDrillPocket == null)
        buMarbleForms.frmDrillPocket = new F_MarbleDrillPocketCam();
      buMarbleForms.frmDrillPocket.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmDrillPocket.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmDrillPocket.varDrill = new marbleDrillPars(buMarbleCalc.varOperation.settingDrillCut);
      buMarbleForms.frmDrillPocket.Init(0);
      int num = (int) buMarbleForms.frmDrillPocket.ShowDialog();
      if (buMarbleForms.frmDrillPocket.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingDrillCut = new marbleDrillPars(buMarbleForms.frmDrillPocket.varDrill);
    }
    AppBool.SaveByTick = true;
    if (marbleCam == null | !Edit)
      marbleCam = new MarbleItemCam();
    if (Item.ItemEntities.EngravingEntities == null)
      Item.ItemEntities.EngravingEntities = new List<buEntity>();
    Item.ItemEntities.EngravingEntities.Clear();
    Item.Settings.settingDrillCut = new marbleDrillPars(buMarbleCalc.varOperation.settingDrillCut);
    buEntity.Copy(Item.ItemEntities.SolidEntity, ref Item.ItemEntities.EngravingEntities);
    marbleCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
    marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
    marbleCam.MeshType = CamTriangularMeshType.ParallelCuts;
    if (CamType == MarbleCamType.PocketByDrilling)
    {
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleHole.buPar);
      marbleCam.CamMarbleType = CamType;
      marbleCam.CamName = $"{buLangTranslate.preDef.Pocket} {buLangTranslate.preDef.Drill}";
      marbleCam.CamType = CamType.Rough;
      marbleCam.CamMode = MarbleCamMode.Rough;
    }
    marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
    if (Item.ItemEntities.SolidInsideEntity == null)
      Item.ItemEntities.SolidInsideEntity = new List<Entity>();
    Item.ItemEntities.SolidInsideEntity.Clear();
    if (Item.ItemEntities.DrawWireEntities == null)
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
    Item.ItemEntities.DrawWireEntities.Clear();
    if (marbleCam.SolidEntities == null)
      marbleCam.SolidEntities = new List<Entity>();
    marbleCam.SolidEntities.Clear();
    clsInit.appMarble.doDrillPocketCamCalc(ref Item, ref marbleCam);
    marbleCam.isCamCalculated = true;
    clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
    Item.CamList.Add(marbleCam);
    this.AddOperationAfterThings();
  }

  public int doDrillPocketCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doDrillPocketCamCalc);
    try
    {
      if (Item.ItemEntities.EngravingEntities == null || Item.ItemEntities.EngravingEntities.Count == 0)
        return -2;
      bool flag1 = false;
      bool flag2 = false;
      clsMW.Containment2DEntities.Clear();
      camTp camTp = new camTp();
      clsMW.CamEntities.Clear();
      clsMW.CamEntities = new List<Entity>();
      Point3D MinPoint1 = new Point3D();
      Point3D MaxPoint1 = new Point3D();
      Point3D point3D1 = new Point3D();
      Point3D point3D2 = new Point3D();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.EngravingEntities, ref MinPoint1, ref MaxPoint1);
      double num1 = MaxPoint1.Z - MinPoint1.Z - Item.Settings.settingDrillCut.HoleTopOffset - Item.Settings.settingDrillCut.HoleBottomOffset;
      int upper = (int) buNumeric5.RoundToUpper(num1 / Item.Settings.settingDrillCut.HoleZDepthStep);
      double num2 = num1 / (double) upper;
      camResult camResult = (camResult) null;
      marbleCam.CamBase = new camTp();
      marbleCam.WireEntities = new List<List<buEntity>>();
      marbleCam.WireEntities.Clear();
      marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      Item.ItemEntities.DrawWireEntities = new List<buEntity>();
      for (int index1 = 1; index1 <= upper; ++index1)
      {
        Entity[][] OffsetSectionsByLayer = (Entity[][]) null;
        clsInit.cVector5.GetMeshZContours(Item.ItemEntities.SolidEntity, Item.SizeItem.MaxPoint.Z - num2 * (double) index1, true, Item.Settings.settingDrillCut.HoleContourOffset, ref OffsetSectionsByLayer);
        List<Entity> refEntities1 = new List<Entity>();
        List<Entity> refEntities2 = new List<Entity>();
        List<Entity> refEntities3 = new List<Entity>();
        List<Point3D> RefPoints = new List<Point3D>();
        if ((OffsetSectionsByLayer == null ? 0 : (OffsetSectionsByLayer.Length != 0 ? 1 : 0)) != 0 && OffsetSectionsByLayer[0].Length != 0)
        {
          RefPoints.AddRange((IEnumerable<Point3D>) ((IEnumerable<Point3D>) OffsetSectionsByLayer[0][OffsetSectionsByLayer[0].Length - 1].Vertices).ToList<Point3D>());
          refEntities1.Add(OffsetSectionsByLayer[0][OffsetSectionsByLayer[0].Length - 1]);
        }
        if (RefPoints.Count > 0)
        {
          List<Point3D> OffsetedPoints = new List<Point3D>();
          clsInit.cVector5.OffsetContour(RefPoints, -20.0, OffsetCornerType.Line, CamOpenContourType.Center, Plane.XY, 0.0, ref OffsetedPoints);
          for (int index2 = 0; index2 <= refEntities1.Count - 1; ++index2)
            Item.ItemEntities.DrawWireEntities.Add(buEntity.Copy(refEntities1[index2]));
          Point3D MinPoint2 = new Point3D();
          Point3D MaxPoint2 = new Point3D();
          clsInit.cVector5.BoxSizeCalculate(refEntities1, ref MinPoint2, ref MaxPoint2);
          if (OffsetedPoints.Count > 0)
          {
            List<buEntity> calcLines = new List<buEntity>();
            clsInit.cVector5.HatchLinear(OffsetedPoints, Item.SizeItem.MaxPoint.Z - num2 * (double) index1, Item.Settings.settingDrillCut.HoleScanYStep, HorizontalVertical.Horizontal, Plane.XY, ref calcLines);
            if (marbleCam.DrillEntities == null)
              marbleCam.DrillEntities = new List<buEntity>();
            marbleCam.DrillEntities.Clear();
            for (int index3 = 0; index3 <= calcLines.Count - 1; ++index3)
            {
              List<Point3D> pntDevided = new List<Point3D>();
              clsInit.cVector5.EntityDevide(calcLines[index3], Item.Settings.settingDrillCut.HoleScanXStep, ref pntDevided);
              for (int index4 = 1; index4 <= pntDevided.Count - 2; ++index4)
              {
                Circle refEntity = new Circle(pntDevided[index4], marbleCam.ToolSelected.Geometry.Diameter);
                marbleCam.DrillEntities.Add(buEntity.Copy((Entity) refEntity));
              }
            }
            this.doDrillCamCalc(marbleCam.DrillEntities, Item, ref marbleCam);
            if (marbleCam.CamBase != null)
              marbleCam.CamBase.TypeCam = CamType.CornerCleanByDrill;
            for (int index5 = 0; index5 <= marbleCam.DrillEntities.Count - 1; ++index5)
            {
              Entity copiedEntity1 = (Entity) null;
              buEntity.Copy(marbleCam.DrillEntities[index5], ref copiedEntity1);
              ICurve[] curveArray = ((ICurve) copiedEntity1).Offset(-4.0, Vector3D.AxisZ);
              if ((curveArray == null ? 0 : (curveArray.Length != 0 ? 1 : 0)) != 0)
              {
                devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((IList<ICurve>) new List<ICurve>()
                {
                  (ICurve) copiedEntity1
                }, Plane.XY, true);
                region.Regen(0.1);
                if ((region.Vertices == null ? 0 : (!buCompare5.EQ(region.Vertices[0].Z, region.BoxMin.Z) ? 1 : 0)) != 0)
                {
                  double dz = marbleCam.DrillEntities[index5].Vertices[0].Z - region.Vertices[0].Z;
                  region.Translate(0.0, 0.0, dz);
                }
                Mesh mesh = region.ExtrudeAsMesh(100.0, 0.05, Mesh.natureType.RichSmooth);
                mesh.Selectable = false;
                mesh.Color = buMarbleCalc.varMarbleColorSettings.colorItemHole.Color;
                mesh.EntityData = (object) new CustomData()
                {
                  typeDefination = entityTypeDefination.MarbleItem
                };
                marbleCam.SolidEntities.Add((Entity) mesh);
              }
              else
              {
                buEntity copiedEntity2 = (buEntity) null;
                buEntity.Copy(marbleCam.DrillEntities[index5], ref copiedEntity2);
              }
            }
          }
          List<Entity> LineEntities1 = new List<Entity>();
          List<Entity> LineEntities2 = new List<Entity>();
          clsInit.cVector5.LineaPathToLine(refEntities2, Item.Settings.settingDrillCut.HoleScanXStep * 0.9, HorizontalVertical.Horizontal, ref LineEntities1);
          clsInit.cVector5.LineaPathToLine(refEntities3, Item.Settings.settingDrillCut.HoleScanYStep * 0.9, HorizontalVertical.Vertical, ref LineEntities2);
          List<List<Point3D>> point3DListList = new List<List<Point3D>>();
          List<Entity> entityList = new List<Entity>();
        }
      }
      if ((camResult == null ? 0 : (camResult.Errors.Count > 0 ? 1 : 0)) != 0)
      {
        F_ErrorList fErrorList = new F_ErrorList();
        fErrorList.Init(camResult.Errors);
        int num3 = (int) fErrorList.ShowDialog();
        clsInit.appCommand.Reset();
        return -2;
      }
      if (flag1)
      {
        if (flag2)
          buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingHorizontalRough.buPar);
      }
      else if (flag2)
        buMWMarbleVars.varCamMarbleSawMillingVerticalRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamMeshContantZPars, clsMW.varbuCamMeshConstantZPars, out buMWMarbleVars.varCamMarbleSawMillingVerticalRough.buPar);
      if (marbleCam.CamBase.CamPoints.Count > 0)
      {
        this.AnalyzeSawCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
        marbleCam.isCamCalculated = true;
      }
      Item.ToolType = MarbleToolType.Saw;
      AppBool.SaveByTick = true;
      return 1;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
      return -1;
    }
  }

  public void doAddItemDrill(Point3D refPoint, bool isFinished = false, bool isCamCalc = false)
  {
    string str = nameof (doAddItemDrill);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      if (this.entitiesForDrill.Count == 0)
        return;
      List<MarbleItem> Items = new List<MarbleItem>();
      this.doDrillCut(refPoint, this.entitiesForDrill, isFinished, ref Items);
      for (int index = 0; index <= Items.Count - 1; ++index)
      {
        MarbleItem MI = Items[index];
        MI.ItemType = MarbleItemType.Drill;
        MI.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool != MarbleToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
        if (isFinished)
          this.doAddItemCommonProps(ref MI);
        if (isFinished)
        {
          MarbleItemCam marbleCam = new MarbleItemCam()
          {
            CamName = $"{buLangTranslate.preDef.Drill} {buLangTranslate.preDef.Cut}",
            CamMarbleType = MarbleCamType.MillingDrill2D,
            CamMode = MarbleCamMode.Drill,
            setCam = new camParameters5(buMWMarbleVars.varCamMarbleDrill.buPar),
            ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
            WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
            MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
            CamType = CamType.Drill,
            isFinish = true
          };
          marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
          if (isCamCalc)
            this.doDrillCamCalc(ref MI, ref marbleCam);
          marbleCam.isCamCalculated = isCamCalc;
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
          MI.CamList.Add(marbleCam);
          if (MI.ItemEntities.SolidEntity != null)
          {
            clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.SolidEntity, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
            ObjectSize3D.CalculateSize(ref MI.SizeItem);
          }
          this.AddOperationBeforeThings();
          this.doAddItemToJob(MI, false, false);
        }
        else
          MarbleTempVars.ItemsDrill.Add(MI);
      }
      if (!isFinished)
        return;
      ++MarbleTempVars.ItemID;
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doDrillCut(
    Point3D refPoint,
    List<buEntity> refEntities,
    bool isFinished,
    ref List<MarbleItem> Items)
  {
    string str = nameof (doDrillCut);
    try
    {
      Items.Clear();
      for (int index = 0; index <= refEntities.Count - 1; ++index)
      {
        MarbleItem marbleItem = new MarbleItem();
        marbleItem.ItemType = MarbleItemType.Drill;
        marbleItem.ItemEntities.SourceEntities = new List<buEntity>();
        marbleItem.ItemEntities.DrawWireEntities = new List<buEntity>();
        marbleItem.ItemEntities.DrillEntities = new List<buEntity>();
        double amount = marbleItem.Settings.MaterialParameter.MaterialThickness;
        if (refEntities[index].Marble != null && refEntities[index].Marble.Depth > 0.0)
          amount = refEntities[index].Marble.Depth;
        Point3D Pnt = new Point3D();
        Entity outer = (Entity) null;
        double radius = buMarbleCalc.varOperation.settingDrillCut.HoleDiameter / 2.0;
        if (refEntities[index] is buCircle)
        {
          radius = ((buCircle) refEntities[index]).Radius;
          Pnt = new Point3D(((buCircle) refEntities[index]).Center.X + refPoint.X, ((buCircle) refEntities[index]).Center.Y + refPoint.Y, marbleItem.Settings.MaterialParameter.MaterialThickness - amount);
          outer = (Entity) new Circle(Plane.XY, new Point3D(Pnt.X, Pnt.Y), ((buCircle) refEntities[index]).Radius);
          marbleItem.BasePoint = buVector5.ToPoint3D(Pnt);
        }
        if (outer != null)
        {
          outer.Regen(buMarbleCalc.varMarbleEntitiesSettings.SolidDeviationResolution);
          devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((ICurve) outer);
          region.Regen(buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution);
          marbleItem.ItemEntities.SolidEntity = new List<Entity>();
          Entity entity = (Entity) region.ExtrudeAsMesh(amount, buMarbleCalc.varMarbleEntitiesSettings.ProfileDeviationResolution, Mesh.natureType.RichSmooth);
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemHole.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemHole.Color);
          marbleItem.ItemEntities.DrillEntities.Add((buEntity) new buCircle(new Point3D(Pnt.X, Pnt.Y, 0.0), radius));
          if (isFinished)
          {
            marbleItem.ItemEntities.SolidEntity.Add(entity);
            marbleItem.ItemEntities.DrawWireEntities.Add((buEntity) new buCircle(new Point3D(Pnt.X, Pnt.Y, buMarbleCalc.varOperation.MaterialParameter.MaterialThickness), radius));
            marbleItem.ItemEntities.SourceEntities.Add((buEntity) new buCircle(new Point3D(Pnt.X, Pnt.Y, 0.0), radius));
          }
          Items.Add(marbleItem);
        }
      }
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doDrillCamCalc(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doDrillCamCalc);
    marbleCam.CamBase = new camTp();
    camTp data = new camTp();
    try
    {
      double num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
      double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
      double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillVelocity;
      if (marbleCam.ToolType == MarbleToolType.Milling)
      {
        num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
        num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
        feed = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillVelocity;
      }
      if (num2 < buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2)
        num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2;
      if (num1 < num2)
        num1 = num2 + 5.0;
      if (buMarbleCalc.varOperation.settingMarbleCam.DefaultDrillTool == MarbleMillingToolType.MillingHead & marbleCam.ToolType == MarbleToolType.MillingHead)
      {
        List<Pnt6D> pnt6DList = new List<Pnt6D>();
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1, 0.0, 0.0, 0.0));
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z, 0.0, 0.0, 0.0));
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1, 0.0, 0.0, 0.0));
        List<Point3D> points = new List<Point3D>();
        points.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1));
        points.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill));
        camTpPoint camTpPoint = new camTpPoint();
        for (int index = 0; index <= pnt6DList.Count - 1; ++index)
        {
          pnt6DList[index].A = 90.0;
          int type = 0;
          if (index == 1)
            type = 1;
          TpPnt9D tpPnt9D = new TpPnt9D(pnt6DList[index], feed, type);
          camTpPoint.Points.Add(tpPnt9D);
        }
        camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
        data.Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        data.EntitiesG1.Add((Entity) linearPath);
        data.CamPoints.Add(camTpPoint);
        marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        marbleCam.ToolType = MarbleToolType.MillingHead;
      }
      else if (buMarbleCalc.varOperation.settingMarbleCam.DefaultDrillTool == MarbleMillingToolType.Milling & marbleCam.ToolType == MarbleToolType.Milling)
      {
        List<Pnt6D> pnt6DList = new List<Pnt6D>();
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1, 0.0, 0.0, 0.0));
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z, 0.0, 0.0, 0.0));
        pnt6DList.Add(new Pnt6D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1, 0.0, 0.0, 0.0));
        List<Point3D> points = new List<Point3D>();
        points.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, Item.BasePoint.Z + num1));
        points.Add(new Point3D(Item.BasePoint.X, Item.BasePoint.Y, buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill));
        camTpPoint camTpPoint = new camTpPoint();
        for (int index = 0; index <= pnt6DList.Count - 1; ++index)
        {
          int type = 0;
          if (index == 1)
            type = 1;
          TpPnt9D tpPnt9D = new TpPnt9D(pnt6DList[index], feed, type);
          camTpPoint.Points.Add(tpPnt9D);
        }
        camTpPoint.ToolCam = new ToolBase5(buMarbleCalc.activeToolMilling);
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) points);
        data.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
        data.EntitiesG1.Add((Entity) linearPath);
        data.CamPoints.Add(camTpPoint);
        marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
        marbleCam.ToolType = MarbleToolType.Milling;
      }
      data.TypeCam = CamType.Drill;
      marbleCam.CamBase = new camTp(data);
      marbleCam.isCamCalculated = true;
      this.AnalyzeMillingCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doDrillCamCalc(
    List<buEntity> DrillEntities,
    MarbleItem Item,
    ref MarbleItemCam marbleCam)
  {
    string str = nameof (doDrillCamCalc);
    marbleCam.CamBase = new camTp();
    camTp data = new camTp();
    try
    {
      double num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
      double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
      double feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillVelocity;
      double drillLeaveVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadDrillLeaveVelocity;
      if (marbleCam.ToolType == MarbleToolType.Milling)
      {
        num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
        num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
        feed = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillVelocity;
        drillLeaveVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingDrillLeaveVelocity;
      }
      if (num2 < buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2)
        num2 = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + num2;
      if (num1 < num2)
        num1 = num2 + 5.0;
      List<Point3D> point3DList = new List<Point3D>();
      for (int index1 = 0; index1 <= DrillEntities.Count - 1; ++index1)
      {
        if (DrillEntities[index1] is buCircle)
        {
          if (point3DList.Count == 0)
          {
            point3DList.Add(new Point3D(((buCircle) DrillEntities[index1]).Center.X, ((buCircle) DrillEntities[index1]).Center.Y, ((buCircle) DrillEntities[index1]).Center.Z));
          }
          else
          {
            Point3D point3D = new Point3D(((buCircle) DrillEntities[index1]).Center.X, ((buCircle) DrillEntities[index1]).Center.Y, ((buCircle) DrillEntities[index1]).Center.Z);
            bool flag = false;
            for (int index2 = 0; index2 <= point3DList.Count - 1; ++index2)
            {
              if (buCompare5.EQ(point3DList[index2], point3D, 0.01))
                flag = true;
            }
            if (!flag)
              point3DList.Add(point3D);
          }
        }
      }
      double num3 = 90.0;
      if (marbleCam.ToolType == MarbleToolType.Milling)
        num3 = 0.0;
      for (int index = 0; index <= point3DList.Count - 1; ++index)
      {
        camTpPoint camTpPoint = new camTpPoint();
        if (index == 0)
        {
          TpPnt9D tpPnt9D1 = new TpPnt9D(point3DList[index], drillLeaveVelocity, 0);
          tpPnt9D1.P9.Z += num1;
          tpPnt9D1.P9.A = 0.0;
          tpPnt9D1.LeaveAxisMovement = true;
          tpPnt9D1.Type = 0;
          camTpPoint.Points.Add(tpPnt9D1);
          if (marbleCam.ToolType == MarbleToolType.MillingHead)
          {
            TpPnt9D tpPnt9D2 = new TpPnt9D(point3DList[index], drillLeaveVelocity, 0);
            tpPnt9D2.P9.Z += num1;
            tpPnt9D2.P9.A = num3;
            tpPnt9D2.P9.C = 0.0;
            tpPnt9D2.Type = 0;
            camTpPoint.Points.Add(tpPnt9D2);
          }
        }
        TpPnt9D tpPnt9D3 = new TpPnt9D(point3DList[index], drillLeaveVelocity, 0);
        tpPnt9D3.P9.Z += num2;
        tpPnt9D3.P9.A = num3;
        tpPnt9D3.P9.C = 0.0;
        tpPnt9D3.Type = 0;
        camTpPoint.Points.Add(tpPnt9D3);
        TpPnt9D tpPnt9D4 = new TpPnt9D(point3DList[index], feed, 0);
        tpPnt9D4.P9.Z = buMarbleCalc.varOperation.settingMarbleCam.TargetZDrill;
        tpPnt9D4.P9.A = num3;
        tpPnt9D4.P9.C = 0.0;
        tpPnt9D4.Type = 1;
        camTpPoint.Points.Add(tpPnt9D4);
        TpPnt9D tpPnt9D5 = new TpPnt9D(point3DList[index], drillLeaveVelocity, 0);
        tpPnt9D5.P9.Z += num2;
        tpPnt9D5.P9.A = num3;
        tpPnt9D5.P9.C = 0.0;
        tpPnt9D5.Type = 0;
        camTpPoint.Points.Add(tpPnt9D5);
        if (index == point3DList.Count - 1)
        {
          TpPnt9D tpPnt9D6 = new TpPnt9D(point3DList[index], drillLeaveVelocity, 0);
          tpPnt9D6.P9.Z += num1;
          tpPnt9D6.P9.A = 0.0;
          tpPnt9D6.P9.C = 0.0;
          tpPnt9D6.Type = 0;
          camTpPoint.Points.Add(tpPnt9D6);
        }
        camTpPoint.ToolCam = marbleCam.ToolType != MarbleToolType.MillingHead ? new ToolBase5(buMarbleCalc.activeToolMilling) : new ToolBase5(buMarbleCalc.activeToolMillingHead);
        LinearPath linearPath = new LinearPath((ICollection<Point3D>) new List<Point3D>()
        {
          new Point3D(point3DList[index].X, point3DList[index].Y, point3DList[index].Z + num2),
          new Point3D(point3DList[index].X, point3DList[index].Y, point3DList[index].Z)
        });
        data.EntitiesG1.Add((Entity) linearPath);
        data.CamPoints.Add(camTpPoint);
      }
      data.Tool = marbleCam.ToolType != MarbleToolType.MillingHead ? new ToolBase5(buMarbleCalc.activeToolMilling) : new ToolBase5(buMarbleCalc.activeToolMillingHead);
      data.Sequnce = CamSequence.ContourConcaveDrill;
      data.TypeCam = CamType.Drill;
      data.Name = marbleCam.CamName;
      data.Obj1 = (object) Item;
      data.Obj2 = (object) marbleCam;
      marbleCam.CamBase = new camTp(data);
      marbleCam.isCamCalculated = true;
      this.AnalyzeMillingCam(new marbleMillingAnalyzePars(), ref marbleCam.CamBase);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doSurfaceClearCamAdd(
    MarbleItem Item,
    MarbleToolType CuttingToolType,
    bool ShowDialog)
  {
    if (ShowDialog)
    {
      if (buMarbleForms.frmStockClear == null)
        buMarbleForms.frmStockClear = new F_MarbleStockClear();
      buMarbleForms.frmStockClear.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
      buMarbleForms.frmStockClear.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
      buMarbleForms.frmStockClear.varSurfaceClean = new marbleSurfaceCleanPars(buMarbleCalc.varOperation.settingSurfaceClean);
      buMarbleForms.frmStockClear.Init();
      int num = (int) buMarbleForms.frmStockClear.ShowDialog();
      if (buMarbleForms.frmStockClear.PropertiesForm.Result != DialogResult.OK)
        return;
      buMarbleCalc.varOperation.settingSurfaceClean = new marbleSurfaceCleanPars(buMarbleForms.frmStockClear.varSurfaceClean);
    }
    Entity refEntity;
    if (this.activeJob.Material.Enable)
    {
      List<Point3D> copiedPoint = new List<Point3D>();
      buVector5.Copy(this.activeJob.Material.Points, ref copiedPoint);
      LinearPath outer = new LinearPath((ICollection<Point3D>) copiedPoint);
      outer.Translate(0.0, 0.0, Item.SizeItem.Depth + buMarbleCalc.varOperation.settingSurfaceClean.ZOffset);
      refEntity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) outer).ExtrudeAsMesh(0.1, 0.01, Mesh.natureType.RichSmooth);
    }
    else
    {
      List<Point3D> Points = new List<Point3D>();
      if (Item.EntGroup != null)
      {
        clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.EntGroup.Outside.Entities, 0.1, ref Points);
        for (int index = 0; index <= Points.Count - 1; ++index)
          Points[index].Z = 0.0;
      }
      if (Points.Count < 1)
      {
        Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y));
        Points.Add(new Point3D(Item.SizeItem.MaxPoint.X, Item.SizeItem.MinPoint.Y));
        Points.Add(new Point3D(Item.SizeItem.MaxPoint.X, Item.SizeItem.MaxPoint.Y));
        Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MaxPoint.Y));
        Points.Add(new Point3D(Item.SizeItem.MinPoint.X, Item.SizeItem.MinPoint.Y));
      }
      LinearPath outer = new LinearPath((ICollection<Point3D>) Points);
      outer.Translate(0.0, 0.0, Item.SizeItem.Depth + buMarbleCalc.varOperation.settingSurfaceClean.ZOffset);
      refEntity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) outer).ExtrudeAsMesh(0.1, 0.01, Mesh.natureType.RichSmooth);
    }
    MarbleItemCam marbleCam = (MarbleItemCam) null;
    ToolBase5 toolFromType = clsInit.cMarble.FindToolFromType(CuttingToolType);
    this.doSurfaceClearCamCalcCut(refEntity, CuttingToolType, toolFromType, true, ref Item, ref marbleCam);
  }

  public void doSurfaceClearCamCalcCut(
    Entity refEntity,
    MarbleToolType CuttingToolType,
    ToolBase5 Tool,
    bool AddAsNew,
    ref MarbleItem Item,
    ref MarbleItemCam marbleCam)
  {
    string str = nameof (doSurfaceClearCamCalcCut);
    try
    {
      bool flag = false;
      if (refEntity == null)
        return;
      if (refEntity.BoxMax == (Point3D) null)
        refEntity.Regen(0.1);
      if (AddAsNew | marbleCam == null)
        marbleCam = new MarbleItemCam();
      marbleCam.CamName = $"{buLangTranslate.preDef.Surface} {buLangTranslate.preDef.Cleaning}";
      marbleCam.CamMarbleType = MarbleCamType.Surface2D;
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.ToolType = CuttingToolType;
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
      marbleCam.CamType = CamType.Rough;
      marbleCam.ToolSelected = new ToolBase5(Tool);
      marbleCam.isFinish = true;
      clsMW.Containment2DEntities.Clear();
      clsMW.CamEntities.Clear();
      clsMW.CamEntities.Add(refEntity);
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.isRough = true;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.AddToCamListInMWCalculation = false;
      MWCalcOptions.DontShowbuDialogBox = true;
      ToolBase5 ToolSelected = new ToolBase5();
      if (CuttingToolType == MarbleToolType.Milling)
      {
        ToolSelected.Geometry.Diameter = Tool.Geometry.Diameter;
        ToolSelected.Purpose = ToolPurpose.Milling;
        flag = true;
      }
      else if (CuttingToolType == MarbleToolType.Milling)
      {
        ToolSelected.Geometry.Diameter = Tool.Geometry.Diameter;
        ToolSelected.Purpose = ToolPurpose.Milling5Axis;
        flag = true;
      }
      else if (CuttingToolType == MarbleToolType.MillingHead)
      {
        ToolSelected.Geometry.Diameter = Tool.Geometry.Diameter;
        ToolSelected.Purpose = ToolPurpose.MillingHead;
        flag = true;
      }
      else if (CuttingToolType == MarbleToolType.Saw)
      {
        ToolSelected.Geometry.Diameter = Tool.Geometry.Thickness;
        ToolSelected.Purpose = ToolPurpose.Saw;
      }
      ToolSelected.Geometry.Length = 30.0;
      ToolSelected.Geometry.GeometryType = buClass.ToolType.Flat;
      double num1 = Item.SizeItem.MaxPoint.Z + Item.Settings.settingSurfaceClean.ZOffset;
      double num2 = 0.0;
      double num3 = 1.0;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStepMode = CamStepDepthMode.ConstantDepthStep;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num1;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num1;
      if (this.activeJob.Material.Enable)
      {
        buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtUserDefined;
        if (this.activeJob.Material.Size.Depth > num1)
        {
          buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num1;
          buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = this.activeJob.Material.Size.Depth;
          num2 = this.activeJob.Material.Size.Depth - num1;
          buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance;
          if (num2 > buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance)
          {
            num3 = buNumeric5.RoundToUpper(num2 / buMarbleCalc.varOperation.settingMarbleCam.SawForwardStepDownDistance);
            buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.DepthStep = Math.Round(num2 / num3, 3) - 0.1;
            MWCalcOptions.CamTriMeshType = CamTriangularMeshType.Rough;
            buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Pockets.PocketType = CamPocketType.WfbRghtParallel;
          }
          else
          {
            buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num1;
            buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num1;
            buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
          }
        }
        else
        {
          buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.EndValue = num1;
          buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue = num1;
          buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
        }
      }
      else
        buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
      if (flag)
      {
        MWCalcOptions.CamTriMeshType = CamTriangularMeshType.Rough;
        buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Pockets.PocketType = CamPocketType.WfbRghtParallel;
      }
      else
        MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.EntryAndExit = Item.Settings.settingSurfaceClean.RapidDistance;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Rapid = Item.Settings.settingMaterialClean.RapidDistance;
      buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe = Item.Settings.settingSurfaceClean.SafeDistance;
      if (buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe < buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue)
        buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Safe = buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Steps.StartValue + buMWMarbleVars.varCamMarbleSurfaceClean.buPar.Distances.Rapid;
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleSurfaceClean.buPar);
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamParTriangleMesh(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, marbleCam.setCam);
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.ParallelMachAngleInYX = 90.0;
      if (buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.ClearancePlaneHeight < refEntity.BoxMax.Z + 2.0)
        buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.ClearancePlaneHeight = refEntity.BoxMax.Z + 20.0;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.MaxStepoverDistance = ToolSelected.Geometry.Diameter * Item.Settings.settingSurfaceClean.ToolDiameterUsagePersentage / 100.0;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeOneway;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.FeedRate = Item.Settings.settingSurfaceClean.CuttingFeed;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.PlungeFeedRate = Item.Settings.settingSurfaceClean.PlungeFeed;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.GapsAlongCut.SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices.SmallMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices.LargeMoveHandling.Action = MoveHandlingAction.ActionGapBrokenFeedRap;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices.GetGapSize();
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.LinkParams.LinkBetweenSlices.SetGapSize(5.0);
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CutTolerance = 0.1;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
      buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeOneway;
      if (Item.Settings.settingSurfaceClean.ZigzagMode)
        buMWMarbleVars.varCamMarbleSurfaceClean.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
      if (MWCalcOptions.CamTriMeshType == CamTriangularMeshType.Rough)
        clsMW.varMWCamMeshRoughPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, buMWMarbleVars.varCamMarbleSurfaceClean.buPar, out clsMW.varbuCamMeshRoughPars);
      else
        clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleSurfaceClean.mwPar, buMWMarbleVars.varCamMarbleSurfaceClean.buPar, out clsMW.varbuCamMeshParallelPars);
      camTpPoint camTpPoint1 = new camTpPoint();
      MWCalcOptions.DontShowDialogBox = true;
      camResult Result = new camResult();
      camTp Cam = new camTp();
      if (clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result) == -1)
        return;
      if (!flag & num3 > 1.0)
      {
        camTp camTp = new camTp(Cam);
        double num4 = Math.Round(num2 / num3, 3);
        for (int index1 = 1; (double) index1 < num3; ++index1)
        {
          List<Entity> collection1 = new List<Entity>();
          List<Entity> collection2 = new List<Entity>();
          List<Entity> collection3 = new List<Entity>();
          List<Entity> collection4 = new List<Entity>();
          buEntity.Copy(camTp.EntitiesG1, ref collection2);
          clsInit.cVector5.Move(0.0, 0.0, (double) index1 * num4, ref collection2);
          buEntity.Copy(camTp.EntitiesG0, ref collection1);
          clsInit.cVector5.Move(0.0, 0.0, (double) index1 * num4, ref collection1);
          buEntity.Copy(camTp.EntitiesLeave, ref collection3);
          clsInit.cVector5.Move(0.0, 0.0, (double) index1 * num4, ref collection3);
          buEntity.Copy(camTp.EntitiesPlunge, ref collection4);
          clsInit.cVector5.Move(0.0, 0.0, (double) index1 * num4, ref collection4);
          for (int index2 = 0; index2 <= camTp.CamPoints.Count - 1; ++index2)
          {
            camTpPoint camTpPoint2 = new camTpPoint();
            for (int index3 = 0; index3 <= camTp.CamPoints[index2].Points.Count - 1; ++index3)
            {
              TpPnt9D tpPnt9D = new TpPnt9D(camTp.CamPoints[index2].Points[index3].P9);
              tpPnt9D.P9.Z += (double) index1 * num4;
              camTpPoint2.Points.Add(tpPnt9D);
            }
            Cam.CamPoints.Insert(0, camTpPoint2);
          }
          Cam.EntitiesG1.AddRange((IEnumerable<Entity>) collection2);
          Cam.EntitiesG0.AddRange((IEnumerable<Entity>) collection1);
          Cam.EntitiesLeave.AddRange((IEnumerable<Entity>) collection3);
          Cam.EntitiesPlunge.AddRange((IEnumerable<Entity>) collection4);
        }
      }
      marbleCam.CamBase = new camTp(Cam);
      if (marbleCam.CamBase != null)
      {
        marbleMillingAnalyzePars AnalyzeSet = new marbleMillingAnalyzePars();
        if (marbleCam.ToolType == MarbleToolType.MillingHead)
          AnalyzeSet.Apply90DegreeToMillingHead = true;
        this.AnalyzeMillingCam(AnalyzeSet, ref marbleCam.CamBase);
        camTp camBase = marbleCam.CamBase;
        camBase.CamID = Item.ID;
        camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
        camBase.TypeCam = CamType.SawCut;
        if (marbleCam.ToolType == MarbleToolType.Milling | marbleCam.ToolType == MarbleToolType.MillingHead)
          camBase.TypeCam = CamType.MillingCut;
        camBase.AxisCount = 5;
        camBase.Explanation = $"{buLangTranslate.preDef.Surface} {buLangTranslate.preDef.Cleaning}";
        camBase.Parameter = new camParameters5(marbleCam.setCam);
        camBase.Tool = new ToolBase5(marbleCam.ToolSelected);
        this.doCamPointsOffsets(ref marbleCam);
        if (CuttingToolType == MarbleToolType.Saw)
        {
          for (int index4 = 0; index4 <= marbleCam.CamBase.CamPoints.Count - 1; ++index4)
          {
            for (int index5 = 0; index5 <= marbleCam.CamBase.CamPoints[index4].Points.Count - 1; ++index5)
              marbleCam.CamBase.CamPoints[index4].Points[index5].P9.Y += clsMarble.activeKinematic.RotateCenterOffsetOfC.Y;
          }
        }
        clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
        marbleCam.isCamCalculated = true;
        if (AddAsNew | Item.CamList.Count == 0)
          Item.CamList.Add(marbleCam);
      }
      this.AddOperationAfterThings();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemMaterialClean(bool isCamCalc = false)
  {
    string str = nameof (doAddItemMaterialClean);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
