        clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      }
      else
      {
        clsMW.varMWCamWFPocketPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleMaterialClean.mwPar, buMWMarbleVars.varCamMarbleMaterialClean.buPar, out clsMW.varbuCamWFPocketPars);
        clsMW.CamEntities.Clear();
        clsMW.CamEntities.Add((Entity) rectangle);
        clsInit.appMW.doWireframeContour(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      }
      marbleCam.CamBase = new camTp(Cam);
      if (marbleCam.CamBase == null)
        return;
      camTp camBase = marbleCam.CamBase;
      camBase.CamID = Item.ID;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.SawCut;
      if (marbleCam.ToolType == MarbleToolType.Milling | marbleCam.ToolType == MarbleToolType.MillingHead)
        camBase.TypeCam = CamType.MillingCut;
      camBase.AxisCount = 5;
      camBase.Explanation = $"{buLangTranslate.preDef.Material} {buLangTranslate.preDef.Cleaning}";
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      camBase.Tool.CamData.SpindleSpeed = Item.Settings.settingMaterialClean.SpindleSpeed;
      this.doCamPointsOffsets(ref marbleCam);
      for (int index1 = 0; index1 <= marbleCam.CamBase.CamPoints.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= marbleCam.CamBase.CamPoints[index1].Points.Count - 1; ++index2)
        {
          TpPnt9D point = marbleCam.CamBase.CamPoints[index1].Points[index2];
          if (marbleCam.ToolType == MarbleToolType.Saw)
            point.P9.Y += clsMarble.activeKinematic.RotateCenterOffsetOfC.Y;
          else if (marbleCam.ToolType == MarbleToolType.MillingHead)
            point.P9.A = 90.0;
          else if (marbleCam.ToolType == MarbleToolType.Milling)
          {
            point.P9.A = 0.0;
            point.P9.C = Item.Settings.settingMaterialClean.CAxisAngle;
          }
        }
      }
      marbleCam.isCamCalculated = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

