          entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) CompositeCurve.CreateRectangle(0.0, 0.0, buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth, buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight)).ExtrudeAsMesh(1.0, 0.1, Mesh.natureType.RichSmooth);
