      else
      {
        CompositeCurve rectangle = CompositeCurve.CreateRectangle(this.activeJob.Material.BoxMaxPoint.X - this.activeJob.Material.BoxMinPoint.X, this.activeJob.Material.BoxMaxPoint.Y - this.activeJob.Material.BoxMinPoint.Y);
        rectangle.Translate(this.activeJob.Material.BoxMinPoint.X, this.activeJob.Material.BoxMinPoint.Y);
        Entity entity = (Entity) new devDept.Eyeshot.Entities.Region((ICurve) rectangle).ExtrudeAsMesh(1.0, 0.1, Mesh.natureType.RichSmooth);
        if (entity != null)
        {
          entity.Translate(0.0, 0.0, this.activeJob.Material.BoxMaxPoint.Z + MI.Settings.settingAirDry.Height);
          entity.ColorMethod = colorMethodType.byEntity;
          entity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemAirDry.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemAirDry.Color);
          MI.ItemEntities.SolidEntity = new List<Entity>();
          MI.ItemEntities.SolidEntity.Add(entity);
        }
      }
      this.doAddItemCommonProps(ref MI);
      MarbleItemCam marbleCam = new MarbleItemCam();
      marbleCam.ID = MarbleTempVars.MarbleCamID;
