      marbleCam.isFinish = true;
      clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
      MI.CamList.Add(marbleCam);
      if (isCamCalc)
        this.doAirDryCamCalcCut(ref MI, ref marbleCam);
      this.AddOperationBeforeThings();
      marbleCam.isCamCalculated = isCamCalc;
      MI.ID = MarbleTempVars.ItemID;
      this.doAddItemToJob(MI, true, true);
