  public void doAirDryCamCalcCut(ref MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doAirDryCamCalcCut);
    try
    {
      clsMW.Containment2DEntities.Clear();
      if (Item.ItemEntities.SolidEntity == null || Item.ItemEntities.SolidEntity.Count == 0)
        return;
      camTp camTp = new camTp();
      Point3D MinPoint = new Point3D();
      Point3D MaxPoint = new Point3D();
      Point3D point3D = new Point3D();
      clsMW.CamEntities.Clear();
      clsInit.cVector5.BoxSizeCalculate(Item.ItemEntities.SolidEntity, ref MinPoint, ref MaxPoint);
      for (int index = 0; index <= Item.ItemEntities.SolidEntity.Count - 1; ++index)
      {
        Entity copiedEntity = (Entity) null;
        buEntity.Copy(Item.ItemEntities.SolidEntity[index], ref copiedEntity);
        if (copiedEntity != null)
          clsMW.CamEntities.Add(copiedEntity);
      }
      camTp = new camTp();
      MWCalculationOptions MWCalcOptions = new MWCalculationOptions();
      MWCalcOptions.NumberofAxis = 3;
      MWCalcOptions.CamTriMeshType = CamTriangularMeshType.ParallelCuts;
      MWCalcOptions.Mode = CamMode.TriangularMesh;
      MWCalcOptions.isRough = true;
      MWCalcOptions.DontApplyReset = true;
      MWCalcOptions.AddToCamListInLocalCalculation = false;
      MWCalcOptions.AddToCamListInMWCalculation = false;
      MWCalcOptions.DontShowbuDialogBox = true;
      ToolBase5 ToolSelected = new ToolBase5();
      ToolSelected.Geometry.Diameter = Item.Settings.settingAirDry.StepDistance;
      ToolSelected.Geometry.Length = 30.0;
      ToolSelected.Geometry.GeometryType = buClass.ToolType.Flat;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.ParallelMachAngleInYX = Item.Settings.settingAirDry.Direction != HorizontalVertical.Horizontal ? 0.0 : 90.0;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.ApproachFeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.FeedPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.RetractPlaneIncremental = 0.0;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.ClearancePlaneHeight = MaxPoint.Z + Item.Settings.settingAirDry.RapidDistance;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.MaxStepoverDistance = ToolSelected.Geometry.Diameter * 0.9;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentFlg = true;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.SilhouetteContainmentCreationType = TriangleMeshBasedTpCalcParamsSilhouetteContainmentCreationType.ScctPartSilhouette;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.CutTolerance = 0.1;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.HeightsType = MachiningAreaHeightsParamsHeightsType.ShpHtAutomatic;
      buMWMarbleVars.varCamMarbleAirDry.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.MachiningAreaHeightsParams.AutomaticHeightsType = MachiningAreaHeightsParamsAutomaticHeightsType.ShpAhtMinMaxFromMachSurf;
      clsMW.varMWCamMeshParalelPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleAirDry.mwPar, buMWMarbleVars.varCamMarbleAirDry.buPar, out clsMW.varbuCamMeshParallelPars);
      camTpPoint camTpPoint = new camTpPoint();
      MWCalcOptions.DontShowDialogBox = true;
      camTp Cam = new camTp();
      camResult Result = new camResult();
      clsInit.appMW.doTriangularMesh3D(MWCalcOptions, ToolSelected, ref Cam, ref Result);
      marbleCam.CamBase = new camTp(Cam);
      if (marbleCam.CamBase == null)
        return;
      marbleCam.isCamCalculated = true;
      camTp camBase = marbleCam.CamBase;
      camBase.CamID = marbleCam.ID;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.AreaScan;
      camBase.AxisCount = 3;
      camBase.Explanation = $"{buLangTranslate.preDef.Air} {buLangTranslate.preDef.Dry}";
      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.UsedCamPost = true;
      camBase.Post.RepetitionDef.Tool = false;
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      this.doCamPointsOffsets(ref marbleCam);
      marbleCam.isCamCalculated = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doAddItemGCode(Point3D refPoint, buFile5.GCodeRead GCodes, List<string> GCodeLine)
  {
    string str = nameof (doAddItemGCode);
    try
    {
      if (this.activeJob == null)
        this.activeJob = new MarbleJob();
      MarbleItem MI = new MarbleItem();
      MI.ItemEntities.DrawWireEntities = new List<buEntity>();
      MI.ItemType = MarbleItemType.GCode;
      MI.BasePoint = buVector5.ToPoint3D(refPoint);
      MI.BaseHeight = buMarbleCalc.varMarbleRunSettings.ScaleBaseHeight;
      buEntity.Add(GCodes.EntitiesG1, ref MI.ItemEntities.DrawWireEntities);
      for (int index = 0; index <= MI.ItemEntities.DrawWireEntities.Count - 1; ++index)
      {
        buEntity drawWireEntity = MI.ItemEntities.DrawWireEntities[index];
        drawWireEntity.Translate(refPoint.X, refPoint.Y, refPoint.Z + MI.BaseHeight);
        drawWireEntity.Marble = new MarbleInfo();
      }
      clsInit.cVector5.BoxSizeCalculate(MI.ItemEntities.DrawWireEntities, ref MI.SizeItem.MinPoint, ref MI.SizeItem.MidPoint, ref MI.SizeItem.MaxPoint);
      ObjectSize3D.CalculateSize(ref MI.SizeItem);
      if (MI.BaseHeight > 0.0)
      {
        Entity surfaceEntity = (Entity) null;
        clsInit.cVector5.surfaceBox(MI.SizeItem.MinPoint, MI.SizeItem.MaxPoint.X - MI.SizeItem.MinPoint.X, MI.SizeItem.MaxPoint.Y - MI.SizeItem.MinPoint.Y, MI.BaseHeight, eyeSurfaceType.Mesh, ref surfaceEntity);
        if (surfaceEntity != null)
        {
          buEntity copiedEntity = (buEntity) null;
          buEntity.Copy(surfaceEntity, ref copiedEntity);
          copiedEntity.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemBase.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemBase.Color);
          MI.ItemEntities.BaseEntities = new List<buEntity>();
        }
      }
      MarbleItemCam marbleCam = new MarbleItemCam();
      List<string> GCodeLineConverted = new List<string>();
      clsInit.cMarble.GetCamID(this.activeJob, ref marbleCam.CamID);
      this.ConvertGCodeToGCode(buMarbleCalc.activeToolMilling, 0.0, GCodeLine, GCodes.Coordinates, ref GCodeLineConverted, ref MI, ref marbleCam);
      this.AddOperationBeforeThings();
      this.doAddItemToJob(MI, true, true);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void ConvertGCodeToGCode(
    ToolBase5 Tool,
    double ZOffset,
    List<string> GCodeLine,
    List<GCodePoint5> Coordinates,
    ref List<string> GCodeLineConverted,
    ref MarbleItem MI,
    ref MarbleItemCam marbleCam)
  {
    if (GCodeLineConverted == null)
      GCodeLineConverted = new List<string>();
    GCodeLineConverted.Clear();
    int num1 = 10;
    if (buMarbleCalc.varMarbleSettings.GCodeConversion == MarbleExternalGCode.AspireGCode)
    {
      GCodeLineConverted.Add("M41");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("M3 K" + Tool.CamData.SpindleSpeed.ToString());
      GCodeLineConverted.Add("M8");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("M154");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
      GCodeLineConverted.Add("G75");
      int num2 = 100;
      for (int index = 0; index <= GCodeLine.Count - 1; ++index)
      {
        bool flag = false;
        string FullLine = GCodeLine[index];
        if (FullLine.IndexOf("G0") >= 0)
          flag = true;
        else if (FullLine.IndexOf("G1") >= 0)
        {
          if (FullLine.IndexOf("G17") == -1)
            flag = true;
        }
        else if (FullLine.IndexOf("G2") >= 0)
        {
          if (FullLine.IndexOf("G21") == -1)
            flag = true;
        }
        else if (FullLine.IndexOf("G3") >= 0)
          flag = true;
        if (flag)
        {
          if (ZOffset != 0.0 && FullLine.IndexOf("Z") >= 0)
          {
            double num3 = 0.0;
            buString5.ReadCharValue(FullLine, "Z", ref num3);
            string newValue = "Z" + (num3 + ZOffset).ToString();
            FullLine = FullLine.Replace("Z" + num3.ToString("f3"), newValue);
          }
          if (FullLine.IndexOf("S") >= 0)
          {
            double num4 = 0.0;
            buString5.ReadCharValue(FullLine, "S", ref num4);
            FullLine = FullLine.Replace("S" + num4.ToString(), "");
          }
          if (FullLine.IndexOf("F") >= 0)
          {
            double num5 = 0.0;
            buString5.ReadCharValue(FullLine, "F", ref num5);
            int num6 = FullLine.IndexOf("X");
            int num7 = FullLine.IndexOf("Y");
            string newValue = " F" + buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Feed.ToString();
            if (num6 == -1 & num7 == -1)
              newValue = " F" + buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Plunge.ToString();
            FullLine = FullLine.Replace("F" + num5.ToString(), newValue);
          }
          GCodeLineConverted.Add(FullLine);
          num2 += 10;
        }
      }
      GCodeLineConverted.Add("M5");
      num1 = num2 + 10;
      GCodeLineConverted.Add("M2");
      marbleCam.CamBase = new camTp();
      marbleCam.CamBase.PreCodes.AddRange((ICollection) GCodeLineConverted);
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.ToolType = buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool != MarbleMillingToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      marbleCam.CamBase.TypeCam = CamType.MillingCut;
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      if (marbleCam.MeshType != CamTriangularMeshType.None)
        MI.CamList.Add(marbleCam);
      marbleCam.isCamCalculated = true;
    }
    else if (buMarbleCalc.varMarbleSettings.GCodeConversion == MarbleExternalGCode.ArtCamMode1)
    {
      GCodeLineConverted.Add("M41");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("M3 K" + Tool.CamData.SpindleSpeed.ToString());
      GCodeLineConverted.Add("M8");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("M154");
      GCodeLineConverted.Add("G75");
      GCodeLineConverted.Add("G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
      GCodeLineConverted.Add("G75");
      int num8 = 100;
      bool flag = false;
      for (int index = 0; index <= GCodeLine.Count - 1; ++index)
      {
        string FullLine = GCodeLine[index];
        if (FullLine.IndexOf("G0") >= 0)
          flag = true;
        else if (FullLine.IndexOf("G1") >= 0)
        {
          if (FullLine.IndexOf("G17") == -1)
            flag = true;
        }
        else if (FullLine.IndexOf("G2") >= 0)
        {
          if (FullLine.IndexOf("G21") == -1)
            flag = true;
        }
        else if (FullLine.IndexOf("G3") >= 0)
          flag = true;
        if (flag)
        {
          if (ZOffset != 0.0 && FullLine.IndexOf("Z") >= 0)
          {
            double num9 = 0.0;
            buString5.ReadCharValue(FullLine, "Z", ref num9);
            string newValue = "Z" + (num9 + ZOffset).ToString();
            FullLine = FullLine.Replace("Z" + num9.ToString("f3"), newValue);
          }
          if (FullLine.IndexOf("S") >= 0)
          {
            double num10 = 0.0;
            buString5.ReadCharValue(FullLine, "S", ref num10);
            FullLine = FullLine.Replace("S" + num10.ToString(), "");
          }
          if (FullLine.IndexOf("F") >= 0)
          {
            double num11 = 0.0;
            buString5.ReadCharValue(FullLine, "F", ref num11);
            int num12 = FullLine.IndexOf("X");
            int num13 = FullLine.IndexOf("Y");
            string newValue = " F" + buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Feed.ToString();
            if (num12 == -1 & num13 == -1)
              newValue = " F" + buMWMarbleVars.varCamMarbleMilling2DRough.buPar.Speeds.Plunge.ToString();
            FullLine = FullLine.Replace("F" + num11.ToString(), newValue);
          }
          GCodeLineConverted.Add(FullLine);
          num8 += 10;
        }
      }
      GCodeLineConverted.Add("M5");
      num1 = num8 + 10;
      GCodeLineConverted.Add("M2");
      marbleCam.CamBase = new camTp();
      marbleCam.CamBase.PreCodes.AddRange((ICollection) GCodeLineConverted);
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.CamBase.TypeCam = CamType.MillingCut;
      marbleCam.ToolType = buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool != MarbleMillingToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      if (marbleCam.MeshType != CamTriangularMeshType.None)
        MI.CamList.Add(marbleCam);
      marbleCam.isCamCalculated = true;
    }
    else if (buMarbleCalc.varMarbleSettings.GCodeConversion == MarbleExternalGCode.Siemens5Axis)
    {
      Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
      this.GCode5AxisRTCPConversion(ref MI, ref marbleCam, Tool, Coordinates);
    }
    else if (buMarbleCalc.varMarbleSettings.GCodeConversion == MarbleExternalGCode.SolidCam3AxisNoToolChange)
    {
      double num14 = 3500.0;
      bool flag1 = false;
      bool flag2 = false;
      for (int index = 0; index <= GCodeLine.Count - 1; ++index)
      {
        bool flag3 = true;
        if (GCodeLine[index].IndexOf("O1") >= 0 | GCodeLine[index].IndexOf("(") >= 0 | GCodeLine[index].IndexOf("G90") >= 0 | GCodeLine[index].IndexOf("G91") >= 0 | GCodeLine[index].IndexOf("G5") >= 0)
          flag3 = false;
        if (GCodeLine[index].IndexOf("G54") >= 0 | GCodeLine[index].IndexOf("G80") >= 0 | GCodeLine[index].IndexOf("M6") >= 0 | GCodeLine[index].IndexOf("M30") >= 0 | GCodeLine[index].IndexOf("M1") >= 0)
          flag3 = false;
        if (GCodeLine[index].IndexOf("M3") >= 0 & GCodeLine[index].IndexOf("S") >= 0)
        {
          double num15 = 0.0;
          buString5.ReadCharValue(GCodeLine[index], "S", ref num15);
          if (num15 > 10.0)
            num14 = num15;
          flag3 = false;
        }
        if (GCodeLine[index].IndexOf("G43") >= 0)
        {
          flag3 = false;
          GCodeLineConverted.Add("G53");
          GCodeLineConverted.Add("G0 Z0 A90");
          GCodeLineConverted.Add("G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
          GCodeLineConverted.Add("M154");
          GCodeLineConverted.Add("M42");
          GCodeLineConverted.Add("G75");
          GCodeLineConverted.Add("M33 K" + num14.ToString("f0"));
          GCodeLineConverted.Add("M8");
          GCodeLineConverted.Add("G75");
          GCodeLineConverted.Add("M154");
          GCodeLineConverted.Add("G75");
          GCodeLineConverted.Add("G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
          GCodeLineConverted.Add("G75");
        }
        if (GCodeLine[index].IndexOf("F") >= 0)
        {
          double num16 = 0.0;
          double num17 = 0.0;
          buString5.ReadCharValue(GCodeLine[index], "F", ref num16);
          num17 = Math.Round(num16 / 60.0, 0);
          if (GCodeLine[index].IndexOf("X") < 0 & GCodeLine[index].IndexOf("Y") < 0 & GCodeLine[index].IndexOf("Z") >= 0 && num17 > 50.0)
            num17 = 50.0;
          GCodeLine[index] = GCodeLine[index].Replace("F" + num16.ToString(), "F" + num17.ToString());
        }
        if (flag3)
        {
          if (GCodeLine[index].IndexOf("G0") >= 0 & !flag1)
          {
            GCodeLineConverted.Add("M101");
            flag1 = true;
            flag2 = false;
          }
          if ((GCodeLine[index].IndexOf("G1") >= 0 | GCodeLine[index].IndexOf("G2") >= 0 | GCodeLine[index].IndexOf("G3") >= 0) & !flag2)
          {
            GCodeLineConverted.Add("M102");
            flag1 = false;
            flag2 = true;
          }
          GCodeLineConverted.Add(GCodeLine[index].Trim());
        }
      }
      GCodeLineConverted.Add("M35");
      GCodeLineConverted.Add("M2");
      marbleCam.CamBase = new camTp();
      marbleCam.CamBase.PreCodes.AddRange((ICollection) GCodeLineConverted);
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.ToolType = buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool != MarbleMillingToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      marbleCam.CamBase.TypeCam = CamType.MillingCut;
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      if (marbleCam.MeshType != CamTriangularMeshType.None)
        MI.CamList.Add(marbleCam);
      marbleCam.isCamCalculated = true;
    }
    else
    {
      GCodeLineConverted.AddRange((IEnumerable<string>) GCodeLine);
      marbleCam.CamBase = new camTp();
      marbleCam.CamBase.PreCodes.AddRange((ICollection) GCodeLineConverted);
      marbleCam.CamMode = MarbleCamMode.Rough;
      marbleCam.ToolType = buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool != MarbleMillingToolType.MillingHead ? MarbleToolType.Milling : MarbleToolType.MillingHead;
      marbleCam.CamBase.TypeCam = CamType.MillingCut;
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.ToolSelected = this.FindToolFromType(marbleCam.ToolType);
      if (marbleCam.MeshType != CamTriangularMeshType.None)
        MI.CamList.Add(marbleCam);
      marbleCam.isCamCalculated = true;
    }
    marbleCam.CamType = CamType.MillingCut;
  }

  public void GCode5AxisRTCPConversion(
    ref MarbleItem MI,
    ref MarbleItemCam marbleCam,
    ToolBase5 Tool,
    List<GCodePoint5> GCodePoits)
  {
    marbleCam.ToolType = MarbleToolType.Saw;
    marbleCam.ToolSelected = new ToolBase5(Tool);
    List<Pnt6DS> pnt6DsList = new List<Pnt6DS>();
    List<Pnt6DList> PLL3D = new List<Pnt6DList>();
    Pnt6DList pnt6Dlist = new Pnt6DList();
    for (int index = 0; index <= GCodePoits.Count - 1; ++index)
      pnt6Dlist.Points.Add(new Pnt6D(GCodePoits[index].Positions.X, GCodePoits[index].Positions.Y, GCodePoits[index].Positions.Z, GCodePoits[index].Positions.A + 90.0, 0.0, GCodePoits[index].Positions.C));
    PLL3D.Add(pnt6Dlist);
    MarbleSawCalcParameters Setting = new MarbleSawCalcParameters();
    Setting.DevideLength = 0.0;
    Setting.ShiftEnable = false;
    Setting.SplineEnable = false;
    marbleCam.CamBase = new camTp();
    clsInit.cMarble.SawExistingToolPointCamCenterCalc(ref MI, ref marbleCam, Setting, PLL3D, true, clsMarble.activeKinematic);
    marbleCam.CamBase.Tool = new ToolBase5(Tool);
    marbleCam.CamBase.TypeCam = CamType.MillingCut;
    MI.CamList.Add(marbleCam);
    marbleCam.isCamCalculated = true;
  }

  public void doAddCamItemContour(
    bool isText,
    bool isMilling,
    bool isMillingHead,
    bool isWaterJet,
    int JobListIndex)
  {
    bool flag = true;
    if (isText & buMarbleCalc.varMarbleRunSettings.BorderEnable)
    {
      if (MarbleTempVars.ItemsContour.Count > 0 && MarbleTempVars.ItemsContour[0].ItemEntities.SolidEntity.Count > 0)
        MarbleTempVars.ItemsContour[0].ItemEntities.SolidEntity.RemoveAt(0);
      flag = false;
    }
    this.AddOperationBeforeThings();
    if (flag)
    {
      for (int index1 = 0; index1 <= MarbleTempVars.ItemsContour.Count - 1; ++index1)
      {
        MarbleItem MI = new MarbleItem(MarbleTempVars.ItemsContour[index1]);
        MI.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
        CustomData customData = new CustomData();
        MI.ItemType = !isText ? MarbleItemType.Contour : MarbleItemType.Text;
        CamWireFrameType selectedWireframeType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
        if (isMilling | isMillingHead)
        {
          MarbleItemCam marbleItemCam = new MarbleItemCam();
          marbleItemCam.CamName = !isMilling ? $"{buLangTranslate.preDef.MillingHead} {buLangTranslate.preDef.Cutting}" : $"{buLangTranslate.preDef.Milling} {buLangTranslate.preDef.Cutting}";
          marbleItemCam.CamMarbleType = MarbleCamType.ContourMillingCut;
          marbleItemCam.CamMode = MarbleCamMode.Contour;
          marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleItemCam.CamID);
          marbleItemCam.ItemID = MI.ID;
          marbleItemCam.setCam.Steps.StartValue = MI.SizeItem.MaxPoint.Z;
          marbleItemCam.setCam.Steps.EndValue = MI.SizeItem.MaxPoint.Z - MI.SizeItem.Depth;
          marbleItemCam.setCam.Steps.Enable = true;
          marbleItemCam.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
          marbleItemCam.WireType = selectedWireframeType;
          marbleItemCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
          marbleItemCam.CamType = clsInit.cCam5.CamWireframeTypeToCamType(selectedWireframeType);
          marbleItemCam.ToolSelected = this.FindToolFromType(marbleItemCam.ToolType);
          marbleItemCam.EntityList = new buEntityList(MarbleTempVars.ItemsContour[index1].EntGroup.Outside);
          marbleItemCam.EntityList.InOutType = entityInOutDirectionType.Outside;
          for (int index2 = 0; index2 <= MarbleTempVars.ItemsContour[index1].EntGroup.Inside.Count - 1; ++index2)
            marbleItemCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) new buEntityList(MarbleTempVars.ItemsContour[index1].EntGroup.Inside[index2])
            {
              InOutType = entityInOutDirectionType.Inside
            }.Entities);
          clsInit.cMarble.GetCamID(this.activeJob, MI.CamList, ref marbleItemCam.CamID);
          MI.CamList.Add(marbleItemCam);
          MI.ToolType = !isMilling ? MarbleToolType.MillingHead : MarbleToolType.Milling;
        }
        else if (isWaterJet)
        {
          MarbleItemCam marbleItemCam = new MarbleItemCam()
          {
            CamName = $"{buLangTranslate.preDef.WaterJet} {buLangTranslate.preDef.Contour} {buLangTranslate.preDef.Cut}",
            CamMarbleType = MarbleCamType.ContourWaterJet,
            CamMode = MarbleCamMode.Contour,
            setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar),
            ItemID = MI.ID,
            ID = MI.ID,
            ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool,
            WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType,
            MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType,
            CamType = clsInit.cCam5.CamWireframeTypeToCamType(CamWireFrameType.Contour)
          };
          marbleItemCam.ToolSelected = this.FindToolFromType(marbleItemCam.ToolType);
          clsInit.cMarble.GetCamID(this.activeJob, ref marbleItemCam.CamID);
          MI.CamList.Add(marbleItemCam);
          MI.ToolType = MarbleToolType.WaterJet;
        }
        else
        {
          if (buMarbleCalc.varOperation.settingMarbleCam.isInsideFirst)
          {
            ToolBase5 toolFromType = this.FindToolFromType(MarbleToolType.Saw);
            clsInit.cMarble.CreateInsideCutCamItem(this.activeJob, ref MI, toolFromType, buMWMarbleVars.varCamMarbleMilling2DContour.buPar);
          }
          MarbleItemCam CamItem = new MarbleItemCam();
          CamItem.CamName = $"{buLangTranslate.preDef.Outside} {buLangTranslate.preDef.Cutting} [{buLangTranslate.preDef.Saw}]";
          CamItem.CamMarbleType = MarbleCamType.ContourSawOutsideCut;
          CamItem.CamMode = MarbleCamMode.Contour;
          CamItem.setCam = new camParameters5(buMWMarbleVars.varCamMarbleContour.buPar);
          clsInit.cMarble.GetCamID(this.activeJob, MI.CamList, ref CamItem.CamID);
          CamItem.ItemID = MI.ID;
          CamItem.ToolType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedTool;
