        double num4 = MaxPoint.X - MinPoint.X + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayXDistance;
        double num5 = MaxPoint.Y - MinPoint.Y + num3 + buMarbleCalc.varMarbleRunSettings.ShapeLinearArrayYDistance;
        for (int index1 = 0; index1 <= num1 - 1; ++index1)
        {
          for (int index2 = 0; index2 <= num2 - 1; ++index2)
          {
            Point3D refPoint = new Point3D(pntActive.X + (double) index1 * num4, pntActive.Y + (double) index2 * num5, pntActive.Z);
            MarbleItem marbleItem = new MarbleItem();
            marbleItem.ToolType = !isMilling ? (!isWaterJet ? (!isMillingHead ? MarbleToolType.Saw : MarbleToolType.MillingHead) : MarbleToolType.WaterJet) : MarbleToolType.Milling;
