  public void doShapeSawCamCalc(MarbleItem Item, ref MarbleItemCam marbleCam)
  {
    string str = "doShapeCamCalc";
    try
    {
      buEntityUtilities.EntityRegenDeviation = buMarbleCalc.varOperation.settingMarbleCam.RegenDeviation;
      Item.Settings.settingMarbleCam.UseCZero = false;
      marbleCam.setCam.Strategy.UseTangentLimit = true;
      marbleCam.setCam.Options.AxesLimit.MaxLimit.C = 370.0;
      marbleCam.setCam.Options.AxesLimit.MinLimit.C = -370.0;
      if (Item.ItemType == MarbleItemType.Contour | Item.ItemType == MarbleItemType.Library | Item.ItemType == MarbleItemType.Shape | Item.ItemType == MarbleItemType.VerticalCut | Item.ItemType == MarbleItemType.HorizontalCut | Item.ItemType == MarbleItemType.SingleCut)
        Item.Settings = new MarbleItemSettings(buMarbleCalc.varOperation);
      clsInit.cMarble.CalculateMarbleWireFrameWithSaw(clsMarble.activeKinematic, buMarbleCalc.activeToolSaw, this.activeJob, 0, true, (TpPnt9D) null, ref Item, ref marbleCam);
      clsInit.cMarble.CamSawCRotationFeedAnalyze(buMarbleCalc.varOperation.SawFeedAnalysisParameter, clsMarble.activeKinematic, ref marbleCam.CamBase);
      if (marbleCam.CamBase == null)
        return;
      camTp camBase = marbleCam.CamBase;
      camBase.CamID = Item.ID;
      camBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      camBase.TypeCam = CamType.SawCut;
      camBase.AxisCount = 5;
      camBase.Explanation = $"{buLangTranslate.preDef.Contour} {buLangTranslate.preDef.Cutting}";
      camBase.Tool = new ToolBase5(buMarbleCalc.activeToolSaw);
      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.UsedCamPost = true;
      camBase.Post.RepetitionDef.Tool = false;
      marbleCam.isCamCalculated = true;
      this.doCamPointsOffsets(ref marbleCam);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

  public void doConcaveCamCalc(MarbleItem Item, bool isConcave, ref MarbleItemCam marbleCam)
  {
    string str = nameof (doConcaveCamCalc);
    try
    {
      if (marbleCam.isCamCalculated || !this.activeJob.isMillingAvailable || buMarbleCalc.activeToolMilling == null)
        return;
      MWCalculationOptions MWCalcoptions = new MWCalculationOptions();
      MWCalcoptions.NumberofAxis = 3;
      MWCalcoptions.CamWireframeType = CamWireFrameType.Contour;
      MWCalcoptions.Mode = CamMode.WireFrame;
      MWCalcoptions.DontApplyReset = true;
      MWCalcoptions.isBuWireframeCalculation = false;
      MWCalcoptions.AddToCamListInLocalCalculation = false;
      MWCalcoptions.AddToCamListInMWCalculation = false;
      MWCalcoptions.ShowLeadInOutPage = false;
      MWCalcoptions.DontShowDialogBox = true;
      ToolBase5 Tool;
      if (isConcave)
      {
        if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool == MarbleCornerCleanToolType.MillingHead)
        {
          marbleCam.ToolType = MarbleToolType.MillingHead;
          Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        }
        else if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool == MarbleCornerCleanToolType.Waterjet)
        {
          marbleCam.ToolType = MarbleToolType.WaterJet;
          Tool = new ToolBase5(buMarbleCalc.activeToolWaterjet);
        }
        else
        {
          marbleCam.ToolType = MarbleToolType.Milling;
          Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
        }
        Tool.Geometry.Diameter += buMarbleCalc.varOperation.settingMarbleCam.ConcaveCornerExtraOffset * 2.0;
      }
      else
      {
        if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool == MarbleCornerCleanToolType.MillingHead)
        {
          marbleCam.ToolType = MarbleToolType.MillingHead;
          Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        }
        else if (buMarbleCalc.varOperation.settingMarbleCam.DefaultCornerCleanTool == MarbleCornerCleanToolType.Waterjet)
        {
          marbleCam.ToolType = MarbleToolType.WaterJet;
          Tool = new ToolBase5(buMarbleCalc.activeToolWaterjet);
        }
        else if (buMarbleCalc.varOperation.settingMarbleCam.DefaultMillingTool == MarbleMillingToolType.Milling)
        {
          marbleCam.ToolType = MarbleToolType.Milling;
          Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
        }
        else
        {
          marbleCam.ToolType = MarbleToolType.MillingHead;
          Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        }
        Tool.Geometry.Diameter += buMarbleCalc.varOperation.settingMarbleCam.ConvexCornerExtraOffset * 2.0;
      }
      camTp Cam = (camTp) null;
      if (isConcave)
      {
        if ((marbleCam.ConcaveEntities == null ? 0 : (marbleCam.ConcaveEntities.Count > 0 ? 1 : 0)) != 0)
        {
          Cam = new camTp();
          this.doConcaveWireframe(MWCalcoptions, Item, marbleCam, marbleCam.ConcaveEntities, Tool, isConcave, ref Cam);
          Cam.Explanation = $"{buLangTranslate.preDef.Concave} {buLangTranslate.preDef.Cleaning} {buLangTranslate.preDef.Cut}";
        }
      }
      else if ((marbleCam.ConvexEntities == null ? 0 : (marbleCam.ConvexEntities.Count > 0 ? 1 : 0)) != 0)
      {
        Cam = new camTp();
        this.doConcaveWireframe(MWCalcoptions, Item, marbleCam, marbleCam.ConvexEntities, Tool, isConcave, ref Cam);
      }
      if (Cam == null)
        return;
      Cam.Explanation = $"{buLangTranslate.preDef.Convex} {buLangTranslate.preDef.Cleaning} {buLangTranslate.preDef.Cut}";
      Cam.TypeCam = CamType.CornerCleanByMilling;
      Cam.AxisCount = 3;
      marbleCam.CamBase = new camTp(Cam);
      marbleCam.CamBase.Obj1 = (object) Item;
      marbleCam.CamBase.Obj2 = (object) marbleCam;
      marbleCam.CamBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      marbleCam.CamBase.Tool = new ToolBase5(marbleCam.ToolSelected);
      marbleCam.WireType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedWireframeType;
      marbleCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
      marbleCam.CamType = CamType.Contour;
      marbleMillingAnalyzePars AnalyzeSet = new marbleMillingAnalyzePars();
      if (marbleCam.ToolType == MarbleToolType.MillingHead)
        AnalyzeSet.Apply90DegreeToMillingHead = true;
      this.AnalyzeMillingCam(AnalyzeSet, ref marbleCam.CamBase);
      marbleCam.isCamCalculated = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

