          buEntity.Copy(marbleCam.EntityList.Entities[index], ref copiedEntity);
          clsMW.CamEntities.Add(copiedEntity);
        }
      }
      else if ((Item.EntGroup == null ? 0 : (Item.EntGroup.Outside != null ? 1 : 0)) != 0)
      {
        for (int index = 0; index <= Item.EntGroup.Outside.Entities.Count - 1; ++index)
        {
          Entity copiedEntity = (Entity) null;
          buEntity.Copy(Item.EntGroup.Outside.Entities[index], ref copiedEntity);
          clsMW.CamEntities.Add(copiedEntity);
        }
        if (Item.EntGroup.Inside != null)
        {
          for (int index3 = 0; index3 <= Item.EntGroup.Inside.Count - 1; ++index3)
          {
            for (int index4 = 0; index4 <= Item.EntGroup.Inside[index3].Entities.Count - 1; ++index4)
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(Item.EntGroup.Inside[index3].Entities[index4], ref copiedEntity);
              clsMW.CamEntities.Add(copiedEntity);
            }
          }
        }
        if (Item.EntGroup.OpenEntities != null)
        {
          for (int index5 = 0; index5 <= Item.EntGroup.OpenEntities.Count - 1; ++index5)
          {
            for (int index6 = 0; index6 <= Item.EntGroup.OpenEntities[index5].Entities.Count - 1; ++index6)
            {
              Entity copiedEntity = (Entity) null;
              buEntity.Copy(Item.EntGroup.OpenEntities[index5].Entities[index6], ref copiedEntity);
              clsMW.CamEntities.Add(copiedEntity);
            }
          }
        }
      }
      if (clsMW.CamEntities.Count <= 0)
        return;
      ToolBase5 Tool = marbleCam.ToolType != MarbleToolType.Milling ? (marbleCam.ToolType != MarbleToolType.MillingHead ? new ToolBase5(marbleCam.ToolSelected) : new ToolBase5(buMarbleCalc.activeToolMillingHead)) : new ToolBase5(buMarbleCalc.activeToolMilling);
      marbleCam.CamBase = (camTp) null;
      this.doWireframeCamCalc(MWCalcoptions, ref marbleCam, Tool, ref marbleCam.CamBase, ZOffset: Item.BaseHeight);
      if (marbleCam.CamBase == null)
        return;
      marbleCam.CamBase.Explanation = $"{buLangTranslate.preDef.Wireframe} {buLangTranslate.preDef.Cut}";
      marbleCam.CamBase.TypeCam = CamType.MillingCut;
      marbleCam.CamBase.AxisCount = 3;
      marbleCam.CamBase.Obj1 = (object) Item;
      marbleCam.CamBase.Obj2 = (object) marbleCam;
      marbleCam.CamBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
      if (marbleCam.ToolType == MarbleToolType.Milling)
      {
        marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMilling);
        marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
      }
      else
      {
        marbleCam.CamBase.Tool = new ToolBase5(buMarbleCalc.activeToolMillingHead);
        marbleCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
      }
      if (marbleCam.CamPlane == planeNames.Bottom)
      {
        Point3D MinPoint = new Point3D();
        Point3D MidPoint = new Point3D();
        Point3D MaxPoint = new Point3D();
        clsInit.cVector5.BoxSizeCalculate(marbleCam.CamBase.EntitiesG1, ref MinPoint, ref MidPoint, ref MaxPoint);
        clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesG1);
        clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesG0);
        clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesPlunge);
        clsInit.cVector5.Rotate(new Point3D(MidPoint.X, MidPoint.Y, MidPoint.Z), 180.0, Vector3D.AxisX, ref marbleCam.CamBase.EntitiesLeave);
      }
      marbleMillingAnalyzePars AnalyzeSet = new marbleMillingAnalyzePars();
      if (marbleCam.ToolType == MarbleToolType.MillingHead)
        AnalyzeSet.Apply90DegreeToMillingHead = true;
      this.AnalyzeMillingCam(AnalyzeSet, ref marbleCam.CamBase);
      marbleCam.isCamCalculated = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

