            pnt6DList.Add(new Pnt6D(Points[0].X, Points[0].Y, Points[0].Z, -Item.EntGroup.Outside.Entities[index1].Marble.Angle, 0.0, c));
          }
          for (int index2 = 1; index2 <= Points.Count - 1; ++index2)
          {
