            double num = c - pnt6DList[pnt6DList.Count - 1].C;
            if (Item.EntGroup.Outside.Entities[index1].Marble.Angle != pnt6DList[pnt6DList.Count - 1].A)
            {
              if (c != pnt6DList[pnt6DList.Count - 1].C)
                pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z, -Item.EntGroup.Outside.Entities[index1].Marble.Angle, 0.0, c));
              pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z, -Item.EntGroup.Outside.Entities[index1].Marble.Angle, 0.0, pnt6DList[pnt6DList.Count - 1].C));
            }
            pnt6DList.Add(new Pnt6D(Points[index2].X, Points[index2].Y, Points[index2].Z, -Item.EntGroup.Outside.Entities[index1].Marble.Angle, 0.0, c));
          }
        }
        pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, pnt6DList[pnt6DList.Count - 1].A, 0.0, pnt6DList[pnt6DList.Count - 1].C));
        for (int index = 0; index <= pnt6DList.Count - 1; ++index)
