              Item.ItemEntities.DrawWireEntities.Add((buEntity) new buLine(Item.EntGroup.Inside[index3].Entities[index4].EndPoint, calcPoint2));
              List<Point3D> Points = new List<Point3D>();
              clsInit.cVector5.EntitiesToPointsWithCamDirection(Item.EntGroup.Inside[index3].Entities[index4], 0.01, ref Points);
              if (index4 == 0)
              {
                double c = clsInit.cVector5.PointAngle(Points[1], Points[0]);
                pnt6DList.Add(new Pnt6D(Points[0].X, Points[0].Y, Points[0].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, -Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle, 0.0, c));
                pnt6DList.Add(new Pnt6D(Points[0].X, Points[0].Y, Points[0].Z, -Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle, 0.0, c));
              }
              for (int index5 = 1; index5 <= Points.Count - 1; ++index5)
              {
                double c = clsInit.cVector5.PointAngle(Points[index5], new Point3D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z));
                double num = c - pnt6DList[pnt6DList.Count - 1].C;
                if (Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle != pnt6DList[pnt6DList.Count - 1].A)
                {
                  if (c != pnt6DList[pnt6DList.Count - 1].C)
                    pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z, -Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle, 0.0, c));
                  pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z, -Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle, 0.0, pnt6DList[pnt6DList.Count - 1].C));
                }
                pnt6DList.Add(new Pnt6D(Points[index5].X, Points[index5].Y, Points[index5].Z, -Item.EntGroup.Inside[index3].Entities[index4].Marble.Angle, 0.0, c));
              }
            }
            pnt6DList.Add(new Pnt6D(pnt6DList[pnt6DList.Count - 1].X, pnt6DList[pnt6DList.Count - 1].Y, pnt6DList[pnt6DList.Count - 1].Z + Item.Settings.settingMarbleCam.WaterjetRapidDistance, pnt6DList[pnt6DList.Count - 1].A, 0.0, pnt6DList[pnt6DList.Count - 1].C));
            camTpPoint camTpPoint2 = new camTpPoint();
            for (int index6 = 0; index6 <= pnt6DList.Count - 1; ++index6)
            {
