        data.Tool = new ToolBase5(buMarbleCalc.activeToolWaterjet);
        if (clsMW.CamEntities.Count > 0)
          ;
        marbleCam.CamBase = new camTp(data);
        if (marbleCam.CamBase != null)
        {
          marbleCam.CamBase.OperationData = (object) new MarbleItemSettings(Item.Settings);
          marbleCam.CamBase.TypeCam = CamType.ContourClosedOutside;
        }
        if (marbleCam.CamBase != null)
        {
          bool flag = false;
          for (int index = 0; index <= marbleCam.CamBase.CamPoints[0].Points.Count - 1; ++index)
          {
            if (flag)
              marbleCam.CamBase.CamPoints[0].Points[index].AfterCodes.Add((object) ("M4 K" + marbleCam.ToolSelected.CamData.SpindleSpeed.ToString()));
            if (!flag && marbleCam.CamBase.CamPoints[0].Points[index].PlungeAxisMovement)
              flag = true;
          }
        }
      }
      if (marbleCam.CamBase == null)
        return;
      camTp camBase = marbleCam.CamBase;
