      camBase.Post = new PostProcessor(ccVars.PostActive);
      camBase.UsedCamPost = true;
      camBase.Post.RepetitionDef.Tool = false;
      camBase.Parameter = new camParameters5(marbleCam.setCam);
      camBase.Post.ToolDef.ToolData.PreCode.Clear();
      camBase.Post.SpindleDef.UseSpindle = true;
      camBase.Post.AxesUsing.Z = true;
      camBase.Post.AxesUsing.A = true;
      camBase.Post.AxesUsing.C = true;
      marbleCam.isCamCalculated = true;
      if (!buSystem.Canceled)
        ;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public int doConcaveWireframe(
    MWCalculationOptions MWCalcoptions,
    MarbleItem Item,
    MarbleItemCam ItemCam,
    List<List<buEntity>> CamEntities,
    ToolBase5 Tool,
    bool isConcave,
    ref camTp Cam)
  {
    string str = nameof (doConcaveWireframe);
    try
    {
      Cam = new camTp();
      double num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
      double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
      double num3 = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
      double num4 = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
      double plungeFirstVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
      double num5 = buMarbleCalc.varOperation.settingMarbleCam.MillingStepDown;
      double num6 = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
      if (ItemCam.ToolType == MarbleToolType.MillingHead)
      {
        num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
        num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
        num3 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
        num4 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
        plungeFirstVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
        num5 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadStepDown;
        num6 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
      }
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Runtime.SimG0DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG0DevideLength;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Runtime.SimG1DevideLength = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimulationG1DevideLength;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar = new camParameters5(ItemCam.setCam);
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.ClosedContour = CamClosedContourType.Inner;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Offsets.OpenContour = !isConcave ? (buMarbleCalc.varOperation.settingMarbleCam.ConcaveDirection != ClockDirectionType.CW ? CamOpenContourType.Right : CamOpenContourType.Left) : (buMarbleCalc.varOperation.settingMarbleCam.ConcaveDirection != ClockDirectionType.CW ? CamOpenContourType.Left : CamOpenContourType.Right);
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamPar(buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar, buMWMarbleVars.varCamMarbleOpenContourMilling.buPar);
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Air = 0.0;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe = num1;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid = num2;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.EntryAndExit = num2;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.EntryAndExit = num2;
      if (buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe < buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
        buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Safe = buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 1.0;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Strategy.TangentFirstAngleGreaterThen180StartMinusAngle = true;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.Feed = num3;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.Plunge = num4;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Speeds.FirstStep = plungeFirstVelocity;
      buMWMarbleVars.varCamMarbleOpenContourMilling.buPar.Steps.Enable = true;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStep = num5;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStep = num6;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.DepthStepMode = MachiningAreaRoughingParamsDepthStepMode.DsmConstantDepthStep;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = buMarbleCalc.varOperation.settingMarbleCam.TargetZ;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.CurMachType = MachiningParamsMachType.MachtypeZigzag;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.MachiningAreaMode = MachiningParamsMachiningAreaMode.MachByRegions;
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaRoughingParams.FirstDepthStepFlg = num6 > 0.0;
      clsMW.varMWCamWFContourPars = buMWCalcs.CopyCamParameter(buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar, buMWMarbleVars.varCamMarbleOpenContourMilling.buPar, out clsMW.varbuCamWFContourPars);
      clsMW.varMWCamWFContourPars.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.CuttingSide.ToString();
      buMWMarbleVars.varCamMarbleOpenContourMilling.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.CuttingSide.ToString();
      clsMW.varMWCamWFContourPars.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
      clsMW.varMWCamWFContourPars.MachParam.CutTolerance = buMarbleCalc.varOperation.settingMarbleCam.CutTolerance;
      clsMW.varMWCamWFContourPars.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.ToolpathOutputType = !buMarbleCalc.varOperation.settingMarbleCam.ToolPathPointDistributionMode ? TriangleMeshBasedTpCalcParamsToolpathOutputType.TotFitArcsAndPointDistribution : TriangleMeshBasedTpCalcParamsToolpathOutputType.TotPolygonizeAndPointDistribution;
      camResult Result = (camResult) null;
      clsMW.CamEntities.Clear();
      clsMW.CamEntitiesGroup.Clear();
      clsMW.varbuCamWFContourPars.Operations.Direction = ClockDirectionType.CW;
      for (int index1 = 0; index1 <= CamEntities.Count - 1; ++index1)
      {
        List<Entity> ChangedEntities = new List<Entity>();
        for (int index2 = 0; index2 <= CamEntities[index1].Count - 1; ++index2)
        {
          Entity copiedEntity1 = (Entity) null;
          buEntity.Copy(CamEntities[index1][index2], ref copiedEntity1);
          if (CamEntities[index1][index2] is buCircle)
          {
            buArc Arc1 = new buArc();
            buArc Arc2 = new buArc();
            buArc Arc3 = new buArc();
            buArc Arc4 = new buArc();
            clsInit.cVector5.CircletoFourArc((buCircle) CamEntities[index1][index2], ref Arc1, ref Arc2, ref Arc3, ref Arc4);
            Entity copiedEntity2 = (Entity) null;
            Entity copiedEntity3 = (Entity) null;
            Entity copiedEntity4 = (Entity) null;
            Entity copiedEntity5 = (Entity) null;
            buEntity.Copy((buEntity) Arc1, ref copiedEntity2);
            buEntity.Copy((buEntity) Arc2, ref copiedEntity3);
            buEntity.Copy((buEntity) Arc3, ref copiedEntity4);
            buEntity.Copy((buEntity) Arc4, ref copiedEntity5);
            ChangedEntities.Add(copiedEntity2);
            ChangedEntities.Add(copiedEntity3);
            ChangedEntities.Add(copiedEntity4);
            ChangedEntities.Add(copiedEntity5);
          }
          else
            ChangedEntities.Add(copiedEntity1);
        }
        if (clsInit.cVector5.EntitiesClockDirection(ChangedEntities) == ClockDirectionType.CCW)
          clsInit.cVector5.ChangeEntitiesDirection(ref ChangedEntities);
        clsMW.CamEntitiesGroup.Add(ChangedEntities);
