          else if (buMarbleCalc.varOperation.CuttingSequence[index1] == MarbleOperationSequence.MillingCuttings)
          {
            if (!Cams[index2].Used & (Cams[index2].TypeCam == CamType.MillingCut | Cams[index2].TypeCam == CamType.Rough | Cams[index2].TypeCam == CamType.ParallelCut | Cams[index2].TypeCam == CamType.ConstantZ | Cams[index2].TypeCam == CamType.ConstantCusp | Cams[index2].TypeCam == CamType.Flatlands | Cams[index2].TypeCam == CamType.Pencil) & buMarbleCalc.varOperation.settingMarbleCam.UseMillingCuttings)
            {
              Cams[index2].Used = true;
              JobCam.Add(Cams[index2]);
