            {
              Cams[index2].Used = true;
              JobCam.Add(Cams[index2]);
            }
          }
          else if (buMarbleCalc.varOperation.CuttingSequence[index1] == MarbleOperationSequence.SawStraight)
          {
            if ((Cams[index2].Used ? 0 : (Cams[index2].TypeCam == CamType.SawCut & buMarbleCalc.varOperation.settingMarbleCam.UseSawCuttings ? 1 : 0)) != 0)
            {
