            num2 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolXOffset;
            num3 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolYOffset;
            num4 = buMarbleCalc.varMarbleMachineSettings.SimulationSettings.SimCalcLaserPointerToolZOffset;
          }
          cam.SimilationPoint.SimMove[index4].X += num2;
          cam.SimilationPoint.SimMove[index4].Y += num3;
          cam.SimilationPoint.SimMove[index4].Z += num4;
          if (index4 % num1 == 0)
          {
            e.Job = $"{buLangTranslate.preDef.Simulation} {buLangTranslate.preDef.Move} {buLangTranslate.preDef.Calculating}";
            e.ActiveProgressPercentage = Convert.ToDouble(index4 + 1) / Convert.ToDouble(cam.SimilationPoint.SimMove.Count) * 100.0;
            clsInit.appCommand.CalculationInProgressCmd(e);
          }
        }
      }
    }
    Job.isSimulationDone = true;
    if (clsItem.FrmProgress == null)
      return;
    clsItem.FrmProgress.Visible = false;
  }

  public void doCreateGCode(MarbleJob Job, ref string strGCodes)
  {
    string str = nameof (doCreateGCode);
    try
    {
      PostProcessor Post = new PostProcessor(ccVars.PostActive);
      if (buMarbleCalc.varOperation.settingMarbleCam.MoveZCAAxesToSafeDistance)
      {
        Post.EndLines.Insert(0, (object) "M50");
        Post.EndLines.Insert(1, (object) "G0 A0");
        Post.EndLines.Insert(2, (object) ("G0 Z" + buMarbleCalc.varOperation.settingMarbleCam.JobFinishZPostion.ToString()));
        Post.EndLines.Insert(3, (object) "G0 C0");
      }
      strGCodes = "";
      clsInit.cGcodeCreate.CreatGCode(Job.Cams, Post, ref strGCodes);
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void SetMillingCamParameter(MarbleCamParameterSetArg Data, ref MarbleItemCam marbleCam)
  {
    if (Data.GeneralCamType == CamType.ContourOpen)
    {
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleOpenContourMilling.buPar);
      marbleCam.WireType = CamWireFrameType.Contour;
    }
    else if (Data.GeneralCamType == CamType.Contour | Data.GeneralCamType == CamType.ContourClosed)
    {
      marbleCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleClosedContourMilling.buPar);
      marbleCam.WireType = CamWireFrameType.Contour;
    }
    marbleCam.CamMode = Data.MarbleCamMode;
    marbleCam.CamMarbleType = Data.MarbleCamType;
    marbleCam.CamType = Data.GeneralCamType;
    marbleCam.setCam.Steps.StartValue = buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + Data.ZOffset;
    marbleCam.setCam.Steps.EndValue = buMarbleCalc.varOperation.settingMarbleCam.TargetZ + Data.ZOffset;
    marbleCam.setCam.Distances.Air = 0.0;
    marbleCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
    marbleCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
    marbleCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
    marbleCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
    marbleCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
    marbleCam.setCam.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingStepDown;
    marbleCam.setCam.Steps.FirstValue = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
    marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
    marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
    if (Data.ToolType == MarbleToolType.MillingHead)
    {
      marbleCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
      marbleCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
      marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
      marbleCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
      marbleCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
      marbleCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
      marbleCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
      marbleCam.setCam.Steps.DepthStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadStepDown;
      marbleCam.setCam.Steps.FirstValue = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
    }
    if (marbleCam.setCam.Distances.Safe >= marbleCam.setCam.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness)
      return;
    marbleCam.setCam.Distances.Safe = marbleCam.setCam.Distances.Rapid + buMarbleCalc.varOperation.MaterialParameter.MaterialThickness + 1.0;
  }

  public void doDeleteItems(bool All, int ItemID)
  {
    try
    {
      if (All)
      {
        buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
        dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
        dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteAllItem);
        int num = (int) dialogMessageBoxYesNo.ShowDialog();
        if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
          return;
        this.UndoBuffer();
        MarbleTempVars.VacuumEnable = false;
        MarbleTempVars.ItemID = 1;
        MarbleTempVars.MarbleCamID = 1;
        MarbleTempVars.MarbleEdgeID = 1;
        MarbleTempVars.MarbleStripID = 1;
        if (this.activeJob.VacuumCuts != null)
          this.activeJob.VacuumCuts.Clear();
        this.activeJob.Items.Clear();
        this.activeJob.Cams.Clear();
        this.activeJob.GCode = "";
        if (this.activeJob.VacuumMaterials != null)
          this.activeJob.VacuumMaterials.Clear();
        clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref this.activeJob);
      }
      else if (ItemID >= 0 & ItemID <= this.activeJob.Items.Count - 1)
      {
        buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
        dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
        dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisItem);
        int num = (int) dialogMessageBoxYesNo.ShowDialog();
        if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
          return;
        this.UndoBuffer();
        this.activeJob.Items.RemoveAt(ItemID);
      }
      else
      {
        this.activeJob.Cams.Clear();
        List<CustomData> customDataList = new List<CustomData>();
        int num1 = -1;
        for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
        {
          if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].Selected && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData != null & ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData is CustomData)
          {
            CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData as CustomData;
            int result = -1;
            int.TryParse(entityData.ID, out result);
            if (result >= 0)
            {
              customDataList.Add(entityData);
              num1 = result;
            }
          }
        }
        if (customDataList.Count > 0)
        {
          buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
          dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
          dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisItem);
          int num2 = (int) dialogMessageBoxYesNo.ShowDialog();
          if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
            return;
          this.UndoBuffer();
          for (int index1 = 0; index1 <= customDataList.Count - 1; ++index1)
          {
            if ((customDataList[index1].Command == null ? 0 : (customDataList[index1].Command.Length > 1 ? 1 : 0)) != 0)
            {
              EntityCommandArgs e = new EntityCommandArgs();
              e.Result = clsInit.cMarble.GetEntityCommand(customDataList[index1].Command, ref e);
              if (e.Result)
              {
                string command1 = e.Command;
                MarbleCommandsEntity marbleCommandsEntity = MarbleCommandsEntity.Slat;
                string str1 = marbleCommandsEntity.ToString();
                if (command1 == str1)
                  this.doSlatDelete(e.ItemID, e.EdgeIndex);
                string command2 = e.Command;
                marbleCommandsEntity = MarbleCommandsEntity.Operation;
                string str2 = marbleCommandsEntity.ToString();
                if (command2 == str2)
                {
                  for (int index2 = this.activeJob.Items.Count - 1; index2 >= 0; --index2)
                  {
                    if (this.activeJob.Items[index2].ID == num1)
                      this.activeJob.Items.RemoveAt(index2);
                  }
                }
              }
            }
            else if (this.activeJob.Items.Count > 0)
            {
              for (int index3 = this.activeJob.Items.Count - 1; index3 >= 0; --index3)
              {
                if (this.activeJob.Items[index3].ID == num1)
                  this.activeJob.Items.RemoveAt(index3);
              }
            }
          }
          clsInit.cMarble.JobCamCalculatedReset(true, true, false, -1, ref this.activeJob);
        }
      }
      this.activeJob.CamCalculated = false;
      AppBool.EditMode = false;
      this.doDrawActiveJob();
      this.JobUpdate();
      clsInit.appCommand.Reset();
    }
    catch (Exception ex)
    {
    }
  }

  public void doDeleteCam(bool All, int JobIndex, int CamIndex)
  {
    if (All)
    {
      buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
      dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
      dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteAllToolpath);
      int num = (int) dialogMessageBoxYesNo.ShowDialog();
      if (dialogMessageBoxYesNo.Result == DialogResult.Yes)
      {
        for (int index = 0; index <= this.activeJob.Items.Count - 1; ++index)
          this.activeJob.Items[index].CamList.Clear();
      }
    }
    else if (JobIndex >= 0 & JobIndex <= this.activeJob.Items.Count - 1 && CamIndex >= 0 & CamIndex <= this.activeJob.Items[JobIndex].CamList.Count - 1)
    {
      buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
      dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
      dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Delete, buLangTranslate.preSentencesMarble.DoyouWanttoDeleteThisToolpath);
      int num = (int) dialogMessageBoxYesNo.ShowDialog();
      if (dialogMessageBoxYesNo.Result == DialogResult.Yes)
        this.activeJob.Items[JobIndex].CamList.RemoveAt(CamIndex);
    }
    this.activeJob.CamCalculated = false;
    this.doCamCalculateMarbleJob(ref this.activeJob);
    this.JobUpdate();
    this.doDrawActiveJob();
    clsInit.appCommand.Reset();
  }

  public void doVisibleItems(bool All, int ItemID)
  {
    if (All)
    {
      this.UndoBuffer();
      for (int index = 0; index <= this.activeJob.Items.Count - 1; ++index)
        this.activeJob.Items[index].Visible = !this.activeJob.Items[index].Visible;
    }
    else
    {
      if (!(ItemID >= 0 & ItemID <= this.activeJob.Items.Count - 1))
