  public void doVisibleCam(bool All, int JobIndex, int CamIndex)
  {
    if (All)
    {
      bool flag1 = false;
      bool flag2 = false;
      if (this.activeJob.Items.Count > 0)
      {
        for (int index1 = 0; index1 <= this.activeJob.Items.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= this.activeJob.Items[index1].CamList.Count - 1; index2 = this.activeJob.Items[index1].CamList.Count + 1)
          {
            flag1 = this.activeJob.Items[index1].CamList[index2].Visible;
            flag2 = true;
          }
          if (flag2)
            index1 = this.activeJob.Items.Count;
        }
      }
      for (int index3 = 0; index3 <= this.activeJob.Items.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= this.activeJob.Items[index3].CamList.Count - 1; ++index4)
          this.activeJob.Items[index3].CamList[index4].Visible = !flag1;
      }
    }
    else if (JobIndex >= 0 & JobIndex <= this.activeJob.Items.Count - 1 && CamIndex >= 0 & CamIndex <= this.activeJob.Items[JobIndex].CamList.Count - 1)
      this.activeJob.Items[JobIndex].CamList[CamIndex].Visible = !this.activeJob.Items[JobIndex].CamList[CamIndex].Visible;
    this.doDrawActiveJob();
  }

  public void doMoveExecute(object Data1, object Data2, object Data3)
  {
    if (Data1 == null)
      return;
    if (Data1.ToString() == "MoveX" && Data2 != null)
    {
      buMarbleCalc.varMarbleRunSettings.ManuelMove = clsMarble.frmMove.spn_move.Value;
      buMarbleCalc.varMarbleRunSettings.ManuelRotate = clsMarble.frmMove.spn_rotate.Value;
      this.doMoveSelectedItem(Convert.ToDouble(Data2.ToString()), 0.0);
    }
    if (Data1.ToString() == "MoveY" && Data2 != null)
    {
      buMarbleCalc.varMarbleRunSettings.ManuelMove = clsMarble.frmMove.spn_move.Value;
      buMarbleCalc.varMarbleRunSettings.ManuelRotate = clsMarble.frmMove.spn_rotate.Value;
      this.doMoveSelectedItem(0.0, Convert.ToDouble(Data2.ToString()));
    }
    if (Data1.ToString() == "Rotate" && Data2 != null)
    {
      buMarbleCalc.varMarbleRunSettings.ManuelMove = clsMarble.frmMove.spn_move.Value;
      buMarbleCalc.varMarbleRunSettings.ManuelRotate = clsMarble.frmMove.spn_rotate.Value;
      this.doRotateSelectedItem(Convert.ToDouble(Data2.ToString()));
    }
    if (Data1.ToString() == "Close")
    {
      if (this.tempJob != null)
      {
        this.activeJob = new MarbleJob(this.tempJob);
        this.activeJob.CamCalculated = false;
      }
      this.tempJob = (MarbleJob) null;
      this.doCamCalculateMarbleJob(ref this.activeJob);
      this.JobUpdate();
      this.doDrawActiveJob();
    }
    if (!(Data1.ToString() == "MoveOk"))
      return;
    this.SaveMarbleFile();
    this.doCamCalculateMarbleJob(ref this.activeJob);
    this.JobUpdate();
    this.doDrawActiveJob();
  }

  public void doMoveSelectedItem(double dX, double dY)
  {
    MarbleTempVars.LastSelectedEntitiesList.Clear();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData)
        MarbleTempVars.LastSelectedEntitiesList.Add(index);
    }
    if (MarbleTempVars.LastSelectedEntitiesList.Count > 0)
      this.UndoBuffer();
    for (int index1 = 0; index1 <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; ++index1)
    {
      CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[index1]].EntityData as CustomData;
      if (entityData.typeDefination == entityTypeDefination.MarbleItem & entityData.ID.Trim().Length >= 0)
      {
        int result = -1;
        int.TryParse(entityData.ID, out result);
        if (result >= 0)
        {
          for (int index2 = 0; index2 <= this.activeJob.Items.Count - 1; ++index2)
          {
            if (this.activeJob.Items[index2].ID == result)
            {
              MarbleItem marbleItem = this.activeJob.Items[index2];
              clsInit.cMarble.MoveItem(ref marbleItem, dX, dY, 0.0);
              this.activeJob.CamCalculated = false;
            }
          }
        }
      }
    }
    ccVars.pntSelectedMid.X += dX;
    ccVars.pntSelectedMid.Y += dY;
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    this.doDrawActiveJob();
    this.SetSelectedToEntities();
  }

