            {
              Point3D MinPoint = new Point3D();
              Point3D MidPoint = new Point3D();
              Point3D MaxPoint = new Point3D();
              clsInit.cVector5.BoxSizeCalculate(entity, ref MinPoint, ref MidPoint, ref MaxPoint);
              MarbleItem marbleItem = this.activeJob.Items[index2];
              clsInit.cMarble.RotateItem(ref marbleItem, Rotation, ccVars.pntSelectedMid);
              break;
            }
          }
        }
      }
    }
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    this.doDrawActiveJob();
    this.SetSelectedToEntities();
  }

  public void doMirrorSelectedItem()
  {
    MarbleTempVars.LastSelectedEntitiesList.Clear();
    List<Entity> refEntities = new List<Entity>();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData)
      {
        MarbleTempVars.LastSelectedEntitiesList.Add(index);
        refEntities.Add(entity);
      }
    }
    if (MarbleTempVars.LastSelectedEntitiesList.Count <= 0)
      return;
    this.UndoBuffer();
    Point3D MinPoint = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
    int count = this.activeJob.Items.Count;
    Point3D pointBase = new Point3D();
    Point3D pointMirror = new Point3D();
    double num = buMarbleCalc.varMarbleRunSettings.MirrorDistance;
    if (num < buMarbleCalc.activeToolSaw.Geometry.Thickness)
      num = buMarbleCalc.activeToolSaw.Geometry.Thickness;
    if (buMarbleCalc.varMarbleRunSettings.MirrorType == MirrorAxisXYType.X)
    {
      pointBase.X = MaxPoint.X + num;
      pointBase.Y = MinPoint.Y;
      pointMirror.X = MaxPoint.X + num;
      pointMirror.Y = MaxPoint.Y;
    }
    else
    {
      pointBase.X = MinPoint.X;
      pointBase.Y = MaxPoint.Y + num;
      pointMirror.X = MaxPoint.X;
      pointMirror.Y = MaxPoint.Y + num;
    }
    for (int index1 = 0; index1 <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; ++index1)
    {
      CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[index1]].EntityData as CustomData;
      if (entityData.typeDefination == entityTypeDefination.MarbleItem & entityData.ID.Trim().Length >= 0)
      {
        int result = -1;
        int.TryParse(entityData.ID, out result);
        if (result >= 0)
        {
          for (int index2 = 0; index2 <= this.activeJob.Items.Count - 1; ++index2)
          {
            if (this.activeJob.Items[index2].ID == result)
            {
              if (buMarbleCalc.varMarbleRunSettings.MirrorDeleteOriginale)
              {
                MarbleItem marbleItem = this.activeJob.Items[index2];
                clsInit.cMarble.MirrorItem(ref marbleItem, pointBase, pointMirror);
              }
              else
              {
                MarbleItem marbleItem = new MarbleItem(this.activeJob.Items[index2]);
                marbleItem.ID = MarbleTempVars.ItemID;
                clsInit.cMarble.MirrorItem(ref marbleItem, pointBase, pointMirror);
                this.activeJob.Items.Add(marbleItem);
                ++MarbleTempVars.ItemID;
              }
              this.activeJob.CamCalculated = false;
              break;
            }
          }
        }
      }
    }
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    AppBool.EditMode = false;
    this.doDrawActiveJob();
    this.activeJob.CamCalculated = false;
  }

  public void doScaleSelectedItem()
  {
    MarbleTempVars.LastSelectedEntitiesList.Clear();
    List<Entity> refEntities = new List<Entity>();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData)
      {
        MarbleTempVars.LastSelectedEntitiesList.Add(index);
        refEntities.Add(entity);
      }
    }
    if (MarbleTempVars.LastSelectedEntitiesList.Count <= 0)
      return;
    this.UndoBuffer();
    Point3D MinPoint = new Point3D();
    Point3D MidPoint = new Point3D();
    Point3D MaxPoint = new Point3D();
    clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MidPoint, ref MaxPoint);
    double num1 = MaxPoint.X - MinPoint.X;
    double num2 = MaxPoint.Y - MinPoint.Y;
    double num3 = num1 / num2;
    double RatioX = 1.0;
    double RatioY = 1.0;
    if (num1 > 0.0)
      RatioX = buMarbleCalc.varMarbleRunSettings.ScaleWidth / num1;
    if (num2 > 0.0)
      RatioY = buMarbleCalc.varMarbleRunSettings.ScaleHeight / num2;
    if (RatioX <= 0.0)
      RatioX = 1.0;
    if (RatioY <= 0.0)
      RatioY = 1.0;
    if (buMarbleCalc.varMarbleRunSettings.ScaleKeepRatio)
    {
      buMarbleCalc.varMarbleRunSettings.ScaleHeight = buMarbleCalc.varMarbleRunSettings.ScaleWidth / num3;
      RatioY = RatioX;
    }
    int count = this.activeJob.Items.Count;
    for (int index1 = 0; index1 <= MarbleTempVars.LastSelectedEntitiesList.Count - 1; ++index1)
    {
      CustomData entityData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[MarbleTempVars.LastSelectedEntitiesList[index1]].EntityData as CustomData;
      if (entityData.typeDefination == entityTypeDefination.MarbleItem & entityData.ID.Trim().Length >= 0)
      {
        int result = -1;
        int.TryParse(entityData.ID, out result);
        if (result >= 0)
        {
          for (int index2 = 0; index2 <= this.activeJob.Items.Count - 1; ++index2)
          {
            if (this.activeJob.Items[index2].ID == result)
            {
              MarbleItem marbleItem = this.activeJob.Items[index2];
              clsInit.cMarble.ScaleItem(ref marbleItem, MinPoint, RatioX, RatioY);
              this.activeJob.CamCalculated = false;
              break;
            }
          }
        }
      }
    }
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    AppBool.EditMode = false;
    this.doDrawActiveJob();
    this.activeJob.CamCalculated = false;
  }

  public void doSetAngle()
  {
    List<int> intList = new List<int>();
    List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
    List<int> EntList = new List<int>();
    EdgeFoundArgs Args = new EdgeFoundArgs();
    this.doGetEdgeList(ref Lst, ref EntList, ref Args);
    if (Lst.Count == 0)
    {
      buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
    }
    else
    {
      if (Lst.Count >= 2)
      {
        buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
        dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
        dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.ThereisMoreThanOneEdgeDoYouWanttoContinue);
        int num = (int) dialogMessageBoxYesNo.ShowDialog();
        if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
        {
          clsInit.appCommand.Reset();
          return;
        }
      }
      F_MarbleSetAngle fMarbleSetAngle = new F_MarbleSetAngle();
      fMarbleSetAngle.AngleValue = Args.FoundAngle;
      fMarbleSetAngle.Init();
      int num1 = (int) fMarbleSetAngle.ShowDialog();
      if (fMarbleSetAngle.PropertiesForm.Result != DialogResult.OK)
        return;
      if (Math.Abs(fMarbleSetAngle.AngleValue) > buMarbleCalc.varOperation.settingMarbleCam.MaxAllowedAngleA)
      {
        buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.AAxisAngleisGreaterThenAllowedLimit);
      }
      else
      {
        this.activeJob.CamCalculated = false;
        for (int index = 0; index <= EntList.Count - 1; ++index)
        {
          if (EntList[index] >= 0 & EntList[index] <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
          {
            Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntList[index]];
            if (entity.EntityData is CustomData)
              ((CustomData) entity.EntityData).infoAngle = fMarbleSetAngle.AngleValue;
          }
        }
        if (Lst.Count > 0)
          this.UndoBuffer();
        for (int index1 = 0; index1 <= Lst.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index2)
          {
            if (Lst[index1].ID == clsInit.appMarble.activeJob.Items[index2].ID)
            {
              int CamIndex = -1;
              int EdgeIndex = -1;
              if (Lst[index1].CamID >= 0 & Lst[index1].EdgeID >= 0)
              {
                clsInit.cMarble.GetCamIndexFromCamID(this.activeJob.Items[index2].CamList, Lst[index1].CamID, ref CamIndex);
                clsInit.cMarble.GetEdgeIndexFromEdgeID(this.activeJob.Items[index2].Edges, Lst[index1].EdgeID, ref EdgeIndex);
                if (CamIndex >= 0)
                {
                  MarbleItemCam cam = this.activeJob.Items[index2].CamList[CamIndex];
                  if ((cam.EntityList == null ? 0 : (Lst[index1].indexEntity >= 0 & Lst[index1].indexEntity <= cam.EntityList.Entities.Count - 1 ? 1 : 0)) != 0)
                  {
                    cam.EntityList.Entities[Lst[index1].indexEntity].Orientation.A = fMarbleSetAngle.AngleValue;
                    cam.EntityList.Entities[Lst[index1].indexEntity].Marble.Angle = fMarbleSetAngle.AngleValue;
                  }
                }
                if (EdgeIndex >= 0 & EdgeIndex <= this.activeJob.Items[index2].Edges.Count - 1)
                  this.activeJob.Items[index2].Edges[EdgeIndex].Angle = fMarbleSetAngle.AngleValue;
              }
            }
          }
        }
        clsInit.appMarble.activeJob.CamCalculated = false;
        for (int index3 = 0; index3 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index3)
        {
          if (clsInit.appMarble.activeJob.Items[index3].ItemType == MarbleItemType.Shape | clsInit.appMarble.activeJob.Items[index3].ItemType == MarbleItemType.Contour)
          {
            MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[index3];
            this.doShapeCutCalculation(ref marbleItem);
            clsInit.cMarble.CamWireItemEntityToExtendEntity(ref marbleItem);
          }
          for (int index4 = 0; index4 <= clsInit.appMarble.activeJob.Items[index3].CamList.Count - 1; ++index4)
            clsInit.appMarble.activeJob.Items[index3].CamList[index4].isCamCalculated = false;
        }
        this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
        clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
        this.JobUpdate();
        this.doDrawActiveJob();
      }
    }
  }

  public void doSlatAdd(AddSlatArgs AddSlatData)
  {
    List<int> EntList = new List<int>();
    List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
    EdgeFoundArgs Args = new EdgeFoundArgs();
    DialogResult dialogResult;
    if (AddSlatData == null)
    {
      this.doGetEdgeList(ref Lst, ref EntList, ref Args);
      if (Lst.Count == 0)
      {
        buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
        return;
      }
      if (Lst.Count >= 2)
      {
        buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
        dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
        dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.MoreThanOneEdgeSelectedSelectOnlyOneEdge);
        int num = (int) dialogMessageBoxYesNo.ShowDialog();
        if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
        {
          clsInit.appCommand.Reset();
          return;
        }
      }
      F_MarbleSlat fMarbleSlat = new F_MarbleSlat();
      fMarbleSlat.RuntimeSettings = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings);
      fMarbleSlat.Init();
      int num1 = (int) fMarbleSlat.ShowDialog();
      dialogResult = fMarbleSlat.PropertiesForm.Result;
      buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(fMarbleSlat.RuntimeSettings);
    }
    else
    {
      Lst.Add(new ShapeEntityIndex()
      {
        indexEdge = AddSlatData.IndexEdge,
        indexEntity = AddSlatData.IndexEntity,
        ID = AddSlatData.ID,
        EdgeID = AddSlatData.EdgeID,
        CamID = AddSlatData.CamID
      });
      Args.Outside = true;
      dialogResult = DialogResult.OK;
    }
    if (dialogResult != DialogResult.OK)
      return;
    this.activeJob.CamCalculated = false;
    int num2 = -1;
    if (Lst.Count > 0)
      num2 = Lst[0].indexEntity;
    if (!(Args.Outside & num2 >= 0))
      return;
    this.UndoBuffer();
    for (int index1 = 0; index1 <= Lst.Count - 1; ++index1)
    {
      for (int index2 = 0; index2 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index2)
      {
        if (Lst[index1].ID == clsInit.appMarble.activeJob.Items[index2].ID)
        {
          int CamIndex = -1;
          int EdgeIndex = -1;
          MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[index2];
          MarbleItemCam marbleItemCam = (MarbleItemCam) null;
          if (Lst[index1].CamID >= 0 & Lst[index1].EdgeID >= 0)
          {
            clsInit.cMarble.GetCamIndexFromCamID(this.activeJob.Items[index2].CamList, Lst[index1].CamID, ref CamIndex);
            clsInit.cMarble.GetEdgeIndexFromEdgeID(this.activeJob.Items[index2].Edges, Lst[index1].EdgeID, ref EdgeIndex);
          }
          if ((CamIndex < 0 ? 0 : (EdgeIndex >= 0 ? 1 : 0)) != 0)
          {
            marbleItemCam = marbleItem.CamList[CamIndex];
            for (int index3 = 0; index3 <= marbleItem.CamList.Count - 1; ++index3)
              marbleItem.CamList[index3].isCamCalculated = false;
          }
          if (num2 <= marbleItem.EntGroup.Outside.Entities.Count - 1)
          {
            buEntity entity = marbleItem.EntGroup.Outside.Entities[num2];
            if (entity.Marble == null)
              entity.Marble = new MarbleInfo();
            entity.Marble.SlatWidth = buMarbleCalc.varMarbleRunSettings.SlatWidth;
            entity.Marble.SlatStartAngle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
            entity.Marble.SlatEndAngle = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
            if (buMarbleCalc.varMarbleRunSettings.SlatAddAngleSelectedEdge)
            {
              entity.Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
              entity.Marble.Angle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
              if (marbleItemCam != null && (marbleItemCam.EntityList == null ? 0 : (num2 >= 0 & num2 <= marbleItemCam.EntityList.Entities.Count - 1 ? 1 : 0)) != 0)
              {
                marbleItemCam.EntityList.Entities[num2].Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
                marbleItemCam.EntityList.Entities[num2].Marble.Angle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
              }
            }
            if (EdgeIndex <= marbleItem.Edges.Count - 1)
            {
              if (marbleItem.Edges[EdgeIndex].Slat == null)
                marbleItem.Edges[EdgeIndex].Slat = new marbleSlatPars();
              clsInit.cMarble.GetStripID(this.activeJob, ref marbleItem.Edges[EdgeIndex].Slat.DataSlat.StripID);
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.Enable = true;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.indexEntitiy = num2;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.ItemID = Lst[index1].ItemID;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.EdgeID = Lst[index1].EdgeID;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.CamID = Lst[index1].CamID;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.Width = buMarbleCalc.varMarbleRunSettings.SlatWidth;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.StartAngle = buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
              marbleItem.Edges[EdgeIndex].Slat.DataSlat.EndAngle = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
              clsInit.cMarble.CreatedSlatEntities(entity, marbleItem.EntGroup, ref marbleItem.Edges[EdgeIndex].Slat.Solid, ref marbleItem.Edges[EdgeIndex].Slat.cutEntities, ref marbleItem.Edges[EdgeIndex].Slat.connectEntities);
              marbleItem.Edges[EdgeIndex].Slat.Solid.EntityData = (object) new CustomData()
              {
                ID = marbleItem.ID.ToString(),
                Command = clsInit.cMarble.SetEntityCommand(MarbleCommandsEntity.Slat.ToString(), marbleItem.ID, num2, num2, -1, -1, "", "")
              };
              if (marbleItemCam != null)
              {
                marbleItemCam.isCamCalculated = false;
                if (marbleItemCam.WireAuxEntities == null)
                  marbleItemCam.WireAuxEntities = new List<List<buEntity>>();
                for (int index4 = 0; index4 <= marbleItem.Edges[EdgeIndex].Slat.cutEntities.Count - 1; ++index4)
                {
                  List<buEntity> refEntities = new List<buEntity>();
                  buEntity copiedEntity = (buEntity) null;
                  buEntity.Copy(marbleItem.Edges[EdgeIndex].Slat.cutEntities[index4], ref copiedEntity);
                  if (copiedEntity.Marble == null)
                    copiedEntity.Marble = new MarbleInfo();
                  refEntities.Add(copiedEntity);
                  if (index4 == 0)
                  {
                    copiedEntity.Orientation.A = marbleItem.Edges[EdgeIndex].Slat.DataSlat.StartAngle;
                    copiedEntity.Marble.Angle = marbleItem.Edges[EdgeIndex].Slat.DataSlat.StartAngle;
                  }
                  else
                  {
                    copiedEntity.Orientation.A = marbleItem.Edges[EdgeIndex].Slat.DataSlat.EndAngle;
                    copiedEntity.Marble.Angle = marbleItem.Edges[EdgeIndex].Slat.DataSlat.EndAngle;
                  }
                  clsInit.cVector5.Move(0.0, 0.0, marbleItem.Settings.settingMarbleCam.TargetZ, ref refEntities);
                  marbleConvexConcaveCalculationPars Pars = new marbleConvexConcaveCalculationPars();
                  List<List<buEntity>> SawEntities = new List<List<buEntity>>();
                  ClockDirectionType CDRefEnt = ClockDirectionType.CCW;
                  if (marbleItem.ClockDir == ClockDirectionType.CCW)
                  {
                    if (index4 == 0)
                    {
                      CDRefEnt = ClockDirectionType.CW;
                      refEntities[0].Orientation.A = -buMarbleCalc.varMarbleRunSettings.SlatStartAngle;
                    }
                    else
                    {
                      CDRefEnt = ClockDirectionType.CCW;
                      refEntities[0].Orientation.A = buMarbleCalc.varMarbleRunSettings.SlatEndAngle;
                    }
                  }
                  clsInit.cMarble.OffsetModifiedEntities(refEntities, CDRefEnt, Pars, marbleItemCam.ToolSelected, buMarbleCalc.varOperation, ref SawEntities);
                  if (SawEntities.Count > 0)
                  {
                    for (int index5 = 0; index5 <= SawEntities[0].Count - 1; ++index5)
                    {
                      if (SawEntities[0][index5].Marble == null)
                        SawEntities[0][index5].Marble = new MarbleInfo();
                      SawEntities[0][index5].Marble.Sequence = index4 != 0 ? CamSequence.StripStartCut : CamSequence.StripEndCut;
                      SawEntities[0][index5].Marble.ItemID = marbleItem.ID;
                      SawEntities[0][index5].Marble.indexEdge = num2;
                      SawEntities[0][index5].Marble.CommandID = marbleItem.Edges[EdgeIndex].Slat.DataSlat.StripID;
                      SawEntities[0][index5].Marble.Command = MarbleCommandsEntity.Slat;
                    }
                    marbleItemCam.WireAuxEntities.Add(SawEntities[0]);
                  }
                }
              }
            }
          }
          if (buMarbleCalc.varMarbleRunSettings.SlatAddAngleSelectedEdge)
            this.doShapeCutCalculation(ref marbleItem);
          clsInit.cMarble.ItemSizeCalculation(ref marbleItem);
        }
      }
    }
    this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
    clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
    this.JobUpdate();
    this.doDrawActiveJob();
  }

  public void doSlatDelete(int ItemID, int EdgeIndex)
  {
    int num = 0;
    for (int index1 = 0; index1 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index1)
    {
      if (clsInit.appMarble.activeJob.Items[index1].ID == ItemID)
      {
        if (num == 0)
          this.UndoBuffer();
        MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[index1];
        if (EdgeIndex >= 0 & EdgeIndex <= marbleItem.Edges.Count - 1)
        {
          marbleItem.Edges[EdgeIndex].Slat.DataSlat.Enable = false;
          marbleItem.Edges[EdgeIndex].Slat.Solid = (Entity) null;
        }
        for (int index2 = 0; index2 <= marbleItem.CamList.Count - 1; ++index2)
        {
          marbleItem.CamList[index2].isCamCalculated = false;
          if (marbleItem.CamList[index2].WireAuxEntities != null)
          {
            for (int index3 = marbleItem.CamList[index2].WireAuxEntities.Count - 1; index3 >= 0; --index3)
            {
              for (int index4 = marbleItem.CamList[index2].WireAuxEntities[index3].Count - 1; index4 >= 0; --index4)
              {
                buEntity buEntity = marbleItem.CamList[index2].WireAuxEntities[index3][index4];
                if ((buEntity.Marble.Command == MarbleCommandsEntity.None ? 0 : (buEntity.Marble.Command == MarbleCommandsEntity.Slat ? 1 : 0)) != 0 && buEntity.Marble.indexEdge == EdgeIndex & buEntity.Marble.ItemID == ItemID)
                  marbleItem.CamList[index2].WireAuxEntities[index3].RemoveAt(index4);
              }
              if (marbleItem.CamList[index2].WireAuxEntities[index3].Count == 0)
                marbleItem.CamList[index2].WireAuxEntities.RemoveAt(index3);
            }
          }
        }
        clsInit.cMarble.ItemSizeCalculation(ref marbleItem);
        ++num;
      }
    }
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
  }

  public void doCollopseAdd(AddCollapseArgs AddCollapseData)
  {
    List<int> intList = new List<int>();
    List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
    List<int> EntList = new List<int>();
    DialogResult dialogResult;
    if (AddCollapseData == null)
    {
      EdgeFoundArgs Args = new EdgeFoundArgs();
      this.doGetEdgeList(ref Lst, ref EntList, ref Args);
      if (Lst.Count == 0)
      {
        buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
        return;
      }
      F_MarbleCollapse fMarbleCollapse = new F_MarbleCollapse()
      {
        RuntimeSettings = new MarbleRuntimeSettings(buMarbleCalc.varMarbleRunSettings)
      };
      fMarbleCollapse.RuntimeSettings.CollapseEnable = true;
      fMarbleCollapse.Init();
      int num = (int) fMarbleCollapse.ShowDialog();
      dialogResult = fMarbleCollapse.PropertiesForm.Result;
      buMarbleCalc.varMarbleRunSettings = new MarbleRuntimeSettings(fMarbleCollapse.RuntimeSettings);
    }
    else
    {
      Lst.Add(new ShapeEntityIndex()
      {
        indexInside = AddCollapseData.IndexInsideEntity,
        ID = AddCollapseData.ItemID
      });
      dialogResult = DialogResult.OK;
    }
    if (dialogResult != DialogResult.OK)
      return;
    this.activeJob.CamCalculated = false;
    marbleCollapseItem marbleCollapseItem = new marbleCollapseItem();
    marbleCollapseItem.Depth = buMarbleCalc.varMarbleRunSettings.CollapseDepth;
    marbleCollapseItem.Offset = buMarbleCalc.varMarbleRunSettings.CollapseOffset;
    marbleCollapseItem.Direction = buMarbleCalc.varMarbleRunSettings.CollapseDirection;
    marbleCollapseItem.ToolType = buMarbleCalc.varMarbleRunSettings.CollapseToolType;
    marbleCollapseItem.EntityIndex = Lst[0].indexEntitySub;
    marbleCollapseItem.isOutsideEntity = Lst[0].Outside;
    marbleCollapseItem.Enable = buMarbleCalc.varMarbleRunSettings.CollapseEnable;
    if (!marbleCollapseItem.Enable)
    {
      this.UndoBuffer();
      for (int index = 0; index <= Lst.Count - 1; ++index)
        this.doCollopseRemove(Lst[index]);
      this.doDrawActiveJob();
    }
    else
    {
      if (Lst.Count > 0)
        this.UndoBuffer();
      for (int index1 = 0; index1 <= Lst.Count - 1; ++index1)
      {
        if (index1 == 0)
          marbleCollapseItem.ItemID = Lst[index1].ID;
        for (int index2 = 0; index2 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index2)
        {
          if (Lst[index1].ID == clsInit.appMarble.activeJob.Items[index2].ID)
          {
            MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[index2];
            if (!marbleCollapseItem.isOutsideEntity)
            {
              int indexInside = Lst[index1].indexInside;
              if ((marbleItem.EntGroup.Inside == null ? 0 : (indexInside >= 0 & indexInside <= marbleItem.EntGroup.Inside.Count - 1 ? 1 : 0)) != 0)
              {
                for (int index3 = 0; index3 <= marbleItem.EntGroup.Inside[indexInside].Entities.Count - 1; ++index3)
                {
                  if (marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble == null)
                    marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble = new MarbleInfo();
                  if (marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse == null)
                    marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse = new marbleCollapsePars();
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.Enable = buMarbleCalc.varMarbleRunSettings.CollapseEnable;
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.Depth = buMarbleCalc.varMarbleRunSettings.CollapseDepth;
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.Offset = buMarbleCalc.varMarbleRunSettings.CollapseOffset;
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.Step = buMarbleCalc.varMarbleRunSettings.CollapseStep;
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.ToolType = buMarbleCalc.varMarbleRunSettings.CollapseToolType;
                  marbleItem.EntGroup.Inside[indexInside].Entities[index1].Marble.Collapse.Direction = buMarbleCalc.varMarbleRunSettings.CollapseDirection;
                  marbleCollapseItem.IndexInsideEntity = indexInside;
                }
                buEntity.Copy(marbleItem.EntGroup.Inside[indexInside].Entities, ref marbleCollapseItem.refEntity);
              }
            }
            else if (marbleItem.EntGroup.Outside != null)
              buEntity.Copy(marbleItem.EntGroup.Outside.Entities, ref marbleCollapseItem.refEntity);
            if (marbleCollapseItem.refEntity != null)
            {
              clsInit.cVector5.Move(0.0, 0.0, marbleItem.SizeItem.Depth - marbleCollapseItem.Depth, ref marbleCollapseItem.refEntity);
              List<Point3D> Points = new List<Point3D>();
              clsInit.cVector5.EntitiesToPointsWithCamDirection(marbleCollapseItem.refEntity, ref Points);
              double amount;
              if (clsInit.cVector5.GetClockDirection(Points) == ClockDirectionType.CW)
              {
                amount = -marbleCollapseItem.Offset;
                if (marbleCollapseItem.Direction == OutsideInsideType.Inside)
                  amount = marbleCollapseItem.Offset;
              }
              else
              {
                amount = marbleCollapseItem.Offset;
                if (marbleCollapseItem.Direction == OutsideInsideType.Inside)
                  amount = -marbleCollapseItem.Offset;
              }
              LinearPath linearPath = new LinearPath((ICollection<Point3D>) Points);
              ICurve[] curveArray = linearPath.Offset(amount, Vector3D.AxisZ, true);
              if ((curveArray == null ? 0 : (curveArray.Length != 0 ? 1 : 0)) != 0)
              {
                buEntity copiedEntity1 = (buEntity) null;
                buEntity.Copy((Entity) curveArray[0], ref copiedEntity1);
                marbleCollapseItem.ContourEntity = new List<buEntity>();
                marbleCollapseItem.ContourEntity.Add(copiedEntity1);
                devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region((IList<ICurve>) new List<ICurve>()
                {
                  (ICurve) linearPath,
                  curveArray[0]
                }, Plane.XY);
                marbleCollapseItem.entSolid = (Entity) region.ExtrudeAsMesh(marbleCollapseItem.Depth, 0.1, Mesh.natureType.RichSmooth);
                marbleCollapseItem.entSolid.Translate(0.0, 0.0, marbleItem.SizeItem.Depth - marbleCollapseItem.Depth);
                marbleCollapseItem.entSolid.Color = Color.FromArgb(buMarbleCalc.varMarbleColorSettings.colorItemCollopse.Transperancy, buMarbleCalc.varMarbleColorSettings.colorItemCollopse.Color);
                MarbleItemCam marbleItemCam = new MarbleItemCam();
                marbleItemCam.setCam = new camParameters5(buMWMarbleVars.varCamMarbleClosedContourMilling.buPar);
                clsInit.cMarble.MarbleCamParameterToCamParameter(buMarbleCalc.varOperation.settingMarbleCam, marbleItemCam.ToolType, marbleItemCam.WireType, ref marbleItemCam.setCam);
                marbleItemCam.setCam.Steps.StartValue = marbleItem.SizeItem.Depth;
                marbleItemCam.setCam.Steps.EndValue = marbleItem.SizeItem.Depth - marbleCollapseItem.Depth;
                marbleItemCam.setCam.Offsets.ClosedContour = marbleCollapseItem.Direction != OutsideInsideType.Outside ? CamClosedContourType.Outter : CamClosedContourType.Inner;
                marbleItemCam.ToolType = marbleCollapseItem.ToolType;
                if (marbleItemCam.ToolType == MarbleToolType.MillingHead)
                {
                  marbleItemCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadCuttingVelocity;
                  marbleItemCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
                  marbleItemCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
                  marbleItemCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadSafeDistance;
                  marbleItemCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
                  marbleItemCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadRapidDistance;
                  marbleItemCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMillingHead);
                }
                else
                {
                  marbleItemCam.setCam.Speeds.Feed = buMarbleCalc.varOperation.settingMarbleCam.MillingCuttingVelocity;
                  marbleItemCam.setCam.Speeds.Plunge = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
                  marbleItemCam.setCam.Speeds.FirstStep = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
                  marbleItemCam.setCam.Distances.Safe = buMarbleCalc.varOperation.settingMarbleCam.MillingSafeDistance;
                  marbleItemCam.setCam.Distances.Rapid = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
                  marbleItemCam.setCam.Distances.EntryAndExit = buMarbleCalc.varOperation.settingMarbleCam.MillingRapidDistance;
                  marbleItemCam.ToolSelected = new ToolBase5(buMarbleCalc.activeToolMilling);
                }
                marbleItemCam.WireType = CamWireFrameType.Pocket;
                if (marbleItemCam.ToolSelected.Geometry.Diameter > marbleCollapseItem.Offset * 0.9)
                  marbleItemCam.WireType = CamWireFrameType.Contour;
                List<buEntity> copiedEntities = new List<buEntity>();
                marbleItemCam.EntityList = new buEntityList();
                if (marbleItemCam.WireType == CamWireFrameType.Pocket)
                {
                  buEntity.Copy(marbleCollapseItem.refEntity, ref copiedEntities);
                  marbleItemCam.EntityList.Entities.AddRange((IEnumerable<buEntity>) copiedEntities);
                }
                buEntity copiedEntity2 = (buEntity) null;
                buEntity.Copy(copiedEntity1, ref copiedEntity2);
                marbleItemCam.EntityList.Entities.Add(copiedEntity2);
                marbleItemCam.indexInside = marbleCollapseItem.EntityIndex;
                marbleItemCam.CamName = $"{buLangTranslate.preDef.Collapse} {buLangTranslate.preDef.Offset} {buLangTranslate.preDef.Cut}";
                marbleItemCam.CamMarbleType = MarbleCamType.Collapse;
                marbleItemCam.CamMode = MarbleCamMode.Contour;
                marbleItemCam.MeshType = buMarbleCalc.varMarbleRunSettings.selectedType.selectedMeshType;
                marbleItemCam.CamType = CamType.Contour;
                marbleItemCam.indexCollapse = marbleItem.Collapses.Count;
                clsInit.cMarble.GetCamID(this.activeJob, marbleItem.CamList, ref marbleItemCam.CamID);
                marbleItem.CamList.Add(marbleItemCam);
                marbleCollapseItem.ID = marbleItem.Collapses.Count;
                marbleItem.Collapses.Add(marbleCollapseItem);
              }
            }
          }
        }
      }
      clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
      this.doDrawActiveJob();
    }
  }

  public void doCollopseRemove(ShapeEntityIndex ShapeEntity)
  {
    int num = 0;
    for (int index1 = 0; index1 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index1)
    {
      if (ShapeEntity.ID == clsInit.appMarble.activeJob.Items[index1].ID)
      {
        MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[index1];
        if (!ShapeEntity.Outside)
        {
          for (int index2 = marbleItem.CamList.Count - 1; index2 >= 0; --index2)
          {
            MarbleItemCam cam = marbleItem.CamList[index2];
            if (cam.CamMarbleType == MarbleCamType.Collapse & cam.indexInside == ShapeEntity.indexEntitySub)
            {
              if (num == 0)
                this.UndoBuffer();
              if (cam.indexCollapse >= 0 & cam.indexCollapse <= marbleItem.Collapses.Count - 1)
                marbleItem.Collapses.RemoveAt(cam.indexCollapse);
              marbleItem.CamList.RemoveAt(index2);
              ++num;
            }
          }
        }
      }
    }
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
  }

  public void doExtend()
  {
    try
    {
      List<int> intList = new List<int>();
      List<ShapeEntityIndex> Lst = new List<ShapeEntityIndex>();
      List<int> EntList = new List<int>();
      EdgeFoundArgs Args = new EdgeFoundArgs();
      this.doGetEdgeList(ref Lst, ref EntList, ref Args);
      if (Lst.Count == 0)
      {
        buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
      }
      else
      {
        if (Lst.Count >= 2)
        {
          buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
          dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
          dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.MoreThanOneEdgeSelectedSelectOnlyOneEdge);
          int num = (int) dialogMessageBoxYesNo.ShowDialog();
          if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
          {
            clsInit.appCommand.Reset();
            return;
          }
        }
        F_MarbleEventExtend marbleEventExtend = new F_MarbleEventExtend();
        marbleEventExtend.spn_extend.Value = buMarbleCalc.varMarbleRunSettings.ExtendLength;
        marbleEventExtend.Init();
        int num1 = (int) marbleEventExtend.ShowDialog();
        if (marbleEventExtend.PropertiesForm.Result != DialogResult.OK)
          return;
        buMarbleCalc.varMarbleRunSettings.ExtendLength = marbleEventExtend.spn_extend.Value;
        if (buMarbleCalc.varMarbleRunSettings.ExtendLength == 0.0)
          return;
        this.activeJob.CamCalculated = false;
        if (Lst.Count > 0)
          this.UndoBuffer();
        for (int index1 = 0; index1 <= Lst.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index2)
          {
            if (Lst[index1].ID == clsInit.appMarble.activeJob.Items[index2].ID)
            {
              MarbleItem refItem = clsInit.appMarble.activeJob.Items[index2];
              clsInit.cMarble.ExtendItem(ref refItem, Lst[index1].indexEntity, Lst[index1].indexEntitySub, Lst[index1].indexEdge, Args.pntPick, buMarbleCalc.varMarbleRunSettings.ExtendLength);
              for (int index3 = 0; index3 <= clsInit.appMarble.activeJob.Items[index2].CamList.Count - 1; ++index3)
                clsInit.appMarble.activeJob.Items[index2].CamList[index3].isCamCalculated = false;
            }
          }
        }
        clsInit.appMarble.activeJob.CamCalculated = false;
        this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
        clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
        this.JobUpdate();
        this.doDrawActiveJob();
      }
    }
    catch (Exception ex)
    {
    }
  }

