  public void doOffset()
  {
    try
    {
      List<ShapeEntityIndex> shapeEntityIndexList = new List<ShapeEntityIndex>();
      bool outside = true;
      for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
      {
        Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
        if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData && ((CustomData) entity.EntityData).Tags == "Edge")
        {
          int result = -1;
          Point3D infoBasePoint = ((CustomData) entity.EntityData).infoBasePoint;
          if ((((CustomData) entity.EntityData).infoData == null ? 0 : (((CustomData) entity.EntityData).infoData == "Inside" ? 1 : 0)) != 0)
            outside = false;
          if (result.ToString().Trim().Length > 0)
            int.TryParse(((CustomData) entity.EntityData).ID, out result);
          if (result >= 0)
            shapeEntityIndexList.Add(new ShapeEntityIndex(((CustomData) entity.EntityData).EntitySubIndex, ((CustomData) entity.EntityData).EntityIndex, result, outside, ((CustomData) entity.EntityData).infoAngle, ((CustomData) entity.EntityData).RefIndex, ((CustomData) entity.EntityData).CamIndex));
        }
      }
      if (shapeEntityIndexList.Count == 0)
      {
        buString5.MessageBoxWarning(buLangTranslate.preSentencesMarble.NoSelectedEdge);
      }
      else
      {
        if (shapeEntityIndexList.Count >= 2)
        {
          buDialogMessageBoxYesNo dialogMessageBoxYesNo = new buDialogMessageBoxYesNo();
          dialogMessageBoxYesNo.StartPosition = FormStartPosition.CenterScreen;
          dialogMessageBoxYesNo.Init(buLangTranslate.preDef.Angle, buLangTranslate.preSentencesMarble.ThereisMoreThanOneEdgeDoYouWanttoContinue);
          int num = (int) dialogMessageBoxYesNo.ShowDialog();
          if (dialogMessageBoxYesNo.Result != DialogResult.Yes)
          {
            clsInit.appCommand.Reset();
            return;
          }
        }
        F_MarbleEventOffset marbleEventOffset = new F_MarbleEventOffset();
        marbleEventOffset.Init();
        int num1 = (int) marbleEventOffset.ShowDialog();
        if (marbleEventOffset.PropertiesForm.Result != DialogResult.OK || buMarbleCalc.varMarbleRunSettings.ExtendLength == 0.0)
          return;
        this.activeJob.CamCalculated = false;
        if (shapeEntityIndexList.Count > 0)
          this.UndoBuffer();
        for (int index1 = 0; index1 <= shapeEntityIndexList.Count - 1; ++index1)
        {
          for (int index2 = 0; index2 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index2)
          {
            if (shapeEntityIndexList[index1].ID == clsInit.appMarble.activeJob.Items[index2].ID)
            {
              MarbleItem refItem = clsInit.appMarble.activeJob.Items[index2];
              clsInit.cMarble.OffsetItem(ref refItem, shapeEntityIndexList[index1].indexEntity, shapeEntityIndexList[index1].indexEntitySub, buMarbleCalc.varMarbleRunSettings.OffsetDistance);
              this.entitiesGroupForContour.Clear();
              this.entitiesGroupForContour.Add(new buEntitiesGroup(refItem.EntGroup));
              this.doAddItemShapeContour(new Point3D(), false, true, false, false, false, false, buMarbleCalc.varMarbleSettings.ContourOnlineCamCalculation, index2);
              for (int index3 = 0; index3 <= clsInit.appMarble.activeJob.Items[index2].CamList.Count - 1; ++index3)
                clsInit.appMarble.activeJob.Items[index2].CamList[index3].isCamCalculated = false;
            }
          }
        }
        clsInit.appMarble.activeJob.CamCalculated = false;
        this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
        clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
        this.JobUpdate();
        this.doDrawActiveJob();
      }
    }
    catch (Exception ex)
    {
    }
  }

  public void doAlignmentMove(MarbleCadCamCommands Cmd, double Value)
  {
    double dX = 0.0;
    double dY = 0.0;
    switch (Cmd)
    {
      case MarbleCadCamCommands.MoveLeft:
        dX = -Value;
        break;
      case MarbleCadCamCommands.MoveLeftUp:
        dX = -Value;
        dY = Value;
        break;
      case MarbleCadCamCommands.MoveLeftDown:
        dX = -Value;
        dY = -Value;
        break;
      case MarbleCadCamCommands.MoveUp:
        dY = Value;
        break;
      case MarbleCadCamCommands.MoveDown:
        dY = -Value;
        break;
      case MarbleCadCamCommands.MoveRight:
        dX = Value;
        break;
      case MarbleCadCamCommands.MoveRightUp:
        dX = Value;
        dY = Value;
        break;
      case MarbleCadCamCommands.MoveRightDown:
        dX = Value;
        dY = -Value;
        break;
    }
    if (buMarbleCalc.SelectedItem.SelectionItems.Count == 0)
      this.doMoveAllItem(dX, dY);
    else
      this.doMoveSelectedItem(dX, dY);
  }

  public void doAlignment(MarbleCadCamCommands Cmd, double Value)
  {
    double dX = 0.0;
    double dY = 0.0;
    Point3D point3D1 = new Point3D();
    Point3D point3D2 = new Point3D();
    double num1 = buMarbleCalc.varMarbleMachineSettings.BaseWoodHeight;
    if (clsInit.appMarble.activeJob.Material.Enable)
      num1 = clsInit.appMarble.activeJob.Material.Size.Height;
    double num2 = buMarbleCalc.varMarbleMachineSettings.BaseWoodWidth;
    if (clsInit.appMarble.activeJob.Material.Enable)
      num2 = clsInit.appMarble.activeJob.Material.Size.Width;
    Point3D point3D3;
    Point3D point3D4;
    if (buMarbleCalc.SelectedItem.SelectionItems.Count == 0)
    {
      clsInit.cMarble.GetBoxSizeJobItems(this.activeJob, ref this.activeJob.SizeOfOperations.MinPoint, ref this.activeJob.SizeOfOperations.MaxPoint);
      point3D3 = buVector5.ToPoint3D(this.activeJob.SizeOfOperations.MinPoint);
      point3D4 = buVector5.ToPoint3D(this.activeJob.SizeOfOperations.MaxPoint);
    }
    else
    {
      clsInit.cMarble.GetBoxSizeSelectedItems(ref buMarbleCalc.SelectedItem);
      point3D3 = buVector5.ToPoint3D(buMarbleCalc.SelectedItem.pntTotalMin);
      point3D4 = buVector5.ToPoint3D(buMarbleCalc.SelectedItem.pntTotalMax);
    }
    if (Cmd == MarbleCadCamCommands.MagnetLeftDown)
    {
      dX = -point3D3.X;
      dY = -point3D3.Y;
    }
    if (Cmd == MarbleCadCamCommands.MagnetLeft)
      dX = -point3D3.X;
    if (Cmd == MarbleCadCamCommands.MagnetLeftUp)
    {
      dX = -point3D3.X;
      dY = num1 - point3D4.Y;
    }
    if (Cmd == MarbleCadCamCommands.MagnetRightDown)
    {
      dX = num2 - point3D4.X;
      dY = -point3D3.Y;
    }
    if (Cmd == MarbleCadCamCommands.MagnetRight)
      dX = num2 - point3D4.X;
    if (Cmd == MarbleCadCamCommands.MagnetRightUp)
    {
      dX = num2 - point3D4.X;
      dY = num1 - point3D4.Y;
    }
    if (Cmd == MarbleCadCamCommands.MagnetDown)
      dY = -point3D3.Y;
    if (Cmd == MarbleCadCamCommands.MagnetUp)
      dY = num1 - point3D4.Y;
    if (buMarbleCalc.SelectedItem.SelectionItems.Count > 0)
    {
      List<buEntity> Entities = new List<buEntity>();
      for (int index1 = 0; index1 <= this.activeJob.Items.Count - 1; ++index1)
      {
        MarbleItem marbleItem = this.activeJob.Items[index1];
        bool flag = false;
        for (int index2 = 0; index2 <= buMarbleCalc.SelectedItem.SelectionItems.Count - 1; ++index2)
        {
          if (index1 == buMarbleCalc.SelectedItem.SelectionItems[index2].indexItem)
          {
            flag = true;
            index2 = buMarbleCalc.SelectedItem.SelectionItems.Count;
          }
        }
        if (!flag)
        {
          if ((marbleItem.EntGroup == null ? 0 : (marbleItem.EntGroup.Outside.Entities.Count > 0 ? 1 : 0)) != 0)
          {
            for (int index3 = 0; index3 <= marbleItem.EntGroup.Outside.Entities.Count - 1; ++index3)
              Entities.Add(marbleItem.EntGroup.Outside.Entities[index3]);
          }
          else if ((marbleItem.ItemEntities.WireEntities == null ? 0 : (marbleItem.ItemEntities.WireEntities.Count > 0 ? 1 : 0)) != 0)
          {
            for (int index4 = 0; index4 <= marbleItem.ItemEntities.WireEntities.Count - 1; ++index4)
            {
              Point3D MinPoint = new Point3D();
              Point3D MaxPoint = new Point3D();
              clsInit.cVector5.BoxSizeCalculate(marbleItem.ItemEntities.WireEntities[index4], ref MinPoint, ref MaxPoint);
              for (int index5 = 0; index5 <= marbleItem.ItemEntities.WireEntities[index4].Count - 1; ++index5)
              {
                buEntity copiedEntity = (buEntity) null;
                buEntity.Copy(marbleItem.ItemEntities.WireEntities[index4][index5], ref copiedEntity);
                copiedEntity.Translate(0.0, 0.0, -MinPoint.Z);
                Entities.Add(copiedEntity);
              }
            }
          }
        }
      }
      if (Entities.Count > 0)
      {
        buLine refEntity1 = (buLine) null;
        buLine refEntity2 = (buLine) null;
        if (Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetLeft)
          refEntity1 = new buLine(new Point3D(point3D3.X, -100.0, 0.0), new Point3D(point3D3.X, 10000.0, 0.0));
        else if (Cmd == MarbleCadCamCommands.MagnetRightUp | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetRight)
          refEntity1 = new buLine(new Point3D(point3D4.X, -100.0, 0.0), new Point3D(point3D4.X, 10000.0, 0.0));
        else if (Cmd == MarbleCadCamCommands.MagnetUp | Cmd == MarbleCadCamCommands.MagnetDown)
        {
          refEntity1 = new buLine(new Point3D(point3D4.X, -100.0, 0.0), new Point3D(point3D4.X, 10000.0, 0.0));
          refEntity2 = new buLine(new Point3D(point3D3.X, -100.0, 0.0), new Point3D(point3D3.X, 10000.0, 0.0));
        }
        List<Point3D> point3DList = new List<Point3D>();
        if (Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetRightUp | Cmd == MarbleCadCamCommands.MagnetUp | Cmd == MarbleCadCamCommands.MagnetDown)
        {
          clsInit.cVector5.IntersectionOfEntities(Entities, (buEntity) refEntity1, ref point3DList);
          if (refEntity2 != null)
            clsInit.cVector5.IntersectionOfEntities(Entities, (buEntity) refEntity2, ref point3DList);
        }
        double y1 = point3D3.Y;
        if (point3DList.Count > 0)
        {
          clsInit.cVector5.SortDeltaY(new Point3D(point3D3.X, -100.0, 0.0), SortDirectionType.Lower, ref point3DList);
          if (Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetDown)
          {
            double y2 = point3DList[point3DList.Count - 1].Y;
            if (y2 < point3D3.Y)
              dY = y2 - point3D3.Y + buMarbleCalc.activeToolSaw.Geometry.Thickness;
          }
          if (Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetRightUp | Cmd == MarbleCadCamCommands.MagnetUp)
          {
            double y3 = point3DList[0].Y;
            if (y3 > point3D4.Y)
              dY = y3 - point3D4.Y - buMarbleCalc.activeToolSaw.Geometry.Thickness;
          }
        }
        else
        {
          if (Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetDown)
            y1 = 1.0;
          if (Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetRightUp | Cmd == MarbleCadCamCommands.MagnetUp)
            y1 = num1 - 1.0;
        }
        buLine refEntity3 = new buLine(new Point3D(-100.0, y1, 0.0), new Point3D(10000.0, y1, 0.0));
        point3DList = new List<Point3D>();
        if (Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetRightUp)
          clsInit.cVector5.IntersectionOfEntities(Entities, (buEntity) refEntity3, ref point3DList);
        else if (Cmd == MarbleCadCamCommands.MagnetLeft | Cmd == MarbleCadCamCommands.MagnetRight)
        {
          buLine refEntity4 = new buLine(new Point3D(-100.0, point3D3.Y, 0.0), new Point3D(10000.0, point3D3.Y, 0.0));
          clsInit.cVector5.IntersectionOfEntities(Entities, (buEntity) refEntity4, ref point3DList);
          buLine refEntity5 = new buLine(new Point3D(-100.0, point3D4.Y, 0.0), new Point3D(10000.0, point3D4.Y, 0.0));
          clsInit.cVector5.IntersectionOfEntities(Entities, (buEntity) refEntity5, ref point3DList);
        }
        if (point3DList.Count > 0)
        {
          clsInit.cVector5.SortDeltaX(new Point3D(-100.0, point3D3.Y, 0.0), SortDirectionType.Lower, ref point3DList);
          if (Cmd == MarbleCadCamCommands.MagnetLeftUp | Cmd == MarbleCadCamCommands.MagnetLeftDown | Cmd == MarbleCadCamCommands.MagnetLeft)
            dX = point3DList[point3DList.Count - 1].X - point3D3.X + buMarbleCalc.activeToolSaw.Geometry.Thickness;
          if (Cmd == MarbleCadCamCommands.MagnetRightUp | Cmd == MarbleCadCamCommands.MagnetRightDown | Cmd == MarbleCadCamCommands.MagnetRight)
            dX = point3DList[0].X - point3D4.X - buMarbleCalc.activeToolSaw.Geometry.Thickness;
        }
      }
    }
    if (Cmd == MarbleCadCamCommands.MagnetLeftDown)
    {
      dX += Value;
      dY += Value;
    }
    if (Cmd == MarbleCadCamCommands.MagnetLeft)
      dX += Value;
    if (Cmd == MarbleCadCamCommands.MagnetLeftUp)
    {
      dX += Value;
      dY -= Value;
    }
    if (Cmd == MarbleCadCamCommands.MagnetRightDown)
    {
      dX -= Value;
      dY += Value;
    }
    if (Cmd == MarbleCadCamCommands.MagnetRight)
      dX -= Value;
    if (Cmd == MarbleCadCamCommands.MagnetRightUp)
    {
      dX -= Value;
      dY -= Value;
    }
    if (Cmd == MarbleCadCamCommands.MagnetDown)
      dY += Value;
    if (Cmd == MarbleCadCamCommands.MagnetUp)
      dY -= Value;
    this.UndoBuffer();
    if (buMarbleCalc.SelectedItem.SelectionItems.Count == 0)
    {
      for (int index6 = 0; index6 <= this.activeJob.Items.Count - 1; ++index6)
      {
        MarbleItem marbleItem = this.activeJob.Items[index6];
        clsInit.cMarble.MoveItem(ref marbleItem, dX, dY, 0.0);
        for (int index7 = 0; index7 <= this.activeJob.Items[index6].CamList.Count - 1; ++index7)
          this.activeJob.Items[index6].CamList[index7].isCamCalculated = false;
