          for (int index9 = 0; index9 <= marbleItem.CamList.Count - 1; ++index9)
            marbleItem.CamList[index9].isCamCalculated = false;
        }
      }
    }
    AppBool.EditMode = false;
    this.doDrawActiveJob();
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    clsInit.appCommand.Reset();
