  public void doAlignmentSide(MarbleCadCamCommands Cmd, double Value)
  {
    Point3D point3D1 = new Point3D();
    Point3D point3D2 = new Point3D();
    if (buMarbleCalc.SelectedItem.SelectionItems.Count < 2)
      return;
    double num1 = 0.0;
    double num2 = 0.0;
    if (Cmd == MarbleCadCamCommands.SideDown)
      num2 = buMarbleCalc.SelectedItem.SelectionItems[0].pntMin.Y;
    if (Cmd == MarbleCadCamCommands.SideUp)
      num2 = buMarbleCalc.SelectedItem.SelectionItems[0].pntMax.Y;
    if (Cmd == MarbleCadCamCommands.SideLeft)
      num1 = buMarbleCalc.SelectedItem.SelectionItems[0].pntMin.X;
    if (Cmd == MarbleCadCamCommands.SideRight)
      num1 = buMarbleCalc.SelectedItem.SelectionItems[0].pntMax.X;
    if (Cmd == MarbleCadCamCommands.SideCenterHorizontal)
      num2 = (buMarbleCalc.SelectedItem.SelectionItems[0].pntMin.Y + buMarbleCalc.SelectedItem.SelectionItems[0].pntMax.Y) / 2.0;
    if (Cmd == MarbleCadCamCommands.SideCenterVertical)
      num1 = (buMarbleCalc.SelectedItem.SelectionItems[0].pntMin.X + buMarbleCalc.SelectedItem.SelectionItems[0].pntMax.X) / 2.0;
    this.UndoBuffer();
    for (int index1 = 1; index1 <= buMarbleCalc.SelectedItem.SelectionItems.Count - 1; ++index1)
    {
      double dX = 0.0;
      double dY = 0.0;
      if (buMarbleCalc.SelectedItem.SelectionItems[index1].indexItem >= 0 & buMarbleCalc.SelectedItem.SelectionItems[index1].indexItem <= this.activeJob.Items.Count - 1)
      {
        MarbleItem marbleItem = this.activeJob.Items[buMarbleCalc.SelectedItem.SelectionItems[index1].indexItem];
        if (Cmd == MarbleCadCamCommands.SideDown)
          dY = num2 - marbleItem.SizeItem.MinPoint.Y;
        if (Cmd == MarbleCadCamCommands.SideUp)
          dY = num2 - marbleItem.SizeItem.MaxPoint.Y;
        if (Cmd == MarbleCadCamCommands.SideLeft)
          dX = num1 - marbleItem.SizeItem.MinPoint.X;
        if (Cmd == MarbleCadCamCommands.SideRight)
          dX = num1 - marbleItem.SizeItem.MaxPoint.X;
        if (Cmd == MarbleCadCamCommands.SideCenterVertical)
          dX = num1 - (marbleItem.SizeItem.MinPoint.X + marbleItem.SizeItem.MaxPoint.X) / 2.0;
        if (Cmd == MarbleCadCamCommands.SideCenterHorizontal)
          dY = num2 - (marbleItem.SizeItem.MinPoint.Y + buMarbleCalc.SelectedItem.SelectionItems[index1].pntMax.Y) / 2.0;
        clsInit.cMarble.MoveItem(ref marbleItem, dX, dY, 0.0);
        for (int index2 = 0; index2 <= marbleItem.CamList.Count - 1; ++index2)
          marbleItem.CamList[index2].isCamCalculated = false;
      }
    }
    AppBool.EditMode = false;
    this.doDrawActiveJob();
    clsInit.cMarble.JobCamCalculatedReset(true, true, true, -1, ref clsInit.appMarble.activeJob);
    clsInit.appCommand.Reset();
    buMarbleCalc.SelectedItem.SelectionItems.Clear();
  }

  public void doEdgeChangeDirection()
  {
    string str = nameof (doEdgeChangeDirection);
    try
    {
      if (!(buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.WireItem & buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexEdge >= 0) || buMarbleCalc.SelectedItem.ActiveItem.indexCam < 0)
        return;
      MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
      if (marbleItem.CamList.Count <= 0)
        return;
      MarbleItemCam cam = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem].CamList[buMarbleCalc.SelectedItem.ActiveItem.indexCam];
      if ((cam.WireEntities == null ? 0 : (cam.WireEntities.Count > 0 ? 1 : 0)) == 0)
        return;
      for (int index1 = 0; index1 <= cam.WireEntities.Count - 1; ++index1)
      {
        for (int index2 = 0; index2 <= cam.WireEntities[index1].Count - 1; ++index2)
        {
          buEntity buEntity = cam.WireEntities[index1][index2];
          if (buEntity.Info.EntityIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdge & buEntity.Info.EntitySubIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub)
            buEntity.sortDirection = buEntity.sortDirection != entitySortDirection.Normal ? entitySortDirection.Normal : entitySortDirection.Reverse;
        }
      }
      cam.isCamCalculated = false;
      clsInit.cMarble.EdgePropertiesFromWireEntities(cam.WireEntities, ref marbleItem.Edges);
      bool isExpanded1 = this.tnPanel.IsExpanded;
      bool isExpanded2 = this.tnItem.IsExpanded;
      bool isExpanded3 = this.tnCams.IsExpanded;
      bool isExpanded4 = this.tnEdgeInside.IsExpanded;
      bool isExpanded5 = this.tnEdgeOutside.IsExpanded;
      this.JobUpdate();
      if (isExpanded1)
        this.tnPanel.Expand();
      if (isExpanded2)
        this.tnItem.Expand();
      if (isExpanded3)
        this.tnCams.Expand();
      if (isExpanded4)
        this.tnEdgeInside.Expand();
      if (isExpanded5)
        this.tnEdgeOutside.Expand();
      this.doCamCalculateMarbleItem(buMarbleCalc.SelectedItem.ActiveItem.indexItem, false, (TpPnt9D) null, ref marbleItem);
      clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
      this.doDrawActiveJob();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

  public void doEdgeMoveUpDown(bool Up)
  {
    string str = nameof (doEdgeMoveUpDown);
    try
    {
      if (!(buMarbleCalc.SelectedItem.ActiveItem.SelectionCommand == MarbleOperationSelectionCommand.WireItem & buMarbleCalc.SelectedItem.ActiveItem.indexItem >= 0 & buMarbleCalc.SelectedItem.ActiveItem.indexEdge >= 0) || buMarbleCalc.SelectedItem.ActiveItem.indexCam < 0)
        return;
      MarbleItem marbleItem = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem];
      if (marbleItem.CamList.Count <= 0)
        return;
      MarbleItemCam cam = clsInit.appMarble.activeJob.Items[buMarbleCalc.SelectedItem.ActiveItem.indexItem].CamList[buMarbleCalc.SelectedItem.ActiveItem.indexCam];
      if ((cam.WireEntities == null ? 0 : (cam.WireEntities.Count > 1 ? 1 : 0)) == 0)
        return;
      int index1 = -1;
      List<int> intList = new List<int>();
      for (int index2 = 0; index2 <= cam.WireEntities.Count - 1; ++index2)
      {
        for (int index3 = 0; index3 <= cam.WireEntities[index2].Count - 1; ++index3)
        {
          buEntity buEntity = cam.WireEntities[index2][index3];
          if (buEntity.Info.EntityIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdge & buEntity.Info.EntitySubIndex == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub)
          {
            index1 = index2;
            intList.Add(index2);
          }
        }
        if (index1 >= 0)
          ;
      }
      if (index1 >= 0)
      {
        for (int index4 = 0; index4 <= marbleItem.Edges.Count - 1; ++index4)
        {
          if (marbleItem.Edges[index4].IndexEntity == buMarbleCalc.SelectedItem.ActiveItem.indexEdge & marbleItem.Edges[index4].IndexEntitySub == buMarbleCalc.SelectedItem.ActiveItem.indexEdgeSub)
          {
            if (Up)
            {
              if (index4 > 0)
              {
                marbleEdgeItem edge = marbleItem.Edges[index4];
                marbleItem.Edges.RemoveAt(index4);
                marbleItem.Edges.Insert(index4 - 1, edge);
              }
            }
            else if (index4 <= marbleItem.Edges.Count - 2)
            {
              marbleEdgeItem edge = marbleItem.Edges[index4];
              marbleItem.Edges.RemoveAt(index4);
              marbleItem.Edges.Insert(index4 + 1, edge);
            }
            index4 = marbleItem.Edges.Count;
          }
        }
      }
      if (Up)
      {
        if (index1 >= 1)
        {
          List<buEntity> wireEntity = cam.WireEntities[index1];
          cam.WireEntities.RemoveAt(index1);
          cam.WireEntities.Insert(index1 - 1, wireEntity);
          cam.isCamCalculated = false;
        }
      }
      else
      {
        for (int index5 = 0; index5 <= intList.Count - 1; ++index5)
        {
          int index6 = intList[index5];
          if (index6 <= cam.WireEntities.Count - 2)
          {
            List<buEntity> wireEntity = cam.WireEntities[index6];
            cam.WireEntities.RemoveAt(index6);
            cam.WireEntities.Insert(index6 + 1, wireEntity);
            cam.isCamCalculated = false;
          }
        }
      }
      clsInit.cMarble.EdgePropertiesFromWireEntities(cam.WireEntities, ref marbleItem.Edges);
      bool isExpanded1 = this.tnPanel.IsExpanded;
      bool isExpanded2 = this.tnItem.IsExpanded;
      bool isExpanded3 = this.tnCams.IsExpanded;
      bool isExpanded4 = this.tnEdgeInside.IsExpanded;
      bool isExpanded5 = this.tnEdgeOutside.IsExpanded;
      this.JobUpdate();
      if (isExpanded1)
        this.tnPanel.Expand();
      if (isExpanded2)
        this.tnItem.Expand();
      if (isExpanded3)
        this.tnCams.Expand();
      if (isExpanded4)
        this.tnEdgeInside.Expand();
      if (isExpanded5)
        this.tnEdgeOutside.Expand();
      this.doCamCalculateMarbleItem(buMarbleCalc.SelectedItem.ActiveItem.indexItem, false, (TpPnt9D) null, ref marbleItem);
      clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
      this.doDrawActiveJob();
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, "Error", "", 0.0, 0.0, true);
      buException.throwException(ex, str, true, "");
    }
  }

