  public void doGetEdgeList(
    ref List<ShapeEntityIndex> Lst,
    ref List<int> EntList,
    ref EdgeFoundArgs Args)
  {
    Args.FoundAngle = 0.0;
    Args.Outside = false;
    Args.pntPick = new Point3D();
    Lst = new List<ShapeEntityIndex>();
    EntList = new List<int>();
    for (int index = 0; index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index];
      if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData && ((CustomData) entity.EntityData).Tags == "Edge")
      {
        int result = -1;
        if ((((CustomData) entity.EntityData).infoData == null ? 0 : (((CustomData) entity.EntityData).infoData == "Inside" ? 1 : 0)) != 0)
          Args.Outside = false;
        else if ((((CustomData) entity.EntityData).infoData == null ? 0 : (((CustomData) entity.EntityData).infoData == "Outside" ? 1 : 0)) != 0)
          Args.Outside = true;
        Args.pntPick = ((CustomData) entity.EntityData).infoBasePoint;
        if (result.ToString().Trim().Length > 0)
          int.TryParse(((CustomData) entity.EntityData).ID, out result);
        if (result >= 0)
          ;
        Lst.Add(new ShapeEntityIndex(((CustomData) entity.EntityData).EntitySubIndex, ((CustomData) entity.EntityData).EntityIndex, result, Args.Outside, ((CustomData) entity.EntityData).infoAngle, ((CustomData) entity.EntityData).RefIndex, ((CustomData) entity.EntityData).CamIndex)
        {
          CamID = ((CustomData) entity.EntityData).CamID,
          ItemID = ((CustomData) entity.EntityData).ItemID,
          EdgeID = ((CustomData) entity.EntityData).EdgeID,
          indexInside = ((CustomData) entity.EntityData).InsideIndex
        });
        EntList.Add(index);
        if (((CustomData) entity.EntityData).infoAngle != 0.0)
          Args.FoundAngle = ((CustomData) entity.EntityData).infoAngle;
      }
    }
  }

