  public void doMoveDownItem(ref int SelectedIndex)
  {
    if (!(this.activeJob.Items.Count > 1 & SelectedIndex >= 0 & SelectedIndex < this.activeJob.Items.Count - 1))
      return;
    MarbleItem marbleItem = this.activeJob.Items[SelectedIndex];
    this.activeJob.Items.RemoveAt(SelectedIndex);
    ++SelectedIndex;
    this.activeJob.Items.Insert(SelectedIndex, marbleItem);
    clsInit.cMarble.JobCamCalculatedReset(true, true, false, -1, ref clsInit.appMarble.activeJob);
  }

  public void doMoveUpItem(ref int SelectedIndex)
  {
    if (!(this.activeJob.Items.Count > 1 & SelectedIndex > 0 & SelectedIndex <= this.activeJob.Items.Count - 1))
      return;
    MarbleItem marbleItem = this.activeJob.Items[SelectedIndex];
    this.activeJob.Items.RemoveAt(SelectedIndex);
    --SelectedIndex;
    this.activeJob.Items.Insert(SelectedIndex, marbleItem);
    clsInit.cMarble.JobCamCalculatedReset(true, true, false, -1, ref clsInit.appMarble.activeJob);
  }

  public void doEditItem()
  {
    List<double> doubleList = new List<double>();
    List<int> intList1 = new List<int>();
    List<ShapeEntityIndex> shapeEntityIndexList = new List<ShapeEntityIndex>();
    List<int> intList2 = new List<int>();
    bool flag1 = true;
    for (int index1 = 0; index1 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; ++index1)
    {
      Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index1];
      if (entity.Selected && entity.EntityData != null & entity.EntityData is CustomData && ((CustomData) entity.EntityData).Tags == "Edge")
      {
        int result = -1;
        if ((((CustomData) entity.EntityData).infoData == null ? 0 : (((CustomData) entity.EntityData).infoData == "Inside" ? 1 : 0)) != 0)
          flag1 = false;
        if (result.ToString().Trim().Length > 0)
          int.TryParse(((CustomData) entity.EntityData).ID, out result);
        if (result >= 0)
          intList1.Add(result);
        shapeEntityIndexList.Add(new ShapeEntityIndex(((CustomData) entity.EntityData).RefIndex, ((CustomData) entity.EntityData).Sequence));
        intList2.Add(index1);
        if (doubleList.Count == 0)
        {
          doubleList.Add(((CustomData) entity.EntityData).infoAngle);
        }
        else
        {
          bool flag2 = true;
