        }
      }
      this.activeJob.CamCalculated = false;
      for (int index3 = 0; index3 <= intList1.Count - 1; ++index3)
      {
        for (int index4 = 0; index4 <= clsInit.appMarble.activeJob.Items.Count - 1; ++index4)
        {
          if (intList1[index3] == clsInit.appMarble.activeJob.Items[index4].ID && !flag1 && this.activeJob.Items[index4].EntGroup.Inside != null & shapeEntityIndexList.Count > 0)
          {
