              int indexEntitySub = shapeEntityIndexList[index5].indexEntitySub;
              if (indexEntitySub >= 0 & indexEntitySub <= this.activeJob.Items[index4].EntGroup.Inside.Count - 1 && indexEntity >= 0 & indexEntity <= this.activeJob.Items[index4].EntGroup.Inside[indexEntitySub].Entities.Count - 1)
              {
                for (int index6 = 0; index6 <= this.activeJob.Items[index4].CamList.Count - 1; ++index6)
                {
                  if (!(this.activeJob.Items[index4].CamList[index6].Direction == InOutCenterType.Inside & (this.activeJob.Items[index4].CamList[index6].ToolType == MarbleToolType.Saw | this.activeJob.Items[index4].CamList[index6].ToolType == MarbleToolType.WaterJet)) || this.activeJob.Items[index4].CamList[index6].indexInside == indexEntitySub)
                    ;
                }
              }
            }
          }
        }
      }
      clsInit.appMarble.activeJob.CamCalculated = false;
      this.doCamCalculateMarbleJob(ref clsInit.appMarble.activeJob);
      clsInit.cMarble.JobCamCalculatedReset(true, false, false, -1, ref clsInit.appMarble.activeJob);
      this.JobUpdate();
      this.doDrawActiveJob();
    }
  }

