  public void AddToolTypeChangeLineCodes(
    MarbleToolType ToolType,
    ToolBase5 Tool,
    marbleGCodeCreateOptions Options,
    ref camTp CamBase)
  {
    string str1 = nameof (AddToolTypeChangeLineCodes);
    try
    {
      bool flag1 = false;
      bool flag2 = false;
      bool flag3 = false;
      bool flag4 = false;
      CamBase.PreCodes.Clear();
      switch (ToolType)
      {
        case MarbleToolType.Saw:
          CamBase.PreCodes.Add((object) "M40");
          CamBase.PreCodes.Add((object) "G75");
          if (!Options.AddM3M4WhilePlunge)
          {
            if (!Tool.CamData.SpindleReverseDir)
              CamBase.PreCodes.Add((object) ("M33 K" + Tool.CamData.SpindleSpeed.ToString()));
            else
              CamBase.PreCodes.Add((object) ("M34 K" + Tool.CamData.SpindleSpeed.ToString()));
            flag3 = true;
          }
          if (!Options.AddM8WhilePlunge)
          {
            CamBase.PreCodes.Add((object) "M8");
            flag4 = true;
          }
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "M154");
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
          CamBase.PreCodes.Add((object) "G75");
          break;
        case MarbleToolType.Milling:
          CamBase.PreCodes.Add((object) "M41");
          CamBase.PreCodes.Add((object) "G75");
          if (!Options.AddM3M4WhilePlunge)
          {
            if (!Tool.CamData.SpindleReverseDir)
              CamBase.PreCodes.Add((object) ("M3 K" + Tool.CamData.SpindleSpeed.ToString()));
            else
              CamBase.PreCodes.Add((object) ("M4 K" + Tool.CamData.SpindleSpeed.ToString()));
            flag3 = true;
          }
          if (!Options.AddM8WhilePlunge)
          {
            CamBase.PreCodes.Add((object) "M8");
            flag4 = true;
          }
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "M154");
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
          CamBase.PreCodes.Add((object) "G75");
          break;
        case MarbleToolType.MillingHead:
          CamBase.PreCodes.Add((object) "M42");
          CamBase.PreCodes.Add((object) "G75");
          if (!Options.AddM3M4WhilePlunge)
          {
            if (!Tool.CamData.SpindleReverseDir)
              CamBase.PreCodes.Add((object) ("M33 K" + Tool.CamData.SpindleSpeed.ToString()));
            else
              CamBase.PreCodes.Add((object) ("M34 K" + Tool.CamData.SpindleSpeed.ToString()));
            flag3 = true;
          }
          if (!Options.AddM8WhilePlunge)
          {
            CamBase.PreCodes.Add((object) "M8");
            flag4 = true;
          }
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "M154");
          CamBase.PreCodes.Add((object) "G75");
          CamBase.PreCodes.Add((object) "G54 X$G54.X$ Y$G54.Y$ Z$G54.Z$");
          CamBase.PreCodes.Add((object) "G75");
          break;
      }
      for (int index1 = 0; index1 <= CamBase.CamPoints.Count - 1; ++index1)
      {
        CamBase.CamPoints[index1].ToolCam = new ToolBase5(CamBase.Tool);
        for (int index2 = 0; index2 <= CamBase.CamPoints[index1].Points.Count - 1; ++index2)
        {
          if (CamBase.Tool.Purpose == ToolPurpose.MillingHead)
            ;
          if (flag1 & !flag2)
          {
            if (Options.AddM3M4WhilePlunge & index2 > 0)
            {
              string str2 = "";
              if (ToolType == MarbleToolType.Saw)
              {
                str2 = "M33";
                if (CamBase.Tool.CamData.SpindleReverseDir)
                  str2 = "M34";
                flag3 = true;
              }
              if (ToolType == MarbleToolType.Milling)
              {
                str2 = "M3";
                if (CamBase.Tool.CamData.SpindleReverseDir)
                  str2 = "M4";
                flag3 = true;
              }
              if (ToolType == MarbleToolType.MillingHead)
              {
                str2 = "M33";
                if (CamBase.Tool.CamData.SpindleReverseDir)
                  str2 = "M34";
                flag3 = true;
              }
              CamBase.CamPoints[index1].Points[index2 - 1].PreCodes.Add((object) $"{str2} K{Tool.CamData.SpindleSpeed.ToString()}");
            }
            if (Options.AddM8WhilePlunge & index2 > 0)
            {
              string str3 = "M8";
              CamBase.CamPoints[index1].Points[index2 - 1].PreCodes.Add((object) str3);
              flag4 = true;
            }
            flag2 = true;
          }
          if (!flag1 && CamBase.CamPoints[index1].Points[index2].PlungeAxisMovement)
            flag1 = true;
        }
      }
      if (!flag3)
      {
        if (ToolType == MarbleToolType.Saw)
        {
          if (!Tool.CamData.SpindleReverseDir)
            CamBase.PreCodes.Add((object) ("M33 K" + Tool.CamData.SpindleSpeed.ToString()));
          else
            CamBase.PreCodes.Add((object) ("M34 K" + Tool.CamData.SpindleSpeed.ToString()));
        }
        if (ToolType == MarbleToolType.Milling)
        {
          if (!Tool.CamData.SpindleReverseDir)
            CamBase.PreCodes.Add((object) ("M3 K" + Tool.CamData.SpindleSpeed.ToString()));
          else
            CamBase.PreCodes.Add((object) ("M4 K" + Tool.CamData.SpindleSpeed.ToString()));
        }
        if (ToolType == MarbleToolType.MillingHead)
        {
          if (!Tool.CamData.SpindleReverseDir)
            CamBase.PreCodes.Add((object) ("M33 K" + Tool.CamData.SpindleSpeed.ToString()));
          else
            CamBase.PreCodes.Add((object) ("M34 K" + Tool.CamData.SpindleSpeed.ToString()));
        }
      }
      if (flag4)
        return;
      CamBase.PreCodes.Add((object) "M8");
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str1, ex.Message, "Exception");
      buException.throwException(ex, str1, true, "Exception");
    }
  }

