  public void AnalyzeSawCam(marbleMillingAnalyzePars AnalyzeSet, ref camTp CamBase)
  {
    string str = "AnalyzeMillingCam";
    try
    {
      if (CamBase == null)
        return;
      CamBase.Post = new PostProcessor(ccVars.PostActive);
      CamBase.UsedCamPost = true;
      CamBase.Post.RepetitionDef.Tool = false;
      CamBase.Post.ToolDef.ToolData.PreCode.Clear();
      CamBase.Post.SpindleDef.UseSpindle = false;
      CamBase.Post.AxesUsing.Z = true;
      CamBase.Post.AxesUsing.A = true;
      CamBase.Post.AxesUsing.C = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }

  public void AnalyzeMillingCam(marbleMillingAnalyzePars AnalyzeSet, ref camTp CamBase)
  {
    string str = nameof (AnalyzeMillingCam);
    try
    {
      if (CamBase == null)
        return;
      double num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeVelocity;
      double plungeFirstVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingPlungeFirstVelocity;
      double num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingFirstStepDown;
      if (CamBase.Tool.Purpose == ToolPurpose.MillingHead)
      {
        num1 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeVelocity;
        plungeFirstVelocity = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadPlungeFirstVelocity;
        num2 = buMarbleCalc.varOperation.settingMarbleCam.MillingHeadFirstStepDown;
      }
      bool flag1 = false;
      for (int index1 = 0; index1 <= CamBase.CamPoints.Count - 1; ++index1)
      {
        TpPnt9D tpPnt9D = (TpPnt9D) null;
        if (index1 > 0)
          tpPnt9D = CamBase.CamPoints[index1 - 1].Points[CamBase.CamPoints[index1 - 1].Points.Count - 1];
        if (index1 == 0)
        {
          CamBase.CamPoints[index1].PreCodes.Add((object) "G39 O1");
          CamBase.CamPoints[index1].PreCodes.Add((object) "G50");
        }
        bool flag2 = false;
        for (int index2 = 0; index2 <= CamBase.CamPoints[index1].Points.Count - 1; ++index2)
        {
          TpPnt9D point1 = CamBase.CamPoints[index1].Points[index2];
          if (!flag1 & (point1.Type == 1 | point1.Type == 2 | point1.Type == 3))
          {
            point1.PreCodes.Add((object) "G50");
            flag1 = true;
          }
          if (CamBase.Tool.Purpose == ToolPurpose.MillingHead && AnalyzeSet.Apply90DegreeToMillingHead)
            CamBase.CamPoints[index1].Points[index2].P9.A = 90.0;
          if (index2 == 0)
          {
            if (tpPnt9D != null && point1.P9.Z < tpPnt9D.P9.Z)
              CamBase.CamPoints[index1].Points[index2].Feed = num1;
          }
          else
          {
            TpPnt9D point2 = CamBase.CamPoints[index1].Points[index2 - 1];
            if (point2.Type == 0 & point1.Type == 1 & point1.PlungeAxisMovement & !flag2 & num2 > 0.0 && point1.P9.Z < point2.P9.Z & buCompare5.EQ(point2.P9.X, point1.P9.X) & buCompare5.EQ(point2.P9.Y, point1.P9.Y))
            {
              CamBase.CamPoints[index1].Points[index2].Feed = plungeFirstVelocity;
              flag2 = true;
            }
          }
        }
      }
      CamBase.Post = new PostProcessor(ccVars.PostActive);
      CamBase.UsedCamPost = true;
      CamBase.Post.RepetitionDef.Tool = false;
      CamBase.Post.ToolDef.ToolData.PreCode.Clear();
      CamBase.Post.SpindleDef.UseSpindle = false;
      CamBase.Post.AxesUsing.Z = true;
      CamBase.Post.AxesUsing.A = true;
      CamBase.Post.AxesUsing.C = true;
    }
    catch (Exception ex)
    {
      buLogVer5.addToLog(this.string_0, str, ex.Message, "Exception");
      buException.throwException(ex, str, true, "Exception");
    }
  }
